/****** Object:  UserDefinedFunction [dbo].[FN_GENERATE_NEXT_ZED_INVOICE_NO_notusing]    Script Date: 9/19/2026 4:27:48 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[FN_GENERATE_NEXT_ZED_INVOICE_NO_notusing]
(
    @CurrentDate DATE
)
RETURNS VARCHAR(50)
AS
BEGIN
    -- DECLARE VARIABLES
    DECLARE @CurrentFY_String VARCHAR(4); 
    DECLARE @NextSequenceNumber INT;
    DECLARE @NewTADAInvoiceNo VARCHAR(50);

    -- 1. DETERMINE THE FY STRING (e.g., '<redacted>')
    SET @CurrentFY_String = 
        CASE
            WHEN MONTH(@CurrentDate) < 4
            THEN CONCAT(RIGHT(CAST(YEAR(@CurrentDate) - 1 AS VARCHAR(4)), 2), RIGHT(CAST(YEAR(@CurrentDate) AS VARCHAR(4)), 2))
            ELSE CONCAT(RIGHT(CAST(YEAR(@CurrentDate) AS VARCHAR(4)), 2), RIGHT(CAST(YEAR(@CurrentDate) + 1 AS VARCHAR(4)), 2))
        END;

    -- 2. FIND THE NEXT SEQUENCE NUMBER (MAX + 1)
    -- NOTE: For robust concurrency, ensure the calling SP uses a SERIALIZABLE transaction scope.
    SELECT @NextSequenceNumber = ISNULL(MAX(
        CAST(RIGHT(TadaInvoiceNo, CHARINDEX('/', REVERSE(TadaInvoiceNo)) - 1) AS INT)
    ), 0) + 1
    FROM MsmePaymentInfo WITH (UPDLOCK, HOLDLOCK) -- Use a lock hint to prevent concurrent users from generating the same number
    WHERE TadaInvoiceNo LIKE CONCAT('ZED/', @CurrentFY_String, '/%');

    -- 3. CONSTRUCT THE FULL INVOICE NUMBER
    SET @NewTADAInvoiceNo = CONCAT('ZED/', @CurrentFY_String, '/', @NextSequenceNumber);

    RETURN @NewTADAInvoiceNo;
END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_IsSafeInput]    Script Date: 9/19/2026 4:27:48 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_IsSafeInput] (@Input NVARCHAR(MAX))
RETURNS BIT
AS
BEGIN
    DECLARE @IsSafe BIT = 1;

    IF @Input IS NULL
        RETURN 1;

    IF @Input LIKE '%<%' OR
       @Input LIKE '%>%' OR
       @Input LIKE '%script%' OR
       @Input LIKE '%onerror=%' OR
       @Input LIKE '%onload=%' OR
       @Input LIKE '%onclick=%' OR
       @Input LIKE '%javascript:%' OR
       @Input LIKE '%vbscript:%' OR
       @Input LIKE '%eval(%' OR
       @Input LIKE '%alert(%' OR
       @Input LIKE '%{{%' OR
       @Input LIKE '%}}%'
    BEGIN
        SET @IsSafe = 0;
    END

    RETURN @IsSafe;
END
GO
