CREATE VIEW [dbo].[DynamicListOfFinancialSupportZedIdsWithDates] AS


select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName, Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' else 'Active' end as ZedIdStatus, P.Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus=6 THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus>=2 and CertificationStatus<=90 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')

		UNION ALL

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' else 'Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus=99 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')

		union all

