CREATE view [dbo].[DownloadListOfWebinarUnits] as
SELECT  ROW_NUMBER() OVER(ORDER BY SelfCertificationDate) [SNo]
	  
	  ,SelfCertificationDate [DateOfSelfCertification]
	  ,EstablishmentName as [UnitName] 
	  ,S.[RegistrationNumber] [HotelCloudRegistrationNumber]
	  ,S.[Acommodationtype] [AcommodationType]
      ,NumOfRooms [TotalRooms]
	   ,isnull(RestaurantType,'Others') RestaurantType
	  ,Category
	  ,SelfCertificateNo
	  ,IsCertificateGenerated as [NoOfSelfCertification]
	  ,ResetDate [ResetOrRetakeDate]
	  ,[EstablishmentAddress]
	  ,[EstablishmentCity]
	  ,[DistrictName]
      ,[StateName]
      ,[EstablishmentPinCode]
	  ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[RespondentName]
      ,S.[MobileNo] MobileNumber
      ,[EmailId]

	  ,W.WebinarId, convert(date,Wn.WebinarDate) WebinarDate,WN.WebinarStartTime WebinarStartTime,WN.WebinarEndTime WebinarEndTime,
	  W.RespondentMobileNo,Title,FirstName,W.MobileNo,W.Email,W.CreatedDate [WebinarRegistrationDate],
	  case when IsSentCertificate=1 then 'Yes' else 'No' end as IsWebinarCertificateSend,
	  W.CertificateDate [WebinarCertificateDate],WebinarCertificateNo,
	  case when FeedbackLink=1 then 'Yes' else 'No' end as  IsFeedBackLinkSend


	  --,REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + '<redacted>' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + '<redacted>' end + StateName),'<redacted>','') EstablishmentFullAddress
	FROM SelfAssessments S LEFT JOIN WebinarRegistrations W ON (S.RegistrationNumber=W.RegistrationNumber)
	LEFT join Webinars Wn on (W.WebinarId=Wn.Id)
	WHERE IsCertificateGenerated>0 and S.RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')

