CREATE   view  [dbo].[DynamicListofZedPaymentReceived] as
SELECT m.ZedId,P.Certification, PUnitName PUnitName,m.pstatename StateName,m.PDistrictName DistrictName,m.EnterpriseTypee Size,case when (M.IsCouponUsed)=1 then 'Yes' when IsCouponUsed is null then 'No' end as JoiningReward,
		B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
		P.GstinNumber, P.TanNumber, P.UtrNumber, P.Id TransactionId, P.TransactionStatus,convert(varchar, P.CreatedDate, 9) as TransactionDate, P.PaymentType, P.SubsidyPercentage,P.Tds,ISNULL(Amount,0) AmountPaid
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	FROM MsmePaymentInfo P inner join Msme M on (P.ZedId=M.ZedId)
	inner join MsmeBasicInformation B on (P.ZedId=B.ZedId )
	left join PaymentGateWayTransactions T on (M.ZedId=T.ZedId and P.Certification=T.Certification and PaymentStatus='Success')
	WHERE P.ZedId=M.ZedId AND M.ZedId=B.ZedId 
	AND UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	
GO
/****** Object:  View [dbo].[DynamicZedStatusReport]    Script Date: 9/19/2026 4:27:53 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE   view  [dbo].[DynamicZedStatusReport] as
select C.ZedId,M.PUnitName UnitName,B.UdyogAadharNo,m.PAddress Address,
			BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			CompletedOn
			 from MsmeCertifications C
			inner join Msme M on (M.ZedId=C.Zedid)
			inner join MsmeBasicInformation B on (B.ZedId=C.Zedid)
			left join
			(select ZedId,CertificationType,
			ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
			case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
			case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
			[ScheduledOn],
			Completed as [CompletedOn],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]			
			from 
			(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
			pivot (
			max(CreatedOn) for StatusType in (
			[BasicInfoStatus],
			[DesktopVerification],
			[ScheduledOn],
			DocVerifiAllot,
			[Completed],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]) ) as Pvt
		) PVD
		on (C.ZedId=PVD.ZedId and C.Certification=PVD.CertificationType ) 
		where c.CertificationStatus!=99
		AND UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		

GO
/****** Object:  View [dbo].[DynamicListofZedCertifiedMsme]    Script Date: 9/19/2026 4:27:53 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE view  [dbo].[DynamicListofZedCertifiedMsme] as
SELECT P.Id,M.ZedId,Certification,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			M.CreatedDate ReigstrationDate,
			-- U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			--UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			--Us.UserName as SiteAssessor, P.SiteAssessorId,
			--UC.UserName as coAssessor, P.CoAssessorId,
			PStateName StateName,PDistrictName DistrictName,  M.EnterpriseName, ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,
			DaCertificateNo,SaCertificateNo,
			CertificationStatusDate CertificationDate
		

		FROM Msme M
		INNER JOIN MSMEBASICINFORMATION b ON (M.ZEDID=B.ZEDID)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		where (CertificationStatus=6 and Certification='Bronze') OR (CertificationStatus=16 and Certification IN ('Silver','Gold'))
		and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	
GO
/****** Object:  View [dbo].[DynamicListOfZEDRegisteredMsme]    Script Date: 9/19/2026 4:27:53 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE   VIEW [dbo].[DynamicListOfZEDRegisteredMsme] AS
SELECT M.ZedId,M.CreatedDate as RegistrationDate,
	case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Registered'			
			when CertificationStatus=1 then 'Payment Received'
			when CertificationStatus=2 then 'Evidence uploaded'
			when CertificationStatus=3 then 'DA in progress'
			when CertificationStatus=4 then 'NC raised in DA'
			when CertificationStatus=5 then 'DA Completed'
			when (certification='Bronze' and CertificationStatus=6) then 'Certified' 
			when (certification in ('Silver','Gold') and CertificationStatus=6) then 'QC Completed'
			when CertificationStatus in (7,99) then 'Rejected'
			when CertificationStatus=8 then 'SA Planned'
			when CertificationStatus=9 then 'SA Planned'
			when CertificationStatus=13 then 'SA in progress'
			when CertificationStatus=14 then 'NC raised in SA'
			when CertificationStatus=15 then 'SA Completed'
			when (certification='Silver' and CertificationStatus=16) then 'Certified' 
			when (certification='Gold' and CertificationStatus=16) then 'Certified' 
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
		end as AssessmentStatus,
		BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			CompletedOn,
		M.EnterpriseName,	PUnitName,	case when Certification is null and IsBronzePaymentDone=1 then 'Bronze'
		when Certification is null and IsSilverPaymentDone=1 then 'Silver' when Certification is null and IsGoldPaymentDone=1 then 'Gold' else Certification end as Certification,
	M.OwnerName,	 M.OrganisationTypeName,	M.EnterpriseTypee,	M.MobileNo,
	M.EmailId,	Activity,	TwoDigitActivity,	FourDigitActivity,	FiveDigitActivity,	IncorporationDate,	WhetherProdCommenced,
	B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	B.PH,	B.PanNo,	B.Address,	PStateName,	PDistrictName,
	B.CommmenceDate, B.TotalEmp, CertificationBodyUserId as AgencyId, U.UserName as AgencyName, DesktopAssessorId, UA.userName DesktopAssessorName,
	SiteAssessorId, US.UserName SiteAssessorName, CoAssessorId, UC.UserName CoAssessorName
		
	

	FROM Msme M
	inner join msmebasicinformation B on (B.ZedId=M.ZedId)
	left join MsmeCertifications P on (P.ZedId=M.ZedId)	
	LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
	LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
	LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
	LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
	left join
			(select ZedId,CertificationType,
			ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
			case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
			case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
			[ScheduledOn],
			Completed as [CompletedOn],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]			
			from 
			(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
			pivot (
			max(CreatedOn) for StatusType in (
			[BasicInfoStatus],
			[DesktopVerification],
			[ScheduledOn],
			DocVerifiAllot,
			[Completed],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]) ) as Pvt
		) PVD
		on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		WHERE UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	--where (@State is null or M.StateId=@State)
	--ORDER By M.MsmeId desc
GO
