/****** Object:  StoredProcedure [dbo].[SP_ADD_CERTIFICATION_ID]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_ADD_CERTIFICATION_ID] --'<redacted>', '<redacted>', '<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
	
)
AS
BEGIN
	
	SET NOCOUNT ON;

				DECLARE @CertificationTblId int = NULL
				select @CertificationTblId=Id from MsmeCertifications where ZedId=@ZedId and Certification=@Certification

				update SaRequirementPhotos SET SaReqCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND SaReqCertId IS NULL
				update SaRawMaterials SET SaRawCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND SaRawCertId IS NULL
				update AssessorComments SET AsCmtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND AsCmtCertId IS NULL
				update MsmeLocations SET MsmeLocCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND MsmeLocCertId IS NULL
				update ScreenshotPhotos SET SrnCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND SrnCertId IS NULL
				update MsmeRawMaterials SET MsmeRawCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND MsmeRawCertId IS NULL				
				update MsmePaymentInfo SET MsmePmtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND MsmePmtCertId IS NULL
				update MsmeSections SET SecCertId=@CertificationTblId WHERE ZedId=@ZedId AND SectionType=@Certification AND SecCertId IS NULL
				update MsmeRequirements SET ReqCertId=@CertificationTblId WHERE ZedId=@ZedId AND SectionType=@Certification AND ReqCertId IS NULL
				update MsmeOptions SET OptCertId=@CertificationTblId WHERE ZedId=@ZedId AND SectionType=@Certification AND OptCertId IS NULL
				update MsmeSubOptions SET SubCertId=@CertificationTblId WHERE ZedId=@ZedId AND SectionType=@Certification AND SubCertId IS NULL
				update MsmeEvidences SET EviCertId=@CertificationTblId WHERE ZedId=@ZedId AND SectionType=@Certification AND EviCertId IS NULL
				update MsmePhotos SET MsPtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND MsPtCertId IS NULL
				update MsmeProducts SET MsPrdCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND MsPrdCertId IS NULL
				update SaPhotos SET SaPtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND SaPtCertId IS NULL
				update SaProducts SET SaPrdCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND SaPrdCertId IS NULL
				update MsmeSelfies SET MsSelfCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND MsSelfCertId IS NULL
				update MsmeHistory SET MsHistCertId=@CertificationTblId WHERE ZedId=@ZedId AND CertificationType=@Certification AND MsHistCertId IS NULL
				update MeetingParticipants SET MeetPartCertId=@CertificationTblId WHERE ZedId=@ZedId AND CertificationType=@Certification AND MeetPartCertId IS NULL
				update Meetings SET MeetCertId=@CertificationTblId WHERE ZedId=@ZedId AND CertificationType=@Certification AND MeetCertId IS NULL
				update EsgCheckList SET EsgCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND EsgCertId IS NULL

				IF EXISTS(select * from MsmeBasicInformation where ZedId=@ZedId and ReCertificationLevel=@Certification and ReCertification>0)
				BEGIN
					update PaymentGateWayTransactions SET PmtGtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND PmtGtCertId IS NULL AND GwReClassification=1
				END
				ELSE
				BEGIN
					update PaymentGateWayTransactions SET PmtGtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND PmtGtCertId IS NULL
				END

				--select top 10 * from esgchecklist

				

	END

GO
