/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_INVOICE_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_API_FINANCE_GET_INVOICE_DETAILS] '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_INVOICE_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	--DECLARE @Etag varchar(50) = NULL
	--SELECT @Etag = JSON_VALUE(SuccessResponse, '<redacted>') FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId and ApiType='<redacted>' and StatusCode='<redacted>'

	IF NOT EXISTS (SELECT * FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId AND Certification=@Certification and ApiType='InvoiceData' and StatusCode='Created' AND ModuleName='ZED')

	AND EXISTS (SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId and UdyogAadharNo not IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	)
	BEGIN
		select TOP 1
		--convert(date,P.CreatedDate) AS Posting_Date,
		format(P.CreatedDate, 'yyyy-MM-dd') AS Posting_Date,
		NULL AS Error_Text,
		'ZED' AS Board,
		'NDIE' AS Portal,
		M.ZedId AS Login_Name,
		format(P.CreatedDate, 'yyyy-MM-dd') AS Voucher_Date,
		'NDIE' AS Location_Code,		
		--'<redacted>' AS Line_Comments,
		--ZED "Silver/Gold/Broznze" Certification Fee(Zed Id)
		CONCAT('ZED "',P.Certification,'" Certification Fee (',M.ZedId,')') AS Line_Comments,
		NULL [NABL4],
		1 AS Quantity,
		NULL AS Ledger_Name,
		0 AS Ledger_Amount,
		'ASSESSMENT FEE' AS TA_DA_LedgerName,
		NULL AS Assessor_Name,
		NULL AS Assessor_ID,
		NULL AS Assessor_Type,
		NULL AS Discipline_Name,
		CASE WHEN P.Certification='Bronze' then 'ZMS - ZED BRONZE CERTIFICATION' 
		WHEN P.Certification='Silver' then 'ZMS - ZED SILVER CERTIFICATION'
		WHEN P.Certification='Gold' then 'ZMS - ZED GOLD CERTIFICATION'
		end AS Sub_Discipline_Name,
		NULL AS Other_Discipline,
		NULL AS Assessment_Period_From,
		NULL AS Assessment_Period_To,
		NULL AS Due_Period_Start_From,
		NULL AS Due_Period_Period_To,
		NULL AS TADA_Amount,
		P.SubsidyAmount AS Other_Amount,
		NULL AS Overhead_Charges,
		NULL AS Invoice_No,
		P.TadaInvoiceNo AS TADA_Invoice_No,
		NULL AS Assessment_Type,
		NULL AS HONORARIUM_Yes_No,
		convert(varchar,P.Id) Entry_No,
		'' Etag

		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join msmepaymentinfo P on (M.ZedId=P.ZedId) 
		inner join PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and T.PaymentStatus='SUCCESS') 
		where M.ZedId=@ZedId and P.Certification=@Certification ORDER BY P.Id desc
	END

	ELSE
	BEGIN
		SELECT 
		NULL AS Posting_Date,
		NULL AS Error_Text,
		NULL AS Board,
		NULL AS Portal,
		NULL AS Login_Name,
		NULL AS Voucher_Date,
		NULL AS Location_Code,
		NULL AS Line_Comments,
		NULL [NABL4],
		NULL AS Quantity,
		NULL AS Ledger_Name,
		NULL AS Ledger_Amount,
		NULL AS TA_DA_LedgerName,
		NULL AS Assessor_Name,
		NULL AS Assessor_ID,
		NULL AS Assessor_Type,
		NULL AS Discipline_Name,
		NULL AS Sub_Discipline_Name,
		NULL AS Other_Discipline,
		NULL AS Assessment_Period_From,
		NULL AS Assessment_Period_To,
		NULL AS Due_Period_Start_From,
		NULL AS Due_Period_Period_To,
		NULL AS TA_DA_Amount,
		NULL AS Other_Amount,
		NULL AS Overhead_Charges,
		NULL AS Invoice_No,
		NULL AS TADA_Invoice_No,
		NULL AS Assessment_Type,
		NULL AS HONORARIUM_Yes_No,
		NULL AS Entry_No,
		NULL AS Etag
		WHERE 
			1=2
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_RECEIPT_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_API_FINANCE_GET_RECEIPT_DETAILS] '<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_RECEIPT_DETAILS] --'<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	--DECLARE @Etag varchar(50) = NULL
	--SELECT @Etag = JSON_VALUE(SuccessResponse, '<redacted>') FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId and ApiType='<redacted>' and StatusCode='<redacted>'

	IF NOT EXISTS (SELECT * FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId AND Certification=@Certification and ApiType='ReceiptData' and StatusCode='Created' AND ModuleName='ZED')

	AND EXISTS (SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId and UdyogAadharNo not IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	)
	BEGIN
		select top 1
		format(P.CreatedDate, 'yyyy-MM-dd') Posting_Date,
		NULL Error_Text,
		convert(varchar,T.Id) Order_ID,
		M.ZedId Reference_ID,
		'ZED' Board,
		convert(bit,CASE WHEN P.TdsDeductible='Yes' then 1 ELSE 0 END) AS TDS_Deducted,
		  SUBSTRING(
			paymentresponse,
			CHARINDEX('payment_mode=', paymentresponse) + LEN('payment_mode='),
			CHARINDEX('&', paymentresponse + '&', CHARINDEX('payment_mode=', paymentresponse)) 
			  - (CHARINDEX('payment_mode=', paymentresponse) + LEN('payment_mode='))
		  ) AS  Payment_Mode,
		P.TanNumber [TAN],
		CASE 
		WHEN P.Tds = 1.5 THEN NetPaybleTds15
		WHEN P.Tds = 7.5 THEN NetPaybleTds75
		ELSE P.ApplicantContributionAfterSubsidy 
		END AS Amount_Received,
		P.ApplicantContributionAfterSubsidy AS Invoice_1_Amount,
		NULL Invoice_2_Amount,
		CASE 
		WHEN P.Tds = 1.5 THEN Tds15
		WHEN P.Tds = 7.5 THEN Tds75
		ELSE 0
		END AS TDS_Amount,
		format(P.CreatedDate, 'yyyy-MM-dd') Payment_Date,
		SUBSTRING(
        paymentresponse,
        CHARINDEX('tracking_id=', paymentresponse) + LEN('tracking_id='),
        CHARINDEX('&', paymentresponse, CHARINDEX('tracking_id=', paymentresponse)) 
            - (CHARINDEX('tracking_id=', paymentresponse) + LEN('tracking_id='))
    ) AS UTR_No,
		FORMAT(P.CreatedDate, 'yyyy-MM-ddTHH:mm:ss') + '+05:30' AS  Created_At,
		P.TadaInvoiceNo Applied_to_invoice,
		NULL Applied_to_invoice2,
		NULL [NABL4],
		CASE WHEN P.Certification='Bronze' then 'ZMS - ZED BRONZE CERTIFICATION' 
		WHEN P.Certification='Silver' then 'ZMS - ZED SILVER CERTIFICATION'
		WHEN P.Certification='Gold' then 'ZMS - ZED GOLD CERTIFICATION' end as Sub_Discipline_Name,
		convert(varchar,P.Id) Entry_No,
		'' Etag,
		 'NDIE' PortalName

		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join msmepaymentinfo P on (M.ZedId=P.ZedId) 
		inner join PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and T.PaymentStatus='SUCCESS') 
		where M.ZedId=@ZedId and P.Certification=@Certification order by P.Id Desc
	END

	ELSE
	BEGIN
		SELECT 
		NULL AS Posting_Date,
		NULL AS Error_Text,
		NULL AS Order_ID,
		NULL AS Reference_ID,
		NULL AS Board,
		NULL AS TDS_Deducted,
		NULL AS Payment_Mode,
		NULL AS TAN,
		NULL AS Amount_Received,
		NULL AS Invoice_1_Amount,
		NULL AS Invoice_2_Amount,
		NULL AS TDS_Amount,
		NULL AS Payment_Date,
		NULL AS UTR_No,
		NULL AS Created_At,
		NULL AS Applied_to_invoice,
		NULL AS Applied_to_invoice2,
		NULL AS NABL4,
		NULL AS Sub_Discipline_Name,
		NULL AS Entry_No,
		NULL AS Etag,
		'' PortalName
		WHERE 
			1=2
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_UNIT_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_UNIT_DETAILS] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	declare @GstNumber varchar(50) = NULL
	DECLARE @TargetZedId VARCHAR(50) = NULL


	--	-- Step 1: Check live database for a valid 15-digit GST
	--SELECT TOP 1 @GstNumber = GstinNumber 
	--FROM msmepaymentinfo 
	--WHERE ZedId = @ZedId 
	--  AND LEN(TRIM(GstinNumber)) = 15 
	--  AND TRIM(GstinNumber) NOT IN ('<redacted>', '<redacted>', '<redacted>', '<redacted>')
	--ORDER BY Id DESC;

	---- Step 2: Fallback to consultant database
	--IF @GstNumber IS NULL
	--BEGIN
	--	SELECT TOP 1 @GstNumber = GstinNumber 
	--	FROM ZED_CONSULTANT.DBO.msmepaymentinfo 
	--	WHERE ZedId = @ZedId 
	--	  AND LEN(TRIM(GstinNumber)) = 15 
	--	  AND TRIM(GstinNumber) NOT IN ('<redacted>', '<redacted>', '<redacted>', '<redacted>')
	--	ORDER BY Id DESC;
	--END

	---- Step 3: Fallback to surveillance database
	--IF @GstNumber IS NULL
	--BEGIN
	--	SELECT TOP 1 @GstNumber = GstinNumber 
	--	FROM ZED_SURVEILLANCE.DBO.msmepaymentinfo 
	--	WHERE ZedId = @ZedId 
	--	  AND LEN(TRIM(GstinNumber)) = 15 
	--	  AND TRIM(GstinNumber) NOT IN ('<redacted>', '<redacted>', '<redacted>', '<redacted>')
	--	ORDER BY Id DESC;
	--END


	-- Step 1: Pool valid 15-digit GSTs from ALL databases and grab the chronologically latest one
	SELECT TOP 1 @GstNumber = GstinNumber 
	FROM (
		SELECT GstinNumber, CreatedDate 
		FROM msmepaymentinfo 
		WHERE ZedId = @ZedId 
		  AND LEN(TRIM(GstinNumber)) = 15 
		  AND TRIM(GstinNumber) NOT IN ('NO', 'NA', 'N/A', 'NOT AVAILABLE')

		UNION ALL

		SELECT GstinNumber, CreatedDate 
		FROM ZED_CONSULTANT.DBO.msmepaymentinfo 
		WHERE ZedId = @ZedId 
		  AND LEN(TRIM(GstinNumber)) = 15 
		  AND TRIM(GstinNumber) NOT IN ('NO', 'NA', 'N/A', 'NOT AVAILABLE')

		UNION ALL

		SELECT GstinNumber, CreatedDate 
		FROM ZED_SURVEILLANCE.DBO.msmepaymentinfo 
		WHERE ZedId = @ZedId 
		  AND LEN(TRIM(GstinNumber)) = 15 
		  AND TRIM(GstinNumber) NOT IN ('NO', 'NA', 'N/A', 'NOT AVAILABLE')
	) AS CombinedValidGSTs
	ORDER BY CreatedDate DESC;

	-- Step 2: Final fallback - if no 15-digit matches anywhere, grab the latest live entry regardless of length
	IF @GstNumber IS NULL
	BEGIN
		SELECT TOP 1 @GstNumber = GstinNumber 
		FROM msmepaymentinfo 
		WHERE ZedId = @ZedId 
		ORDER BY CreatedDate DESC;
	END

	---- Step 4: Final fallback - if no 15-digit matches anywhere, grab the live entry regardless of length
	--IF @GstNumber IS NULL
	--BEGIN
	--	SELECT TOP 1 @GstNumber = GstinNumber 
	--	FROM msmepaymentinfo 
	--	WHERE ZedId = @ZedId 
	--	ORDER BY Id DESC;
	--END


	IF EXISTS (SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
	)
	AND 
	NOT EXISTS (select * from ApiFinanceUnitDetailsResponse where ZedId=@ZedId and StatusCode='Created' and apitype='CustomerData')
	BEGIN
		insert into FinanTableCheck (ZedId) Values (@ZedId)
		SELECT top 1
		--GETDATE() AS [Created_At],
		FORMAT(GETDATE(), 'yyyy-MM-ddTHH:mm:ss') + '+05:30' AS [Created_At],
		NULL AS [Error_Text],
		NULL AS [Customer_Exist],
		'ZED' AS [Board],
		'NDIE' AS [Portal_Name],
		M.ZedId AS [Reference_No],
		B.UdyogAadharNo AS [Lab_ID],
		LEFT(M.PUnitName, 100) AS [Client_Name_1],
		CASE 
			WHEN LEN(M.PUnitName) > 100 THEN SUBSTRING(M.PUnitName, 101, LEN(M.PUnitName) - 100)
			ELSE NULL
		END AS [Client_Name_2],
		LEFT(M.PAddress, 100) AS [Address_1],
		CASE 
			WHEN LEN(M.PAddress) > 100 THEN SUBSTRING(M.PAddress, 101, 50)
			ELSE NULL
		END AS [Address_2],
		CASE 
			WHEN LEN(M.PAddress) > 150 THEN SUBSTRING(M.PAddress, 151, LEN(M.PAddress) - 150)
			ELSE NULL
		END AS [Address_3],
		NULL AS [City],
		M.PDistrictName AS [District],
		M.PStateName AS [State],
		'INDIA' AS [Country],
		M.PPin AS [Pincode],
		M.OwnerName AS [SPOC_Name],
		M.MobileNo AS [Mobile],
		M.EmailId AS [Email],
		NULL AS [Head_Phone_No],
		NULL AS [Organisation_Head_Email],
		PanNo AS [PAN],
		NULL AS [TAN],
		NULL AS [TAN_Based_GST],
		--case when (P.GstinNumber is null OR len(P.GstinNumber)>15) then '<redacted>' else '<redacted>' end as [GST_Customer_Type],
		--case when len(P.GstinNumber)<=15 then P.GstinNumber else NULL end AS [GSTIN],
		CASE WHEN @GstNumber IS NULL OR LEN(TRIM(@GstNumber)) != 15 OR TRIM(@GstNumber) IN ('NO', 'NA', 'N/A', 'NOT AVAILABLE')
		THEN 'Unregistered' ELSE 'Registered' END AS [GST_Customer_Type],
	
		CASE WHEN @GstNumber IS NOT NULL AND LEN(TRIM(@GstNumber)) = 15 AND TRIM(@GstNumber) NOT IN ('NO', 'NA', 'N/A', 'NOT AVAILABLE')
		 THEN @GstNumber ELSE NULL END AS [GSTIN],
		M.OwnerName AS [HOD_Name],
		NULL AS [Trade_Name],
		M.EnterpriseName AS [Legal_Name],
		NULL AS [Certificate_No],
		M.EnterpriseTypee AS [MSME_Type],
		B.UdyogAadharNo AS [MSME_Registration_No]
	FROM 
		Msme M 	
		INNER JOIN MsmeBasicInformation B ON (M.ZedId = B.ZedId) 
		INNER JOIN msmepaymentinfo P on (M.ZedId=P.ZedId)
	WHERE 
		M.ZedId = @ZedId order by P.CreatedDate desc

	END

	ELSE
	BEGIN
	SELECT 
		GETDATE() AS [Created_At],
		NULL AS [Error_Text],
		NULL AS [Customer_Exist],
		'ZED' AS [Board],
		'MSME' AS [Portal_Name],
		M.ZedId AS [Reference_No.],
		B.UdyogAadharNo AS [Lab_ID],
		LEFT(M.PUnitName, 100) AS [Client_Name_1],
		CASE 
			WHEN LEN(M.PUnitName) > 100 THEN SUBSTRING(M.PUnitName, 101, LEN(M.PUnitName) - 100)
			ELSE NULL
		END AS [Client_Name_2],
		LEFT(M.PAddress, 100) AS [Address_1],
		CASE 
			WHEN LEN(M.PAddress) > 100 THEN SUBSTRING(M.PAddress, 101, 50)
			ELSE NULL
		END AS [Address_2],
		CASE 
			WHEN LEN(M.PAddress) > 150 THEN SUBSTRING(M.PAddress, 151, LEN(M.PAddress) - 150)
			ELSE NULL
		END AS [Address_3],
		NULL AS [City],
		M.PDistrictName AS [District],
		M.PStateName AS [State],
		'INDIA' AS [Country],
		M.PPin AS [Pincode],
		M.OwnerName AS [SPOC_Name],
		M.MobileNo AS [Mobile],
		M.EmailId AS [Email],
		NULL AS [Head_Phone_No],
		NULL AS [Organisation_Head_Email],
		PanNo AS [PAN],
		NULL AS [TAN],
		NULL AS [TAN_Based_GST],
		NULL AS [GST_Customer_Type],
		NULL AS [GSTIN],
		M.OwnerName AS [HOD_Name],
		NULL AS [Trade_Name],
		M.EnterpriseName AS [Legal_Name],
		NULL AS [Certificate_No],
		M.EnterpriseTypee AS [MSME_Type],
		B.UdyogAadharNo AS [MSME_Registration_No.]
	FROM 
		Msme M 
	INNER JOIN 
		MsmeBasicInformation B 
	ON 
		M.ZedId = B.ZedId 
	WHERE 
		1=2
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_ZEDIDS_PENDING]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
--[SP_API_FINANCE_GET_ZEDIDS_PENDING] '<redacted>','<redacted>',null
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_ZEDIDS_PENDING] --'<redacted>','<redacted>',null
(
    @UserId varchar(50) = NULL,
    @RoleId varchar(50) = NULL,
    @ZedId varchar(50) = NULL,
	@MileStoneNo varchar(50) = NULL,
	@ProcessDate DATE = '2026-09-17'
)
AS
BEGIN
    SET NOCOUNT ON;
	----************* https://loginzed.msme.gov.in/Pay/RetriggerFinanceApi ************----

    -- Logic only executes when RoleId is 7
    IF (@RoleId = '7')
    BEGIN
        -- A: ApiFinanceUnitDetailsResponseerrors (Source)
        -- B: ApiFinanceUnitDetailsResponse (Target check)
        
        SELECT top 200
            A.* FROM ApiFinanceUnitDetailsResponseerrors A
        LEFT JOIN ApiFinanceUnitDetailsResponse B 
            ON A.ZedId = B.ZedId
            AND A.ApiType = B.ApiType
            AND A.Certification = B.Certification
            AND A.ModuleName = B.ModuleName
            -- Null-safe check for Milestone number
            AND (A.MileStoneNo = B.MileStoneNo OR (A.MileStoneNo IS NULL AND B.MileStoneNo IS NULL))
			--AND (ISNULL(A.MileStoneNo, '<redacted>') = ISNULL(B.MileStoneNo, '<redacted>'))
        WHERE B.ZedId IS NULL --and a.ZedId='<redacted>'
		and A.ModuleName='ZED' 
		and A.apitype='CustomerData'
		AND (@MileStoneNo IS NULL OR A.MileStoneNo = @MileStoneNo)
		AND (@ProcessDate IS NULL OR A.ProcessDate = @ProcessDate)
		and A.ModuleName is not null
		AND CHARINDEX('_', A.ZedId) = 0
        ORDER BY A.ZedId,A.ApiType;
    END
    ELSE
    BEGIN
        -- Optional: Return empty set or error if RoleId is not 7
        SELECT TOP 0 * FROM ApiFinanceUnitDetailsResponseerrors;
    END

END
GO
/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_SAVE_INVOICE_RECEIPT_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_API_FINANCE_SAVE_INVOICE_RECEIPT_DETAILS] --'<redacted>','<redacted>','<redacted>'
(
    @ZedId varchar(50),
    @TadaInvoiceNo varchar(100),
    @InvoicePath nvarchar(500),
	@DocumentType varchar(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Certification varchar(50);
    DECLARE @ModuleName varchar(50);
    DECLARE @MileStoneNo varchar(50);
	DECLARE @SubModuleName varchar(50) = NULL;

    -- 1. First Check in ZED (Primary)
    IF EXISTS (SELECT 1 FROM msmepaymentinfo WHERE TadaInvoiceNo = @TadaInvoiceNo AND ZedId = @ZedId)
    BEGIN
        SELECT TOP 1 
            @Certification = Certification,
            @ModuleName = 'ZED'
        FROM msmepaymentinfo 
        WHERE TadaInvoiceNo = @TadaInvoiceNo AND ZedId = @ZedId;

		IF EXISTS (SELECT 1 FROM msmebasicinformation WHERE ZedId = @ZedId AND Recertification = 2)
        BEGIN
            SET @SubModuleName = 'RECERTIFICATION';
        END

    END

    -- 2. Else Check in Consultancy
    ELSE IF EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.MsmePaymentInfo WHERE TadaInvoiceNo = @TadaInvoiceNo AND ZedId = @ZedId)
    BEGIN
        SELECT TOP 1 
            @Certification = Certification,
            @ModuleName = 'HANDHOLDING',
            @MileStoneNo = MileStoneNum
        FROM ZED_CONSULTANT.dbo.MsmePaymentInfo 
        WHERE TadaInvoiceNo = @TadaInvoiceNo AND ZedId = @ZedId;
    END

    -- 3. Else Check in Surveillance
    ELSE IF EXISTS (SELECT 1 FROM Zed_Surveillance.dbo.MsmePaymentInfo WHERE TadaInvoiceNo = @TadaInvoiceNo AND ZedId = @ZedId)
    BEGIN
        SELECT TOP 1 
            @Certification = Certification,
            @ModuleName = 'SURVEILLANCE'
           -- @MileStoneNo = SurveillanceType
        FROM ZED_SURVEILLANCE.dbo.MsmePaymentInfo 
        WHERE TadaInvoiceNo = @TadaInvoiceNo AND ZedId = @ZedId;

		IF EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.msmebasicinformation WHERE ZedId = @ZedId AND Resurveillance = 2)
        BEGIN
            SET @SubModuleName = 'SURVEILLANCE 2';
        END

    END

    -- 4. Final Insert if data found
    IF (@Certification IS NOT NULL)
    BEGIN
        
        IF EXISTS (SELECT 1 FROM [dbo].[MsmeInvoiceData] WHERE ZedId = @ZedId AND TadaInvoiceNo = @TadaInvoiceNo AND DocumentType = @DocumentType)
        BEGIN
            UPDATE [dbo].[MsmeInvoiceData]
            SET InvoicePath = @InvoicePath,
                UpdatedDate = GETDATE(),
                Certification = @Certification,
                ModuleName = @ModuleName,
				SubModuleName=@SubModuleName,
                MileStoneNo = @MileStoneNo
            WHERE ZedId = @ZedId AND TadaInvoiceNo = @TadaInvoiceNo AND DocumentType = @DocumentType;

            SELECT 'SUCCESS' AS Status, CONCAT(@DocumentType , ' Updated Successfully') AS ErrorMessage;
        END
        ELSE
        BEGIN
            
            INSERT INTO [dbo].[MsmeInvoiceData] 
            (ZedId, Certification, ModuleName,SubModuleName, MileStoneNo, TadaInvoiceNo, InvoicePath, CreatedDate, DocumentType, UpdatedDate)
            VALUES 
            (@ZedId, @Certification, @ModuleName,@SubModuleName, @MileStoneNo, @TadaInvoiceNo, @InvoicePath, GETDATE(), @DocumentType, GETDATE());

            SELECT 'SUCCESS' AS Status, CONCAT(@DocumentType , ' Saved Successfully') AS ErrorMessage;
        END
    END
    ELSE
    BEGIN
        SELECT 'ERROR' AS Status, 'TadaInvoiceNo Not Found' AS ErrorMessage;
    END
END
