	insert into FinanTableCheck (ZedId) Values (concat(@ZedId,'_response'))

	INSERT INTO ApiFinanceUnitDetailsResponse (ZedId, StatusCode, SuccessResponse, ErrorResponse, ApiType, Certification, ModuleName,MileStoneNo)
	VALUES (@ZedId, @StatusCode, @SuccessResponse, @ErrorResponse, @ApiType, @Certification, @ModuleName,@LatestMileStoneNo)



