-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Email varchar(500) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SELECT * FROM Msme WHERE ZedId=@ZedId AND PledgeEmailId=@Email
	
    SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId

	select
	(select convert(varchar, CreatedDate, 103) from Msme where ZedId=@ZedId) RegisteredDate, 
	isnull((select case when DaCertificateNo is not null then 'Yes' else 'No' end as BronzeCertified from MsmeCertifications where Certification='Bronze' and ZedId=@ZedId),'No') BronzeCertified, 
	isnull((select case when SaCertificateNo is not null then 'Yes' else 'No' end as BronzeCertified from MsmeCertifications where Certification='Silver' and ZedId=@ZedId),'No') SilverCertified, 
	isnull((select case when SaCertificateNo is not null then 'Yes' else 'No' end as BronzeCertified from MsmeCertifications where Certification='Gold' and ZedId=@ZedId),'No') GoldCertified 

END
