CREATE PROCEDURE [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS_BY_MULTIPLE_UDYAMS] --'<redacted>', '<redacted>'
(
	@Token varchar(500) = NULL,
	@ParametersTable  UdyamAndCertificates READONLY
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SELECT * FROM ApiClientDynamicTokens WHERE DynamicToken=@Token AND CreatedDate >= DATEADD(hour, -24, GETDATE()) and IsValid=1
	
	insert into ApiClientDynamicMultipleRequests (Token,Udyam,CertificateNo)
	select @Token,UdyamNumber,CertificationNumber from @ParametersTable

	
	 SELECT PUnitName, PStateName,PDistrictName, UdyogAadharNo UdyamNo,P.CertificationNumber CertificateNo, Certification CertificationType, 
	 convert(varchar,(convert(date,dateadd(yy,3,C.CertificationStatusDate))),103) CertificationStatusDate,
	CASE 
        WHEN DATEADD(YEAR, 3, C.CertificationStatusDate) >= GETDATE() THEN 'No'
        ELSE 'Yes'
    END AS Expired 
    FROM Msme M
    INNER JOIN MsmeBasicInformation B ON (M.ZedId = B.ZedId)
    INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId)
    INNER JOIN @ParametersTable P ON B.UdyogAadharNo = P.UdyamNumber
     AND (C.DaCertificateNo = P.CertificationNumber OR C.SaCertificateNo = P.CertificationNumber)
END



