/****** Object:  StoredProcedure [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS_BY_UDYAM]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS_BY_UDYAM] --'<redacted>', '<redacted>'
(
	@UdyamNumber varchar(50) = NULL,
	@CertificationNumber varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @ZedId varchar(50) = NULL
	DECLARE @ExpiryDate varchar(50) = NULL
	DECLARE @LatestCertificateNo varchar(100) = NULL
	DECLARE @CertificationFee DECIMAL(20, 2) = 0
	DECLARE @SubsidyAmount DECIMAL(20, 2) = 0
	DECLARE @AmountPaid DECIMAL(20, 2) = 0
	DECLARE @LastestCertification varchar(100) = NULL

	SELECT @ZedId=M.ZedId FROM Msme M Inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	WHERE B.UdyogAadharNo=@UdyamNumber and ((C.DaCertificateNo IS NOT NULL AND C.DaCertificateNo=@CertificationNumber) OR (C.SaCertificateNo IS NOT NULL AND C.SaCertificateNo=@CertificationNumber))

	SELECT TOP 1 @LatestCertificateNo=isnull(DaCertificateNo,SaCertificateNo),
	@ExpiryDate=convert(varchar,(convert(date,dateadd(yy,3,CertificationStatusDate))),103)
	FROM MsmeCertifications WHERE ZedId=@ZedId AND isnull(DaCertificateNo,SaCertificateNo) is not null ORDER BY CreatedDate DESC

	IF @CertificationNumber!=@LatestCertificateNo
	SET @ZedId='000'
	

	SELECT M.*,	convert(varchar,CertificationStatusDate,103) CertificationStatusDate,
	CASE WHEN C.CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath
	FROM Msme M Inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	WHERE M.ZedId=@ZedId and isnull(DaCertificateNo,SaCertificateNo)=@LatestCertificateNo
	
    SELECT B.*,
	CASE WHEN C.CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath
	FROM Msme M Inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	WHERE B.ZedId=@ZedId and isnull(DaCertificateNo,SaCertificateNo)=@LatestCertificateNo

	SELECT @LastestCertification=LastestCertification from MsmeBasicInformation where ZedId=@ZedId
	--SELECT @AmountPaid=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@LastestCertification and PaymentStatus='<redacted>'
	SELECT top 1 @CertificationFee=Total, @AmountPaid=ApplicantContributionAfterSubsidy from MsmePaymentInfo where ZedId=@ZedId and Certification=@LastestCertification order by id
	SET @SubsidyAmount = @CertificationFee-@AmountPaid

	--select
	--(select convert(varchar, CreatedDate, 103) from Msme where ZedId=@ZedId) RegisteredDate, 
	--isnull((select case when DaCertificateNo is not null then '<redacted>' else '<redacted>' end as BronzeCertified from MsmeCertifications where Certification='<redacted>' and ZedId=@ZedId),'<redacted>') BronzeCertified, 
	--isnull((select case when SaCertificateNo is not null then '<redacted>' else '<redacted>' end as BronzeCertified from MsmeCertifications where Certification='<redacted>' and ZedId=@ZedId),'<redacted>') SilverCertified, 
	--isnull((select case when SaCertificateNo is not null then '<redacted>' else '<redacted>' end as BronzeCertified from MsmeCertifications where Certification='<redacted>' and ZedId=@ZedId),'<redacted>') GoldCertified,
	--@ExpiryDate AS ExpiryDate

	 select convert(varchar, CreatedDate, 103) RegisteredDate,Bronze BronzeCertified,Silver SilverCertified,Gold GoldCertified,@ExpiryDate AS ExpiryDate,
	 @CertificationFee CertificationFee, @SubsidyAmount SubsidyAmount, @AmountPaid AmountPaid
	 from Msme M 
	LEFT JOIN
 
	(select ZedId, case when Bronze is not null and Silver is null and Gold is null then 'Yes' else 'No' end as Bronze,
	case when Silver is not null and Gold is null then 'Yes' else 'No' end as Silver,
	case when Gold is not null then 'Yes' else 'No' end as Gold
	from 
	(
	select ZedId,Certification,isnull(DaCertificateNo,SaCertificateNo) CertificateNo from MsmeCertifications where ZedId=@ZedId
	) X

	pivot 
	(
	max(CertificateNo) for certification in ([Bronze],[Silver],[Gold])
	) p
	) Y
	ON (M.ZedId=Y.ZedId)
	where M.ZedId=@ZedId

END
GO
