/****** Object:  StoredProcedure [dbo].[SP_API_GET_LIST_OF_CERTIFIED_MSME]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_LIST_OF_CERTIFIED_MSME] --null,null,null,'<redacted>',1,10
(
	  
	
	@CertificationType varchar(50) = NULL,
	@State varchar(100) = NULL,
	@MsmeSize varchar(50) = NULL,
	@Sector varchar(2000) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 200
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;
		
		IF @NoOfRecords>200 
		set @NoOfRecords=200

		SELECT 
		ROW_NUMBER() OVER(order by P.certificationstatusdate desc) as Sno,
		M.PUnitName EnterpriseName,
		TwoDigitActivity,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,PStateName StateName,M.EnterpriseTypee,Certification
			
		FROM Msme M
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		INNER join MsmeCertifications P on (P.ZedId=M.ZedId )
		WHERE CertificationStatus in (6,16)
		AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		AND (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
		AND UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		ORDER By P.certificationstatusdate desc 	
		offset ((@PageNo-1) * @NoOfRecords) rows fetch next @NoOfRecords rows only


		SELECT count(*) as TotalCounts, @PageNo PageNo, @NoOfRecords NoOfRecords
		FROM Msme M
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		INNER join MsmeCertifications P on (P.ZedId=M.ZedId )
		WHERE CertificationStatus in (6,16)
		AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		AND (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
		AND UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		
		
	
END


GO
/****** Object:  StoredProcedure [dbo].[SP_API_GET_STATE_CERTIFIED_UNIT_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_STATE_CERTIFIED_UNIT_DETAILS] --'<redacted>', 1, 1000, '<redacted>'
(
	@DynamicToken varchar(500),  
	@PageNo INT = 1,
    @PageSize INT = 1000,
	@ApplicationType varchar(50)  -- Certification/Handholding
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SELECT * FROM ApiClientDynamicTokens WHERE DynamicToken=@DynamicToken AND CreatedDate >= DATEADD(hour, -24, GETDATE()) and IsValid=1
	
	insert into ApiClientDynamicRequests (Token,ZedId,EmailId)
	values (@DynamicToken,@PageNo,@PageSize)

	IF @ApplicationType IS NULL OR @ApplicationType = '' OR @ApplicationType NOT IN ('Certification', 'Handholding')
	BEGIN
		SELECT 400 StatusCode, 'Application Type must be either ''Certification'' or ''Handholding''.' StatusMessage
		RETURN; -- Stops execution immediately
	END


	IF @PageNo IS NULL 
    SET @PageNo = 1;

    IF @PageSize IS NULL
    SET @PageSize = 100;
    
	IF @PageSize>1000 
	BEGIN
		SELECT 400 StatusCode, 'Page Size should be less than 1000.' StatusMessage
		SET @PageSize=1
	END
    
	ELSE
	BEGIN
		SELECT 200 StatusCode, 'Success.' StatusMessage
	END 


	IF @ApplicationType = 'Certification'
	BEGIN
		SELECT 
		P.Id as RefId, 
		M.EnterpriseName,
		B.UdyogAadharNo AS UdyamNumber,
		PlantIdNo PlantId,
		@ApplicationType Applicationtype,
		FORMAT(P.CreatedDate, 'dd/MM/yyyy') ApplicationPaymentDate,
		
		C.SaCertificateNo AS CertificateNumber,
		P.Certification AS CertificationType,
		case when C.CertificationStatus in (16,99) then FORMAT(C.CertificationStatusDate, 'dd/MM/yyyy') 
		else NULL end 		
		AS CertifiedDate,
		CASE 
			WHEN C.CertificationStatus = 16 THEN FORMAT(DATEADD(year, 3, C.CertificationStatusDate), 'dd/MM/yyyy')
			ELSE '' 
		END AS CertificateExpiryDate,
		'' MileStone,
		PStateName AS State,
		PDistrictName AS District,
		concat(M.PAddress, M.PPin) as PlantAddress,
		--CASE WHEN CertificationStatus=16 THEN '<redacted>' WHEN CertificationStatus=99 THEN '<redacted>' 
		--END AS ApplicationStatus,

		--CASE 
		--WHEN C.CertificationStatus IS NULL THEN '<redacted>'
		--WHEN CertificationStatus=1 THEN '<redacted>' --
		--WHEN CertificationStatus=2 THEN '<redacted>'
		--WHEN CertificationStatus in (3,5) THEN '<redacted>' --
		--WHEN CertificationStatus=6 THEN '<redacted>'
		--WHEN CertificationStatus=8 THEN '<redacted>'
		--WHEN CertificationStatus=9 THEN '<redacted>'
		--WHEN CertificationStatus in (13,14,15,17) THEN '<redacted>'
		--WHEN CertificationStatus=16 THEN '<redacted>'--
		--WHEN CertificationStatus=99 THEN '<redacted>'--
		--END AS ApplicationStatus,

		--Assessment inprogress
		CASE 
		WHEN (CertificationStatus=1 OR C.CertificationStatus IS NULL)  THEN 'Payment done By MSME' --
		WHEN CertificationStatus in (2,3,5,6,8,9,13,14,15,17) THEN 'Assessment in progress'
		WHEN CertificationStatus=16 THEN 'Certified'--
		WHEN CertificationStatus=99 THEN 'Rejected'--
		END AS ApplicationStatus,



		CAST(ROUND(ISNULL(P.Total, 0), 0) AS DECIMAL(18,2)) AS ApplicationFee, 
		ISNULL(P.UseCoupon,'No') JoiningReward,
	  	ISNULL(P.SubsidyPercentage, 0) AS CentralGovernmentSubsidyPercentage, 
		ISNULL(P.StateSubsidyPercentage, 0) AS AndhraPradeshGovernmentSubsidyPercentage, 
		CAST(ISNULL(P.StateContributionAfterSubsidy, 0) AS DECIMAL(18,2)) AS AndhraPradeshGovernmentSubsidyAmount
		--CAST(ISNULL(P.ApplicantContributionAfterSubsidy, 0) AS DECIMAL(18,2)) AS FinalAmountPaid 

		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)		
		INNER join MsmePaymentInfo P on (M.ZedId=P.ZedId)
		LEFT join MsmeCertifications C on (P.ZedId=C.ZedId  and C.Certification=P.Certification)
		where PStateName='ANDHRA PRADESH' AND P.Certification!='Bronze'
		and convert(date,P.CreatedDate)>='2026-04-01'
		and B.ReCertification=0
		and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		order by PStateName,PDistrictName,ApplicationPaymentDate desc
		OFFSET ((@PageNo - 1) * @PageSize) ROWS FETCH NEXT @PageSize ROWS ONLY


		SELECT COUNT(*) AS TotalCount, @PageNo AS PageNo, @PageSize AS PageSize
		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		INNER join MsmePaymentInfo P on (M.ZedId=P.ZedId)
		LEFT join MsmeCertifications C on (P.ZedId=C.ZedId and C.Certification=P.Certification)		
		where PStateName='ANDHRA PRADESH' AND P.Certification!='Bronze'
		and convert(date,P.CreatedDate)>='2026-04-01'
		and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		--and CertificationStatus in (16,100)
	END

	ELSE IF @ApplicationType = 'Handholding'
	BEGIN
	SELECT 
		P.Id as RefId, 
		M.EnterpriseName,
		B.UdyogAadharNo AS UdyamNumber,
		PlantIdNo PlantId,
		@ApplicationType Applicationtype,
		FORMAT(P.CreatedDate, 'dd/MM/yyyy') ApplicationPaymentDate,
		
		'' AS CertificateNumber,
		C.Certification AS CertificationType,
		'' CertifiedDate,
		'' CertificateExpiryDate,
		concat('M',NcCount) MileStone,
		PStateName AS State,
		PDistrictName AS District,
		concat(M.PAddress, M.PPin) as PlantAddress,
		
		--CASE 
		--WHEN CertificationStatus=6 THEN '<redacted>'   --
		--WHEN CertificationStatus=8 THEN '<redacted>'
		--WHEN CertificationStatus=9 THEN '<redacted>'  --
		--WHEN CertificationStatus in (13,14,15) THEN '<redacted>'
		--WHEN CertificationStatus=16 THEN '<redacted>'  --
		--WHEN CertificationStatus=100 THEN '<redacted>'
		--END AS ApplicationStatus,

		CASE 
		WHEN CertificationStatus=6 THEN 'Payment done By MSME'   --
		WHEN CertificationStatus in (8,9,13,14,15) THEN 'Handholding In progress'
		WHEN CertificationStatus in (16,100) THEN 'Handholding Completed'  --
		END AS ApplicationStatus,

		CAST(ROUND(ISNULL(P.Total, 0), 0) AS DECIMAL(18,2)) AS ApplicationFee, 
		ISNULL(P.UseCoupon,'No') JoiningReward,
	  	ISNULL(P.SubsidyPercentage, 0) AS CentralGovernmentSubsidyPercentage, 
		ISNULL(P.StateSubsidyPercentage, 0) AS AndhraPradeshGovernmentSubsidyPercentage, 
		CAST(ISNULL(P.StateContributionAfterSubsidy, 0) AS DECIMAL(18,2)) AS AndhraPradeshGovernmentSubsidyAmount
		--CAST(ISNULL(P.ApplicantContributionAfterSubsidy, 0) AS DECIMAL(18,2)) AS FinalAmountPaid 

		from ZED_CONSULTANT.DBO.Msme M inner join ZED_CONSULTANT.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId)		
		inner join ZED_CONSULTANT.DBO.MsmePaymentInfo P on (M.ZedId=P.ZedId )
		inner join ZED_CONSULTANT.DBO.MsmeCertifications C on (P.ZedId=C.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum)
		where PStateName='ANDHRA PRADESH' AND P.Certification!='Bronze'
		--and convert(date,P.CreatedDate)>='<redacted>'
		and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		and P.ZedId in (select ZedId from ZED_CONSULTANT.DBO.StateHandholdingPaymentDates where MileStoneNum=1)
		order by PStateName,PDistrictName,ApplicationPaymentDate desc
		OFFSET ((@PageNo - 1) * @PageSize) ROWS FETCH NEXT @PageSize ROWS ONLY


		SELECT COUNT(*) AS TotalCount, @PageNo AS PageNo, @PageSize AS PageSize
		from ZED_CONSULTANT.DBO.Msme M inner join ZED_CONSULTANT.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join ZED_CONSULTANT.DBO.MsmePaymentInfo P on (M.ZedId=P.ZedId )
		inner join ZED_CONSULTANT.DBO.MsmeCertifications C on (P.ZedId=C.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum)
		where PStateName='ANDHRA PRADESH' AND P.Certification!='Bronze'
		--and convert(date,P.CreatedDate)>='<redacted>'
		and P.ZedId in (select ZedId from ZED_CONSULTANT.DBO.StateHandholdingPaymentDates where MileStoneNum=1)
		and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		--and CertificationStatus in (16,100)
	END
		

END

