-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_KEY_MAKER] --'<redacted>'
(
	@ClientName varchar(50) = NULL
)
AS
BEGIN
	
	DECLARE @ApiKey varchar(100) = NULL
	DECLARE @ClientId varchar(50) = NULL

	SET NOCOUNT ON;

	SET @ApiKey=left(concat((REPLACE(NEWID(),'-','')),(REPLACE(NEWID(),'-','')),(REPLACE(NEWID(),'-',''))),75)
	SELECT @ClientId = MAX(ClientId)+1 from ApiClientTokens where ClientId is not null

	IF(select count(*) from ApiClientTokens where token=@ApiKey)=0
	BEGIN
		insert into ApiClientTokens (Client,Token,CreatedDate,BaseUrl,ReverseToken,ClientId)
		values (@ClientName,@ApiKey,getdate(),concat('https://loginzed.msme.gov.in/Msme/GetStateCertificationsByPage?token=',@ApiKey,'&udyamNumber=UDYAM-MH-23-0006117&certificationNumber=02052022_002612'),1,@ClientId)
	END
	ELSE
	SELECT 'ID ALREADY EXISTS'
END

