/****** Object:  StoredProcedure [dbo].[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--UDYAM-OD-07-0000476   UDYAM-TN-03-0034313  UDYAM-BR-26-0030922
--[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO] '<redacted>', '<redacted>', null,'<redacted>'
CREATE PROCEDURE [dbo].[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO] --'<redacted>', '<redacted>', null,'<redacted>'
(
	@Token varchar(500) = NULL,
	@UdyogAadharNo varchar(50) = NULL,
	@ClientRequestId varchar(100) = NULL,
	@IpAddress varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF NOT EXISTS (SELECT * FROM ApiClientTokens WHERE Token=@Token)
	BEGIN
		SELECT 401 as Status, 'Invalid Token.' AS ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken, CreatedDate,Description,ApiDetails)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Invalid Token.','Fetch Existing Units with UdyamNumber')
	END
	ELSE IF NOT EXISTS (Select  1 from MsmeBasicInformation where UdyogAadharNo=@UdyogAadharNo)
	BEGIN
		SELECT 404 as Status, 'Udyam Number Not found' ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,Description,ApiDetails)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Udyam Number Not found.','Fetch Existing Units with UdyamNumber')
	END

	ELSE
	BEGIN
		SELECT 200 AS Status, 'Success.' AS ErrorMessage 

		
		SELECT 
	@ClientRequestId RequestId,
    M.ZedId,
	ISNULL(C.Certification,'Pledge') Certification, 
    FORMAT(ISNULL(P.PaymentDate,M.CreatedDate), 'dd/MM/yyyy') as Date,
    @UdyogAadharNo UdyogAadharNo, 
	PlantIdNo PlantId, 
	CONCAT('ZED_',isnull(C.Id,M.MsmeId)) RefId,
	CASE 
				WHEN (ISNULL(C.Certification,'Pledge')) = 'Bronze' THEN 'Bronze Certified'
				WHEN (ISNULL(C.Certification,'Pledge')) = 'Silver' THEN 'Silver Certified'
				WHEN (ISNULL(C.Certification,'Pledge')) = 'Gold' THEN 'Gold Certified'
				ELSE 'Pledge Accepted' 
			END AS ApplicationStatus,
	CONCAT(ISNULL(C.Certification,'Pledge'),'_Certification_',isnull(C.Id,M.MsmeId)) FileName
   
FROM 
    Msme M 
INNER JOIN 
    MsmeBasicInformation B 
    ON M.ZedId = B.ZedId
LEFT JOIN 
    (
        SELECT 
            Id,
            ZedId,
            Certification,
            CertificationStatus 
        FROM 
            (
                SELECT 
                    ROW_NUMBER() OVER (PARTITION BY ZedId ORDER BY CertificationStatusDate DESC) AS RankOrder, 
                    Id,
                    ZedId,
                    Certification,
                    CertificationStatus 
                FROM MsmeCertifications  
                WHERE 
                    (CertificationStatus = 6 AND Certification = 'Bronze') 
                    OR (CertificationStatus = 16 AND Certification IN ('Silver', 'Gold'))
            ) A 
        WHERE 
            RankOrder = 1
    ) C 
    ON M.ZedId = C.ZedId
LEFT JOIN 
    (
        SELECT 
            ZedId,
            Certification,
            CreatedDate AS PaymentDate 
        FROM 
            (
                SELECT 
                    ROW_NUMBER() OVER (PARTITION BY ZedId, Certification ORDER BY CreatedDate DESC) AS Rank2, 
                    ZedId,
                    Certification,
                    CreatedDate 
                FROM MsmePaymentInfo
            ) A 
        WHERE 
            Rank2 = 1
    ) P 
    ON (C.ZedId = P.ZedId AND C.Certification = P.Certification)
WHERE 
    B.UdyogAadharNo = @UdyogAadharNo
	order by zedid




		INSERT INTO UdyamiAPIRequests (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,ApiDetails)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Fetch Existing Units with UdyamNumber')
	END

END
GO
/****** Object:  StoredProcedure [dbo].[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO_AND_ZEDID]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--UDYAM-OD-07-0000476   UDYAM-TN-03-0034313  UDYAM-BR-26-0030922
--[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO_AND_ZEDID] '<redacted>', '<redacted>', '<redacted>', NULL,'<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO_AND_ZEDID] 
(
	@Token varchar(500) = NULL,
	@UdyogAadharNo varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@ClientRequestId varchar(100) = NULL,
	@IpAddress varchar(100) = NULL,
	@FileId varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF NOT EXISTS (SELECT * FROM ApiClientTokens WHERE Token=@Token)
	BEGIN
		SELECT 401 as Status, 'Invalid Token.' AS ErrorMessage

		INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken, CreatedDate,Description,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Invalid Token.','Fetch Details with Udyam and ZedId',@ZedId)
	END

	ELSE IF NOT EXISTS (Select 1 from MsmeBasicInformation where UdyogAadharNo=@UdyogAadharNo and ZedId=@ZedId)
	BEGIN
		SELECT 404 as Status, 'Udyam Number Or ZedId Not found' ErrorMessage

		INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,Description,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Udyam Number Or ZedId Not found.','Fetch Details with Udyam and ZedId', @ZedId)
	END

	ELSE IF EXISTS (SELECT * FROM MsmeCertifications WHERE ZedId=@ZedId AND CONCAT('ZED_', Id)=@FileId)
	BEGIN
		SELECT 200 AS Status, 'Success.' AS ErrorMessage

		SELECT @ClientRequestId RequestId,UdyogAadharNo,PlantIdNo PlantId,M.ZedId, ISNULL(Certification,'Pledge') Certification,		
			FORMAT(CASE WHEN CertificationStatusDate IS NOT NULL THEN DATEADD(YEAR, 3, CertificationStatusDate) ELSE '' END, 'dd-MM-yyyy') as ValidUpto,		
			'.pdf' FileExtension, '' Base64File,
			concat('/',CertPath,'/',@ZedId,'/Pledge.pdf') PledgePath,
			concat('/',CertPath,'/DA/',@ZedId,'/Bronze.pdf') BronzePath,
			concat('/',CertPath,'/SA/',@ZedId,'/Silver.pdf') SilverPath,
			concat('/',CertPath,'/SA/',@ZedId,'/Gold.pdf') GoldPath,
			concat(ISNULL(Certification,'Pledge'),'_Certification_',isnull(C.Id,M.MsmeId)) FileName
		FROM 
		Msme M INNER JOIN MsmeBasicInformation B ON (M.ZedId = B.ZedId)
		LEFT JOIN 
		(SELECT Id,ZedId,Certification,CertificationStatus,CertificationStatusDate,CertPath FROM 
					(SELECT ROW_NUMBER() OVER (PARTITION BY ZedId ORDER BY CertificationStatusDate DESC) AS RankOrder, 
							Id,	ZedId, Certification, CertificationStatus,	CertificationStatusDate,
							CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END AS CertPath
					FROM MsmeCertifications  
						WHERE (CertificationStatus = 6 AND Certification = 'Bronze') OR (CertificationStatus = 16 AND Certification IN ('Silver', 'Gold'))
					) A 
					WHERE RankOrder = 1
		) C ON (M.ZedId = C.ZedId)
		WHERE B.UdyogAadharNo=@UdyogAadharNo AND M.ZedId=@ZedId AND CONCAT('ZED_', C.Id)=@FileId

		INSERT INTO UdyamiAPIRequests (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Fetch Details with Udyam and ZedId',@ZedId)
	END

	ELSE IF EXISTS (SELECT * FROM Msme WHERE ZedId=@ZedId AND CONCAT('ZED_', MsmeId)=@FileId)
	BEGIN
		SELECT 200 AS Status, 'Success.' AS ErrorMessage

		SELECT @ClientRequestId RequestId,UdyogAadharNo,PlantIdNo PlantId,M.ZedId, ISNULL(Certification,'Pledge') Certification,		
			'' as ValidUpto,		
			'.pdf' FileExtension,
			'' Base64File,
		
			concat('/',CASE WHEN CreatedDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END,'/',@ZedId,'/Pledge.pdf') PledgePath,
			'' BronzePath,
			'' SilverPath,
			'' GoldPath,
			concat(ISNULL(Certification,'Pledge'),'_Certification_',isnull(C.Id,M.MsmeId)) FileName
		FROM 
		Msme M INNER JOIN MsmeBasicInformation B ON (M.ZedId = B.ZedId)
		LEFT JOIN 
		(SELECT NULL Id,NULL ZedId,NULL Certification,NULL CertificationStatus,NULL CertificationStatusDate FROM MsmeCertifications
		) C ON M.ZedId = C.ZedId
		WHERE B.UdyogAadharNo=@UdyogAadharNo AND M.ZedId=@ZedId AND CONCAT('ZED_', M.MsmeId)=@FileId

		INSERT INTO UdyamiAPIRequests (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Fetch Details with Udyam and ZedId',@ZedId)
	END

	ELSE
	BEGIN
		 SELECT 404 as Status, 'File Id Not found' ErrorMessage

		 INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,Description,ApiDetails,ZedId)
		 VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'File Id Not found.','Fetch Details with Udyam and ZedId', @ZedId)
	END

END
GO
