-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--UDYAM-OD-07-0000476   UDYAM-TN-03-0034313  UDYAM-BR-26-0030922
--[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO_AND_ZEDID] '<redacted>', '<redacted>', '<redacted>', NULL,'<redacted>'
create PROCEDURE [dbo].[SP_API_MSME_GET_CERTIFICATIONS_BY_UDYAM_NO_AND_ZEDID_duplicate] --'<redacted>', '<redacted>', '<redacted>', NULL,'<redacted>'
(
	@Token varchar(500) = NULL,
	@UdyogAadharNo varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@ClientRequestId varchar(100) = NULL,
	@IpAddress varchar(100) = NULL,
	@FileId varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	--DECLARE @ExpiryDate varchar(50) = NULL

	IF NOT EXISTS (SELECT * FROM ApiClientTokens WHERE Token=@Token)
	BEGIN
		SELECT 401 as Status, 'Invalid Token.' AS ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken, CreatedDate,Description,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Invalid Token.','Fetch Details with Udyam and ZedId',@ZedId)
	END
	ELSE IF NOT EXISTS (Select 1 from MsmeBasicInformation where UdyogAadharNo=@UdyogAadharNo and ZedId=@ZedId)
	BEGIN
		SELECT 404 as Status, 'Udyam Number Or ZedId Not found' ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,Description,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Udyam Number Or ZedId Not found.','Fetch Details with Udyam and ZedId', @ZedId)
	END

	ELSE
	BEGIN

		select 200 AS Status, 'Success.' AS ErrorMessage	
		select @ClientRequestId RequestId,UdyogAadharNo,PlantId,ZedId, ISNULL(Certification,'Pledge') Certification,		
		FORMAT(CASE WHEN CertificationStatusDate IS NOT NULL THEN DATEADD(YEAR, 3, CertificationStatusDate) ELSE '' END, 'dd-MM-yyyy') as ValidUpto,		
		'.pdf' FileExtension, '' Base64File,
		concat('/Certificates/DA/',@ZedId,'/Bronze.pdf') BronzePath,
		concat('/Certificates/SA/',@ZedId,'/Silver.pdf') SilverPath,
		concat('/Certificates/SA/',@ZedId,'/Gold.pdf') GoldPath,
		concat(ISNULL(Certification,'Pledge'),'_Certification_',isnull(Id,MsmeId)) FileName
		from (
		SELECT C.Id, M.MsmeId,M.ZedId,C.Certification,CertificationStatusDate,M.CreatedDate,CertificationStatus,UdyogAadharNo,M.PlantIdNo PlantId,  RANK() OVER(Partition By M.ZedId ORDER BY CertificationStatusDate desc) RankOrder FROM Msme M 
		INNER JOIN MsmeBasicInformation B ON (M.ZedId=B.ZedId)
		LEFT JOIN MsmeCertifications C on (M.ZedId=C.ZedId)
		where B.UdyogAadharNo=@UdyogAadharNo and C.ZedId=@ZedId and B.ZedId=@ZedId and (CertificationStatus IS NULL OR (CertificationStatus=6 AND Certification='Bronze') OR (CertificationStatus=16 AND Certification in ('Silver','Gold')))
	    ) A where RankOrder=1

		INSERT INTO UdyamiAPIRequests (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,ApiDetails,ZedId)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Fetch Details with Udyam and ZedId',@ZedId)
	END

END
