		select @ClientRequestId RequestId, ZedId, ISNULL(Certification,'Pledge') Certification, 
		FORMAT(ISNULL(CertificationStatusDate,CreatedDate), 'dd/mm/yyyy') as Date,
		--FORMAT(ISNULL(CertificationStatusDate,CreatedDate), '<redacted>') as Date,
		@UdyogAadharNo UdyogAadharNo, PlantIdNo PlantId, concat('ZED_',isnull(Id,MsmeId)) RefId,
		CASE 
		WHEN (ISNULL(Certification,'Pledge')) = 'Bronze' THEN 'Bronze Certified'
		WHEN (ISNULL(Certification,'Pledge')) = 'Silver' THEN 'Silver Certified'
		WHEN (ISNULL(Certification,'Pledge')) = 'Gold' THEN 'Gold Certified'
		ELSE 'Pledge Accepted' end ApplicationStatus,
		concat(ISNULL(Certification,'Pledge'),'_Certification_',isnull(Id,MsmeId)) FileName
		from (
		SELECT M.ZedId,C.Certification,CertificationStatusDate,M.CreatedDate,CertificationStatus,PlantIdNo,M.MsmeId,C.Id, RANK() OVER(Partition By M.ZedId ORDER BY CertificationStatusDate desc) RankOrder FROM Msme M 
		INNER JOIN MsmeBasicInformation B ON (M.ZedId=B.ZedId)
		LEFT JOIN MsmeCertifications C on (M.ZedId=C.ZedId)
		where B.UdyogAadharNo=@UdyogAadharNo and (CertificationStatus IS NULL OR (CertificationStatus=6 AND Certification='Bronze') OR (CertificationStatus=16 AND Certification in ('Silver','Gold')))
	    ) A where RankOrder=1

		INSERT INTO UdyamiAPIRequests (RequestId,IpAddress,UdyogAadharNo,ClientToken,CreatedDate,ApiDetails)
		VALUES (@ClientRequestId,@IpAddress,@UdyogAadharNo,@Token,getdate(),'Fetch Existing Units with UdyamNumber')
	END

END
GO
