CREATE PROCEDURE [dbo].[SP_API_MSME_INSERT_UDYAM_DETAILS] --'<redacted>', '<redacted>'
(
	@MsmeId	varchar(50)	= NULL,
	@ZedId	varchar(50)	= NULL,
	@StateId	varchar(50)	= NULL,
	@StateName	varchar(100)	= NULL,
	@DistrictId	varchar(50)	= NULL,
	@DistrictName	varchar(100)	= NULL,
	@OwnerName	varchar(200)	= NULL,
	@EnterpriseName	varchar(250)	= NULL,
	@OrganisationType	varchar(50)	= NULL,
	@OrganisationTypeName	varchar(50)	= NULL,
	@EnterpriseType	varchar(50)	= NULL,
	@EnterpriseTypee	varchar(50)	= NULL,
	@MobileNo	varchar(50)	= NULL,
	@EmailId	varchar(200)	= NULL,
	@PledgeEmailId	varchar(200)	= NULL,
	@ApplicationId	varchar(50)	= NULL,
	@PFlat	varchar(200)	= NULL,
	@PBuilding	varchar(200)	= NULL,
	@PRoad	varchar(200)	= NULL,
	@PArea	varchar(200)	= NULL,
	@PCity	varchar(200)	= NULL,
	@PPin	varchar(50)	= NULL,
	@PStateId	varchar(50)	= NULL,
	@PStateName	varchar(100)	= NULL,
	@PLgDistrictCode	varchar(50)	= NULL,
	@PDistrictName	varchar(100)	= NULL,
	@PPlantDetailId	varchar(50)	= NULL,
	@Activity	varchar(100)	= NULL,
	@TwoDigitActivity	varchar(2000)	= NULL,
	@FourDigitActivity	varchar(2000)	= NULL,
	@FiveDigitActivity	varchar(2000)	= NULL,
	@ActivityDetailId	varchar(50)	= NULL,
	@UdyogAadharNo	varchar(50)	= NULL,
	@SocialCategory	varchar(50)	= NULL,
	@SocialCategoryName	varchar(50)	= NULL,
	@Gender	varchar(50)	= NULL,
	@PH	varchar(50)	= NULL,
	@PanNo	varchar(50)	= NULL,
	@Address	varchar(max)	= NULL,
	@MajorActivity	varchar(50)	= NULL,
	@MajorActivityName	varchar(50)	= NULL,
	@CommmenceDate	varchar(50)	= NULL,	
	@LgDistrictCode	varchar(50)	= NULL,
	@Pincode	varchar(50)	= NULL,
	@PreviousEMType	varchar(50)	= NULL,
	@PreviousEMNumber	varchar(50)	= NULL,
	@TotalEmp	varchar(50)	= NULL,
	@InvestmentCost	varchar(50)	= NULL,
	@DicName	varchar(50)	= NULL,
	@AppliedDate varchar(50)	= NULL,
	@Password varchar(50) = NULL,
	@IpAddress varchar(50) = NULL,
	@PAddress varchar(2000) = NULL,
	@UamNumber varchar(50) = NULL,
	@IncorporationDate varchar(50) = NULL,
	@WhetherProdCommenced varchar(50) = NULL,
	@PlantIdNo varchar(50) = NULL,
	@UnitName varchar(500) = NULL,
	@UnitIdNo varchar(50) = NULL,
	@RegistrationFrom varchar(50) = NULL,
	@ZedCertified  bit = NULL,
	@QrCodeNo varchar(50) = NULL,
	@Token varchar(500),
	@ClientRequestId varchar(500),
	@ClientReqTimeStamp varchar(500)
	
)
AS
BEGIN
	  
	SET NOCOUNT ON;

	DECLARE @ClientId varchar(50) = NULL
	SELECT @RegistrationFrom=Client,@ClientId=ClientId FROM ApiClientTokens where Token=@Token

	----------CHECK THE TOKEN IS VALID OR NOT--------
	IF NOT EXISTS (SELECT * FROM ApiClientTokens WHERE Token=@Token)
	BEGIN
		SELECT 401 as Status, 'Invalid Token.' AS ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,Description, ApiDetails)
		VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),'Invalid Token.','Insertion API')
	END
	ELSE IF (@EmailId IS NULL OR @EmailId='')
	BEGIN
		SELECT 400 as Status, 'Email Id Required.' ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,Description,ApiDetails)
		VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),'Email Id Required.','Insertion API')
	END
	
	----TO CHECK IF THE PLANT ID ALREADY EXISTS-----
	ELSE IF EXISTS (SELECT * FROM MsmeBasicInformation B inner join Msme M on (B.ZedId=M.ZedId) Where UdyogAadharNo=@UdyogAadharNo AND PlantIdNo=@PlantIdNo)
	BEGIN
		SELECT 400 Status, concat('Plant (' ,@PlantIdNo,') Already registered.') ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,Description,ApiDetails)
		VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),concat('Plant (' ,@PlantIdNo,') Already registered.'),'Insertion API')
	END
		------TO CHECK IF TWO DIGIT ACTIVITY IS EXISTS OR NOT-------------
	ELSE IF NOT EXISTS (SELECT * FROM Sectors WHERE @TwoDigitActivity LIKE SectorCode + '%')
	BEGIN
		SELECT 400 as Status, 'Currently this scheme is not applicable for the selected plant activity.' AS ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,Description,ApiDetails)
		VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),'Currently this scheme is not applicable for the selected plant activity.','Insertion API')
	END
	 

	 -------- TO CHECK THE EMAIL IS ALREADY REGISTERED OR NOT ------------
    
    -- 1. Check in Users table (Local)
    ELSE IF EXISTS (SELECT 1 FROM Users WHERE Email = @EmailId AND RoleId != 5)
    BEGIN
        SELECT 400 as Status, 'Email ID already registered as Assessor.' AS ErrorMessage
        INSERT INTO UdyamiAPIRequestFailures (RequestId, RequestTimeStamp, UdyogAadharNo, PlantId, EmailId, MobileNo, ClientToken, ClientId, CreatedDate, Description, ApiDetails)
        VALUES (@ClientRequestId, @ClientReqTimeStamp, @UdyogAadharNo, @PlantIdNo, @EmailId, @MobileNo, @Token, @ClientId, getdate(), 'Email ID already registered as Assessor.', 'Insertion API')
    END

    -- 2. Check in Zed Consultant Database
    ELSE IF EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.users WHERE Email = @EmailId AND RoleId != 5)
    BEGIN
        SELECT 400 as Status, 'Email ID already registered as Consultant.' AS ErrorMessage
        INSERT INTO UdyamiAPIRequestFailures (RequestId, RequestTimeStamp, UdyogAadharNo, PlantId, EmailId, MobileNo, ClientToken, ClientId, CreatedDate, Description, ApiDetails)
        VALUES (@ClientRequestId, @ClientReqTimeStamp, @UdyogAadharNo, @PlantIdNo, @EmailId, @MobileNo, @Token, @ClientId, getdate(), 'Email ID already registered as Consultant.', 'Insertion API')
    END

    -- 3. Check in Training Program
    ELSE IF EXISTS (SELECT 1 FROM ZED_CENTER_AUDIT_V2.dbo.candidates WHERE EmailId = @EmailId)
    BEGIN
        SELECT 400 as Status, 'Email ID already registered in Training Program.' AS ErrorMessage
        INSERT INTO UdyamiAPIRequestFailures (RequestId, RequestTimeStamp, UdyogAadharNo, PlantId, EmailId, MobileNo, ClientToken, ClientId, CreatedDate, Description, ApiDetails)
        VALUES (@ClientRequestId, @ClientReqTimeStamp, @UdyogAadharNo, @PlantIdNo, @EmailId, @MobileNo, @Token, @ClientId, getdate(), 'Email ID already registered in Training Program.', 'Insertion API')
    END

    -- 4. Check in Professional Training Program
    ELSE IF EXISTS (SELECT 1 FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.candidates WHERE EmailId = @EmailId )
    BEGIN
        SELECT 400 as Status, 'Email ID already registered in Professional Training Program.' AS ErrorMessage
        INSERT INTO UdyamiAPIRequestFailures (RequestId, RequestTimeStamp, UdyogAadharNo, PlantId, EmailId, MobileNo, ClientToken, ClientId, CreatedDate, Description, ApiDetails)
        VALUES (@ClientRequestId, @ClientReqTimeStamp, @UdyogAadharNo, @PlantIdNo, @EmailId, @MobileNo, @Token, @ClientId, getdate(), 'Email ID already registered in Professional Training Program.', 'Insertion API')
    END

    
		-------- TO CHECK THE EMAIL IS ALREADY REGISTERED OR NOR------------
	ELSE IF @EmailId IS NOT NULL AND ( SELECT COUNT(*) FROM Msme where EmailId=@EmailId) >= 5
	BEGIN
		SELECT 400 as Status, 'This Email Id is already registered.' ErrorMessage
		INSERT INTO UdyamiAPIRequestFailures (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,Description,ApiDetails)
		VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),'This Email Id is already registered.','Insertion API')
	END
	ELSE
	BEGIN
		
		DECLARE @ReferenceId varchar(100) = NULL
		SET @ReferenceId=CONCAT(@ClientId, RIGHT('000000' + CAST((Next Value For RefIdSequence) AS VARCHAR(6)), 6))
		

		--RefIdSequence
		 SELECT 200 AS Status, 'Success.' AS ErrorMessage, @ClientRequestId RequestId,@UdyogAadharNo UdyogAadharNo,@PlantIdNo PlantId,@ReferenceId RefId, 'Pledge' FileType, '.pdf' FileExtension
		 ----call sp here with try catch----
		 BEGIN TRY
			EXEC [dbo].[SP_MSME_INSERT_UDYAM_DETAILS]
			@MsmeId
			,@ZedId
			,@StateId
			,@StateName
			,@DistrictId
			,@DistrictName
			,@OwnerName
			,@EnterpriseName
			,@OrganisationType
			,@OrganisationTypeName
			,@EnterpriseType
			,@EnterpriseTypee
			,@MobileNo
			,@EmailId
			,@PledgeEmailId
			,@ApplicationId
			,@PFlat
			,@PBuilding
			,@PRoad
			,@PArea
			,@PCity
			,@PPin
			,@PStateId
			,@PStateName
			,@PLgDistrictCode
			,@PDistrictName
			,@PPlantDetailId	
			,@Activity
			,@TwoDigitActivity
			,@FourDigitActivity
			,@FiveDigitActivity
			,@ActivityDetailId
			,@UdyogAadharNo
			,@SocialCategory
			,@SocialCategoryName
			,@Gender
			,@PH
			,@PanNo
			,@Address
			,@MajorActivity
			,@MajorActivityName
			,@CommmenceDate
			,@LgDistrictCode
			,@Pincode
			,@PreviousEMType
			,@PreviousEMNumber
			,@TotalEmp
			,@InvestmentCost
			,@DicName
			,@AppliedDate
			,@Password
			,@IpAddress
			,@PAddress
			,@UamNumber
			,@IncorporationDate
			,@WhetherProdCommenced
			,@PlantIdNo
			,@UnitName
			,@UnitIdNo
			,@RegistrationFrom
			,@ZedCertified
			,@QrCodeNo			

		 INSERT INTO UdyamiAPIRequests (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,ReferenceId,ApiDetails)
		 VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),@ReferenceId,'Insertion API')

		 END TRY
		BEGIN CATCH
			SELECT 0 AS Status, 'Please check the data and try again.' AS ErrorMessage
			INSERT INTO UdyamiAPIRequestFailures (RequestId,RequestTimeStamp,UdyogAadharNo,PlantId,EmailId,MobileNo,ClientToken,ClientId,CreatedDate,Description,ApiDetails)
			VALUES (@ClientRequestId,@ClientReqTimeStamp,@UdyogAadharNo,@PlantIdNo,@EmailId,@MobileNo,@Token,@ClientId,getdate(),'Please check the data and try again.','Insertion API')
		END CATCH
	END

END
