GO
--[SP_API_MSME_RAMP_REPORT] 38, 100
CREATE PROCEDURE [dbo].[SP_API_MSME_RAMP_REPORT_BKP] --8, 100
(
    @PageNo INT = 1,
    @PageSize INT = 500
    
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @PageSize IS NULL OR @PageSize > 200 
    SET @PageSize = 200;

    IF @PageNo IS NULL 
    SET @PageNo = 1;

    
    SELECT 
        m.ZedId AS [ZedId],
        m.PUnitName AS [UnitName],
        m.PStateName AS [StateName],
        m.PDistrictName AS [DistrictName],
        c.Certification AS [Certifications],
        m.EnterpriseType AS [EnterpriseType],
        b.Gender AS [Gender],
        b.SocialCategoryName AS [SocialCategoryName],
        CONVERT(VARCHAR(10), m.CreatedDate, 23) AS [RegistrationDate],
        CONVERT(VARCHAR(10), C.CertificationStatusDate, 23) AS [CertificationDate],
        b.UdyogAadharNo AS [UdyogAadharNo],
        m.TwoDigitActivity AS [Sectors Name],
        MAX(CASE 
                WHEN c.Certification = 'Bronze' AND c.CertificationStatus IN (3, 4, 5, 7) THEN 'Under Evaluation'
                WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus IN (13, 14, 15, 17) THEN 'Under Evaluation'
                WHEN c.CertificationStatus = 99 THEN 'Rejected' 
                ELSE NULL
        END) AS [Application Status],
        MAX(CASE   
                WHEN c.CertificationStatus = 99 AND c.Certification = 'Bronze' THEN c.AssessorRemarks 
                WHEN c.CertificationStatus = 99 AND c.Certification != 'Bronze' THEN c.SaAssessorRemarks 
                ELSE NULL 
        END) AS [Reason for rejection],
        c.Certification AS [Application Certification Category],
        MAX(CASE 
                WHEN cc.Certification IN ('Silver', 'Gold') AND cc.NcCount = 1 THEN CONVERT(VARCHAR(10), CC.CreatedDate, 23) 
        END) AS [Handholding Opted Date],
        cc.Certification AS [Handholding Level Certification],
        MAX(CASE 
                WHEN cc.NcCount = 1 THEN 
                    CASE 
                        WHEN cc.CertificationStatus = 100 AND cc.SaCertificateNo IS NOT NULL THEN 'Completed'
                        WHEN cc.CertificationStatus BETWEEN 6 AND 100 THEN 'Applied'
                        ELSE NULL
                    END
        END) AS [Milestone 1 process (Applied/Completed)],
        MAX(CASE 
                WHEN cc.NcCount = 1 AND cc.CertificationStatus = 100 AND cc.SaCertificateNo IS NOT NULL 
                THEN CONVERT(VARCHAR(10), CC.CertificationStatusDate, 23)
        END) AS [Date of M1 Completion],
        MAX(CASE 
                WHEN cc.NcCount = 2 THEN 
                    CASE 
                        WHEN cc.CertificationStatus = 100 AND cc.SaCertificateNo IS NOT NULL THEN 'Completed'
                        WHEN cc.CertificationStatus BETWEEN 6 AND 100 THEN 'Applied'
                        ELSE NULL
                    END
        END) AS [Milestone 2 process (Applied/Completed)],
        MAX(CASE 
                WHEN cc.NcCount = 2 AND cc.CertificationStatus = 100 AND cc.SaCertificateNo IS NOT NULL 
                THEN CONVERT(VARCHAR(10), CC.CertificationStatusDate, 23)
        END) AS [Date of M2 Completion],
        MAX(CASE 
                WHEN cc.NcCount = 3 THEN 
                    CASE 
                        WHEN cc.CertificationStatus = 100 AND cc.SaCertificateNo IS NOT NULL THEN 'Completed'
                        WHEN cc.CertificationStatus BETWEEN 6 AND 100 THEN 'Applied'
                        ELSE NULL
                    END
        END) AS [Milestone 3 process (Applied/Completed)],
        MAX(CASE 
                WHEN cc.NcCount = 3 AND cc.CertificationStatus = 100 AND cc.SaCertificateNo IS NOT NULL 
                THEN CONVERT(VARCHAR(10), CC.CertificationStatusDate, 23)
        END) AS [Final Date of Completion],
        MAX(CASE 
            WHEN c.Certification = 'Bronze' AND c.CertificationStatus = 6 THEN 'Completed'
            WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus = 16 THEN 'Completed'
            WHEN c.CertificationStatus = 99 THEN 'Rejected'
            WHEN c.Certification = 'Bronze' AND c.CertificationStatus = 2 AND c.DesktopAccepted = 1 AND c.DesktopAssessorId IS NOT NULL THEN 'Scheduled'
            WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus IN (8,9) AND c.AssessmentDate IS NOT NULL THEN 'Scheduled'
            WHEN c.Certification IN ('Bronze') AND c.CertificationStatus IN (3,4,5,7) THEN 'Under Evaluation'
            WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus IN (13,14,15,17) THEN 'Under Evaluation'
            ELSE NULL
        END) AS [Assessment Status]
    FROM Msme m
    JOIN MsmeBasicInformation b ON m.ZedId = b.ZedId
    LEFT JOIN MsmeCertifications c ON m.ZedId = REPLACE(REPLACE(c.ZedId,'_D',''), CONCAT('_',c.Id),'')
    LEFT JOIN (
      select B.LastestCertification,C.Id,C.ZedId, C.Certification,C.CertificationStatusDate,C.NcCount,C.CreatedDate,C.SaCertificateNo,C.CertificationStatus
     from  ZED_CONSULTANT.dbo.MsmeBasicInformation B inner join  ZED_CONSULTANT.dbo.MsmeCertifications C on (B.ZedId=C.ZedId)
     ) cc ON c.ZedId = cc.ZedId AND c.Certification = cc.LastestCertification
    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
    GROUP BY 
        m.ZedId,
        m.PUnitName,
        m.PStateName,
        m.PDistrictName,
        c.Certification,
        cc.Certification,
        cc.LastestCertification,
        m.EnterpriseType,
        b.Gender,
        b.SocialCategoryName,
        CONVERT(VARCHAR(10), M.CreatedDate, 23),
        CONVERT(VARCHAR(10), C.CertificationStatusDate, 23),
        b.UdyogAadharNo,
        m.TwoDigitActivity
    ORDER BY m.ZedId
    OFFSET ((@PageNo - 1) * @PageSize) ROWS FETCH NEXT @PageSize ROWS ONLY;

    
    SELECT COUNT(*) AS TotalCounts, @PageNo AS PageNo, @PageSize AS PageSize
    FROM Msme M
    INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId

    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

END;
GO
