--[SP_API_RAMP_REPORT_ZED] 20, 1000
CREATE PROCEDURE [dbo].[SP_API_RAMP_REPORT_CONSULTANCY] --8, 200
(
    @PageNo INT = 1,
    @PageSize INT = 1000,
	@DynamicToken varchar(2000) = NULL
    
)
AS
BEGIN
    SET NOCOUNT ON;

	INSERT INTO ZedRampConsultancyReportRequestLog (DynamicToken, PageNo, PageSize, RequestDate)
	VALUES (@DynamicToken, @PageNo, @PageSize, GETDATE());

	IF @PageNo IS NULL 
    SET @PageNo = 1;

    IF @PageSize IS NULL
    SET @PageSize = 100;
    
	IF @PageSize>1000 
	BEGIN
		SELECT 400 StatusCode, 'Page Size should be less than 1000.' StatusMessage
		SET @PageSize=1
	END
    
	ELSE
	BEGIN
		SELECT 200 StatusCode, 'Success.' StatusMessage
	END 


    SELECT * FROM ZED_CONSULTANT.dbo.ConsultancyRampReport ORDER BY Id
    OFFSET ((@PageNo - 1) * @PageSize) ROWS FETCH NEXT @PageSize ROWS ONLY;

	SELECT COUNT(*) AS TotalCount, @PageNo AS PageNo, @PageSize AS PageSize
    FROM ZED_CONSULTANT.dbo.ConsultancyRampReport
	




END;
