-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_SUBMIT_INCENTIVE_DETAILS] --'<redacted>', '<redacted>'
(
	@Token varchar(200) = NULL,
	@UdyamNo varchar(50) = NULL,
	@Certificateno varchar(50) = NULL,
	@Pin varchar(50) = NULL,
	@ApplicationId varchar(50) = NULL,
	@UnitName varchar(200) = NULL,
	@District varchar(50) = NULL,
	@FCI varchar(50) = NULL,
	@DateOfProduction varchar(50) = NULL,
	@ServiceName varchar(200) = NULL,
	@AppliedDate varchar(50) = NULL,
	@ApprovalId varchar(50) = NULL,
	@ApprovedDate varchar(50) = NULL,
	@IncentiveName varchar(2000) = NULL,
	@DisbursedDate varchar(50) = NULL,
	@DisbursedAmount varchar(50) = NULL
)
AS
BEGIN

	  IF (
			dbo.fn_IsSafeInput(@UdyamNo) = 0 OR
			dbo.fn_IsSafeInput(@Certificateno) = 0 OR
			dbo.fn_IsSafeInput(@Pin) = 0 OR
			dbo.fn_IsSafeInput(@ApplicationId) = 0 OR
			dbo.fn_IsSafeInput(@UnitName) = 0 OR
			dbo.fn_IsSafeInput(@District) = 0 OR
			dbo.fn_IsSafeInput(@FCI) = 0 OR
			dbo.fn_IsSafeInput(@DateOfProduction) = 0 OR
			dbo.fn_IsSafeInput(@ServiceName) = 0 OR
			dbo.fn_IsSafeInput(@AppliedDate) = 0 OR
			dbo.fn_IsSafeInput(@ApprovalId) = 0 OR
			dbo.fn_IsSafeInput(@ApprovedDate) = 0 OR
			dbo.fn_IsSafeInput(@IncentiveName) = 0 OR
			dbo.fn_IsSafeInput(@DisbursedDate) = 0 OR
			dbo.fn_IsSafeInput(@DisbursedAmount) = 0
			)
	BEGIN
		SELECT 400 StatusCode, 'Bad Request' StatusMessage
	END

	ELSE IF(SELECT count(*) FROM ApiClientTokens WHERE Token=@Token AND ReverseToken=1)=0 AND 
	( SELECT count(*) FROM ApiClientDynamicTokens WHERE DynamicToken=@Token AND CreatedDate >= DATEADD(hour, -24, GETDATE()) and IsValid=1)=0
	BEGIN
		SELECT 401 StatusCode, 'Unauthorized User' StatusMessage
	END
	ELSE IF(SELECT count(*) FROM MsmeBasicInformation B inner join MsmeCertifications C on (B.ZedId=C.ZedId) 
	WHERE B.UdyogAadharNo=@UdyamNo and ((C.DaCertificateNo IS NOT NULL AND C.DaCertificateNo=@Certificateno) OR (C.SaCertificateNo IS NOT NULL AND C.SaCertificateNo=@Certificateno)))=0
	BEGIN
		SELECT 404 StatusCode, 'Record Not Found' StatusMessage
	END
	ELSE IF (@IncentiveName is null or @DisbursedDate is null or @DisbursedAmount is null or @ServiceName is null or @FCI is null)
	BEGIN
	SELECT 400 StatusCode, 'Bad Request' StatusMessage
	END
	ELSE
	BEGIN		
		INSERT INTO ApiIncentives (
			Token, 
			UdyamNo,
			Certificateno,
			Pin,
			ApplicationId,
			UnitName,
			District,
			FCI,
			DateOfProduction,
			ServiceName,
			AppliedDate,
			ApprovalId,
			ApprovedDate,
			IncentiveName,
			DisbursedDate,
			DisbursedAmount,
			SubmittedFrom

		)
		VALUES (
			@Token,
			@UdyamNo,
			@Certificateno,
			@Pin,
			@ApplicationId,
			@UnitName,
			@District,
			@FCI,
			@DateOfProduction,
			@ServiceName,
			@AppliedDate,
			@ApprovalId,
			@ApprovedDate,
			@IncentiveName,
			@DisbursedDate,
			@DisbursedAmount,
			'API'
		)

		SELECT 200 StatusCode, 'Success' StatusMessage
	END	

END
