/****** Object:  StoredProcedure [dbo].[SP_APP_CHECK_DATA_SYNC_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_CHECK_DATA_SYNC_FINAL_SUBMIT] --'<redacted>','<redacted>'
(
	@ZedId VarChar(50)				= NULL,
	@CertificationType VarChar(50)	= NULL
)
AS
BEGIN

	Declare @NcCount int  = NULL

	Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

	IF @NcCount>0 
	BEGIN
		IF @CertificationType='Bronze' AND EXISTS (
			SELECT 1 FROM MsmePhotos PC WHERE PC.ZedId=@ZedId AND PC.NcCount=@NcCount-1 AND Certification=@CertificationType AND PC.PhotoType='SiteExteriorPhotos' AND PC.IsVerified='No'
			AND NOT EXISTS (SELECT 1 FROM MsmePhotos CC WHERE CC.ZedId=@ZedId AND CC.NcCount = @NcCount AND Certification=@CertificationType AND CC.PhotoType = 'SiteExteriorPhotos')
			)
		BEGIN
			select 0 AllowFinalSubmit, CONCAT('Site Exterior for NC ',@NcCount,' is not synced. Please review.') ErrorMessage
		END

		ELSE IF @CertificationType='Bronze' AND EXISTS (
			SELECT 1 FROM MsmeProducts PC WHERE PC.ZedId=@ZedId AND PC.NcCount=@NcCount AND Certification=@CertificationType AND (ProductPhoto is null or ProductDescriptionPhoto is null)
			)
		BEGIN
			select 0 AllowFinalSubmit, CONCAT('Products for NC ',@NcCount,' are not synced. Please review.') ErrorMessage
		END

		ELSE IF EXISTS(SELECT 1 FROM MsmeEvidences WHERE ZedId=@ZedId AND SectionType=@CertificationType AND NcCount=@NcCount and SyncedDate is null)
		BEGIN
			select 0 AllowFinalSubmit, CONCAT('One of the evidences in NC ',@NcCount,' are not synced. Please review.') ErrorMessage
		END

		ELSE IF EXISTS (
			SELECT * FROM MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType AND CertificationStatus in (4,14))
		BEGIN
			select 1 AllowFinalSubmit, '' ErrorMessage
		END
		ELSE
		BEGIN
			select 0 AllowFinalSubmit, 'Cannot allow final submit right now. Please check with Assessor Once.' ErrorMessage
		END
	END

	ELSE
	BEGIN
		IF NOT EXISTS (SELECT 1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@CertificationType AND CertificationStatus=1)
			BEGIN
				select 0 AllowFinalSubmit, 'Final submission already done. Please review.' ErrorMessage
			END

		ELSE IF NOT EXISTS (SELECT 1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@CertificationType)
		BEGIN
			select 0 AllowFinalSubmit, 'Basic info not submitted. Please review.' ErrorMessage
		END

		ELSE IF EXISTS (SELECT 1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@CertificationType AND DomesticCustomers IS NULL)
		BEGIN
			select 0 AllowFinalSubmit, 'Basic info not submitted. Please review.' ErrorMessage
		END

		ELSE IF EXISTS (SELECT 1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@CertificationType AND RawMaterialImported IS NOT NULL and RawMaterialImported='Yes')
		AND
		NOT EXISTS (SELECT 1 FROM MsmeRawMaterials where ZedId=@ZedId AND Certification=@CertificationType)
		BEGIN
			
			select 0 AllowFinalSubmit, 'Raw materials not submitted. Please review.' ErrorMessage
		END

		ELSE IF NOT EXISTS (SELECT 1 FROM MsmeProducts WHERE ZedId=@ZedId AND Certification=@CertificationType)
			BEGIN
				select 0 AllowFinalSubmit, 'Products details are not submitted. Please review.' ErrorMessage
			END

		ELSE IF EXISTS (SELECT 1 FROM MsmeEvidences WHERE ZedId=@ZedId AND SectionType=@CertificationType AND ValidationRequired=0 and SyncedDate is null)
			BEGIN
				select 0 AllowFinalSubmit, 'One of the evidences are not synced. Please review.' ErrorMessage
			END
		ELSE 
		BEGIN
			select 1 AllowFinalSubmit, '' ErrorMessage
		END
	END


END
GO
