	--SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, EvidenceCode) SNo, Id,SectionCode, RequirementCode,EvidenceCode,EvidenceName,E.SectionType,ValidationRequired
	--FROM Evidences E
	--where E.SectionType=@CertificationType
