CREATE PROCEDURE [dbo].[SP_APP_MSME_GET_REQUIREMENT_PHOTOS] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId VarChar(50)			= NULL,
	@RequirementId VarChar(50)		= NULL,	
	@CertificationType VarChar(50)		= NULL
)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	IF @CertificationType='Bronze'
		SELECT concat(PhotoId,'.',PhotoExtension) PhotoPath FROM MsmePhotos WHERE ZedId=@ZedId and RequirementId=@RequirementId and Certification=@CertificationType and NcCount=@NcCount ORDER BY Id	
	ELSE
	SELECT concat(PhotoId,'.',SaPhotoExtension) PhotoPath FROM SaRequirementPhotos WHERE ZedId=@ZedId and RequirementId=@RequirementId and Certification=@CertificationType and NcCount=@NcCount ORDER BY Id

END
