-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_TECHNOLOGY_DETAILS] 
(
	@RefId VarChar(50)						= NULL,
	@ZedId VarChar(50)						= NULL,
	@CertificationType varchar(50)			= NULL,
	@CertId varchar(50)					    = NULL,
	@TechnologyCode varchar(50)				= NULL,
	@TechnologyName varchar(500)			= NULL,

	@NameOfTheManufaturer VarChar(500)		= NULL,
	@MakeOrModelName VarChar(500)			= NULL,
	@DateOfPurchase varchar(50)				= NULL,

	--@CertificationAgency VarChar(200)		= NULL,
	--@CertficateNumber VarChar(50)			= NULL,
	--@DateOfIssue VarChar(50)				= NULL,
	--@ValidityOfCertificate VarChar(50)		= NULL,
	@AnyOtherInformation VarChar(5000)		= NULL,

	--@ExpenditureCertficate VarChar(200)		= NULL,
	@AgencyOrSupplier VarChar(200)			= NULL,
	@InvoiceNo VarChar(50)					= NULL,
	@InvoiceBillDate VarChar(50)			= NULL,
	@AmountPaid VarChar(50)					= NULL,
	@EligibleAmount VarChar(50)				= NULL,
	@ModeOfPayment VarChar(50)				= NULL,

	--@AccountNo VarChar(50)					= NULL,
	--@IfscCode VarChar(50)					= NULL,
	--@BranchAddress VarChar(2000)			= NULL,
	--@BankName VarChar(200)					= NULL,

	@SubmittedFrom VarChar(50)				= NULL,
			
	@PhotoListWeb	DynamicPhotoList	READONLY,
	@PhotoListApp	DynamicPhotoList2	READONLY
)
AS
BEGIN

	

	select @TechnologyName=TechnologyName from ZED_CONSULTANT.dbo.RecommandedTechnologies where ZedId=@ZedId and Certification=@CertificationType and TechnologyCode=@TechnologyCode and CertId=@CertId


	IF (SELECT count(*) FROM ZED_CONSULTANT.DBO.MSME WHERE ZedId=@ZedId and TechnologyUpgradation=0)>0
	BEGIN
		SELECT 0 Status, 'Not eligible to submit the data for this Unit.' ErrorMessage
	END

	ELSE
	BEGIN
		DECLARE @FinancialAssistanceId varchar(200)
		DECLARE @TechDetailsId varchar(100)

		IF NOT EXISTS (SELECT * FROM ZED_CONSULTANT.DBO.FinancialAssistance  where ZedId=@ZedId and CertificationType=@CertificationType and CertId=@CertId and TechUpgradeStatus=1)
		BEGIN
			SET @FinancialAssistanceId =Next Value For FinancialIdSequence

			INSERT INTO ZED_CONSULTANT.DBO.FinancialAssistance (ZedId,SubmittedFrom,CertificationType,FinancialAssistanceId,CertId)
			VALUES (@ZedId,@SubmittedFrom,@CertificationType,@FinancialAssistanceId,@CertId)
		END
		ELSE
		BEGIN
			SELECT @FinancialAssistanceId=FinancialAssistanceId FROM ZED_CONSULTANT.DBO.FinancialAssistance  where ZedId=@ZedId and CertificationType=@CertificationType and CertId=@CertId and TechUpgradeStatus=1
		END

		DELETE FROM ZED_CONSULTANT.DBO.TechnologyUpgradation WHERE ZedId=@ZedId and CertificationType=@CertificationType and CertId=@CertId and TechnologyCode=@TechnologyCode
		INSERT INTO ZED_CONSULTANT.DBO.TechnologyUpgradation (
			ZedId,CertId,NameOfTheManufaturer,MakeOrModelName,DateOfPurchase,
			--CertificationAgency, CertficateNumber, DateOfIssue, ValidityOfCertificate,
			AnyOtherInformation,
			--ExpenditureCertficate,
			AgencyOrSupplier,
			InvoiceNo, InvoiceBillDate,AmountPaid,MsmeAmountPaid,EligibleAmount,ModeOfPayment,
			SubmittedFrom,CertificationType,FinancialAssistanceId,TechDetailsId,TechnologyCode,TechnologyName
		)
		VALUES (
			@ZedId,@CertId,@NameOfTheManufaturer,@MakeOrModelName,@DateOfPurchase,
			--@CertificationAgency, @CertficateNumber, @DateOfIssue, @ValidityOfCertificate,
			@AnyOtherInformation,
			--@ExpenditureCertficate, 
			@AgencyOrSupplier,
			@InvoiceNo, @InvoiceBillDate,@AmountPaid,@AmountPaid,@EligibleAmount,@ModeOfPayment,
			@SubmittedFrom,@CertificationType,@FinancialAssistanceId,@TechDetailsId,@TechnologyCode,@TechnologyName
		)

		DELETE FROM ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] WHERE ZedId=@ZedId and CertificationType=@CertificationType and CertId=@CertId and TechnologyCode=@TechnologyCode
		INSERT INTO ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType,TechnologyCode,CertId)
		SELECT distinct @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],@FinancialAssistanceId,@CertificationType,@TechnologyCode,@CertId FROM @PhotoListApp

		
		INSERT INTO ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType,TechnologyCode,CertId)
		SELECT distinct @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [Name],@FinancialAssistanceId,@CertificationType,@TechnologyCode,@CertId FROM @PhotoListWeb

		SELECT 1 Status, 'Data submitted Successfully.' ErrorMessage
	END	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_TECHNOLOGY_UPGRADATION]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_TECHNOLOGY_UPGRADATION] 
(
	@RefId VarChar(50)						= NULL,
	@ZedId VarChar(50)						= NULL,
	@CertificationType varchar(50)			= NULL,
	@CertId varchar(50)						= NULL,

	@CategoryOfCertificate VarChar(50)		= NULL,
	@NameOfCertficate VarChar(200)			= NULL,
	@CertificationAgency VarChar(200)		= NULL,
	@CertficateNumber VarChar(50)			= NULL,
	@DateOfIssue VarChar(50)				= NULL,
	@ValidityOfCertificate VarChar(50)		= NULL,
	@AnyOtherInformation VarChar(5000)		= NULL,

	@ExpenditureCertficate VarChar(200)		= NULL,
	@AgencyOrSupplier VarChar(200)			= NULL,
	@InvoiceNo VarChar(50)					= NULL,
	@InvoiceBillDate VarChar(50)			= NULL,
	@AmountPaid VarChar(50)					= NULL,
	@EligibleAmount VarChar(50)				= NULL,
	@ModeOfPayment VarChar(50)				= NULL,

	@AccountNo VarChar(50)					= NULL,
	@IfscCode VarChar(50)					= NULL,
	@BranchAddress VarChar(2000)			= NULL,
	@BankName VarChar(200)					= NULL,

	@SubmittedFrom VarChar(50)				= NULL,

	@TechnologyCode VarChar(50)			    = NULL,
	@TechnologyName VarChar(2000)			= NULL,
			
	@PhotoListWeb	DynamicPhotoList	READONLY,
	@PhotoListApp	DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @FinancialAssistanceId varchar(200)--,@CertificationType varchar(50) = NULL

	--SET @FinancialAssistanceId =Next Value For FinancialIdSequence

	SELECT @FinancialAssistanceId=FinancialAssistanceId FROM ZED_CONSULTANT.DBO.FinancialAssistance  where ZedId=@ZedId and CertificationType=@CertificationType and CertId=@CertId and TechUpgradeStatus=1
	
	-----LOGIC FOR ELIGIBILITY AMOUNT START----------
	DECLARE @TotalAmountPaid DECIMAL(18,2), 
            @SubsidyPercentage DECIMAL(5,2),
            @SubsidyAmount DECIMAL(18,2);

	SELECT @TotalAmountPaid=SUM(CAST(amountpaid AS DECIMAL(18,2))) FROM ZED_CONSULTANT.DBO.TechnologyUpgradation WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND CertId=@CertId

	SELECT @SubsidyPercentage=SubsidyPercentage FROM ZED_CONSULTANT.DBO.MsmePaymentInfo WHERE ZedId=@ZedId and Certification=@CertificationType and MileStoneNum=3 AND MsmePmtCertId=@CertId

	SET @SubsidyAmount = @TotalAmountPaid*(@SubsidyPercentage/100)

	SET @EligibleAmount = CASE WHEN @SubsidyAmount>300000 THEN 300000 ELSE @SubsidyAmount END	

	-----LOGIC FOR ELIGIBILITY AMOUNT END-------------


	IF (SELECT count(*) FROM ZED_CONSULTANT.DBO.MSME WHERE ZedId=@ZedId and TechnologyUpgradation=0)>0  ----- 1 means apply(avail), 0 means view
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END

	ELSE
	BEGIN
		
		declare @Agencyid varchar(50) = null
		
		UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET AccountNo=@AccountNo, IfscCode=@IfscCode, BranchAddress=@BranchAddress, BankName=@BankName, EligibleAmount=@EligibleAmount
		WHERE ZedId=@ZedId and CertificationType=@CertificationType AND CertId=@CertId

		INSERT INTO ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType, CertId)
		SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],@FinancialAssistanceId,@CertificationType, @CertId FROM @PhotoListApp WHERE [PhotoType]='Copy of Cancelled Cheque'

		INSERT INTO ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType, CertId)
		SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [Name],@FinancialAssistanceId,@CertificationType, @CertId FROM @PhotoListWeb WHERE [Name]='Copy of Cancelled Cheque'

		UPDATE ZED_CONSULTANT.DBO.Msme SET TechnologyUpgradation=0 WHERE ZedId=@ZedId

		UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=2 WHERE ZedId=@ZedId and CertificationType=@CertificationType AND CertId=@CertId AND FinancialAssistanceId=@FinancialAssistanceId

		INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
		VALUES (@ZedId,concat('MSME Submitted TU application on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'ApplicationOfTUDoneByMSME','3')



		-----ALLOTING AGENCY -------------
		select @Agencyid=U.UserId from ZED_CONSULTANT.dbo.Msme M 
		inner join ZED_CONSULTANT.dbo.TuAgencyUserDistricts D on (M.PLgDistrictCode=D.Districts) 
		inner join ZED_CONSULTANT.dbo.Users U on (D.UserId=U.UserId)
		WHERE ZedId=@ZedId AND U.IsActive=1 and FinancialVerification=1 and U.RoleId=2 and U.Email not in ('ks@geostat.in','keerthisreenu@gmail.com','keesree21@gmail.com','viswa@geostat.in')

		IF @Agencyid IS NULL
		BEGIN
			SELECT @Agencyid=UserId FROM ZED_CONSULTANT.dbo.Msme M inner join ZED_CONSULTANT.dbo.Users U on (M.StateId=U.TuPreferredState) WHERE ZedId=@ZedId AND U.IsActive=1 and FinancialVerification=1 and U.RoleId=2
			and U.Email not in ('ks@geostat.in','keerthisreenu@gmail.com','keesree21@gmail.com','viswa@geostat.in')
		END

		IF @Agencyid IS NOT NULL
		BEGIN
		UPDATE ZED_CONSULTANT.dbo.FinancialAssistance set CertificationBodyUserId=@Agencyid where ZedId=@ZedId and CertId=@CertId and CertificationType=@CertificationType

		INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
		VALUES (@ZedId,concat(@Agencyid, ' Agency Auto alloted on',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'AgencyAutoAlloted','3')

		EXEC ZED_CONSULTANT.DBO.[SP_SEND_MAIL_AUTO_ALLOT_CONSULTING_ORGANISATION_TU] @ZedId, @Agencyid

		END

		

	END
END
GO
