SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SA_INSERT_BASIC_INFO] 
(
	@ZedId VarChar(50)						= NULL,
	@RefId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AuditsConducted VarChar(50)			= NULL,
	@DomesticCustomers VarChar(2000)		= NULL,	
	@InternationalCustomers varchar(2000)	= NULL, 
	@RawMaterialImported varchar(50)		= NULL, 
	@OutsourcedProcesses varchar(2000)		= NULL,
	@EnergySources varchar(2000)            = NULL,	
	@ManufacturingCapacityUnits VarChar(50)	= NULL,
	@ManufacturingCapacityValue VarChar(50)	= NULL,
	@MonthlyUtilizationUnits VarChar(50)	= NULL,
	@MonthlyUtilizationValue VarChar(50)	= NULL,

	@ProductList		ProductDetails2		READONLY,
	@RawMaterialList	RawMaterial			READONLY,

	@ProductDescriptionPhotos	DynamicPhotoList2	READONLY,
	@ProductPhotos				DynamicPhotoList2	READONLY
)
AS
BEGIN
			IF @InternationalCustomers is null
			BEGIN
			SET @InternationalCustomers= 'NA'
			END

			IF @OutsourcedProcesses is null
			BEGIN
			SET @OutsourcedProcesses= 'NA'
			END

			UPDATE MsmeCertifications SET SaAuditsConducted=@AuditsConducted, SaDomesticCustomers=@DomesticCustomers, SaInternationalCustomers=@InternationalCustomers,
			SaRawMaterialImported=@RawMaterialImported,	SaOutsourcedProcesses=@OutsourcedProcesses, SaEnergySources=@EnergySources, 
			SaManufacturingCapacityUnits=@ManufacturingCapacityUnits, SaManufacturingCapacityValue=@ManufacturingCapacityValue,
			SaMonthlyUtilizationUnits=@MonthlyUtilizationUnits, SaMonthlyUtilizationValue=@MonthlyUtilizationValue
			where ZedId=@ZedId and Certification=@CertificationType


			DELETE FROM SaProducts WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO SaProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList
	

			DELETE FROM SaRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO SaRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
	

			DELETE FROM SaPhotos WHERE ZedId=@ZedId and PhotoType='ProductDescriptionPhotos'  and Certification=@CertificationType
			INSERT INTO SaPhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from SaProducts M inner join SaPhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',P.PhotoExtension))  
			where M.zedid=@ZedId and M.Certification=@CertificationType and P.NcCount=0
		

			DELETE FROM SaPhotos WHERE ZedId=@ZedId and PhotoType='ProductPhotos'  and Certification=@CertificationType
			INSERT INTO SaPhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType FROM @ProductPhotos

			update P set P.ProductId=M.Id from SaProducts M inner join SaPhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',P.PhotoExtension))  
			where M.zedid=@ZedId and M.Certification=@CertificationType and P.NcCount=0
		
	
END
GO
