	DECLARE @NcCount int = NULL
	DECLARE @FinancialAssistanceId int = NULL

	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null

	SELECT TOP 1 @FinancialAssistanceId=FinancialAssistanceId FROM FinancialAssistance WHERE ZedId=@ZedId and CertificationType=@CertificationType ORDER BY Id DESC
	--IF EXISTS (select * from ConsultantDailyAttendance where convert(date,CreatedDate)=convert(date,getdate()) AND ConsultantId=@AssessorId and ZedId=@ZedId and Certification=@CertificationType and AttendanceType=@AttendanceType  )
	--BEGIN
	--	SELECT 0 Status, CONCAT(@AttendanceType,'<redacted>') Message
	--END
	--ELSE
	BEGIN
		INSERT INTO ZedDailyAttendance(RefId,ZedId,Certification,ConsultantId,PhotoId,PhotoPath,Timestamp,Latitude,Longitude,AttendanceType,Comments,CreatedDate,MileStoneNo,FinancialAssistanceId)
		VALUES (@RefId,@ZedId,@CertificationType,@AssessorId,@PhotoId,@PhotoPath,@TimeStamp,@Latitude,@Longitude,@AttendanceType,@Comments, Getdate(),@NcCount,@FinancialAssistanceId)

		SELECT 1 Status, CONCAT(@AttendanceType,' ATTENDANCE SUBMITTED SUCCESSFULLY') Message
	END
	

