/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_CHECK_NC_PHOTO_AVAILABILITY]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_ASSESSMENT_CHECK_NC_PHOTO_AVAILABILITY] --'<redacted>','<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
	
)
AS
BEGIN

	DECLARE @NcCount int = NULL,
			@CertStatus int = NULL
	
	select @NcCount=NcCount, @CertStatus=CertificationStatus from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType
	print @NcCount

	SET NOCOUNT ON;

	IF @CertStatus<6
	BEGIN

		SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/SiteExteriorPhotos/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos 
		where name='SiteExteriorPhotos' and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount --and NcCount>0 
		order by Id

		SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos
		where name in ('BasicInfo','ProductPhoto','ProductDescriptionPhoto') and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount --and NcCount>0 
		order by Id

		SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/Evidences/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos 
		where name='Evidences' and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount --and NcCount>0
		order by Id

	
	END

	IF @CertStatus=14
	BEGIN

		SELECT CONCAT('Photos/',@ZedId,'/SiteExteriorPhotos/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where 1=2

		SELECT CONCAT('Photos/',@ZedId,'/BasicInfo/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where 1=2

		SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/Evidences/',PhotoId,'.jpg') as PhotoPath, PhotoId from SaRequirementPhotos 
		where name='Evidences' and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount --and NcCount>0
		order by Id

	END


	BEGIN

		SELECT CONCAT('Photos/',@ZedId,'/SiteExteriorPhotos/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where 1=2

		SELECT CONCAT('Photos/',@ZedId,'/BasicInfo/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where 1=2
		
		--SELECT PhotoId, CONCAT('<redacted>',@ZedId,@CertificationType,'<redacted>',PhotoId,'<redacted>') as PhotoPath from SaRequirementPhotos where RequirementId in (SELECT RequirementId from MsmeRequirements where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and NcCount>0) 
		--and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0
		
		SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/Evidences/',PhotoId,'.jpg') as PhotoPath, PhotoId from SaRequirementPhotos where 
		ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0 and 1=2
	
	END

END



