/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_UPDATE_TIMESTAMP]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_UPDATE_TIMESTAMP] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@PhotoType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE 
		@SectionCode varchar(50) = NULL,
		@RequirementCode varchar(50) = NULL,
		@SectionType varchar(50) = NULL

		DECLARE @NcCount int = NULL
		

		IF @RoleId=3
		BEGIN

			IF @PhotoType IN  ('SiteExteriorPhoto','SiteExteriorPhotos') 
			BEGIN
				IF (select count(*) from SaPhotos where ZedId=@ZedId AND Id=@Id and NcCount>0 and Certification='Silver')>0
					UPDATE SaPhotos SET DocumentOpenedTime=GETDATE() WHERE ZedId=@ZedId AND Id=@Id
				ELSE
					UPDATE MsmePhotos SET DocumentOpenedTime=GETDATE() WHERE ZedId=@ZedId AND Id=@Id
			END

			ELSE IF @PhotoType = 'ProductPhoto'
			BEGIN
			UPDATE MsmeProducts SET ProductOpenedTime=GETDATE() WHERE ZedId=@ZedId AND Id=@Id
			END 

			ELSE IF @PhotoType = 'ProductDescriptionPhoto'
			BEGIN
			UPDATE MsmeProducts SET ProductDescOpenedTime=GETDATE() WHERE ZedId=@ZedId AND Id=@Id
			END 

			ELSE
			BEGIN
					UPDATE MsmeEvidences SET DocumentOpenedTime=GETDATE() WHERE ZedId=@ZedId AND Id=@Id

					select @SectionCode=SectionCode,@RequirementCode=RequirementCode,@SectionType=SectionType  from MsmeEvidences where Id=@Id and ZedId=@ZedId
					SELECT @NcCount=Max(NcCount) FROM MsmeEvidences WHERE ZedId=@ZedId and SectionType=@SectionType

					IF (select count(*) from MsmeEvidences where ZedId=@ZedId and SectionCode=@SectionCode and RequirementCode=@RequirementCode and SectionType=@SectionType and DocumentOpenedTime is null and SyncedDate is not null and NcCount=@NcCount)=0
					BEGIN
						IF (select count(*) from MsmeEvidences where ZedId=@ZedId and SectionCode=@SectionCode and RequirementCode=@RequirementCode and SectionType=@SectionType and ValidationRequired =1 and IsVerified is null and NcCount=@NcCount)=0

						UPDATE MsmeRequirements set OpenedFlag=1 where ZedId=@ZedId and SectionCode=@SectionCode and RequirementCode=@RequirementCode and SectionType=@SectionType
					END
			END
		END
END



GO
