/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_CONFIRM_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_RA_CONFIRM_FINAL_SUBMIT] --'<redacted>','<redacted>'
(
	@ZedId VarChar(50)				= NULL,
	@CertificationType VarChar(50)	= NULL
)
AS
BEGIN

	Declare @NcCount int  = NULL
	Declare @ModeOfAssessment varchar(100)  = NULL

	Select @NcCount=NcCount,@ModeOfAssessment=ModeOfAssessment from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType


	IF
	(select count(*) from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified IS NULL and NcCount=@NcCount and ModeOfAssessment='Remote Assessment')>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more Exterior Photos. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified IS NULL and NcCount=@NcCount and @ModeOfAssessment='Remote Assessment')>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more products. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeRequirements M inner join MsmeSections S on (M.ZedId=S.ZedId and M.SectionType=S.SectionType and M.NcCount=S.NcCount and M.SectionCode=S.SectionCode)
	inner join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification and S.AssessorId=C.CoAssessorId)
	where M.SectionType=@CertificationType and M.ZedId=@ZedId and SaConformance IS NULL and M.NcCount=@NcCount and( S.IsAssessmentExcempted='No' or  S.IsAssessmentExcempted is null))>0
	select 0 AllowFinalSubmit, 'Co-Assessor missed assessment of one or more parameters. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeRequirements M inner join MsmeSections S on (M.ZedId=S.ZedId and M.SectionType=S.SectionType and M.NcCount=S.NcCount and M.SectionCode=S.SectionCode) where M.SectionType=@CertificationType and M.ZedId=@ZedId and SaConformance IS NULL and M.NcCount=@NcCount and( S.IsAssessmentExcempted='No' or  S.IsAssessmentExcempted is null))>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more parameters. Please review.' ErrorMessage

	ELSE IF (select count(*) from MsmeSections where SectionType=@CertificationType and ZedId=@ZedId and OfiComments is null and NcCount=0 and IsAssessmentExcempted='No')>0
				select 0 AllowFinalSubmit, 'You may have missed one or more OFI comments. Please review.' ErrorMessage	

	ELSE IF @CertificationType = 'Silver'
		BEGIN
			IF (select SaAuditsConducted from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount) IS NULL
				select 0 AllowFinalSubmit, 'Please enter 3rd Party Financial Audits' ErrorMessage	
			ELSE IF (select SaDomesticCustomers from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount) IS NULL
				select 0 AllowFinalSubmit, 'Please enter Domestic customers details' ErrorMessage		
			ELSE IF (select SaInternationalCustomers from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount) IS NULL
				select 0 AllowFinalSubmit, 'Please enter International customers details' ErrorMessage
			--ELSE IF (select SaRawMaterialImported from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount) IS NULL
			--	select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
			ELSE IF (select SaOutsourcedProcesses from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount) IS NULL
				select 0 AllowFinalSubmit, 'Please enter Outsourced Processes' ErrorMessage
			ELSE IF (select SaEnergySources from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount) IS NULL
				select 0 AllowFinalSubmit, 'Please enter Energy Sources' ErrorMessage
		   ELSE IF (select count(*) from MeetingParticipants where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='Close Meeting')=0
				select 0 AllowFinalSubmit, 'Please complete the closing meeting' ErrorMessage
           ELSE IF (select count(*) from SaPhotos where Certification=@CertificationType and ZedId=@ZedId and PhotoType='Close Meeting')=0
				select 0 AllowFinalSubmit, 'Please Capture the closing meeting photo' ErrorMessage
		   
			ELSE 
				select 1 AllowFinalSubmit, '' ErrorMessage
		END
	ELSE 
	select 1 AllowFinalSubmit, '' ErrorMessage

	IF @NcCount>=5
	SELECT 0 RaisedForNc

	IF(select count(*) from SaPhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE IF(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc
	
	ELSE IF(select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and SaConformance='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE 
		SELECT 0 RaisedForNc
END
GO
