-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_RA_UPDATE_JOIN_ROOM_STATUS] 
(
	
	@ZedId VarChar(50)					= NULL,
	@CertificationType VarChar(50)		    = NULL

)
AS
BEGIN

	
	
	UPDATE MsmeCertifications SET JoinRoomStatus=1 where ZedId=@ZedId and Certification=@CertificationType 

END
