/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_UPDATE_PHOTOS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_ASSESSMENT_RA_UPDATE_PHOTOS]
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@TableName varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@Name varchar(500) = NULL,
	@Url varchar(8000) = NULL
)
AS
BEGIN

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	set @Url =concat(@CurrentUrl,@Url)

	IF @TableName='MsmeProducts' AND @Name = 'Product Photo'
	BEGIN
		UPDATE MsmeProducts 
		SET SaProductPhoto=@Url
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType

		INSERT INTO SaPhotos (ZedId,Certification,PhotoType,AssessorId,Photo,Name,TimeStamp,ProductId)
		VALUES (@ZedId,@CertificationType,'ProductPhotos',@UserId,@Url,@Name,Getdate(),@Id)
	END
	ELSE IF @TableName='MsmeProducts' AND @Name = 'Product Description Photo'
	BEGIN
		UPDATE MsmeProducts 
		SET SaProductDescriptionPhoto=@Url
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType

		INSERT INTO SaPhotos (ZedId,Certification,PhotoType,AssessorId,Photo,Name,TimeStamp,ProductId)
		VALUES (@ZedId,@CertificationType,'ProductDescriptionPhotos',@UserId,@Url,@Name,Getdate(),@Id)
	END

	ELSE IF @TableName='MsmeRequirements'
	BEGIN
		
		DECLARE @RequirementId varchar(50) = NULL
		select @RequirementId=RequirementId from MsmeRequirements where Id=@Id

		INSERT INTO SaPhotos (ZedId,Certification,PhotoType,AssessorId,Photo,RequirementId,Name,TimeStamp)
		VALUES (@ZedId,@CertificationType,'Evidence Photo',@UserId,@Url,@RequirementId,@Name,Getdate())
	END

	ELSE IF @TableName='SiteExteriorPhotos'
	BEGIN
		INSERT INTO SaPhotos (ZedId,Certification,PhotoType,AssessorId,Photo,Name,TimeStamp)
		VALUES (@ZedId,@CertificationType,'SiteExteriorPhotos',@UserId,@Url,@Name,Getdate())
	END

	ELSE IF @TableName='Meetings'
	BEGIN

		INSERT INTO SaPhotos (ZedId,Certification,PhotoType,AssessorId,Photo,Name,TimeStamp)
		SELECT @ZedId,@CertificationType,MeetingType,@UserId,@Url,@Name,Getdate() FROM Meetings WHERE Id=@Id

	END

	ELSE
	BEGIN
		INSERT INTO SaPhotos (ZedId,Certification,PhotoType,AssessorId,Photo,Name,TimeStamp)
		VALUES (@ZedId,@CertificationType,'SiteTour',@UserId,@Url,@Name,Getdate())
	END

END

GO
