CREATE PROC [dbo].[SP_ASSESSMENT_REJECT_UNIT_FOR_DA]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@ReasonForRejection varchar(100) = NULL
)
AS
BEGIN

	UPDATE MsmeCertifications SET ReasonForRejection=@ReasonForRejection,AcceptOrRejectDate=getdate(),DesktopAssessorId=NULL where  ZedId=@ZedId AND Certification=@Certification


	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('DA for ',@Certification, ' Rejected by Agency due to ',@ReasonForRejection),getdate(),@Certification,'DaAgencyRejected')

END


