/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_SA_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_ASSESSMENT_SA_DETAILS]
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;

	IF @Certification='SilverMilestone1'
	BEGIN 
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_SA_DETAILS] @UserId, @RoleId, @ZedId, 'Silver', 1
	END

	ELSE IF @Certification='SilverMilestone2'
	BEGIN 
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_SA_DETAILS] @UserId, @RoleId, @ZedId, 'Silver', 2
	END

	ELSE IF @Certification='SilverMilestone3'
	BEGIN 
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_SA_DETAILS] @UserId, @RoleId, @ZedId, 'Silver', 3
	END

	ELSE IF @Certification='GoldMilestone1'
	BEGIN 
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_SA_DETAILS] @UserId, @RoleId, @ZedId, 'Gold', 1
	END

	ELSE IF @Certification='GoldMilestone2'
	BEGIN 
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_SA_DETAILS] @UserId, @RoleId, @ZedId, 'Gold', 2
	END

	ELSE IF @Certification='GoldMilestone3'
	BEGIN 
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_SA_DETAILS] @UserId, @RoleId, @ZedId, 'Gold', 3
	END

	ELSE
	BEGIN
		DECLARE @CurrentUrl varchar(100) = NULL,
		@ModeOfAssessment varchar(50) = NULL,
		@DynamicSaPath varchar(100) = 'SaPhotos/',
		@IsMoved bit = 0

		IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((SiteAssessorId=@UserId and @RoleId=3) OR (CoAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=7) OR (@RoleId=8) OR (ZedId=@ZedId AND (@RoleId is null OR @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END

		SELECT @CurrentUrl=UrlName from UrlsMasterData
		SELECT @ModeOfAssessment=ModeOfAssessment from MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

		-- logic to check the Record is moved to network drive or not
		IF EXISTS(SELECT 1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification AND PhotosPath IS NOT NULL)
		BEGIN
			SET @DynamicSaPath = 'SaCertifiedPhotos/'
			SET @IsMoved = 1
		END

		IF @ModeOfAssessment='Onsite Assessment'
		BEGIN
			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
			isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END,
			CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/',PhotoFileName,'.jpg')) src,CreatedDate	
			,'SaPhotos' TableName
			FROM SaPhotos WHERE (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0

			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/',PhotoFileName,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/',PhotoFileName,'.jpg') src,name  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification
	
			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') src,name  FROM SaPhotos WHERE PhotoType in ('SiteTour') AND ZedId=@ZedId AND Certification=@Certification
			
			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId, null RequirementCode, null SectionCode,	
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src
			FROM SaPhotos WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,	R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
			case when R.PhotoType='Evidences' then isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(R.Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE R.Photo END,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) else
			isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(R.Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE R.Photo END,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,FORMAT(R.CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(R.Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE R.Photo END,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) src
			FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0 and (R.PhotoType='Evidence Photo')

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/Closing Meeting Photo.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/',PhotoFileName,'.jpg') src,name  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification

			select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification

			select *,'SaRawMaterials' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId, CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/BasicInfo/', PhotoId,'.',PhotoExtension) Photo,CreatedDate,'SaPhotos' TableName, CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/BasicInfo/', PhotoId,'.',PhotoExtension) src,name,ProductId  FROM SaPhotos WHERE PhotoType in ('ProductPhotos','ProductDescriptionPhotos') AND ZedId=@ZedId AND Certification=@Certification order by PhotoType desc

			SELECT Id, ZedId, Certification, PhotoId, TimeStamp, Latitude, Longitude, PhotoType, EvidenceId, IsVerified, AssessorId, AssessorRemarks, UpdatedDate, NcCount, PhotoExtension,RequirementId, 
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo, 
			CreatedDate, 'SaPhotos' TableName, CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/',AssessorId,'.jpg') as PhotoPath,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src,name  FROM SaPhotos WHERE PhotoType in ('Selfie') AND ZedId=@ZedId AND Certification=@Certification


			----- ======================================================================================
			------    SITE TOUR AND SA PHOTOS SURVEILLANCE-------------
			------=======================================================================================
			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,
			RequirementId,Photo,CreatedDate,'SaPhotos' TableName,
			CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,
			CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') src,name  FROM ZED_SURVEILLANCE.DBO.SaPhotos 
			WHERE PhotoType in ('SiteTour') AND [Name] not in ('Site Exteripr Photo','Site Interior Photo','Selfie') 
			AND ZedId=@ZedId AND Certification=@Certification

			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,
			UpdatedDate,	NcCount,	PhotoExtension,	RequirementId, null RequirementCode, null SectionCode,	
			Photo,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,Photo src
			FROM ZED_SURVEILLANCE.DBO.SaPhotos WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,
			R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
			case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) else
			isnull(R.Photo,CONCAT('/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,
			FORMAT(R.CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) src
			FROM  ZED_SURVEILLANCE.DBO.SaRequirementPhotos R	inner join ZED_SURVEILLANCE.DBO.MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0 and (R.PhotoType='Evidence Photo')
														
		END												

		ELSE
		BEGIN
			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
			isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END,
			CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',Name,'.jpg')) src,CreatedDate	
			,'SaPhotos' TableName
			FROM SaPhotos WHERE (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0

			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/Opening Meeting Photo.jpg') as PhotoPath,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src,name  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification
	
			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src,name  FROM SaPhotos WHERE PhotoType in ('SiteTour') AND ZedId=@ZedId AND Certification=@Certification

			SELECT 
			R.Id,	R.ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	R.AssessorRemarks,	R.UpdatedDate,	R.NcCount,	PhotoExtension,	R.RequirementId, M.RequirementCode, M.SectionCode,	
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate	
			,'SaPhotos' TableName,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src,
			FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime
			FROM SaPhotos R inner join MsmeRequirements M on (R.RequirementId=M.RequirementId and r.NcCount=m.NcCount and r.ZedId=m.ZedId and r.Certification=m.SectionType) WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,	R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
			case when R.PhotoType='Evidences' then isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(R.Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE R.Photo END,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',@Certification,'/Evidences/',R.PhotoId,'.jpg')) else
			isnull(CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(R.Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE R.Photo END,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,R.CreatedDate	
			,'SaPhotos' TableName,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(R.Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE R.Photo END as src,
			FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime
			FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0 and (R.PhotoType='Evidence Photo')

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/',@DynamicSaPath,@ZedId,'/',PhotoFileName,'.jpg') as PhotoPath,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src,name  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification

			select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification

			select *,'SaRawMaterials' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as Photo,
			CreatedDate,'SaPhotos' TableName, 
			CASE WHEN @IsMoved=1 THEN REPLACE(REPLACE(Photo, '/mobileapi/Photos/', '/mobileapi/CertifiedPhotos/'), '/mobileapi/SaPhotos/', '/mobileapi/SaCertifiedPhotos/') ELSE Photo END as src,name,ProductId  FROM SaPhotos WHERE PhotoType in ('ProductPhotos','ProductDescriptionPhotos') AND ZedId=@ZedId AND Certification=@Certification order by PhotoType desc

			SELECT TOP 1	Id,	ZedId,	Certification,	Timestamp,	CONCAT(@CurrentUrl,'/mobileapi/',PhotoPath) PhotoPath,	Latitude,	Longitude,	CreatedDate,	RepresentativeName,	Designation FROM MsmeSelfies WHERE ZedId=@ZedId AND Certification=@Certification ORDER BY ID DESC

		END
	END
END
GO
