/****** Object:  StoredProcedure [dbo].[SP_AUTO_FINAL_REJECT_EXPIRED_NC]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_AUTO_FINAL_REJECT_EXPIRED_NC]
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Get the list of units to reject. We include '<redacted>' because your rename logic needs it.
    CREATE TABLE #ExpiredCertifications (
        ZedId VARCHAR(50),
        CertificationType VARCHAR(50),
        InternalId INT 
    )

    INSERT INTO #ExpiredCertifications (ZedId, CertificationType, InternalId)
    SELECT ZedId, Certification, Id
    FROM MsmeCertifications
    WHERE (CertificationStatus = 7 OR CertificationStatus = 17)
      AND DATEDIFF(day, CertificationStatusDate, GETDATE()) > 15
	  --and ZedId='<redacted>'

    DECLARE @CurrentZedId VARCHAR(50)
    DECLARE @CurrentCertType VARCHAR(50)
    DECLARE @CurrentInternalId INT

    WHILE EXISTS (SELECT 1 FROM #ExpiredCertifications)
    BEGIN
        SELECT TOP 1 
            @CurrentZedId = ZedId, 
            @CurrentCertType = CertificationType,
            @CurrentInternalId = InternalId
        FROM #ExpiredCertifications

        -- 2. Run your existing status update logic
        EXEC [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT] @ZedId = @CurrentZedId, @CertificationType = @CurrentCertType

        -- 3. Run your existing renaming logic (This renames the ID in the tables)
        EXEC [dbo].[SP_MONITORING_REJECT_CERTIFICATION] @ZedId = @CurrentZedId, @CertificationType = @CurrentCertType

        ---------------------------------------------------------------------------
        -- PREPARING THE @RenamedZedId HERE
        ---------------------------------------------------------------------------
        -- We combine the original ID and the Internal ID to match: concat(ZedId,'<redacted>',Id)
        DECLARE @RenamedZedId VARCHAR(100) = CONCAT(@CurrentZedId, '_D_', @CurrentInternalId)
        ---------------------------------------------------------------------------

        -- 4. Pass the prepared @RenamedZedId into the mail procedure
        EXEC [dbo].[SP_SEND_MAIL_AUTO_REJECT_NC_FROM_PARTIAL_REJECTION] 
            @OriginalZedId = @CurrentZedId, 
            @RenamedZedId = @RenamedZedId, 
            @Certification = @CurrentCertType

        DELETE FROM #ExpiredCertifications WHERE ZedId = @CurrentZedId AND CertificationType = @CurrentCertType
    END

    DROP TABLE #ExpiredCertifications
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BLOCK_UNBLOCK_BRONZE_AGENCY]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_BLOCK_UNBLOCK_BRONZE_AGENCY] --'<redacted>'
(
	@AllowBronzeAssessments bit = NULL,
	@UserId varchar(50) = NULL,
	@ReasonForBlock varchar(2000) = NULL
)
AS
BEGIN
	IF @AllowBronzeAssessments=1
	BEGIN
		UPDATE Users SET AllowBronzeAssessments=1 WHERE UserId=@UserId AND RoleId=2

		SELECT 200 StatusCode, 'BRONZE ASSESSMENTS UNBLOCKED SUCCESSFULLY' Message, UserName, Email,MobileNo FROM Users where RoleId=2 and UserId=@UserId

		SELECT UserName, Email,MobileNo FROM Users where RoleId=2 and UserId=@UserId

	END
	ELSE
	IF @AllowBronzeAssessments=0
	BEGIN
		UPDATE Users SET AllowBronzeAssessments=0, ReasonForRejectionForBA=@ReasonForBlock  WHERE UserId=@UserId AND RoleId=2

		SELECT 200 StatusCode, 'BRONZE ASSESSMENTS BLOCKED SUCCESSFULLY' Message, UserName, Email,MobileNo FROM Users where RoleId=2 and UserId=@UserId

		SELECT UserName, Email,MobileNo FROM Users where RoleId=2 and UserId=@UserId
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_BLOCK_UNBLOCK_USER]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
