/****** Object:  StoredProcedure [dbo].[SP_DA_GET_CERTIFICATE_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DA_GET_CERTIFICATE_DETAILS]  --'<redacted>','<redacted>'
(
	@ZedId Varchar(100) =NULL,
	@CertificationType Varchar(100) =NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	BEGIN TRY

	SELECT   UPPER(M.PUnitName) EnterpriseName,DaCertificateNo,FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DateOfCertification,
		case when RegistrationType='UAM' THEN B.Address ELSE concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) end as Address ,	
		B.UdyogAadharNo,M.MobileNo,M.EmailId,M.EnterpriseName EstablishmentName, TwoDigitActivity NicCode, 
		case when Certification='Bronze' then '' else U.UserName end as AssessmentAgency, U.Email AgencyEmailId,
		concat('https://loginzed.msme.gov.in/Verify/BC/',QrCodeSeqNo) QrCodeSeqNo,
		UPPER(PUnitName) PUnitName, concat(C.ZedId,'_D_',C.Id) as RejectedZedId
	from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join MsmeBasicInformation B WITH (NOLOCK) on (M.ZedId=B.ZedId)
	left join Users U on (U.UserId=C.CertificationBodyUserId)
	where Certification=@CertificationType and C.ZedId=@ZedId

	END TRY

	BEGIN CATCH
			INSERT INTO ErrorLogForConsultancy (
				ErrorNumber,
				ErrorSeverity,
				ErrorState,
				ErrorProcedure,
				ErrorLine,
				ErrorMessage,
				InputZedId,
				InputCertificationType
			)
			VALUES (
				ERROR_NUMBER(),
				ERROR_SEVERITY(),
				ERROR_STATE(),
				ERROR_PROCEDURE(),
				ERROR_LINE(),
				ERROR_MESSAGE(),
				@ZedId,
				@CertificationType
			)

	END CATCH

END


GO
/****** Object:  StoredProcedure [dbo].[Sp_Daily_ERP_Auto_Reconciliation]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Sp_Daily_ERP_Auto_Reconciliation]
    @FromDate DATE = NULL,
    @ToDate DATE = NULL,
    @DaysBack INT = 30,
    @ExecuteInsert BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TodayDate DATE = CAST(GETDATE() AS DATE);

    IF @ToDate IS NULL 
        SET @ToDate = @TodayDate;

    IF @FromDate IS NULL 
        SET @FromDate = CAST(DATEADD(DAY, -@DaysBack, @ToDate) AS DATE);

    PRINT '--------------------------------------------------------------------------';
    PRINT 'Reconciliation Payment Range: ' + CONVERT(VARCHAR(10), @FromDate, 120) + ' to ' + CONVERT(VARCHAR(10), @ToDate, 120);
    PRINT 'Queue ProcessDate: ' + CONVERT(VARCHAR(10), @TodayDate, 120);
    IF @ExecuteInsert = 1
        PRINT 'Mode: EXECUTE INSERT (Records will be queued into Errors Table)';
    ELSE
        PRINT 'Mode: PREVIEW ONLY (No data will be modified)';
    PRINT '--------------------------------------------------------------------------';

    -- STEP 1: గేట్‌వే పేమెంట్లను లాగడం
    IF OBJECT_ID('tempdb..#DailyGatewayPayments') IS NOT NULL DROP TABLE #DailyGatewayPayments;
    
    SELECT 
        CAST(TrackingId AS VARCHAR(100)) AS TrackingId,
        zedid AS ZedId,
        'CONSULTANCY' AS ModuleName,
        milestonenumber AS MileStoneNo,
        Certification,
        amount AS PayableAmount,
        CreatedDate AS PaymentDate
    INTO #DailyGatewayPayments
    FROM ZED_consultant.dbo.PaymentGateWayTransactions WITH (NOLOCK)
    WHERE TrackingId IS NOT NULL 
      AND PaymentStatus = 'Success'
      AND CAST(CreatedDate AS DATE) BETWEEN @FromDate AND @ToDate
      AND amount > 1
      AND zedid NOT LIKE '%_RESET%' AND zedid NOT LIKE '%_reset%'
      AND zedid NOT LIKE '%_del%' AND zedid NOT LIKE '%_DEL%'

    UNION ALL

    SELECT 
        CAST(TrackingId AS VARCHAR(100)) AS TrackingId,
        zedid AS ZedId,
        'ZED' AS ModuleName,
        NULL AS MileStoneNo,
        Certification,
        amount AS PayableAmount,
        CreatedDate AS PaymentDate
    FROM ZEDCS_V2_LIVE.dbo.PaymentGateWayTransactions WITH (NOLOCK)
    WHERE TrackingId IS NOT NULL 
      AND PaymentStatus = 'Success'
      AND CAST(CreatedDate AS DATE) BETWEEN @FromDate AND @ToDate
      AND amount > 1
      AND zedid NOT LIKE '%_RESET%' AND zedid NOT LIKE '%_reset%'
      AND zedid NOT LIKE '%_del%' AND zedid NOT LIKE '%_DEL%'

    UNION ALL

    SELECT 
        CAST(TrackingId AS VARCHAR(100)) AS TrackingId,
        zedid AS ZedId,
        'SURVEILLANCE' AS ModuleName,
        NULL AS MileStoneNo,
        Certification,
        amount AS PayableAmount,
        CreatedDate AS PaymentDate
    FROM zed_surveillance.dbo.PaymentGateWayTransactions WITH (NOLOCK)
    WHERE TrackingId IS NOT NULL 
      AND PaymentStatus = 'Success'
      AND CAST(CreatedDate AS DATE) BETWEEN @FromDate AND @ToDate
      AND amount > 1
      AND zedid NOT LIKE '%_RESET%' AND zedid NOT LIKE '%_reset%'
      AND zedid NOT LIKE '%_del%' AND zedid NOT LIKE '%_DEL%';

    CREATE CLUSTERED INDEX IX_Temp_Gateway ON #DailyGatewayPayments(ZedId, ModuleName);

    -- STEP 2: V2 రెస్పాన్స్ లేని మిస్సింగ్ టాస్కులను లాగడం
    IF OBJECT_ID('tempdb..#MissingTasks') IS NOT NULL DROP TABLE #MissingTasks;

    -- A. CustomerData Pending
    SELECT 
        gw.ZedId,
        MAX(gw.TrackingId) AS TrackingId,
        'CustomerData' AS ApiType,
        MAX(gw.Certification) AS Certification,
        'ZED' AS ModuleName,
        NULL AS MileStoneNo,
        0.00 AS PayableAmount,
        MAX(gw.PaymentDate) AS PaymentDate
    INTO #MissingTasks
    FROM #DailyGatewayPayments gw
    WHERE NOT EXISTS (
        SELECT 1 
        FROM ApiFinanceUnitDetailsResponse resp WITH (NOLOCK)
        WHERE resp.ZedId = gw.ZedId
          AND resp.ApiType = 'CustomerData'
          AND resp.VersionNo = 'V2'
          AND resp.StatusCode IN ('200', 'OK', 'Created')
          AND (resp.SuccessResponse NOT LIKE '%"error"%' OR resp.SuccessResponse IS NULL)
          AND (resp.ErrorResponse IS NULL OR resp.ErrorResponse IN ('Created', '200', 'OK'))
          AND resp.ZedId NOT LIKE '%_del%' AND resp.ZedId NOT LIKE '%_DEL%'
          AND resp.ZedId NOT LIKE '%_RESET%' AND resp.ZedId NOT LIKE '%_reset%'
    )
    GROUP BY gw.ZedId

    UNION ALL

    -- B. InvoiceData Pending
    SELECT DISTINCT
        gw.ZedId,
        gw.TrackingId,
        'InvoiceData' AS ApiType,
        gw.Certification,
        gw.ModuleName,
        gw.MileStoneNo,
        gw.PayableAmount,
        gw.PaymentDate
    FROM #DailyGatewayPayments gw
    WHERE NOT EXISTS (
        SELECT 1 
        FROM ApiFinanceUnitDetailsResponse resp WITH (NOLOCK)
        WHERE resp.ZedId = gw.ZedId
          AND resp.ApiType = 'InvoiceData'
          AND resp.ModuleName = gw.ModuleName
          AND ISNULL(resp.MileStoneNo, 0) = ISNULL(gw.MileStoneNo, 0)
          AND resp.VersionNo = 'V2'
          AND resp.StatusCode IN ('200', 'OK', 'Created')
          AND (resp.SuccessResponse NOT LIKE '%"error"%' OR resp.SuccessResponse IS NULL)
          AND (resp.ErrorResponse IS NULL OR resp.ErrorResponse IN ('Created', '200', 'OK'))
          AND resp.ZedId NOT LIKE '%_del%' AND resp.ZedId NOT LIKE '%_DEL%'
          AND resp.ZedId NOT LIKE '%_RESET%' AND resp.ZedId NOT LIKE '%_reset%'
    )

    UNION ALL

    -- C. ReceiptData Pending
    SELECT DISTINCT
        gw.ZedId,
        gw.TrackingId,
        'ReceiptData' AS ApiType,
        gw.Certification,
        gw.ModuleName,
        gw.MileStoneNo,
        gw.PayableAmount,
        gw.PaymentDate
    FROM #DailyGatewayPayments gw
    WHERE NOT EXISTS (
        SELECT 1 
        FROM ApiFinanceUnitDetailsResponse resp WITH (NOLOCK)
        WHERE resp.ZedId = gw.ZedId
          AND resp.ApiType = 'ReceiptData'
          AND resp.ModuleName = gw.ModuleName
          AND ISNULL(resp.MileStoneNo, 0) = ISNULL(gw.MileStoneNo, 0)
          AND resp.VersionNo = 'V2'
          AND resp.StatusCode IN ('200', 'OK', 'Created')
          AND (resp.SuccessResponse NOT LIKE '%"error"%' OR resp.SuccessResponse IS NULL)
          AND (resp.ErrorResponse IS NULL OR resp.ErrorResponse IN ('Created', '200', 'OK'))
          AND resp.ZedId NOT LIKE '%_del%' AND resp.ZedId NOT LIKE '%_DEL%'
          AND resp.ZedId NOT LIKE '%_RESET%' AND resp.ZedId NOT LIKE '%_reset%'
    );

    -- STEP 3: రిజల్ట్ ప్రివ్యూ
    SELECT 
        ZedId,
        TrackingId,
        ApiType,
        ModuleName,
        MileStoneNo,
        Certification,
        PayableAmount,
        PaymentDate
    FROM #MissingTasks
    ORDER BY PaymentDate DESC, ZedId, ApiType;

    SELECT 
        ApiType,
        ModuleName,
        COUNT(1) AS Total_Pending_Tasks,
        SUM(PayableAmount) AS Total_Amount
    FROM #MissingTasks
    GROUP BY ApiType, ModuleName;

    -- STEP 4: ఇన్సర్ట్ ఆపరేషన్
    IF @ExecuteInsert = 1
    BEGIN
        INSERT INTO ApiFinanceUnitDetailsResponseErrors (
            ZedId,
            StatusCode,
            SuccessResponse,
            ErrorResponse,
            CreatedDate,
            ApiType,
            Certification,
            ModuleName,
            MileStoneNo,
            VersionNo,
            ProcessDate
        )
        SELECT 
            m.ZedId,
            NULL AS StatusCode,
            NULL AS SuccessResponse,
            NULL AS ErrorResponse,
            NULL AS CreatedDate,
            m.ApiType,
            m.Certification,
            m.ModuleName,
            m.MileStoneNo,
            'V2' AS VersionNo,
            @TodayDate AS ProcessDate -- ఎల్లప్పుడూ ఈరోజు రన్ చేసిన తేదీనే సేవ్ చేస్తుంది
        FROM #MissingTasks m
        WHERE NOT EXISTS (
            SELECT 1 
            FROM ApiFinanceUnitDetailsResponseErrors err WITH (NOLOCK)
            WHERE err.ZedId = m.ZedId
              AND err.ApiType = m.ApiType
              AND err.ModuleName = m.ModuleName
              AND ISNULL(err.MileStoneNo, 0) = ISNULL(m.MileStoneNo, 0)
              AND err.ProcessDate = @TodayDate
        );

        DECLARE @InsertedCount INT = @@ROWCOUNT;
        PRINT 'SUCCESS: Total ' + CAST(@InsertedCount AS VARCHAR(10)) + ' missing tasks queued into Errors table for ProcessDate: ' + CONVERT(VARCHAR(10), @TodayDate, 120);
    END
    ELSE
    BEGIN
        PRINT 'PREVIEW COMPLETED: Set @ExecuteInsert = 1 to queue these tasks.';
    END

    DROP TABLE #DailyGatewayPayments;
    DROP TABLE #MissingTasks;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DAILY_RUN_WEB_SITE_COUNTS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DAILY_RUN_WEB_SITE_COUNTS] 
AS
BEGIN
	SET NOCOUNT ON;
	-- 1. to avoid deadlock
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	-- 2. Variables for final totals
	DECLARE @MsmeRegistered INT = 0,
	        @BronzeCertified INT = 0,
	        @SilverCertified INT = 0,
	        @GoldCertified INT = 0,
	        @FinancialSupport DECIMAL(18,2) = 0;

	-- Variables to split up the heavy calculations cleanly
	DECLARE @MainDBSupport DECIMAL(18,2) = 0,
	        @ConsultantSupport DECIMAL(18,2) = 0,
	        @FASupport DECIMAL(18,2) = 0;

	------------------------------------------------------------
	-- STEP 1: Get Basic Registered Count (Exactly matching original tables)
	------------------------------------------------------------
	SELECT @MsmeRegistered = COUNT(*) 
	FROM Msme M 
	INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId 
	WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

	------------------------------------------------------------
	-- STEP 2: Get Certification Counts (1 Pass instead of 3)
	------------------------------------------------------------
	SELECT 
		@BronzeCertified = ISNULL(SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 AND C.DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END), 0),
		@SilverCertified = ISNULL(SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 AND C.SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END), 0),
		@GoldCertified   = ISNULL(SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 AND C.SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END), 0)
	FROM MsmeCertifications C 
	INNER JOIN MsmeBasicInformation B ON C.ZedId = B.ZedId
	WHERE C.Certification IN ('Bronze', 'Silver', 'Gold')
	  AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

	------------------------------------------------------------
	-- STEP 3: Main DB Financial Support (1 Pass instead of 3)
	------------------------------------------------------------
	SELECT @MainDBSupport = ISNULL(SUM(
		CASE 
			WHEN P.Certification = 'Bronze' THEN 10000 - P.ApplicantContributionAfterSubsidy
			WHEN P.Certification = 'Silver' THEN 40000 - P.ApplicantContributionAfterSubsidy
			WHEN P.Certification = 'Gold'   THEN 90000 - P.ApplicantContributionAfterSubsidy
			ELSE 0
		END
	), 0)
	FROM Msme M 
	INNER JOIN MsmeCertifications C ON M.ZedId = REPLACE(C.ZedId, '_D', '')
	INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
	INNER JOIN (
		SELECT DISTINCT zedid, certification, ApplicantContributionAfterSubsidy 
		FROM MsmePaymentInfo
	) P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
	WHERE C.CertificationStatus >= 2
	  AND P.Certification IN ('Bronze', 'Silver', 'Gold')
	  AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

	------------------------------------------------------------
	-- STEP 4: Consultant DB Support (1 Pass instead of 3)
	------------------------------------------------------------
	SELECT @ConsultantSupport = ISNULL(SUM(
		CASE 
			WHEN C.NcCount = 1 THEN 80000 - P.ApplicantContributionAfterSubsidy
			WHEN C.NcCount = 2 THEN 60000 - P.ApplicantContributionAfterSubsidy
			WHEN C.NcCount = 3 THEN 60000 - P.ApplicantContributionAfterSubsidy
			ELSE 0
		END
	), 0)
	FROM ZED_CONSULTANT.dbo.msme M 
	INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications C ON M.ZedId = C.ZedId
	INNER JOIN ZED_CONSULTANT.dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
	INNER JOIN (
		SELECT zedid, certification, paymentrefid, ApplicantContributionAfterSubsidy, MileStoneNum 
		FROM ZED_CONSULTANT.dbo.MsmePaymentInfo
	) P ON C.ZedId = P.ZedId AND C.Certification = P.Certification AND C.NcCount = P.MileStoneNum
	WHERE C.CertificationStatus >= 2
	  AND C.NcCount IN (1, 2, 3)
	  AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

	------------------------------------------------------------
	-- STEP 5: Financial Assistance Support
	------------------------------------------------------------
	SELECT @FASupport = ISNULL(SUM(ApproverAmount), 0) FROM FinancialAssistance WHERE ApproverAmount IS NOT NULL;

	------------------------------------------------------------
	-- STEP 6: Final Calculation and Insert
	------------------------------------------------------------
	SET @FinancialSupport = @MainDBSupport + @ConsultantSupport + @FASupport;

	BEGIN TRANSACTION;
	BEGIN TRY
		
		TRUNCATE TABLE WebSiteCounts;

		INSERT INTO WebSiteCounts (MsmeRegistered, Pledge, BronzeCertified, SilverCertified, GoldCertified, FinancialSupport, CreatedOn)
		VALUES (
			ISNULL(@MsmeRegistered, 0), 
			ISNULL(@MsmeRegistered, 0), 
			ISNULL(@BronzeCertified, 0), 
			ISNULL(@SilverCertified, 0), 
			ISNULL(@GoldCertified, 0), 
			ISNULL(@FinancialSupport, 0), 
			GETDATE()
		);

		COMMIT TRANSACTION;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK TRANSACTION;
		THROW;
	END CATCH
END
GO
