-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
create PROCEDURE [dbo].[SP_DAILY_RUN_WEB_SITE_COUNTS_backup_before_optimize] 

AS
BEGIN
	
	SET NOCOUNT ON;

	TRUNCATE TABLE WebSiteCounts

	INSERT INTO WebSiteCounts 

	SELECT
		(SELECT count(*) FROM Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) MsmeRegistered, 
		(SELECT count(*) FROM Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) Pledge, 
		(SELECT count(*) FROM MsmeCertifications C inner join MsmeBasicInformation B on (C.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=6 and DaCertificateNo is not null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) BronzeCertified, 
		(SELECT count(*) FROM MsmeCertifications C inner join MsmeBasicInformation B on (C.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=16 and SaCertificateNo is not null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) SilverCertified, 
		(SELECT count(*) FROM MsmeCertifications C inner join MsmeBasicInformation B on (C.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=16 and SaCertificateNo is not null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) GoldCertified,
	

		(select 
		(select sum(10000-ApplicantContributionAfterSubsidy)
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (replace(C.ZedId,'<redacted>','')=replace(T.ZedId,'<redacted>','') and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='<redacted>' )
		where P.Certification='Bronze' and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) 
		+
			(select sum(40000-ApplicantContributionAfterSubsidy)
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (replace(C.ZedId,'<redacted>','')=replace(T.ZedId,'<redacted>','') and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='<redacted>' )
		where P.Certification='Silver' and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915'))
		+
		(select sum(90000-ApplicantContributionAfterSubsidy)
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (replace(C.ZedId,'<redacted>','')=replace(T.ZedId,'<redacted>','') and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='<redacted>' )
		where P.Certification='Gold' and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915'))

		--+
		--(select sum(6175) from KAWACH.dbo.MsmeCertifications where CertificationStatus>=2)

		+

		(
		select isnull(sum(80000-ApplicantContributionAfterSubsidy),0)
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,MileStoneNum from ZED_CONSULTANT.dbo.MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		--left join 
		--ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='<redacted>' )
		where NcCount=1 and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		)

		+

		(
		select isnull(sum(60000-ApplicantContributionAfterSubsidy),0)
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,MileStoneNum from ZED_CONSULTANT.dbo.MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		--left join 
		--ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='<redacted>' )
		where NcCount=2 and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		)

		+

		(
		select isnull(sum(60000-ApplicantContributionAfterSubsidy),0)
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,MileStoneNum from ZED_CONSULTANT.dbo.MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		--left join 
		--ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='<redacted>' )
		where NcCount=3 and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		)


		+

		isnull((select sum(ApproverAmount) from FinancialAssistance where ApproverAmount is not null),0)
		)  FinancialSupport,

		getdate()

   
END

