		)

		+

		(
		select isnull(sum(60000-ApplicantContributionAfterSubsidy),0)
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,MileStoneNum from ZED_CONSULTANT.dbo.MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		--left join 
		--ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='<redacted>' )
		where NcCount=2 and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		)

		+

		(
		select isnull(sum(60000-ApplicantContributionAfterSubsidy),0)
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,MileStoneNum from ZED_CONSULTANT.dbo.MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		--left join 
		--ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='<redacted>' )
		where NcCount=3 and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		)


		+

		isnull((select sum(ApproverAmount) from FinancialAssistance where ApproverAmount is not null),0)
		)  FinancialSupport,

		getdate()

   
END

