/****** Object:  StoredProcedure [dbo].[SP_DAILY_RUN_WEB_SITE_COUNTS_optimized]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROCEDURE [dbo].[SP_DAILY_RUN_WEB_SITE_COUNTS_optimized] 
AS
BEGIN
    SET NOCOUNT ON;
    
    
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    -- 1. memory variables declaring
    DECLARE @MsmeRegistered INT = 0,
            @Pledge INT = 0,
            @BronzeCertified INT = 0,
            @SilverCertified INT = 0,
            @GoldCertified INT = 0,
            @FinancialSupport DECIMAL(18,2) = 0,
            @FinancialAssistanceSum DECIMAL(18,2) = 0;

    -- 2. MSME counts
    SELECT 
        @MsmeRegistered = COUNT(1),
        @Pledge = COUNT(1)
    FROM dbo.Msme M 
    INNER JOIN dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

    -- 3. certificationcounts single pass - fast read 
    SELECT 
        @BronzeCertified = SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 AND C.DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        @SilverCertified = SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 AND C.SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        @GoldCertified   = SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 AND C.SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END)
    FROM dbo.MsmeCertifications C 
    INNER JOIN dbo.MsmeBasicInformation B ON C.ZedId = B.ZedId
    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

    -- 4. financial support
    SELECT @FinancialSupport = ISNULL(SUM(
        CASE 
            WHEN P.Certification = 'Bronze' THEN (10000 - P.ApplicantContributionAfterSubsidy)
            WHEN P.Certification = 'Silver' THEN (40000 - P.ApplicantContributionAfterSubsidy)
            WHEN P.Certification = 'Gold'   THEN (90000 - P.ApplicantContributionAfterSubsidy)
            ELSE 0 
        END
    ), 0)
    FROM dbo.msme M 
    INNER JOIN dbo.MsmeCertifications C ON M.ZedId = REPLACE(C.ZedId, '_D', '') 
    INNER JOIN dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
    INNER JOIN (
        SELECT DISTINCT zedid, certification, ApplicantContributionAfterSubsidy 
        FROM dbo.MsmePaymentInfo
    ) P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
    WHERE C.CertificationStatus >= 2 
      AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

    -- 5. financial support(ZED_CONSULTANT DB)
    SELECT @FinancialSupport = @FinancialSupport + ISNULL(SUM(
        CASE 
            WHEN C.NcCount = 1 THEN (80000 - P.ApplicantContributionAfterSubsidy)
            WHEN C.NcCount = 2 THEN (60000 - P.ApplicantContributionAfterSubsidy)
            WHEN C.NcCount = 3 THEN (60000 - P.ApplicantContributionAfterSubsidy)
            ELSE 0 
        END
    ), 0)
    FROM ZED_CONSULTANT.dbo.msme M 
    INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications C ON M.ZedId = C.ZedId 
    INNER JOIN ZED_CONSULTANT.dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
    INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification AND C.NcCount = P.MileStoneNum
    WHERE C.NcCount IN (1, 2, 3) 
      AND C.CertificationStatus >= 2 
      AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915');

    -- 6. adding all financial assistance
    SELECT @FinancialAssistanceSum = ISNULL(SUM(ApproverAmount), 0) 
    FROM dbo.FinancialAssistance 
    WHERE ApproverAmount IS NOT NULL;

    SET @FinancialSupport = @FinancialSupport + @FinancialAssistanceSum;

    -- 7. atomic swap
    BEGIN TRANSACTION;
    BEGIN TRY
        
        TRUNCATE TABLE WebSiteCounts;

        INSERT INTO WebSiteCounts (
            MsmeRegistered, 
            Pledge, 
            BronzeCertified, 
            SilverCertified, 
            GoldCertified, 
            FinancialSupport
            
        )
        VALUES (
            ISNULL(@MsmeRegistered, 0),
            ISNULL(@Pledge, 0),
            ISNULL(@BronzeCertified, 0),
            ISNULL(@SilverCertified, 0),
            ISNULL(@GoldCertified, 0),
            ISNULL(@FinancialSupport, 0)
            
        );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH

END
GO
