			(select COUNT(DISTINCT M.ZedId) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(C.ZedId, '_R', ''), CONCAT('_', C.Id), '')) where (@State IS NULL OR M.PStateName=@State) AND (@Size IS NULL OR M.EnterpriseTypee=@Size) AND (@SocialCategory IS NULL OR SocialCategoryName=@SocialCategory) AND (@Gender IS NULL OR Gender=@Gender) AND UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915') AND C.CertificationStatus=16 and C.Certification='Gold') Gold
		
		OPTION (RECOMPILE);
		END

