/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS] -- '<redacted>',10
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	DECLARE @State varchar(100) = NULL;
	IF @RoleId = '8'
	BEGIN
		SELECT @State = StateCode FROM USERS WHERE UserId = @UserId AND RoleId = 8;
	END

    DECLARE @AssessmentAgencies INT = 0, @DesktopAssessors INT = 0, @SiteAssessors INT = 0, @FinancialAssessors INT = 0;
    DECLARE @FaBronzeCompleted INT = 0, @FaSilverCompleted INT = 0, @FaGoldCompleted INT = 0, @FaTotal INT = 0, @FaPending INT = 0, @FaCompleted INT = 0, @FaRejected INT = 0;

	---------------------------------------------------------------------------
	-- CATEGORY 1: ADMIN ROLES (7, 10, 8, 11, 17)
	---------------------------------------------------------------------------
	IF @RoleId IN ('7', '10', '8', '11', '17')
	BEGIN
        -- 1. Calculate User Counts
		SELECT 
            @AssessmentAgencies = ISNULL(SUM(CASE WHEN RoleId = 2 THEN 1 ELSE 0 END), 0),
            @DesktopAssessors = ISNULL(SUM(CASE WHEN RoleId = 3 AND DesktopVerification = 1 THEN 1 ELSE 0 END), 0),
            @SiteAssessors = ISNULL(SUM(CASE WHEN RoleId = 3 AND SiteVerification = 1 THEN 1 ELSE 0 END), 0),
            @FinancialAssessors = ISNULL(SUM(CASE WHEN RoleId = 3 AND FinancialVerification = 1 THEN 1 ELSE 0 END), 0)
        FROM Users WHERE RoleId IN (2, 3);

        -- 2. Calculate Financial Counts 
        SELECT 
            @FaBronzeCompleted = ISNULL(SUM(CASE WHEN CertificationType = 'Bronze' AND IsApproved = 1 THEN 1 ELSE 0 END), 0),
            @FaSilverCompleted = ISNULL(SUM(CASE WHEN CertificationType = 'Silver' AND IsApproved = 1 THEN 1 ELSE 0 END), 0),
            @FaGoldCompleted   = ISNULL(SUM(CASE WHEN CertificationType = 'Gold' AND IsApproved = 1 THEN 1 ELSE 0 END), 0),
            @FaTotal           = ISNULL(SUM(CASE WHEN VerificationStatus <> 5 THEN 1 ELSE 0 END), 0),
            @FaPending         = ISNULL(SUM(CASE WHEN VerificationStatus < 5 THEN 1 ELSE 0 END), 0),
            @FaCompleted       = ISNULL(SUM(CASE WHEN VerificationStatus = 6 THEN 1 ELSE 0 END), 0),
            @FaRejected        = ISNULL(SUM(CASE WHEN VerificationStatus = 5 THEN 1 ELSE 0 END), 0)
        FROM FinancialAssistance;

        -- 3. SINGLE PASS DEDUPLICATION (The Secret to 3-4 Second Speed)
        WITH ValidMsme AS (
            SELECT M.ZedId
            FROM Msme M
            INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
            WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
              AND (@State IS NULL OR M.StateId = @State)
        ),
        DedupedCerts AS (
            SELECT 
                VM.ZedId,
                MC.Certification,
                MC.CertificationStatus,
                -- Idi okkate ROW_NUMBER(). Ikkada manam Pending records ni venakki nettesi, 
                -- Certified records ki top Priority rank isthunnam! Rejections ni separate ga uncham.
                ROW_NUMBER() OVER (
                    PARTITION BY 
                        VM.ZedId, 
                        MC.Certification, 
                        CASE WHEN MC.CertificationStatus = 99 THEN 1 ELSE 0 END
                    ORDER BY 
                        CASE 
                            WHEN MC.CertificationStatus = 16 THEN 1 
                            WHEN MC.CertificationStatus = 6 THEN 2 
                            ELSE 3 
                        END ASC,
                        MC.Id DESC
                ) as rn
            FROM MsmeCertifications MC
            INNER HASH JOIN ValidMsme VM ON VM.ZedId = 
                CASE 
                    WHEN CHARINDEX('_D', MC.ZedId) > 0 AND (CHARINDEX('_R_', MC.ZedId) = 0 OR CHARINDEX('_D', MC.ZedId) < CHARINDEX('_R_', MC.ZedId)) 
                        THEN LEFT(MC.ZedId, CHARINDEX('_D', MC.ZedId) - 1)
                    WHEN CHARINDEX('_R_', MC.ZedId) > 0 
                        THEN LEFT(MC.ZedId, CHARINDEX('_R_', MC.ZedId) - 1)
                    ELSE MC.ZedId 
                END
        )
        -- 4. Fast Stream Output (Original ultra-fast queries that drop pending naturally)
		SELECT 
			@AssessmentAgencies AS AssessmentAgencies,
			@DesktopAssessors AS DesktopAssessors,
			@SiteAssessors AS SiteAssessors,
			@FinancialAssessors AS FinancialAssessors,

			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus = 6 THEN 1 ELSE 0 END), 0) AS BronzeCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus = 6 THEN 1 ELSE 0 END), 0) AS SilverCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus = 6 THEN 1 ELSE 0 END), 0) AS GoldCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus IN (2,3) THEN 1 ELSE 0 END), 0) AS BronzePending,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END), 0) AS SilverPending,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END), 0) AS GoldPending,
			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus <> 1 THEN 1 ELSE 0 END), 0) AS BronzeTotal,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus <> 1 THEN 1 ELSE 0 END), 0) AS SilverTotal,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus <> 1 THEN 1 ELSE 0 END), 0) AS GoldTotal,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus = 16 THEN 1 ELSE 0 END), 0) AS SaSilverCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus = 16 THEN 1 ELSE 0 END), 0) AS SaGoldCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus IN (2,3,5,6,8,9,13) THEN 1 ELSE 0 END), 0) AS SaSilverPending,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus IN (2,3,5,6,8,9,13) THEN 1 ELSE 0 END), 0) AS SaGoldPending,
			ISNULL(SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Bronze' THEN 1 ELSE 0 END), 0) AS BronzeRejected,
			ISNULL(SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Silver' THEN 1 ELSE 0 END), 0) AS SilverRejected,
			ISNULL(SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Gold' THEN 1 ELSE 0 END), 0) AS GoldRejected,
			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus IN (4,5,7) THEN 1 ELSE 0 END), 0) AS BronzeNcRaised,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END), 0) AS SilverNcRaised,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END), 0) AS GoldNcRaised,

            @FaBronzeCompleted AS FaBronzeCompleted,
            @FaSilverCompleted AS FaSilverCompleted,
            @FaGoldCompleted AS FaGoldCompleted,
            @FaTotal AS FaTotal,
            @FaPending AS FaPending,
            @FaCompleted AS FaCompleted,
            @FaRejected AS FaRejected
		FROM DedupedCerts
        WHERE rn = 1 
		OPTION (RECOMPILE);
	END

	---------------------------------------------------------------------------
	-- CATEGORY 2: AGENCY (2) OR ASSESSOR (3) ROLES
	---------------------------------------------------------------------------
	ELSE IF @RoleId IN ('2', '3')
	BEGIN
        -- 1. Calculate User Counts
		SELECT 
            @DesktopAssessors = ISNULL(SUM(CASE WHEN RoleId = 3 AND DesktopVerification = 1 THEN 1 ELSE 0 END), 0),
            @SiteAssessors = ISNULL(SUM(CASE WHEN RoleId = 3 AND SiteVerification = 1 THEN 1 ELSE 0 END), 0),
            @FinancialAssessors = ISNULL(SUM(CASE WHEN RoleId = 3 AND FinancialVerification = 1 THEN 1 ELSE 0 END), 0)
        FROM Users 
        WHERE CreatedBy = @UserId;

        -- 2. Calculate Financial Counts
        SELECT 
            @FaTotal     = ISNULL(SUM(CASE WHEN VerificationStatus <> 5 THEN 1 ELSE 0 END), 0),
            @FaPending   = ISNULL(SUM(CASE WHEN VerificationStatus < 5 THEN 1 ELSE 0 END), 0),
            @FaCompleted = ISNULL(SUM(CASE WHEN VerificationStatus = 6 THEN 1 ELSE 0 END), 0),
            @FaRejected  = ISNULL(SUM(CASE WHEN VerificationStatus = 5 THEN 1 ELSE 0 END), 0)
        FROM FinancialAssistance
        WHERE (@RoleId = '2' AND CertificationBodyUserId = @UserId)
           OR (@RoleId = '3' AND FinancialAssessorId = @UserId);

        -- 3. SINGLE PASS DEDUPLICATION
        ;WITH FilteredCerts AS (
            SELECT 
                CASE 
                    WHEN CHARINDEX('_D', ZedId) > 0 AND (CHARINDEX('_R_', ZedId) = 0 OR CHARINDEX('_D', ZedId) < CHARINDEX('_R_', ZedId)) 
                        THEN LEFT(ZedId, CHARINDEX('_D', ZedId) - 1)
                    WHEN CHARINDEX('_R_', ZedId) > 0 
                        THEN LEFT(ZedId, CHARINDEX('_R_', ZedId) - 1)
                    ELSE ZedId 
                END AS BaseZedId,
                Certification, CertificationStatus, Id,
                CASE WHEN DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END AS HasDaCert,
                CASE WHEN SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END AS HasSaCert
            FROM MsmeCertifications
            WHERE (@RoleId = '2' AND CertificationBodyUserId = @UserId)
               OR (@RoleId = '3' AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId))
        ),
        DedupedCerts AS (
            SELECT 
                BaseZedId, Certification, CertificationStatus, HasDaCert, HasSaCert,
                ROW_NUMBER() OVER (
                    PARTITION BY 
                        BaseZedId, 
                        Certification, 
                        CASE WHEN CertificationStatus = 99 THEN 1 ELSE 0 END
                    ORDER BY 
                        CASE 
                            WHEN HasSaCert = 1 THEN 1 
                            WHEN HasDaCert = 1 THEN 2 
                            ELSE 3 
                        END ASC,
                        Id DESC
                ) as rn
            FROM FilteredCerts
        )
        -- 4. Fast Output
		SELECT 
			0 AS AssessmentAgencies,
			@DesktopAssessors AS DesktopAssessors,
			@SiteAssessors AS SiteAssessors,
			@FinancialAssessors AS FinancialAssessors,

			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND HasDaCert = 1 THEN 1 ELSE 0 END), 0) AS BronzeCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND HasDaCert = 1 THEN 1 ELSE 0 END), 0) AS SilverCompleted,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND HasDaCert = 1 THEN 1 ELSE 0 END), 0) AS GoldCompleted,
			
			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND HasDaCert = 0 AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END), 0) AS BronzePending,
			
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND HasDaCert = 0 AND CertificationStatus < 6 
				AND ((@RoleId = '2' AND CertificationStatus > 2) OR (@RoleId <> '2' AND CertificationStatus > 0)) THEN 1 ELSE 0 END), 0) AS SilverPending,
			
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND HasDaCert = 0 AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END), 0) AS GoldPending,
			
			ISNULL(SUM(CASE WHEN Certification = 'Bronze' THEN 1 ELSE 0 END), 0) AS BronzeTotal,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' THEN 1 ELSE 0 END), 0) AS SilverTotal,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' THEN 1 ELSE 0 END), 0) AS GoldTotal,
			
			ISNULL(SUM(CASE WHEN HasSaCert = 1 AND Certification = 'Silver' THEN 1 ELSE 0 END), 0) AS SaSilverCompleted,
			ISNULL(SUM(CASE WHEN HasSaCert = 0 AND Certification = 'Silver' THEN 1 ELSE 0 END), 0) AS SaSilverPending,
			ISNULL(SUM(CASE WHEN HasSaCert = 1 AND Certification = 'Gold' THEN 1 ELSE 0 END), 0) AS SaGoldCompleted,
			ISNULL(SUM(CASE WHEN HasSaCert = 0 AND Certification = 'Gold' THEN 1 ELSE 0 END), 0) AS SaGoldPending,
			
			ISNULL(SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Bronze' THEN 1 ELSE 0 END), 0) AS BronzeRejected,
			ISNULL(SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Silver' THEN 1 ELSE 0 END), 0) AS SilverRejected,
			ISNULL(SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Gold' THEN 1 ELSE 0 END), 0) AS GoldRejected,
			
			ISNULL(SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus IN (4,5,7) THEN 1 ELSE 0 END), 0) AS BronzeNcRaised,
			ISNULL(SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END), 0) AS SilverNcRaised,
			ISNULL(SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END), 0) AS GoldNcRaised,

            @FaTotal AS FaTotal,
            @FaPending AS FaPending,
            @FaCompleted AS FaCompleted,
            @FaRejected AS FaRejected
		FROM DedupedCerts
        WHERE rn = 1
		OPTION (RECOMPILE);
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_OLD]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_DASHBOARD_GET_DETAILS] '<redacted>','<redacted>'
CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS_OLD] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	
		DECLARE @State varchar(100) =NULL

		IF @State IS NULL OR @State=''
		BEGIN
		SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		END

		IF @RoleId=7 OR @RoleId=10 OR @RoleId=8 OR @RoleId=11
		BEGIN
				

				SELECT (select count(*) from Users where RoleId=2) AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1) DesktopAssessors, (select count(*) from Users where RoleId=3 and SiteVerification=1) SiteAssessors,  
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1) FinancialAssessors,
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus=6 AND (@State is null or M.StateId=@State)) BronzeCompleted,
			   (select count(*) from FinancialAssistance where CertificationType='Bronze' and IsApproved=1) FaBronzeCompleted,

			   (		
				--(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>') and Certification='<redacted>' and CertificationStatus<6 and CertificationStatus>1 AND (@State is null or M.StateId=@State))) BronzePending,
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus in (2,3) AND (@State is null or M.StateId=@State))) BronzePending,
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=6 AND (@State is null or M.StateId=@State)) SilverCompleted, 
			   (select count(*) from FinancialAssistance where CertificationType='Silver' and IsApproved=1) FaSilverCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus<6 and CertificationStatus>1 AND (@State is null or M.StateId=@State)) SilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=6 AND (@State is null or M.StateId=@State)) GoldCompleted,
			   (select count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1) FaGoldCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus<6 and CertificationStatus>1 AND (@State is null or M.StateId=@State)) GoldPending,

			   --(select count(*) from Msme where IsBronzePaymentDone=1 AND (@State is null or StateId=@State)) BronzeTotal, 

			   --(select count(*) from Msme where IsSilverPaymentDone=1 AND (@State is null or StateId=@State)) SilverTotal, 

			   --(select count(*) from Msme where IsGoldPaymentDone=1 AND (@State is null or StateId=@State)) GoldTotal,


			   (select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) 
			   inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
			   inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				where P.Certification='Bronze' AND CertificationStatus!=1 AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) BronzeTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId)
				 inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
			     inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				where P.Certification='Silver' AND CertificationStatus!=1 AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) SilverTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId)
				 inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
			     inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				where P.Certification='Gold' AND CertificationStatus!=1 AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) GoldTotal,

			   (select count(*) from FinancialAssistance where VerificationStatus!=5) FaTotal,
			   (select count(*) from FinancialAssistance where VerificationStatus<5) FaPending,
			   (select count(*) from FinancialAssistance where VerificationStatus=6) FaCompleted,
			    (select count(*) from FinancialAssistance where VerificationStatus=5) FaRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (@State is null or M.StateId=@State)) SaSilverCompleted, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (@State is null or M.StateId=@State)) SaGoldCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus in (2,3,5,6,8,9,13) AND (@State is null or M.StateId=@State)) SaSilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus in (2,3,5,6,8,9,13) AND (@State is null or M.StateId=@State)) SaGoldPending,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationStatus=99 AND (@State is null or M.StateId=@State)) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationStatus=99 AND (@State is null or M.StateId=@State)) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationStatus=99 AND (@State is null or M.StateId=@State)) GoldRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus in (4,5,7) AND (@State is null or M.StateId=@State)) BronzeNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus in (14,15,17) AND (@State is null or M.StateId=@State)) SilverNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus in (14,15,17) AND (@State is null or M.StateId=@State)) GoldNcRaised
			  

		END

		ELSE IF @RoleId=2
		BEGIN
		SELECT 0 AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId) DesktopAssessors, 
			   (select count(*) from Users where RoleId=3 and SiteVerification=1 and  CreatedBy=@UserId) SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null ) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1) BronzePending, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) SilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>2) SilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) GoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1) GoldPending,

			   (select count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is not null) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaSilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is not null) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaGoldPending,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) SilverTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) GoldTotal,
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1 and  CreatedBy=@UserId) FinancialAssessors,

			   (select count(*) from FinancialAssistance where VerificationStatus!=5 and CertificationBodyUserId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where VerificationStatus<5  and CertificationBodyUserId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where VerificationStatus=6  and CertificationBodyUserId=@UserId) FaCompleted,
			   (select count(*) from FinancialAssistance where VerificationStatus=5  and CertificationBodyUserId=@UserId) FaRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) where Certification='Bronze' and CertificationStatus=99 and CertificationBodyUserId=@UserId) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) where Certification='Silver' and CertificationStatus=99 and  CertificationBodyUserId=@UserId) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) where Certification='Gold' and CertificationStatus=99 and CertificationBodyUserId=@UserId) GoldRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus in (4,5,7) and CertificationBodyUserId=@UserId) BronzeNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus in (14,15,17) and CertificationBodyUserId=@UserId) SilverNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus in (14,15,17) and CertificationBodyUserId=@UserId) GoldNcRaised

		END

		ELSE IF @RoleId=3
		BEGIN
		SELECT 0 AssessmentAgencies,
			   0 DesktopAssessors,	
			   0 SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null and CertificationStatus<5) BronzePending, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is not null) SilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null) SilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null) GoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null) GoldPending,

			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null) SaSilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null) SaGoldPending,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) SilverTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) GoldTotal,

			    (select count(*) from FinancialAssistance where VerificationStatus!=5 and FinancialAssessorId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where VerificationStatus<5  and FinancialAssessorId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where VerificationStatus=6  and FinancialAssessorId=@UserId) FaCompleted,
			   (select count(*) from FinancialAssistance where VerificationStatus=5  and FinancialAssessorId=@UserId) FaRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) where Certification='Silver' and CertificationStatus=99 and  (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldRejected,

			   			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus in (4,5,7) and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) BronzeNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus in (14,15,17) and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus in (14,15,17) and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldNcRaised

		END
		

END





GO
