/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_testing_Sk]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS_testing_Sk] --'<redacted>', 10
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	DECLARE @State varchar(100) = NULL;
	IF @RoleId = '8'
	BEGIN
		SELECT @State = StateCode FROM USERS WHERE UserId = @UserId AND RoleId = 8;
	END

	---------------------------------------------------------------------------
	-- CATEGORY 1: ADMIN ROLES (7, 10, 8, 11)
	---------------------------------------------------------------------------
	IF @RoleId IN ('7', '10', '8', '11', '17')
	BEGIN
		SELECT 
			(SELECT COUNT(*) FROM Users WHERE RoleId = 2) AS AssessmentAgencies,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND DesktopVerification = 1) AS DesktopAssessors,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND SiteVerification = 1) AS SiteAssessors,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND FinancialVerification = 1) AS FinancialAssessors,
			C.*, 
			F.*
		FROM (
			SELECT 
				SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus = 6 THEN 1 ELSE 0 END) AS BronzeCompleted,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus = 6 THEN 1 ELSE 0 END) AS SilverCompleted,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus = 6 THEN 1 ELSE 0 END) AS GoldCompleted,
				SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus IN (2,3) THEN 1 ELSE 0 END) AS BronzePending,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END) AS SilverPending,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END) AS GoldPending,
				SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus <> 1 THEN 1 ELSE 0 END) AS BronzeTotal,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus <> 1 THEN 1 ELSE 0 END) AS SilverTotal,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus <> 1 THEN 1 ELSE 0 END) AS GoldTotal,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus = 16 THEN 1 ELSE 0 END) AS SaSilverCompleted,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus = 16 THEN 1 ELSE 0 END) AS SaGoldCompleted,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus IN (2,3,5,6,8,9,13) THEN 1 ELSE 0 END) AS SaSilverPending,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus IN (2,3,5,6,8,9,13) THEN 1 ELSE 0 END) AS SaGoldPending,
				SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Bronze' THEN 1 ELSE 0 END) AS BronzeRejected,
				SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Silver' THEN 1 ELSE 0 END) AS SilverRejected,
				SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Gold' THEN 1 ELSE 0 END) AS GoldRejected,
				SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus IN (4,5,7) THEN 1 ELSE 0 END) AS BronzeNcRaised,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END) AS SilverNcRaised,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END) AS GoldNcRaised
			--FROM MsmeCertifications MC
			--CROSS APPLY (SELECT CHARINDEX('<redacted>', MC.ZedId) AS Pos) AS CheckD
			--CROSS APPLY (SELECT CASE WHEN CheckD.Pos > 0 THEN LEFT(MC.ZedId, CheckD.Pos - 1) ELSE MC.ZedId END AS CleanZedId) AS P
			--INNER JOIN Msme M ON P.CleanZedId = M.ZedId
			--INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
			--WHERE B.UdyogAadharNo NOT IN ('<redacted>','<redacted>','<redacted>','<redacted>')

			--FROM MsmeCertifications MC
			--CROSS APPLY (SELECT CHARINDEX('<redacted>', MC.ZedId) AS PosD,CHARINDEX('<redacted>', MC.ZedId) AS PosR) AS CheckD
			--CROSS APPLY (SELECT CASE 
   --         WHEN CheckD.PosD > 0 AND (CheckD.PosR = 0 OR CheckD.PosD < CheckD.PosR) 
   --             THEN LEFT(MC.ZedId, CheckD.PosD - 1)
   --         WHEN CheckD.PosR > 0 
   --             THEN LEFT(MC.ZedId, CheckD.PosR - 1)
   --         ELSE MC.ZedId
   --          END AS CleanZedId
		 --   ) AS P
			--INNER JOIN Msme M ON P.CleanZedId = M.ZedId
			--INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
			--WHERE B.UdyogAadharNo NOT IN ('<redacted>','<redacted>','<redacted>','<redacted>')


			FROM MsmeCertifications MC
CROSS APPLY (
    SELECT 
        CASE 
            WHEN CHARINDEX('_D', MC.ZedId) > 0 
                 AND (CHARINDEX('_R_', MC.ZedId) = 0 
                      OR CHARINDEX('_D', MC.ZedId) < CHARINDEX('_R_', MC.ZedId))
                THEN LEFT(MC.ZedId, CHARINDEX('_D', MC.ZedId) - 1)
            WHEN CHARINDEX('_R_', MC.ZedId) > 0 
                THEN LEFT(MC.ZedId, CHARINDEX('_R_', MC.ZedId) - 1)
            ELSE MC.ZedId
        END AS CleanZedId
) AS P
INNER JOIN Msme M ON P.CleanZedId = M.ZedId
INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

			
			AND (@State IS NULL OR M.StateId = @State)
		) AS C
		CROSS JOIN (
			SELECT 
				SUM(CASE WHEN CertificationType = 'Bronze' AND IsApproved = 1 THEN 1 ELSE 0 END) AS FaBronzeCompleted,
				SUM(CASE WHEN CertificationType = 'Silver' AND IsApproved = 1 THEN 1 ELSE 0 END) AS FaSilverCompleted,
				SUM(CASE WHEN CertificationType = 'Gold' AND IsApproved = 1 THEN 1 ELSE 0 END) AS FaGoldCompleted,
				SUM(CASE WHEN VerificationStatus <> 5 THEN 1 ELSE 0 END) AS FaTotal,
				SUM(CASE WHEN VerificationStatus < 5 THEN 1 ELSE 0 END) AS FaPending,
				SUM(CASE WHEN VerificationStatus = 6 THEN 1 ELSE 0 END) AS FaCompleted,
				SUM(CASE WHEN VerificationStatus = 5 THEN 1 ELSE 0 END) AS FaRejected
			FROM FinancialAssistance
		) AS F
		OPTION (RECOMPILE);
	END

	---------------------------------------------------------------------------
	-- CATEGORY 2: AGENCY (2) OR ASSESSOR (3) ROLES
	---------------------------------------------------------------------------
	ELSE IF @RoleId IN ('2', '3')
	BEGIN
		SELECT 
			0 AS AssessmentAgencies,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND DesktopVerification = 1 AND CreatedBy = @UserId) AS DesktopAssessors,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND SiteVerification = 1 AND CreatedBy = @UserId) AS SiteAssessors,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND FinancialVerification = 1 AND CreatedBy = @UserId) AS FinancialAssessors,
			UC.*, 
			UF.*
		FROM (
			SELECT 
				SUM(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS BronzeCompleted,
				SUM(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SilverCompleted,
				SUM(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS GoldCompleted,
				
				SUM(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NULL AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END) AS BronzePending,
				
				SUM(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NULL AND CertificationStatus < 6 
					AND ((@RoleId = '2' AND CertificationStatus > 2) OR (@RoleId <> '2' AND CertificationStatus > 0)) THEN 1 ELSE 0 END) AS SilverPending,
				
				SUM(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NULL AND CertificationStatus < 6 AND CertificationStatus > 1 THEN 1 ELSE 0 END) AS GoldPending,
				
				SUM(CASE WHEN Certification = 'Bronze' THEN 1 ELSE 0 END) AS BronzeTotal,
				SUM(CASE WHEN Certification = 'Silver' THEN 1 ELSE 0 END) AS SilverTotal,
				SUM(CASE WHEN Certification = 'Gold' THEN 1 ELSE 0 END) AS GoldTotal,
				
				SUM(CASE WHEN SaCertificateNo IS NOT NULL AND Certification = 'Silver' THEN 1 ELSE 0 END) AS SaSilverCompleted,
				SUM(CASE WHEN SaCertificateNo IS NULL AND Certification = 'Silver' THEN 1 ELSE 0 END) AS SaSilverPending,
				SUM(CASE WHEN SaCertificateNo IS NOT NULL AND Certification = 'Gold' THEN 1 ELSE 0 END) AS SaGoldCompleted,
				SUM(CASE WHEN SaCertificateNo IS NULL AND Certification = 'Gold' THEN 1 ELSE 0 END) AS SaGoldPending,
				
				SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Bronze' THEN 1 ELSE 0 END) AS BronzeRejected,
				SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Silver' THEN 1 ELSE 0 END) AS SilverRejected,
				SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Gold' THEN 1 ELSE 0 END) AS GoldRejected,
				
				SUM(CASE WHEN Certification = 'Bronze' AND CertificationStatus IN (4,5,7) THEN 1 ELSE 0 END) AS BronzeNcRaised,
				SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END) AS SilverNcRaised,
				SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus IN (14,15,17) THEN 1 ELSE 0 END) AS GoldNcRaised
			FROM MsmeCertifications
			WHERE (@RoleId = '2' AND CertificationBodyUserId = @UserId)
			   OR (@RoleId = '3' AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId))
		) AS UC
		CROSS JOIN (
			SELECT 
				SUM(CASE WHEN VerificationStatus <> 5 THEN 1 ELSE 0 END) AS FaTotal,
				SUM(CASE WHEN VerificationStatus < 5 THEN 1 ELSE 0 END) AS FaPending,
				SUM(CASE WHEN VerificationStatus = 6 THEN 1 ELSE 0 END) AS FaCompleted,
				SUM(CASE WHEN VerificationStatus = 5 THEN 1 ELSE 0 END) AS FaRejected
			FROM FinancialAssistance
			WHERE (@RoleId = '2' AND CertificationBodyUserId = @UserId)
			   OR (@RoleId = '3' AND FinancialAssessorId = @UserId)
		) AS UF
		OPTION (RECOMPILE);
	END
END
