-- =============================================
CREATE PROCEDURE [dbo].[SP_DASHBOARD_REGISTERED_MSME_testing] --null, null, 28,'<redacted>',null,10,null,'<redacted>',null, null
(
	
	@ZedId varchar(50) = NULL,
	@Status varchar(50) =null,
	@State varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@PageSize int = 25000
	
	
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @PageSize is null OR @PageSize > 25000 
	set @PageSize = 25000

	IF @PageNo is null 
	set @PageNo = 1
	
	IF @State='' 
	SET @State = NULL

	IF @CertificationType='' 
	SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	IF @State IS NULL OR @State=''
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	 print @PageSize 
	 print @PageNo
	 
	SELECT P.Id,M.ZedId,Certification,EvidenceSubmissionDate,CertificationBodyUserId,
		AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
			when CertificationStatus=1 then 'Payment done By MSME'
			when CertificationStatus=2 then 'Evidence upload done by MSME'
			when CertificationStatus=3 then 'DA Verification in progress'
			when CertificationStatus=4 then 'DA Verification done with errors'
			when CertificationStatus=5 then 'DA Verification done without errors'
			when CertificationStatus=6 then 'Agency Final submit done for DA'
			when CertificationStatus=7 then 'Failed in NC'
			when CertificationStatus=8 then 'SA Allocation Done'
			when CertificationStatus=9 then 'SA is ready to start'
			when CertificationStatus=13 then 'SA Verification in progress'
			when CertificationStatus=14 then 'SA Verification done with errors'
			when CertificationStatus=15 then 'SA verification done without errors'
			when CertificationStatus=16 then 'Agency Final submit for SA' 
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,

		case when CertificationBodyUserId is null and AcceptOrRejectDate is null then 'Not allotted to Agency'
			when CertificationBodyUserId is not null and AcceptOrRejectDate is null then 'Agency to be approve'
			when CertificationBodyUserId is not null and P.ReasonForRejection is not null then 'Agency is rejected'
			when CertificationBodyUserId is not null and DesktopAssessorId is not null and DesktopAcceptOrRejectDate is null then 'Allocated to Assessor'
			when CertificationBodyUserId is not null and DesktopAssessorId is not null and DesktopAcceptOrRejectDate is not null and DesktopReasonForRejection is not null then 'Assessor Rejected'
			when CertificationBodyUserId is not null and DesktopAssessorId is not null and DesktopAccepted=1 then 'Assessor Accepted' 
		end as AllocationStatus,
				
		DaCertificateNo,SaCertificateNo,
		CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
		P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin, M.EnterpriseName, U.UserName,
		M.CreatedDate RegisteredDate, M.PUnitName,
		ROW_NUMBER() OVER (order by M.msmeId desc) as RowNumber
    
	FROM Msme M
	inner JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
	left join MsmeCertifications P on (P.ZedId=M.ZedId)
	LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
	
	WHERE (@State is null or M.StateId=@State) --AND CertificationStatus=@Status
	AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
	ORDER By M.MsmeId desc
	offset ((@PageNo-1) * @PageSize) rows fetch next @PageSize rows only

	

END



