/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_ASSESSOR_COMMENTS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_ASSESSOR_COMMENTS]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	select ZedId,	PUnitName,Certification,
case when Certificationstatus=16 then 'Certified' 
	 when Certificationstatus=15 then 'Quality Check'
	 when Certificationstatus=14 then 'NC Raised'
	 when Certificationstatus=17 then 'In Partial Rejection'
	 when Certificationstatus=99 then 'REJECTED' END AS CertificationStatusName,
	SectionCode,	SectionName,	RequirementCode,	RequirementName,SaConformance,
[0] [SaAssessorRemarks in Nc0],	[1] [SaAssessorRemarks in Nc1],
[2] [SaAssessorRemarks in Nc2],	[3] [SaAssessorRemarks in Nc3],
[4] [SaAssessorRemarks in Nc4],	[5] [SaAssessorRemarks in Nc5],
TwoDigitActivity
from (
select C.ZedId,PUnitName,Certification,Certificationstatus,SaConformance, TwoDigitActivity, S.SectionCode,s.SectionName,R.RequirementCode,O.optionname RequirementName,R.nccount,r.saAssessorRemarks
from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
Inner join MsmeSections S on (C.ZedId=S.ZedId and C.Certification=s.SectionType and (isassessmentexcempted is null or isassessmentexcempted='No'))
Inner join MsmeRequirements  R on (C.ZedId=R.ZedId and C.Certification=R.SectionType and S.SectionCode=R.SectionCode and ((c.Certificationstatus>13 and r.nccount=0) OR (C.NC1STATUS=2 AND R.NCCOUNT=1) OR (C.NC2STATUS=2 AND R.NCCOUNT=2) OR (C.NC3STATUS=2 AND R.NCCOUNT=3) OR (C.NC1STATUS=4 AND R.NCCOUNT=4) OR (C.Nc5STATUS=2 AND R.NCCOUNT=5)))
inner join MsmeOptions O on (C.ZedId=O.ZedId and C.Certification=O.SectionType and R.SectionCode=O.SectionCode and R.RequirementCode=O.RequirementCode)
--inner join AssessorComments A On (C.ZedId=A.ZedId and C.Certification=A.Certification)
where C.certification!='Bronze' and CertificationStatus>13) A
pivot
(
max(saassessorremarks) for NcCount in ([0],[1],[2],[3],[4],[5])
) as P
order by ZedId,CAST(SectionCode AS INT), 
    CAST(RequirementCode AS INT)

END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_BRONZE_SURVEILLANCE_2025_26]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_BRONZE_SURVEILLANCE_2025_26] --NULL,'<redacted>',10
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL,
    @StartDate Date='2025-04-01', 
    @EndDate Date='2026-03-31'
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Status Descriptions and History
    ;WITH StatusDescriptions AS (
        SELECT Descrip, MonitoringGetList 
        FROM CertificationStatuses 
    ),
    SurveillanceHistory AS (
        SELECT zedid, CertificationType, MIN(CreatedDate) as MinCreatedDate
        FROM ZED_SURVEILLANCE.dbo.msmehistory 
        WHERE StatusType IN ('BasicInfoStatus')
        GROUP BY zedid, CertificationType
    )

    -- 2. Main Data Body (Bronze Surveillance Only)
    SELECT 
        M.ZedId, 
        PUnitName, 
        Paddress AS UnitAddress, 
        PStateName, 
        PDistrictName, 
        Ppin AS Pincode, 
        M.EnterpriseTypee AS EnterpriseType, 
        M.OldEnterpriseType, 
        P.EnterpriseTypee AS PaymentEnterpriseType, 
        C.Certification,
        CASE 
            WHEN C.CertificationStatus = 99 THEN 'Bronze Surveillance Rejected'
            WHEN C.CertificationStatus = 6 THEN 'Bronze Surveillance Certified'
            ELSE CONCAT(UPPER(C.Certification), ' SURVEILLANCE - ', ISNULL(S.MonitoringGetList, 'In Progress'))
        END AS ZedIdStatus,
        P.Total AS CertificationFee, 
        ApplicantContributionAfterSubsidy, 
        T.Amount AS AmountPaid, 
        (P.Total - ApplicantContributionAfterSubsidy) AS FinancialSupport,
        CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
        T.TanNumber, 
        T.Tds, 
        P.UseCoupon AS JoiningReward, 
        SubsidyPercentage, 
        Gender, 
        SocialCategoryName, 
        B.PanNo,
        DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
        DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
        DATEDIFF(DAY, '18991230', 
            CASE 
                WHEN C.CertificationStatus = 99 THEN C.CertificationStatusDate
                WHEN C.CertificationStatus = 6 THEN C.CertificationStatusDate
                ELSE NULL 
            END) AS [Certified/RejectedDate],
        DATEDIFF(DAY, '18991230', H.MinCreatedDate) AS DocumentUploadDate,
        NULL AS ApproverDateOfReceiptOfPayment
    FROM ZED_SURVEILLANCE.DBO.msme M
    INNER JOIN ZED_SURVEILLANCE.DBO.MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(C.Zedid,'_D',''), CONCAT('_',C.Id),''))
    INNER JOIN ZED_SURVEILLANCE.DBO.MsmeBasicInformation B ON M.ZedId = B.ZedId
    INNER JOIN ZED_SURVEILLANCE.DBO.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
    LEFT JOIN ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
    LEFT JOIN SurveillanceHistory H ON C.zedid = H.zedid AND H.CertificationType = C.certification
    LEFT JOIN StatusDescriptions S ON C.CertificationStatus = S.Descrip
    WHERE C.Certification = 'Bronze'
      AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
      --AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
      AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
    ORDER BY M.ZedId;

END
