/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_CERTIFIED_MSME]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-----[SP_DYNAMIC_REPORT_LIST_OF_CERTIFIED_MSME]  NULL,'<redacted>',2
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_CERTIFIED_MSME] -- NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL ----------------------
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
		SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	

		SELECT P.Id,M.ZedId,Certification,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			M.CreatedDate ReigstrationDate,
			-- U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			--UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			--Us.UserName as SiteAssessor, P.SiteAssessorId,
			--UC.UserName as coAssessor, P.CoAssessorId,
			PStateName StateName,PDistrictName DistrictName,  M.PUnitName,B.EnterpriseTypee as EnterpriseType, B.Gender, ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,
			DaCertificateNo,SaCertificateNo,
			--CertificationStatusDate CertificationDate
			DATEDIFF(DAY, '18991230', CertificationStatusDate) CertificationDate
		

		FROM Msme M
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		--where CertificationStatus in (6,16)
		where ((CertificationStatus=6 and Certification='Bronze') OR (CertificationStatus=16 and Certification IN ('Silver','Gold')))
		AND (@State is null or M.StateId=@State)
		and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		ORDER By M.MsmeId desc
	END

	ELSE IF @RoleId=2
	BEGIN
		--SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	

		SELECT M.ZedId,Certification,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,B.UdyogAadharNo UdyamNumber,
			M.CreatedDate ReigstrationDate,
			 U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			Us.UserName as SiteAssessor, P.SiteAssessorId,
			UC.UserName as coAssessor, P.CoAssessorId,
			PStateName StateName,PDistrictName DistrictName,  M.PUnitName,M.MobileNo,M.EmailId,TwoDigitActivity,  B.EnterpriseTypee as EnterpriseType, B.Gender, ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,			
			--CertificationStatusDate CertificationDate,
			DATEDIFF(DAY, '18991230', A.CreatedDate) AS AllotedDate,
			DATEDIFF(DAY, '18991230', CertificationStatusDate) CertificationDate,
			NcCount
			--A.AllotType,
			
			
		

		FROM Msme M
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)

		LEFT JOIN (SELECT AAH.ZedId, AAH.AgencyId, AAH.AllotType, AAH.CreatedDate, ROW_NUMBER() OVER (PARTITION BY AAH.ZedId, AAH.AgencyId ORDER BY AAH.CreatedDate DESC) AS rn
        FROM AgencyAllotmentHistory AAH
	    ) A ON A.ZedId = M.ZedId AND A.AgencyId = P.CertificationBodyUserId AND A.rn = 1

		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		where ((CertificationStatus=6 and Certification='Bronze') OR (CertificationStatus=16 and Certification IN ('Silver','Gold')))
		AND (@State is null or M.StateId=@State)
		AND CertificationBodyUserId=@UserId
		and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		ORDER By M.MsmeId desc
	END
	
	ELSE IF (@RoleId=10 OR @RoleId=11)
	BEGIN
		
		SELECT P.Id,M.ZedId,Certification,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			M.CreatedDate ReigstrationDate,
			 U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			Us.UserName as SiteAssessor, P.SiteAssessorId,
			UC.UserName as coAssessor, P.CoAssessorId,
			PStateName StateName,PDistrictName DistrictName,PPin PinCode,  M.PUnitName,B.EnterpriseTypee as EnterpriseType,TwoDigitActivity, B.Gender,B.SocialCategoryName SocialCategory, ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,
			DaCertificateNo,SaCertificateNo,
			--CertificationStatusDate CertificationDate,
			DATEDIFF(DAY, '18991230', CertificationStatusDate) CertificationDate,
			NcCount
		

		FROM Msme M
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		where ((CertificationStatus=6 and Certification='Bronze') OR (CertificationStatus=16 and Certification IN ('Silver','Gold')))
		AND (@State is null or M.StateId=@State)
		and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		ORDER By M.MsmeId desc
	END

	ELSE
		BEGIN
		SELECT NULL DATAS
		END

END


GO
