		DECLARE @state varchar(100) = NULL

		IF @RoleId = 8
		BEGIN
			SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		END

			SELECT 
			P.Id,M.ZedId,Certification,M.CreatedDate as RegisteredDate,
			DaCertificateNo WASHCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,PCity,PStateName StateNam,PDistrictName DistrictName, EnterpriseName,
			--P.CertificationStatusDate CertificationDate
			DATEDIFF(DAY, '18991230', P.CertificationStatusDate) CertificationDate
		
		
			FROM kawach.dbo.Msme M
			left join kawach.dbo.MsmeCertifications P on (P.ZedId=M.ZedId)
			LEFT JOIN kawach.dbo.Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN kawach.dbo.Users UA on (P.DesktopAssessorId=UA.UserId)
			WHERE CertificationStatus=6
			AND (@State is null or StateId=@State) AND (@RoleId=10 or @RoleId=8)
			ORDER By MsmeId desc
		


END

GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_DATE_MSME_NEW_BRONZE]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME]  NULL,'<redacted>',10
Create PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_DATE_MSME_NEW_BRONZE]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	--DATEDIFF(DAY, '<redacted>', s)
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	IF @RoleId = 10
	BEGIN
		SELECT M.ZedId,DATEDIFF(DAY, '18991230', M.CreatedDate) as RegistrationDate,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Registered'			
				when CertificationStatus=1 then 'Payment Received'
				when CertificationStatus=2 then 'Evidence uploaded'
				when CertificationStatus=3 then 'DA in progress'
				when CertificationStatus=4 then 'NC raised in DA'
				when CertificationStatus=5 then 'DA Completed'
				when (certification='Bronze' and CertificationStatus=6) then 'Certified' 
				when (certification in ('Silver','Gold') and CertificationStatus=6) then 'QC Completed'
				when CertificationStatus in (7,99) then 'Rejected'
				when CertificationStatus=8 then 'SA Planned'
				when CertificationStatus=9 then 'SA Planned'
				when CertificationStatus=13 then 'SA in progress'
				when CertificationStatus=14 then 'NC raised in SA'
				when CertificationStatus=15 then 'SA Completed'
				when (certification='Silver' and CertificationStatus=16) then 'Silver Certified' 
				when (certification='Gold' and CertificationStatus=16) then 'Gold Certified' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
			end as AssessmentStatus,
				BasicInfoStatus DocsubmissionDate,
				DATEDIFF(DAY, '18991230', DocVerifiAllot) DocVerifiAllot,
				DATEDIFF(DAY, '18991230', AssessmentDate) OnAssessmentDate,
				DATEDIFF(DAY, '18991230', [Nc1Raised]) [Nc1Raised],
				DATEDIFF(DAY, '18991230', [Nc1Submitted]) [Nc1Submitted],
				DATEDIFF(DAY, '18991230', [Nc2Raised]) [Nc2Raised],
				DATEDIFF(DAY, '18991230', [Nc2Submitted]) [Nc2Submitted],
				DATEDIFF(DAY, '18991230', [Nc3Raised]) [Nc3Raised],
				DATEDIFF(DAY, '18991230', [Nc3Submitted]) [Nc3Submitted],
				DATEDIFF(DAY, '18991230', [Nc4Raised]) [Nc4Raised],
				DATEDIFF(DAY, '18991230', [Nc4Submitted]) [Nc4Submitted],
				DATEDIFF(DAY, '18991230', [Nc5Raised]) [Nc5Raised],
				DATEDIFF(DAY, '18991230', [Nc5Submitted]) [Nc5Submitted],
				DATEDIFF(DAY, '18991230', [NcClosed]) [NcClosed],
				DATEDIFF(DAY, '18991230', CompletedOn) CompletedOn,
			PUnitName,	case when Certification is null and IsBronzePaymentDone=1 then 'Bronze'
			when Certification is null and IsSilverPaymentDone=1 then 'Silver' when Certification is null and IsGoldPaymentDone=1 then 'Gold' else Certification end as Certification,
		M.OwnerName,	M.EnterpriseTypee,	M.MobileNo, U.UserName as AgencyName, P.DesktopAssessorId,P.SiteAssessorId,P.CoAssessorId,
		M.EmailId, TwoDigitActivity,
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	PAddress,	PStateName,	PDistrictName
		
	

		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)
		
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State) 
		and (CertificationStatus IS NULL OR (NOT (CertificationStatus = 16 OR (CertificationStatus = 6 AND Certification = 'Bronze')))) 
		--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		ORDER By M.MsmeId desc
	END

	ELSE IF @RoleId=2
	BEGIN
		SELECT M.ZedId,DATEDIFF(DAY, '18991230', M.CreatedDate) as RegistrationDate, US.UserName as DesktopAssessorName, UK.UserName as SiteAssessorName,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Registered'			
				when CertificationStatus=1 then 'Payment Received'
				when CertificationStatus=2 then 'Evidence uploaded'
				when CertificationStatus=3 then 'DA in progress'
				when CertificationStatus=4 then 'NC raised in DA'
				when CertificationStatus=5 then 'DA Completed'
				when (certification='Bronze' and CertificationStatus=6) then 'Certified' 
				when (certification in ('Silver','Gold') and CertificationStatus=6) then 'QC Completed'
				when CertificationStatus in (7,99) then 'Rejected'
				when CertificationStatus=8 then 'SA Planned'
				when CertificationStatus=9 then 'SA Planned'
				when CertificationStatus=13 then 'SA in progress'
				when CertificationStatus=14 then 'NC raised in SA'
				when CertificationStatus=15 then 'SA Completed'
				when (certification='Silver' and CertificationStatus=16) then 'Silver Certified' 
				when (certification='Gold' and CertificationStatus=16) then 'Gold Certified' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
			end as AssessmentStatus,
				DATEDIFF(DAY, '18991230', BasicInfoStatus)  DocsubmissionDate,
				DATEDIFF(DAY, '18991230', DocVerifiAllot) DocVerifiAllot,
				DATEDIFF(DAY, '18991230', AssessmentDate) OnAssessmentDate,
				DATEDIFF(DAY, '18991230', [Nc1Raised]) [Nc1Raised],
				DATEDIFF(DAY, '18991230', [Nc1Submitted]) [Nc1Submitted],
				DATEDIFF(DAY, '18991230', [Nc2Raised]) [Nc2Raised],
				DATEDIFF(DAY, '18991230', [Nc2Submitted]) [Nc2Submitted],
				DATEDIFF(DAY, '18991230', [Nc3Raised]) [Nc3Raised],
				DATEDIFF(DAY, '18991230', [Nc3Submitted]) [Nc3Submitted],
				DATEDIFF(DAY, '18991230', [Nc4Raised]) [Nc4Raised],
				DATEDIFF(DAY, '18991230', [Nc4Submitted]) [Nc4Submitted],
				DATEDIFF(DAY, '18991230', [Nc5Raised]) [Nc5Raised],
				DATEDIFF(DAY, '18991230', [Nc5Submitted]) [Nc5Submitted],
				DATEDIFF(DAY, '18991230', [NcClosed]) [NcClosed],
				DATEDIFF(DAY, '18991230', CompletedOn) CompletedOn,
			PUnitName,	case when Certification is null and IsBronzePaymentDone=1 then 'Bronze'
			when Certification is null and IsSilverPaymentDone=1 then 'Silver' when Certification is null and IsGoldPaymentDone=1 then 'Gold' else Certification end as Certification,
		M.OwnerName,	M.EnterpriseTypee,	M.MobileNo,
		M.EmailId,	TwoDigitActivity,	
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,		PAddress,	PStateName,	PDistrictName
		
	

		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)		
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users US on (P.DesktopAssessorId=US.UserId)
		LEFT JOIN Users UK on (P.SiteAssessorId=UK.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State) AND CertificationBodyUserId=@Userid 
		and (CertificationStatus IS NULL OR (NOT (CertificationStatus = 16 OR (CertificationStatus = 6 AND Certification = 'Bronze')))) 
		--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		ORDER By M.MsmeId desc
	END

	ELSE IF (@RoleId=8 OR @RoleId=11)
	BEGIN
		SELECT M.ZedId,DATEDIFF(DAY, '18991230', M.CreatedDate) as RegistrationDate,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Registered'			
				when CertificationStatus=1 then 'Payment Received'
				when CertificationStatus=2 then 'Evidence uploaded'
				when CertificationStatus=3 then 'DA in progress'
				when CertificationStatus=4 then 'NC raised in DA'
				when CertificationStatus=5 then 'DA Completed'
				when (certification='Bronze' and CertificationStatus=6) then 'Certified' 
				when (certification in ('Silver','Gold') and CertificationStatus=6) then 'QC Completed'
				when CertificationStatus in (7,99) then 'Rejected'
				when CertificationStatus=8 then 'SA Planned'
				when CertificationStatus=9 then 'SA Planned'
				when CertificationStatus=13 then 'SA in progress'
				when CertificationStatus=14 then 'NC raised in SA'
				when CertificationStatus=15 then 'SA Completed'
				when (certification='Silver' and CertificationStatus=16) then 'Silver Certified' 
				when (certification='Gold' and CertificationStatus=16) then 'Gold Certified' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
			end as AssessmentStatus,
		--NULL AssessmentStatus,
				DATEDIFF(DAY, '18991230', BasicInfoStatus)  DocsubmissionDate,
				DATEDIFF(DAY, '18991230', DocVerifiAllot) DocVerifiAllot,
				DATEDIFF(DAY, '18991230', AssessmentDate) OnAssessmentDate,
				DATEDIFF(DAY, '18991230', [Nc1Raised]) [Nc1Raised],
				DATEDIFF(DAY, '18991230', [Nc1Submitted]) [Nc1Submitted],
				DATEDIFF(DAY, '18991230', [Nc2Raised]) [Nc2Raised],
				DATEDIFF(DAY, '18991230', [Nc2Submitted]) [Nc2Submitted],
				DATEDIFF(DAY, '18991230', [Nc3Raised]) [Nc3Raised],
				DATEDIFF(DAY, '18991230', [Nc3Submitted]) [Nc3Submitted],
				DATEDIFF(DAY, '18991230', [Nc4Raised]) [Nc4Raised],
				DATEDIFF(DAY, '18991230', [Nc4Submitted]) [Nc4Submitted],
				DATEDIFF(DAY, '18991230', [Nc5Raised]) [Nc5Raised],
				DATEDIFF(DAY, '18991230', [Nc5Submitted]) [Nc5Submitted],
				DATEDIFF(DAY, '18991230', [NcClosed]) [NcClosed],
				DATEDIFF(DAY, '18991230', CompletedOn) CompletedOn,
			PUnitName,	case when Certification is null and IsBronzePaymentDone=1 then 'Bronze'
			when Certification is null and IsSilverPaymentDone=1 then 'Silver' when Certification is null and IsGoldPaymentDone=1 then 'Gold' else Certification end as Certification,
		M.OwnerName,	M.EnterpriseTypee,	M.MobileNo,
		M.EmailId,	TwoDigitActivity,	
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,		PAddress,	PStateName,	PDistrictName
		
		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)		
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State) 
		and (CertificationStatus IS NULL OR (NOT (CertificationStatus = 16 OR (CertificationStatus = 6 AND Certification = 'Bronze')))) 
		--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		ORDER By M.MsmeId desc
	END

	ELSE
	BEGIN

	SELECT NULL DATAS

	END

