/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_DUPLICATE_UDYAM_PADDRESS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_DUPLICATE_UDYAM_PADDRESS]  --NULL,null,3
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME
	IF @RoleId = 10
	BEGIN
	
			SET NOCOUNT ON;

			SELECT 
			M.ZedId,
			M.CreatedDate AS RegistrationDate,
			B.UdyogAadharNo,
			Y.PAddress,
			M.PStateName,
			M.PDistrictName,
			M.PUnitName,
			M.OwnerName,
			M.EnterpriseTypee,
			M.MobileNo,
			M.EmailId,
			B.SocialCategoryName,
			B.Gender,
			M.SameUdyamAddress
		FROM 
			Msme M
		INNER JOIN
		(
			SELECT 
				M.PAddress, 
				B.UdyogAadharNo, 
				COUNT(*) AS counts
			FROM 
				Msme M
			INNER JOIN 
				MsmeBasicInformation B 
			ON 
				M.ZedId = B.ZedId
			GROUP BY 
				M.PAddress, 
				B.UdyogAadharNo
			HAVING 
				COUNT(*) > 1
		) Y 
		ON 
			M.PAddress = Y.PAddress
		INNER JOIN 
			MsmeBasicInformation B 
		ON 
			M.ZedId = B.ZedId 
			AND B.UdyogAadharNo = Y.UdyogAadharNo
			
		ORDER BY 
			B.UdyogAadharNo, 
			M.PAddress
	END

END


