/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_AND_TECH_SUPPORT_ZEDIDS_WITH_DATES]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_AND_TECH_SUPPORT_ZEDIDS_WITH_DATES] -- NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME1

	SET NOCOUNT ON;

	IF @RoleId=10 OR @RoleId=11
	BEGIN
	

		
		--select null,null,null,isnull(FApproverAmount,0) FinancialSupport
		select F.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, CertificationType Certification,
		'Financial Support' as ZedStatus, null,null,null, isnull(ApproverAmount,0) FinancialSupport,
		null,null,null,null,null,Gender,SocialCategoryName,B.PanNo,
		NULL RegdDate,
		NULL PaymentDate,
		NULL AS [Certified/RejectedDate],
		NULL as DocumentUploadDate,
		DATEDIFF(DAY, '18991230', ApproverDateOfReceiptOfPayment) AS ApproverDateOfReceiptOfPayment
		from FinancialAssistance F left join Msme m on (F.ZedId=M.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		where isnull(ApproverAmount,0)>0 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		UNION ALL

		
		--select null,null,null,isnull(FApproverAmount,0) FinancialSupport
		select F.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, CertificationType Certification,
		'Technology Support' as ZedStatus, null,null,null, isnull(ApproverAmount,0) FinancialSupport, null PanNo,
		null,null,null,null,null,Gender,SocialCategoryName,
		NULL RegdDate,
		NULL PaymentDate,
		NULL AS [Certified/RejectedDate],
		NULL as DocumentUploadDate,
		DATEDIFF(DAY, '18991230', ApproverDateOfReceiptOfPayment) AS ApproverDateOfReceiptOfPayment
		from ZED_CONSULTANT.dbo.FinancialAssistance F left join ZED_CONSULTANT.dbo.Msme m on (F.ZedId=M.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		where isnull(ApproverAmount,0)>0 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		

		order by F.ZedId
		
	END

	ELSE
	BEGIN
		select NULL DATAS
		
	END

END


