/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_PAID_ZEDIDS_2025_26]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_PAID_ZEDIDS_2025_26]  --NULL,'<redacted>',10
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL,
    @StartDate Date='2025-04-01', 
    @EndDate Date='2026-03-31'
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Document Upload Dates to avoid scalar subqueries in the main loop
    ;WITH HistoryDates AS (
        SELECT zedid, CertificationType, StatusType, MIN(CreatedDate) as MinCreatedDate
        FROM msmehistory 
        WHERE StatusType IN ('BasicInfoStatus')
        GROUP BY zedid, CertificationType, StatusType
    ),
    ConsultantHistoryDates AS (
        SELECT zedid, CertificationType, StatusType, NcCount, MIN(CreatedDate) as MinCreatedDate
        FROM ZED_CONSULTANT.dbo.msmehistory 
        WHERE StatusType = 'ApplicationReceived'
        GROUP BY zedid, CertificationType, StatusType, NcCount
    )

    -- 2. Main Data Body
   SELECT * FROM (
        -- BRONZE, SILVER, GOLD (Standard)
        SELECT 
            M.ZedId, PUnitName, Paddress AS UnitAddress, PStateName, PDistrictName, Ppin AS Pincode, 
            M.EnterpriseTypee AS EnterpriseType, M.OldEnterpriseType,P.EnterpriseTypee AS PaymentEnterpriseType, C.Certification,
			
            CASE 
                WHEN C.CertificationStatus = 99 THEN 'Rejected'
                --WHEN C.CertificationStatus IN (6, 16) THEN '<redacted>' 
				WHEN ((C.CertificationStatus=6 and C.certification='Bronze') OR (C.CertificationStatus=16 and C.certification!='Bronze')) THEN 'Certified' 
                ELSE 'Active' 
            END AS ZedIdStatus, 
            P.Total AS CertificationFee, ApplicantContributionAfterSubsidy, T.Amount AS AmountPaid, 
            (P.Total - ApplicantContributionAfterSubsidy) AS FinancialSupport,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
            T.TanNumber, T.Tds, P.UseCoupon AS JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
            DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
            DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus IN (6, 16, 99) THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
            DATEDIFF(DAY, '18991230', H.MinCreatedDate) AS DocumentUploadDate,
            NULL AS ApproverDateOfReceiptOfPayment
        FROM msme M 
        INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(C.Zedid,'_D',''), CONCAT('_',C.Id),''))
        INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        INNER JOIN PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        LEFT JOIN HistoryDates H ON C.zedid = H.zedid AND H.CertificationType = C.certification
        WHERE C.Certification IN ('Bronze', 'Silver', 'Gold')
          AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
		  and B.ReCertification<=1
          AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

        UNION ALL

        -- CONSULTANT MILESTONES (1, 2, 3)
        SELECT 
            M.ZedId, PUnitName, Paddress, PStateName, PDistrictName, Ppin, M.EnterpriseTypee,M.OldEnterpriseType,P.EnterpriseTypee AS PaymentEnterpriseType, C.Certification,
            CONCAT('Milestone ', C.NcCount) AS ZedIdStatus, 
            CASE WHEN C.NcCount = 1 THEN 80000 ELSE 60000 END AS CertificationFee,
            ApplicantContributionAfterSubsidy, T.Amount, 
            (CASE WHEN C.NcCount = 1 THEN 80000 ELSE 60000 END - ApplicantContributionAfterSubsidy) AS FinancialSupport,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END,
            T.TanNumber, T.Tds, P.UseCoupon, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate), DATEDIFF(DAY, '18991230', P.CreatedDate),
            DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus IN (16, 100) THEN C.CertificationStatusDate ELSE NULL END),
            DATEDIFF(DAY, '18991230', CH.MinCreatedDate), NULL
        FROM ZED_CONSULTANT.dbo.msme M
        INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications C ON M.ZedId = C.ZedId
        INNER JOIN ZED_CONSULTANT.dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification AND C.NcCount = P.MileStoneNum
        INNER JOIN ZED_CONSULTANT.dbo.PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND P.MileStoneNum = T.MileStoneNumber AND T.PaymentStatus = 'Success'
        LEFT JOIN ConsultantHistoryDates CH ON C.zedid = CH.zedid AND CH.CertificationType = C.certification AND CH.NcCount = C.NcCount
        WHERE C.NcCount IN (1, 2, 3) AND C.CertificationStatus >= 2
          AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

        UNION ALL

        -- SURVEILLANCE DATA
        SELECT 
            M.ZedId, PUnitName, Paddress, PStateName, PDistrictName, Ppin, M.EnterpriseTypee,M.OldEnterpriseType,P.EnterpriseTypee AS PaymentEnterpriseType, C.Certification,
            CASE WHEN C.CertificationStatus = 99 THEN 'Surveillance Rejected' 
			--WHEN C.CertificationStatus = 16 THEN '<redacted>' ELSE '<redacted>' END,
			WHEN ((C.CertificationStatus=6 and C.certification='Bronze') OR (C.CertificationStatus=16 and C.certification!='Bronze')) THEN 'Surveillance Certified' 
			ELSE 'Surveillance Active' END,
            P.Total, ApplicantContributionAfterSubsidy, T.Amount, (P.Total - ApplicantContributionAfterSubsidy),
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END,
            T.TanNumber, T.Tds, P.UseCoupon, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate), DATEDIFF(DAY, '18991230', P.CreatedDate),
            DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus IN (16, 99) THEN C.CertificationStatusDate ELSE NULL END),
            DATEDIFF(DAY, '18991230', H.MinCreatedDate), NULL
        FROM ZED_SURVEILLANCE.DBO.msme M
        INNER JOIN ZED_SURVEILLANCE.DBO.MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(C.Zedid,'_D',''), CONCAT('_',C.Id),''))
        INNER JOIN ZED_SURVEILLANCE.DBO.MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN ZED_SURVEILLANCE.DBO.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        INNER JOIN ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        LEFT JOIN HistoryDates H ON C.zedid = H.zedid AND H.CertificationType = C.certification -- Assuming local history table used for surveillance lookup as per original
        WHERE C.Certification IN ('Silver', 'Gold')
          AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
          AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		--   UNION ALL

		--select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, C.Certification, '<redacted>' as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		----T.UnitGstin,
		--case WHEN P.UnitGstin = '<redacted>' THEN T.Gstin WHEN P.UnitGstin = '<redacted>' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		--T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		--DATEDIFF(DAY, '<redacted>', M.CreatedDate) AS RegdDate,
		--DATEDIFF(DAY, '<redacted>', P.CreatedDate) AS PaymentDate,
		--DATEDIFF(DAY, '<redacted>', C.CertificationStatusDate) AS [Certified/RejectedDate],
		--(select top 1 DATEDIFF(DAY, '<redacted>', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='<redacted>') 
		--as DocumentUploadDate,
		--NULL AS ApproverDateOfReceiptOfPayment
		--from msme M inner join MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'<redacted>',''),concat('<redacted>',C.Id),'')) 
		--inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		--inner join 
		--MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='<redacted>' )
		--where P.Certification!='<redacted>' and CertificationStatus=16 and B.ReCertification>1
		----and YEAR(P.CreatedDate) between @StartYear and @EndYear
		--AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
		--and UdyogAadharNo NOT IN ('<redacted>', '<redacted>', '<redacted>','<redacted>')

		---------RECERTIFIED UNITS LIST END -----------------------------

  ) FinalResult
    ORDER BY ZedId;

END
