/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME1

	SET NOCOUNT ON;

	IF @RoleId=10 OR @RoleId=11
	BEGIN
	
		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName, Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' else 'Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName
		from msme M inner join MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,SubsidyPercentage,UseCoupon,Total from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus>=2 and CertificationStatus<=90 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		UNION ALL

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' else 'Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName
		from msme M inner join MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,SubsidyPercentage ,UseCoupon,MsmePmtCertId,Total from MsmePaymentInfo) P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus=99 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		
		union all

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Silver' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' else 'Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
