/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_APPLIED_FOR_RECERTIFICATION]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_APPLIED_FOR_RECERTIFICATION]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL,
	@StartDate Date='2025-04-01', 
    @EndDate Date='2026-03-31'
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME1

	SET NOCOUNT ON;

	--DECLARE @StartYear INT = YEAR(@StartDate);
    --DECLARE @EndYear INT = YEAR(@EndDate);

	IF @RoleId=10 OR @RoleId=11
	BEGIN
	SELECT  
    M.ZedId,
    M.PUnitName,
    M.Paddress AS UnitAddress,
    M.PStateName,
    M.PDistrictName,
    M.Ppin AS Pincode,
    M.EnterpriseTypee AS EnterpriseType,
    P.Certification,
     CASE 
                WHEN C.CertificationStatus = 99 THEN 'Rejected'
                --WHEN C.CertificationStatus IN (6, 16) THEN '<redacted>' 
				WHEN ((C.CertificationStatus=6 and C.certification='Bronze') OR (C.CertificationStatus=16 and C.certification!='Bronze')) THEN 'Certified' 
                ELSE 'Active' 
            END AS ZedIdStatus,
    P.Total CertificationFee,
    P.ApplicantContributionAfterSubsidy,
    T.Amount AS AmountPaid,
    P.Total - P.ApplicantContributionAfterSubsidy AS FinancialSupport,

    CASE 
        WHEN P.UnitGstin = 'Yes' THEN T.Gstin
        WHEN P.UnitGstin = 'No' THEN NULL
        ELSE P.UnitGstin
    END AS UnitGstin,

    T.TanNumber,
    T.Tds,
    P.UseCoupon AS JoiningReward,
    P.SubsidyPercentage,
    B.Gender,
    B.SocialCategoryName,
    B.PanNo,

    DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
    DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
    DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Certified/RejectedDate],
    H.DocumentUploadDate,
    NULL AS ApproverDateOfReceiptOfPayment

FROM Msme M
INNER JOIN MsmeBasicInformation B 
    ON M.ZedId = B.ZedId

INNER JOIN MsmePaymentInfo P 
    ON P.ZedId = B.ZedId
   AND P.Certification = B.LastestCertification

LEFT JOIN PaymentGateWayTransactions T 
    ON T.ZedId = P.ZedId
   AND T.Certification = P.Certification
   AND T.PaymentRefId = P.PaymentRefId
   AND T.PaymentStatus = 'Success'

LEFT JOIN MsmeCertifications C 
    ON C.ZedId = P.ZedId
   AND C.Certification = P.Certification

OUTER APPLY
(
    SELECT TOP 1 
        DATEDIFF(DAY, '18991230', H.CreatedDate) AS DocumentUploadDate
    FROM MsmeHistory H
    WHERE H.ZedId = C.ZedId
      AND H.CertificationType = C.Certification
      AND H.StatusType = 'BasicInfoStatus'
    ORDER BY H.CreatedDate
) H

WHERE B.Recertification > 1
  AND B.UdyogAadharNo NOT IN (
        'UDYAM-GJ-01-0013310',
        'UDYAM-MH-23-0006117',
        'UDYAM-UP-29-0003915',
        'UDYAM-UP-16-0001476'
  );

		
	END

	ELSE
	BEGIN
		select NULL DATAS
		
	END

END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CERT_GOLD]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CERT_GOLD]  --NULL,'<redacted>',10
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Document Upload Dates
    ;WITH HistoryDates AS (
        SELECT zedid, CertificationType, StatusType, MAX(CreatedDate) as MinCreatedDate
        FROM msmehistory 
        WHERE StatusType IN ('BasicInfoStatus')
        GROUP BY zedid, CertificationType, StatusType
    ),
 
	StatusDescriptions AS (
        SELECT Descrip, MonitoringGetList 
        FROM CertificationStatuses 
    ),

    -- 2. Fetch all raw data and apply Row Number for deduplication
    RawReportData AS (
        SELECT 
            M.ZedId, PUnitName, Paddress AS UnitAddress, PStateName, PDistrictName, Ppin AS Pincode, 
            M.EnterpriseTypee AS EnterpriseType,M.OldEnterpriseType,
			
		    case when p.EnterpriseTypee  = 'REJECTED' then b.EnterpriseTypee else P.EnterpriseTypee end as PaymentEnterpriseType,

			C.Certification,
   
            -- FIX 1: Prioritize '<redacted>' label for Excel filtering
			CASE
			WHEN C.CertificationStatus = 99 THEN 'Rejected'
			WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
			  OR (C.Certification IN ('Gold') AND C.CertificationStatus = 16) THEN 'Certified'
            WHEN C.ZedId LIKE '%\_R\_%' ESCAPE '\' THEN 'Certified & Re-applied'
			ELSE CONCAT(UPPER(C.Certification), ' - ', ISNULL(S.MonitoringGetList, 'Active'))
		    END AS ZedIdStatus,

            P.Total AS CertificationFee, ApplicantContributionAfterSubsidy, T.Amount AS AmountPaid, 
            (P.Total - ApplicantContributionAfterSubsidy-isnull(P.StateContributionAfterSubsidy,0.00)) AS GoIContribution,
			isnull(P.StateContributionAfterSubsidy,0.00) StateGovtContribution,
			SubsidyPercentage GoISubsidyPercentage,
			isnull(P.StateSubsidyPercentage,0.00) StateGovtSubsidyPercentage,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
            T.TanNumber, T.Tds, P.UseCoupon AS JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
            DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
            DATEDIFF(DAY, '18991230', 
			CASE 
				WHEN C.CertificationStatus = 99 THEN C.CertificationStatusDate
				WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN C.CertificationStatusDate
				WHEN C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16 THEN C.CertificationStatusDate
				ELSE NULL 
			END) AS [Certified/RejectedDate],
            DATEDIFF(DAY, '18991230', H.MinCreatedDate) AS DocumentSubmissionDate,
            NULL AS ApproverDateOfReceiptOfPayment,
            
            -- FIX 2: Rank records to eliminate duplicates (prioritizing status 16)
           ROW_NUMBER() OVER(
                PARTITION BY M.ZedId, CASE WHEN C.CertificationStatus = 99 THEN 1 ELSE 0 END
                ORDER BY 
                    CASE WHEN C.CertificationStatus = 16 THEN 1 ELSE 2 END ASC, 
                    C.Id DESC
            ) as rn

        FROM msme M 
		INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, '_R', ''), '_D', ''), CONCAT('_', C.Id), ''))
        INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
        
        -- FIX 3: Changed to LEFT JOIN to prevent data loss if payment record is missing
        LEFT JOIN MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        
        LEFT JOIN PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        LEFT JOIN HistoryDates H ON C.zedid = H.zedid AND H.CertificationType = C.certification
		LEFT JOIN StatusDescriptions S ON C.CertificationStatus = S.Descrip
        
        WHERE C.Certification IN ('Gold')
          AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
    )

    -- 3. Output only the correct deduplicated record (rn = 1)
    SELECT 
        ZedId, PUnitName, UnitAddress, PStateName, PDistrictName, Pincode, 
        EnterpriseType, OldEnterpriseType, PaymentEnterpriseType,
        Certification, ZedIdStatus, CertificationFee, ApplicantContributionAfterSubsidy, AmountPaid, 
         GoIContribution,
		StateGovtContribution,GoISubsidyPercentage,StateGovtSubsidyPercentage, UnitGstin, TanNumber, Tds, JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, PanNo,
        RegdDate, PaymentDate, [Certified/RejectedDate], DocumentSubmissionDate--, ApproverDateOfReceiptOfPayment
    FROM RawReportData
    WHERE rn = 1
    ORDER BY ZedId;

END
GO
