--[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CERT_SILVER]  NULL,'<redacted>',10

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CERT_SILVER] 
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Document Upload Dates
    ;WITH HistoryDates AS (
        SELECT zedid, CertificationType, StatusType, max(CreatedDate) as MinCreatedDate
        FROM msmehistory 
        WHERE StatusType IN ('BasicInfoStatus')
        GROUP BY zedid, CertificationType, StatusType
    ),
 
	StatusDescriptions AS (
        SELECT Descrip, MonitoringGetList 
        FROM CertificationStatuses 
    ),

    -- 2. Fetch all raw data
    RawReportData AS (
        SELECT 
            M.ZedId, PUnitName, Paddress AS UnitAddress, PStateName, PDistrictName, Ppin AS Pincode, 
            M.EnterpriseTypee AS EnterpriseType,M.OldEnterpriseType,
			
		    case when p.EnterpriseTypee  = 'REJECTED' then b.EnterpriseTypee else P.EnterpriseTypee end as PaymentEnterpriseType,

			C.Certification,
   
            -- FIX 2: Moved Certified logic above the Re-applied logic so the Excel filter works correctly
			CASE
			WHEN C.CertificationStatus = 99 THEN 'Rejected'
			WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
			  OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16) THEN 'Certified'
            WHEN C.ZedId LIKE '%\_R\_%' ESCAPE '\' THEN 'Certified & Re-applied'
			ELSE CONCAT(UPPER(C.Certification), ' - ', ISNULL(S.MonitoringGetList, 'Active'))
		    END AS ZedIdStatus,

            P.Total AS CertificationFee, ApplicantContributionAfterSubsidy, T.Amount AS AmountPaid, 
            (P.Total - ApplicantContributionAfterSubsidy-isnull(P.StateContributionAfterSubsidy,0.00)) AS GoIContribution,
			isnull(P.StateContributionAfterSubsidy,0.00) StateGovtContribution,
			SubsidyPercentage GoISubsidyPercentage,
			isnull(P.StateSubsidyPercentage,0.00) StateGovtSubsidyPercentage ,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
            T.TanNumber, T.Tds, P.UseCoupon AS JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
            DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
            DATEDIFF(DAY, '18991230', 
			CASE 
				WHEN C.CertificationStatus = 99 THEN C.CertificationStatusDate
				WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN C.CertificationStatusDate
				WHEN C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16 THEN C.CertificationStatusDate
				ELSE NULL 
			END) AS [Certified/RejectedDate],
            DATEDIFF(DAY, '18991230', H.MinCreatedDate) AS DocumentSubmissionDate,
          --  NULL AS ApproverDateOfReceiptOfPayment,
            
            -- FIX 3: Prioritize Status 16 rows. If they are renewing, it still pulls their certified row.
            ROW_NUMBER() OVER(
                PARTITION BY M.ZedId, CASE WHEN C.CertificationStatus = 99 THEN 1 ELSE 0 END
                ORDER BY 
                    CASE WHEN C.CertificationStatus = 16 THEN 1 ELSE 2 END ASC, 
                    C.Id DESC
            ) as rn

        FROM msme M 
		INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, '_R', ''), '_D', ''), CONCAT('_', C.Id), ''))
        INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
        -- FIX 1: Changed to LEFT JOIN so MSMEs missing payment records aren't deleted
        LEFT JOIN MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        LEFT JOIN PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        LEFT JOIN HistoryDates H ON C.zedid = H.zedid AND H.CertificationType = C.certification
		LEFT JOIN StatusDescriptions S ON C.CertificationStatus = S.Descrip
        
        WHERE C.Certification IN ('Silver')
          AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
    )

    -- 3. Output only the correct deduplicated record
    SELECT 
        ZedId, PUnitName, UnitAddress, PStateName, PDistrictName, Pincode, 
        EnterpriseType, OldEnterpriseType, PaymentEnterpriseType,
        Certification, ZedIdStatus, CertificationFee, ApplicantContributionAfterSubsidy, AmountPaid, 
        GoIContribution,
		StateGovtContribution,GoISubsidyPercentage,StateGovtSubsidyPercentage,
		UnitGstin, TanNumber, Tds, JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, PanNo,
        RegdDate, PaymentDate, [Certified/RejectedDate], DocumentSubmissionDate --, ApproverDateOfReceiptOfPayment
    FROM RawReportData
    WHERE rn = 1
    ORDER BY ZedId;

END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CERT_SILVER_old]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CERT_SILVER_old] -- NULL,'<redacted>',10
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL
    --@StartDate Date='<redacted>', 
    --@EndDate Date='<redacted>'
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Document Upload Dates to avoid scalar subqueries in the main loop
    ;WITH HistoryDates AS (
        SELECT zedid, CertificationType, StatusType, MIN(CreatedDate) as MinCreatedDate
        FROM msmehistory 
        WHERE StatusType IN ('BasicInfoStatus')
        GROUP BY zedid, CertificationType, StatusType
    ),
 
	StatusDescriptions AS (
    SELECT Descrip, MonitoringGetList 
    FROM CertificationStatuses -- Replace with your actual table name if different
)

        SELECT 
            M.ZedId, PUnitName, Paddress AS UnitAddress, PStateName, PDistrictName, Ppin AS Pincode, 
            M.EnterpriseTypee AS EnterpriseType,M.OldEnterpriseType,
			--P.EnterpriseTypee AS PaymentEnterpriseType, 
		case when p.EnterpriseTypee  = 'REJECTED' then b.EnterpriseTypee else P.EnterpriseTypee end as PaymentEnterpriseType,

			C.Certification,
   --     

			CASE
			WHEN C.ZedId LIKE '%\_R\_%' ESCAPE '\' THEN 'Certified & Re-applied'
			WHEN C.CertificationStatus = 99 THEN 'Rejected'
			WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
			  OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16) THEN 'Certified'
			ELSE CONCAT(UPPER(C.Certification), ' - ', ISNULL(S.MonitoringGetList, 'Active'))
		END AS ZedIdStatus,



            P.Total AS CertificationFee, ApplicantContributionAfterSubsidy, T.Amount AS AmountPaid, 
            (P.Total - ApplicantContributionAfterSubsidy) AS FinancialSupport,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
            T.TanNumber, T.Tds, P.UseCoupon AS JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
            DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
           DATEDIFF(DAY, '18991230', 
			CASE 
				WHEN C.CertificationStatus = 99 THEN C.CertificationStatusDate
				WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN C.CertificationStatusDate
				WHEN C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16 THEN C.CertificationStatusDate
				ELSE NULL 
			END) AS [Certified/RejectedDate],
            DATEDIFF(DAY, '18991230', H.MinCreatedDate) AS DocumentUploadDate,
            NULL AS ApproverDateOfReceiptOfPayment
        FROM msme M 
        --INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(C.Zedid,'<redacted>',''), CONCAT('<redacted>',C.Id),''))
		INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, '_R', ''), '_D', ''), CONCAT('_', C.Id), ''))

        INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        LEFT JOIN PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        LEFT JOIN HistoryDates H ON C.zedid = H.zedid AND H.CertificationType = C.certification
		LEFT JOIN StatusDescriptions S ON C.CertificationStatus = S.Descrip
        WHERE C.Certification IN ('Silver')
		--and B.ReCertification<=1
          AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
          --AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')


    ORDER BY ZedId;

END
GO
