		UNION ALL

		
		--select null,null,null,isnull(FApproverAmount,0) FinancialSupport
		select F.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, CertificationType Certification,
		'Financial Support' as ZedStatus, null,null,null, isnull(ApproverAmount,0) FinancialSupport,
		null,null,null,null,null,Gender,SocialCategoryName,B.PanNo,
		NULL RegdDate,
		NULL PaymentDate,
		NULL AS [Certified/RejectedDate],
		NULL as DocumentUploadDate,
		DATEDIFF(DAY, '18991230', ApproverDateOfReceiptOfPayment) AS ApproverDateOfReceiptOfPayment,NULL CertificationStatus
		from FinancialAssistance F left join Msme m on (F.ZedId=M.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		where isnull(ApproverAmount,0)>0 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		UNION ALL

		  
	    select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, C.Certification, 'Milestone 1' as ZedIdStatus, 80000 CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, 80000-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN (C.CertificationStatus=16 OR C.CertificationStatus=100) THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from ZED_CONSULTANT.dbo.msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='ApplicationReceived' and NcCount=1) 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		ZED_CONSULTANT.dbo.MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		left join 
		ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='Success' )
		where NcCount=1 and CertificationStatus>=2 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		UNION ALL

		--select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType,  C.Certification, M.ZedId,'<redacted>' as ZedIdStatus, 60000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 60000-ApplicantContributionAfterSubsidy FinancialSupport
		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, C.Certification, 'Milestone 2' as ZedIdStatus, 60000 CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, 60000-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN (C.CertificationStatus=16 OR C.CertificationStatus=100) THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from ZED_CONSULTANT.dbo.msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='ApplicationReceived' and NcCount=2) 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		ZED_CONSULTANT.dbo.MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		left join 
		ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='Success' )
		where NcCount=2 and CertificationStatus>=2 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		union all

		--select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType,  C.Certification, M.ZedId,'<redacted>' as ZedIdStatus, 60000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 60000-ApplicantContributionAfterSubsidy FinancialSupport
		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, C.Certification, 'Milestone 3' as ZedIdStatus, 60000 CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, 60000-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN (C.CertificationStatus=16 OR C.CertificationStatus=100) THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from ZED_CONSULTANT.dbo.msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='ApplicationReceived' and NcCount=3) 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		ZED_CONSULTANT.dbo.MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		left join 
		ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='Success' )
		where NcCount=3 and CertificationStatus>=2 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')		


		UNION ALL

		
		--select null,null,null,isnull(FApproverAmount,0) FinancialSupport
		select F.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, CertificationType Certification,
		'Technology Support' as ZedStatus, null,null,null, isnull(ApproverAmount,0) FinancialSupport, null PanNo,
		null,null,null,null,null,Gender,SocialCategoryName,
		NULL RegdDate,
		NULL PaymentDate,
		NULL AS [Certified/RejectedDate],
		NULL as DocumentUploadDate,
		DATEDIFF(DAY, '18991230', ApproverDateOfReceiptOfPayment) AS ApproverDateOfReceiptOfPayment, NULL CertificationStatus
		from ZED_CONSULTANT.dbo.FinancialAssistance F left join ZED_CONSULTANT.dbo.Msme m on (F.ZedId=M.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		where isnull(ApproverAmount,0)>0 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		UNION ALL

		-------------------SURVEILLANCE DATA---------------------------------

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Silver' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Surveillance Rejected' else 'Surveillance Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN C.CertificationStatus=16 THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		--(select top 1 DATEDIFF(DAY, '<redacted>', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='<redacted>') 
		--as DocumentUploadDate,
		DATEDIFF(DAY, '18991230', AssessmentDate) AssessmentDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_SURVEILLANCE.DBO.msme M inner join ZED_SURVEILLANCE.DBO.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_SURVEILLANCE.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		ZED_SURVEILLANCE.DBO.MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus>=13 and CertificationStatus<=90 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		--order by m.zedid

		UNION ALL 

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Silver' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Surveillance Rejected' else 'Surveillance Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_SURVEILLANCE.DBO.msme M inner join ZED_SURVEILLANCE.DBO.MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
		inner join ZED_SURVEILLANCE.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		ZED_SURVEILLANCE.DBO.MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		left join 
		ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus=99 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		union all

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Gold' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Surveillance Rejected' else 'Surveillance Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN C.CertificationStatus=16 THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		--(select top 1 DATEDIFF(DAY, '<redacted>', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='<redacted>') 
		--as DocumentUploadDate,
		DATEDIFF(DAY, '18991230', AssessmentDate) AssessmentDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_SURVEILLANCE.DBO.msme M inner join ZED_SURVEILLANCE.DBO.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_SURVEILLANCE.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join 
		ZED_SURVEILLANCE.DBO.MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Gold' and CertificationStatus>=13 and CertificationStatus<=90 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		UNION ALL

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Gold' Certification, case when CHARINDEX('_D', C.ZedId) > 0 then 'Surveillance Rejected' else 'Surveillance Active' end as ZedIdStatus, Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment,CertificationStatus
		from ZED_SURVEILLANCE.DBO.msme M inner join ZED_SURVEILLANCE.DBO.MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
		inner join ZED_SURVEILLANCE.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join 
		ZED_SURVEILLANCE.DBO.MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		left join 
		ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Gold' and CertificationStatus=99 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')



		order by M.ZedId
		
	END

	ELSE
	BEGIN
		select NULL DATAS
		
	END

END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CONSULTANCY]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CONSULTANCY] NULL,'<redacted>',10

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_CONSULTANCY] --NULL,'<redacted>',10
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL
    --@StartDate Date='<redacted>', 
    --@EndDate Date='<redacted>'
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Document Upload Dates to avoid scalar subqueries in the main loop
    --;WITH HistoryDates AS (
    --    SELECT zedid, CertificationType, StatusType, MIN(CreatedDate) as MinCreatedDate
    --    FROM msmehistory 
    --    WHERE StatusType IN ('<redacted>')
    --    GROUP BY zedid, CertificationType, StatusType
    --),
  ; with  ConsultantHistoryDates AS (
        SELECT zedid, CertificationType, StatusType, NcCount, MAX(CreatedDate) as MinCreatedDate
        FROM ZED_CONSULTANT.dbo.msmehistory 
        WHERE StatusType = 'CoAlloted'
        GROUP BY zedid, CertificationType, StatusType, NcCount
    )
--	,StatusDescriptions AS (
--    SELECT Descrip, MonitoringGetList 
--    FROM CertificationStatuses -- Replace with your actual table name if different
--)


        -- CONSULTANT MILESTONES (1, 2, 3)
        SELECT 
            M.ZedId
			,PUnitName
			,Paddress as UnitAddress
			,PStateName
			,PDistrictName
			,Ppin as Pincode
			,M.EnterpriseTypee as EnterpriseType
			,M.OldEnterpriseType
			,P.EnterpriseTypee AS PaymentEnterpriseType
			,C.Certification,
            --CONCAT('<redacted>', C.NcCount) AS ZedIdStatus, 
			CASE 
				WHEN C.CertificationStatus IN (16, 100) 
				THEN CONCAT('Milestone ', C.NcCount, ' - Completed')
				ELSE CONCAT('Milestone ', C.NcCount, ' - In Progress') 
			END AS ZedIdStatus,
            CASE WHEN C.NcCount = 1 THEN 80000 ELSE 60000 END AS HandholdingFee,
            ApplicantContributionAfterSubsidy
			,Isnull(T.Amount,0.00) as AmountPaid
            ,(CASE WHEN C.NcCount = 1 THEN 80000 ELSE 60000 END - ApplicantContributionAfterSubsidy-isnull(P.StateContributionAfterSubsidy,0.00)) AS GoIContribution,
			isnull(P.StateContributionAfterSubsidy,0.00) StateGovtContribution,
			SubsidyPercentage GoISubsidyPercentage,
			isnull(P.StateSubsidyPercentage,0.00) StateGovtSubsidyPercentage ,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
            T.TanNumber
			,T.Tds
			--,P.UseCoupon as JoiningReward
			
			,Gender
			,SocialCategoryName
			,B.PanNo
            ,DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate
			,DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate
            ,DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus IN (16, 100) THEN C.CertificationStatusDate ELSE NULL END) AS [CompletionDate]
            ,case when CH.MinCreatedDate is null then DATEDIFF(DAY, '18991230', P.CreatedDate) else
			DATEDIFF(DAY, '18991230', CH.MinCreatedDate) end AS AllocationDate
			--,NULL AS [ApproverDateOfReceiptOfPayment]
			
        FROM ZED_CONSULTANT.dbo.msme M
        INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications C ON M.ZedId = C.ZedId
        INNER JOIN ZED_CONSULTANT.dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification AND C.NcCount = P.MileStoneNum
        LEFT JOIN ZED_CONSULTANT.dbo.PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND P.MileStoneNum = T.MileStoneNumber AND T.PaymentStatus = 'Success'
        LEFT JOIN ConsultantHistoryDates CH ON C.zedid = CH.zedid AND CH.CertificationType = C.certification AND CH.NcCount = C.NcCount
        WHERE C.NcCount IN (1, 2, 3) AND C.CertificationStatus >= 2
          --AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')


    ORDER BY ZedId;

END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_SURVEILLANCE]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_SURVEILLANCE]   --NULL,'<redacted>',10
(
    @UlbCode varchar(100) = NULL,  
    @Userid varchar(100)= NULL,  
    @RoleId varchar(100)= NULL
    ----@StartDate Date='<redacted>', 
    ----@EndDate Date='<redacted>'
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Security Check
    IF @RoleId NOT IN (10, 11)
    BEGIN
        SELECT NULL AS DATAS;
        RETURN;
    END

    -- 1. Pre-calculate Document Upload Dates to avoid scalar subqueries in the main loop

;with StatusDescriptions AS (
    SELECT Descrip, RegisteredMsmeStatus 
    FROM ZED_SURVEILLANCE.dbo.CertificationStatuses -- Replace with your actual table name if different
),
    -- Surveillance History (ZED_SURVEILLANCE)
    SurveillanceHistory AS (
        SELECT zedid, CertificationType, MIN(CreatedDate) as MinCreatedDate
        FROM ZED_SURVEILLANCE.dbo.msmehistory 
        WHERE StatusType IN ('BasicInfoStatus')
        GROUP BY zedid, CertificationType
    )

 
        SELECT 
             M.ZedId
			,PUnitName
			,Paddress as UnitAddress
			,PStateName
			,PDistrictName
			,Ppin  AS Pincode
			,M.EnterpriseTypee  AS EnterpriseType
			,M.OldEnterpriseType
			,P.EnterpriseTypee AS PaymentEnterpriseType
			,C.Certification,
  

	CASE 
    -- 1. Surveillance Rejected
    WHEN C.CertificationStatus = 99 THEN 
        CASE 
            WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance Rejected'
            WHEN B.ReSurveillance = 2 THEN '2nd Surveillance Rejected'
            ELSE '1st Surveillance Rejected'
        END

    -- 2. Surveillance Certified
    WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6) 
         OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16) THEN 
        CASE 
            WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance Certified'
            WHEN B.ReSurveillance = 2 THEN '2nd Surveillance Certified'
            ELSE '1st Surveillance Certified'
        END

	-- 3. Surveillance Status 17 (Rejected Without Assessment or Partial Rejection)
            WHEN C.CertificationStatus = 17 THEN
                CASE
                    WHEN C.PreviousCertificationStatus IN (8, 9, 13) THEN
                        CASE 
                            WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance Rejected Without Assessment'
                            WHEN B.ReSurveillance = 2 THEN '2nd Surveillance Rejected Without Assessment'
                            ELSE '1st Surveillance Rejected Without Assessment'
                        END
                    ELSE
                        CASE 
                            WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance Partial Rejection'
                            WHEN B.ReSurveillance = 2 THEN '2nd Surveillance Partial Rejection'
                            ELSE '1st Surveillance Partial Rejection'
                        END
                END


    -- 3. Intermediate Statuses (Payment Done, Evidence Upload, etc.)
    ELSE 
        CONCAT(
            CASE 
                WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance'
                WHEN B.ReSurveillance = 2 THEN '2nd Surveillance'
                ELSE '1st Surveillance'
            END, 
            ' - ', 
            S.RegisteredMsmeStatus
        )
END AS ZedIdStatus,

            P.Total  AS CertificationFee
			, ApplicantContributionAfterSubsidy, T.Amount As AmountPaid
, (P.Total - ApplicantContributionAfterSubsidy) FinancialSupport,
            CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
            T.TanNumber, T.Tds, P.UseCoupon AS JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
            DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate, DATEDIFF(DAY, '18991230', P.CreatedDate) as PaymentDate,
            DATEDIFF(DAY, '18991230', 
			CASE 
				WHEN C.CertificationStatus = 99 THEN C.CertificationStatusDate
				WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN C.CertificationStatusDate
				WHEN C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16 THEN C.CertificationStatusDate
				ELSE NULL 
			END)as [Certified/RejectedDate]
           -- DATEDIFF(DAY, '<redacted>', H.MinCreatedDate) AS DocumentUploadDate, NULL as ApproverDateOfReceiptOfPayment
        FROM ZED_SURVEILLANCE.DBO.msme M
      -- INNER JOIN ZED_SURVEILLANCE.DBO.MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(C.Zedid,'<redacted>',''), CONCAT('<redacted>',C.Id),''))
		inner join ZED_SURVEILLANCE.DBO.MsmeCertifications C ON (M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, CONCAT('_D_', C.Id), ''), CONCAT('_S_', C.Id), ''), '_D',''))

        INNER JOIN ZED_SURVEILLANCE.DBO.MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN ZED_SURVEILLANCE.DBO.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        LEFT JOIN ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        LEFT JOIN SurveillanceHistory H ON C.zedid = H.zedid AND H.CertificationType = C.certification -- Assuming local history table used for surveillance lookup as per original
		LEFT JOIN StatusDescriptions S ON C.CertificationStatus = S.Descrip
        WHERE C.Certification IN ('Silver', 'Gold')
          AND ((C.CertificationStatus BETWEEN 2 AND 90) OR C.CertificationStatus = 99)
          ----AND P.CreatedDate >= @StartDate AND P.CreatedDate < DATEADD(DAY, 1, @EndDate)
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')



    ORDER BY ZedId;

END
