		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from ZED_CONSULTANT.dbo.msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='ApplicationReceived' and NcCount=2) 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		ZED_CONSULTANT.dbo.MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification and C.NcCount=P.MileStoneNum)
		left join 
		ZED_CONSULTANT.dbo.PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='Success' )
		where NcCount=2 and CertificationStatus>=2 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		union all

		--select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType,  C.Certification, M.ZedId,'<redacted>' as ZedIdStatus, 60000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 60000-ApplicantContributionAfterSubsidy FinancialSupport
		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, C.Certification, 'Milestone 3' as ZedIdStatus, 60000 CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, 60000-ApplicantContributionAfterSubsidy FinancialSupport,
		--T.UnitGstin,
		case WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
		T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN (C.CertificationStatus=16 OR C.CertificationStatus=100) THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from ZED_CONSULTANT.dbo.msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='ApplicationReceived' and NcCount=3) 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeCertifications C  on (M.ZedId=C.ZedId) 
