/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_WITH_DATES_STATECODE_DISTRICTCODE]    Script Date: 9/19/2026 4:28:41 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS_WITH_DATES_STATECODE_DISTRICTCODE] -- NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME1

	SET NOCOUNT ON;

	IF @RoleId=10 OR @RoleId=11
	BEGIN
	select M.ZedId,PUnitName,Paddress UnitAddress,M.StateId,M.PLgDistrictCode,PStateName,PDistrictName, Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, 
	--case when CHARINDEX('<redacted>', C.ZedId) > 0 then '<redacted>' 
	--when ((C.CertificationStatus=16 and C.Certification!='<redacted>') or (C.CertificationStatus=6 and C.Certification='<redacted>')) then '<redacted>'
	--when ((C.CertificationStatus<16 and C.certification!='<redacted>') or (C.CertificationStatus<6 and C.certification='<redacted>') or (C.CertificationStatus in (7,17))) then '<redacted>'	
	--else '<redacted>' end as ZedIdStatus,
	case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' 
	when C.CertificationStatus=6 then 'Certified'
	when ((C.CertificationStatus<6) or (C.CertificationStatus=7)) then 'Inprogress'	
	else 'Active' end as ZedIdStatus,
	P.Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus=6 THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus>=2 and CertificationStatus<=90 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		
		UNION ALL

		select M.ZedId,PUnitName,Paddress UnitAddress,M.StateId,M.PLgDistrictCode, PStateName,PDistrictName, Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, 
	    'Registered' as ZedIdStatus,
	    null CertificationFee,null ApplicantContributionAfterSubsidy,null as AmountPaid, null FinancialSupport,
		null UnitGstin,null TanNumber,null Tds,null JoiningReward, null SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		null PaymentDate,
		null AS [Certified/RejectedDate],
		--(select top 1 DATEDIFF(DAY, '<redacted>', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='<redacted>') 
		null as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		where isbronzepaymentdone is null and issilverpaymentdone is null and isgoldpaymentdone is null		
		 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		


		UNION ALL

		select M.ZedId,PUnitName,Paddress UnitAddress,M.StateId,M.PLgDistrictCode, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification,
		'Rejected' as ZedIdStatus, 
		Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus=99 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

		union all

		select M.ZedId,PUnitName,Paddress UnitAddress,M.StateId,M.PLgDistrictCode, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Silver' Certification, 
		case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected'
		when C.CertificationStatus=16 then 'Certified'
		when ((C.CertificationStatus<16) or (C.CertificationStatus=17)) then 'Inprogress'	
		else 'Active' end as ZedIdStatus,
		Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230',  CASE WHEN C.CertificationStatus=16 THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus>=2 and CertificationStatus<=90 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		--order by m.zedid

		UNION ALL 

		select M.ZedId,PUnitName,Paddress UnitAddress, M.StateId,M.PLgDistrictCode,PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Silver' Certification, 
		case when CHARINDEX('_D', C.ZedId) > 0 then 'Rejected' else 'Active' end as ZedIdStatus,
		Total CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, Total-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,T.Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName,B.PanNo,
		DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
		DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Certified/RejectedDate],
		(select top 1 DATEDIFF(DAY, '18991230', CreatedDate) from msmehistory H where C.zedid=H.zedid and H.CertificationType=C.certification and StatusType='BasicInfoStatus') 
		as DocumentUploadDate,
		NULL AS ApproverDateOfReceiptOfPayment
		from msme M inner join MsmeCertifications C  on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus=99 and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')

