-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-----[SP_DYNAMIC_REPORT_LIST_OF_CERTIFIED_MSME]  NULL,'<redacted>',2
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_NEW_TRANSACTIONS]  --NULL,'<redacted>',6
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 6
	BEGIN
	 SELECT F.ZedId,M.PUnitName,CategoryOfCertificate,NameOfCertficate,CertificationAgency,F.CertficateNumber,DateOfIssue,ValidityOfCertificate,
	 ExpenditureCertficate,AgencyOrSupplier,InvoiceNo,InvoiceBillDate,AmountPaid,BankName,AccountNo,IfscCode,BranchAddress,P.AssessorRemarks
			
		FROM  Msme M INNER JOIN MsmeBasicInformation B ON (M.ZedId=B.ZedId)		
		INNER JOIN FinancialAssistance F ON (B.ZedId=F.ZedId)
		LEFT JOIN FinancialAssistancePhotos P on (F.FinancialAssistanceId=P.FinancialAssistanceId and PhotoType='Copy of Invoice')
		WHERE F.VerificationStatus=4
		ORDER By F.CreatedDate

	END	

	ELSE
		BEGIN
		SELECT NULL DATAS
		END

END


