SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED] --NULL,null,10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	SET NOCOUNT ON;
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; -- Best practice for large read-only reports

	DECLARE @state varchar(100) = NULL

	-- Safety check for Roles
	IF (@RoleId = '10' OR @RoleId = '11')
	BEGIN
		SELECT 
			M.ZedId,
			P.Certification, 
			M.PUnitName, 
			M.EnterpriseTypee AS Size,
			ISNULL(P.UseCoupon, 'No') AS JoiningReward,
			B.UdyogAadharNo,
			B.TotalEmp,
			B.Gender, 
			B.SocialCategoryName,
			B.PanNo,
			CASE 
				WHEN P.GstinNumber = 'No' THEN NULL 
				WHEN P.GstinNumber = 'Yes' THEN P.UnitGstin 
				ELSE P.GstinNumber 
			END AS GstinNumber, 
			P.TanNumber, 
			P.Id AS TransactionId, 
			P.TransactionStatus,
			CONVERT(VARCHAR, P.CreatedDate, 9) AS TransactionDate,
			P.SubsidyPercentage,
			P.Tds,
			P.ApplicantContributionAfterSubsidy,
			ISNULL(T.Amount, 0) AS AmountPaid,
			T.TrackingId [CCAvenue Ref#],
			DATEDIFF(DAY, '18991230', P.CreatedDate) AS TransactionDateNum
			
		FROM MsmePaymentInfo P
		
		-----------------------------------------------------------------------
		-- 1. CLEANING MsmePaymentInfo (P)
		-----------------------------------------------------------------------
		CROSS APPLY (SELECT CHARINDEX('_D', P.ZedId) AS Pos) AS PPos
		CROSS APPLY (SELECT CASE WHEN PPos.Pos > 0 THEN LEFT(P.ZedId, PPos.Pos - 1) ELSE P.ZedId END AS CleanZedId) AS PClean
		
		-----------------------------------------------------------------------
		-- 2. JOINING Msme (M) - Standardized Join
		-----------------------------------------------------------------------
		INNER JOIN Msme M ON PClean.CleanZedId = M.ZedId
		
		-----------------------------------------------------------------------
		-- 3. JOINING MsmeBasicInformation (B) - Standardized Join
		-----------------------------------------------------------------------
		INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
		
		-----------------------------------------------------------------------
		-- 4. JOINING PaymentGateWayTransactions (T) - Includes Cleaning Logic
		-----------------------------------------------------------------------
		LEFT JOIN PaymentGateWayTransactions T 
			CROSS APPLY (SELECT CHARINDEX('_D', T.ZedId) AS TPos) AS TPosCheck
			CROSS APPLY (SELECT CASE WHEN TPosCheck.TPos > 0 THEN LEFT(T.ZedId, TPosCheck.TPos - 1) ELSE T.ZedId END AS TCleanId) AS TDerived
		ON M.ZedId = TDerived.TCleanId 
			AND P.PaymentRefId = T.PaymentRefId 
			AND P.Certification = T.Certification 
			AND T.PaymentStatus = 'Success'

		-----------------------------------------------------------------------
		-- FILTERS & ORDERING
		-----------------------------------------------------------------------
		WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		AND (@state IS NULL OR M.StateId = @state)
		
		ORDER BY M.ZedId DESC;
	END
END
GO
