-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED_OLD]  --NULL,null,10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	--IF @RoleId = 8
	--BEGIN
	--SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	--END

	

	SELECT m.ZedId,P.Certification, PUnitName PUnitName,
	--PAddress, m.pstatename StateName,m.PDistrictName DistrictName,PPin,
	m.EnterpriseTypee Size,
	case when P.UseCoupon is null then 'No' else P.UseCoupon end as JoiningReward,UdyogAadharNo,TotalEmp,
		B.Gender, B.SocialCategoryName,PanNo,
		case when P.GstinNumber='No' then NULL when P.GstinNumber='Yes' then P.UnitGstin else GstinNumber end as GstinNumber, P.TanNumber, 
		P.Id TransactionId, P.TransactionStatus,
		--P.UtrNumber, P.PaymentType, 
		convert(varchar, P.CreatedDate, 9) as TransactionDate,
		P.SubsidyPercentage,
		P.Tds,ApplicantContributionAfterSubsidy,
		ISNULL(Amount,0) AmountPaid,
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS TransactionDate
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	--FROM MsmePaymentInfo P inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
	--inner join MsmeBasicInformation B on (replace(P.ZedId,'<redacted>','')=B.ZedId )
	--left join PaymentGateWayTransactions T on (M.ZedId=replace(T.ZedId,'<redacted>','') and P.PaymentRefId=T.PaymentRefId and P.Certification=T.Certification and PaymentStatus='<redacted>')
	--WHERE replace(P.ZedId,'<redacted>','')=M.ZedId AND M.ZedId=B.ZedId 

	FROM MsmePaymentInfo P
	INNER JOIN Msme M ON (SUBSTRING(P.ZedId, 1, CHARINDEX('_D', P.ZedId + '_D') - 1) = M.ZedId)
	INNER JOIN MsmeBasicInformation B ON (SUBSTRING(P.ZedId, 1, CHARINDEX('_D', P.ZedId + '_D') - 1) = B.ZedId)
	LEFT JOIN PaymentGateWayTransactions T ON (M.ZedId = SUBSTRING(T.ZedId, 1, CHARINDEX('_D', T.ZedId + '_D') - 1) AND P.PaymentRefId = T.PaymentRefId AND P.Certification = T.Certification AND PaymentStatus = 'Success')
	WHERE SUBSTRING(P.ZedId, 1, CHARINDEX('_D', P.ZedId + '_D') - 1) = M.ZedId

	AND (@State is null or M.StateId=@State)
	and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	and (@RoleId=10 OR @RoleId=11)
	ORDER By ZedId desc
	

END


