-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REJECTED_MSME]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	IF @RoleId=2
	BEGIN
		SELECT M.ZedId,case when P.IsAutoReject=1 then 'Yes' else 'No' end as IsAutoReject, M.CreatedDate as RegistrationDate,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
				when CertificationStatus=1 then 'Payment done By MSME'
				when CertificationStatus=2 then 'Evidence upload done by MSME'
				when CertificationStatus=3 then 'DA Verification in progress'
				when CertificationStatus=4 then 'DA Verification done with errors'
				when CertificationStatus=5 then 'DA Verification done without errors'
				when (P.certification='Bronze' and CertificationStatus=6) then 'Agency Approved and Bronze Certification Done' 
				when (P.certification in ('Silver','Gold') and CertificationStatus=6) then 'Agency Final submit done for DA'
				when CertificationStatus=7 then 'Failed in NC'
				when CertificationStatus=8 then 'SA Allocation Done'
				when CertificationStatus=9 then 'SA is ready to start'
				when CertificationStatus=13 then 'SA Verification in progress'
				when CertificationStatus=14 then 'SA Verification done with errors'
				when CertificationStatus=15 then 'SA verification done without errors'
				when (P.certification='Silver' and CertificationStatus=16) then 'Agency Approved and Silver Certification Done' 
				when (P.certification='Gold' and CertificationStatus=16) then 'Agency Approved and Gold Certification Done' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
			end as AssessmentStatus,
			BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				CompletedOn,
			[Unit Rejected due to NCs],
			M.EnterpriseName,	PUnitName,	P.Certification,
		M.OwnerName,	 M.OrganisationTypeName,	M.EnterpriseTypee,	M.MobileNo,
		M.EmailId,	Activity,	TwoDigitActivity,	FourDigitActivity,	FiveDigitActivity,	IncorporationDate,	WhetherProdCommenced,
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	B.PH,	B.PanNo,	B.Address,	PStateName,	PDistrictName,
		B.CommmenceDate, B.TotalEmp, U.UserName as AgencyName,
		I.GstinNumber, I.TanNumber, I.UtrNumber, P.Id TransactionId, I.TransactionStatus,convert(varchar, P.CreatedDate, 9) as TransactionDate, I.PaymentType,case when I.UseCoupon is null then 'No' else I.UseCoupon end as JoiningReward, I.SubsidyPercentage,I.Tds,ApplicantContributionAfterSubsidy,
		ISNULL(Amount,0) AmountPaid
		
	

		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		inner join MsmeCertifications P on (SUBSTRING(P.ZedId, 1, CHARINDEX('_D', P.ZedId + '_D') - 1)=M.ZedId)
		left join MsmePaymentInfo I on (P.ZedId=I.ZedId and P.Certification=I.Certification)
		left join PaymentGateWayTransactions T on (I.ZedId=T.ZedId and I.PaymentRefId=T.PaymentRefId and I.Certification=T.Certification and PaymentStatus='Success')
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate],
				[Unit Rejected due to NCs]
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate],
				[Unit Rejected due to NCs]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State)
		AND CertificationStatus=99 and CertificationBodyUserId=@Userid
		ORDER By M.MsmeId desc
	END

	ELSE IF (@RoleId=10 or @RoleId=11 or @RoleId=8)
	BEGIN
		SELECT M.ZedId,case when P.IsAutoReject=1 then 'Yes' else 'No' end as IsAutoReject, M.CreatedDate as RegistrationDate,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
				when CertificationStatus=1 then 'Payment done By MSME'
				when CertificationStatus=2 then 'Evidence upload done by MSME'
				when CertificationStatus=3 then 'DA Verification in progress'
				when CertificationStatus=4 then 'DA Verification done with errors'
				when CertificationStatus=5 then 'DA Verification done without errors'
				when (P.certification='Bronze' and CertificationStatus=6) then 'Agency Approved and Bronze Certification Done' 
				when (P.certification in ('Silver','Gold') and CertificationStatus=6) then 'Agency Final submit done for DA'
				when CertificationStatus=7 then 'Failed in NC'
				when CertificationStatus=8 then 'SA Allocation Done'
				when CertificationStatus=9 then 'SA is ready to start'
				when CertificationStatus=13 then 'SA Verification in progress'
				when CertificationStatus=14 then 'SA Verification done with errors'
				when CertificationStatus=15 then 'SA verification done without errors'
				when (P.certification='Silver' and CertificationStatus=16) then 'Agency Approved and Silver Certification Done' 
				when (P.certification='Gold' and CertificationStatus=16) then 'Agency Approved and Gold Certification Done' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
			end as AssessmentStatus,
			BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				CompletedOn,
			[Unit Rejected due to NCs],
			M.EnterpriseName,	PUnitName,	P.Certification,
		M.OwnerName,	 M.OrganisationTypeName,	M.EnterpriseTypee,	M.MobileNo,
		M.EmailId,	Activity,	TwoDigitActivity,	FourDigitActivity,	FiveDigitActivity,	IncorporationDate,	WhetherProdCommenced,
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	B.PH,	B.PanNo,	B.Address,	PStateName,	PDistrictName,
		B.CommmenceDate, B.TotalEmp,
		U.UserName as AgencyName, --Agency Name Added
		I.GstinNumber, I.TanNumber, I.UtrNumber, P.Id TransactionId, I.TransactionStatus,convert(varchar, P.CreatedDate, 9) as TransactionDate, I.PaymentType,case when I.UseCoupon is null then 'No' else I.UseCoupon end as JoiningReward, I.SubsidyPercentage,I.Tds,ApplicantContributionAfterSubsidy,
		ISNULL(Amount,0) AmountPaid
		
	

		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		inner join MsmeCertifications P on (SUBSTRING(P.ZedId, 1, CHARINDEX('_D', P.ZedId + '_D') - 1)=M.ZedId)
		left join MsmePaymentInfo I on (P.ZedId=I.ZedId and P.Certification=I.Certification)
		left join PaymentGateWayTransactions T on (I.ZedId=T.ZedId and I.PaymentRefId=T.PaymentRefId and I.Certification=T.Certification and PaymentStatus='Success')
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate],
				[Unit Rejected due to NCs]
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate],
				[Unit Rejected due to NCs]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State)
		AND CertificationStatus=99
		ORDER By M.MsmeId desc
	END

	ELSE
		BEGIN
		SELECT NULL DATAS		
		END

END


