CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_UNITS_STATUS_MINISTRY] --null, null, 11
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN


	
	SET NOCOUNT ON;

--	SELECT 
