--        ELSE '<redacted>'
--    END AS UnitStatus,
--    C.Certification,
--    M.EnterpriseTypee  EnterpriseType,
--    B.Gender,
--    SocialCategoryName,
--    DATEDIFF(DAY, '<redacted>', M.CreatedDate) AS RegistrationDate,
--    CASE
--        WHEN (C.CertificationStatus = 6 AND C.Certification = '<redacted>') OR
--             (C.CertificationStatus = 16 AND C.Certification IN ('<redacted>', '<redacted>'))
--        THEN DATEDIFF(DAY, '<redacted>', C.CertificationStatusDate)
--        ELSE NULL
--    END AS CertificactionDate,
--    M.EmailId,
--    M.MobileNo, UdyogAadharNo, TwoDigitActivity
--FROM
--    Msme M
--INNER JOIN
--    MsmeBasicInformation B ON (M.ZedId = B.ZedId)
--LEFT JOIN
--    MsmeCertifications C ON (M.ZedId = C.ZedId)
--	where @RoleId=11 
--	and UdyogAadharNo not in ('<redacted>', '<redacted>', '<redacted>','<redacted>')
--	order by M.CreatedDate



-- 1. Check RoleId immediately to save resources
	IF @RoleId <> '11' RETURN;

	-- 2. Define the CTE to handle complex logic and joins
	;WITH UnitData AS (
		SELECT 
			M.ZedId,
			M.PUnitName AS UnitName,
			M.PStateName AS StateName,
			M.PDistrictName AS DistrictName,
			M.PAddress,
			M.EnterpriseTypee AS EnterpriseType,
			M.CreatedDate,
			M.EmailId,
			M.MobileNo, 
			B.UdyogAadharNo, 
			M.TwoDigitActivity,
			B.Gender,
			B.SocialCategoryName,
			C.Certification,
			C.CertificationStatusDate,
			-- Centralized Status Logic
			CASE 
				WHEN (C.CertificationStatus = 6 AND C.Certification = 'Bronze') OR 
				     (C.CertificationStatus = 16 AND C.Certification IN ('Silver', 'Gold')) 
				THEN 'Certified' 
				ELSE 'Registered' 
			END AS UnitStatus
		FROM Msme M
		INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
		LEFT JOIN MsmeCertifications C ON M.ZedId = C.ZedId
