	)

	-- 3. Final Select using the CTE results
	SELECT 
		ZedId,
		UnitName,
		StateName,
		DistrictName,
		PAddress,
		UnitStatus,
		Certification,
		EnterpriseType,
		Gender,
		SocialCategoryName,
		DATEDIFF(DAY, '18991230', CreatedDate) AS RegistrationDate,
		CASE 
			WHEN UnitStatus = 'Certified' THEN DATEDIFF(DAY, '18991230', CertificationStatusDate)
			ELSE NULL 
		END AS CertificactionDate,
		EmailId,
		MobileNo, 
		UdyogAadharNo, 
		TwoDigitActivity
	FROM UnitData
	ORDER BY CreatedDate;


END

