-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_UNITS_STATUS_MINISTRY_2022-2023] --null, null, 11
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN


	
	SET NOCOUNT ON;

-- 1. Check RoleId immediately to save resources
	IF @RoleId <> '11' RETURN;

	DECLARE @StartDate DATE = '2022-04-01', @EndDate DATE = '2023-03-31';

	-- 2. Define the CTE to handle complex logic and joins
	;WITH UnitData AS (
		SELECT 
			M.ZedId,
			M.PUnitName AS UnitName,
			M.PStateName AS StateName,
			M.PDistrictName AS DistrictName,
			M.PAddress,
			M.EnterpriseTypee AS EnterpriseType,
			M.CreatedDate,
			M.EmailId,
			M.MobileNo, 
			B.UdyogAadharNo, 
			M.TwoDigitActivity,
			B.Gender,
			B.SocialCategoryName,
			C.Certification,
			C.CertificationStatusDate,
			-- Centralized Status Logic
			CASE 
				WHEN (C.CertificationStatus = 6 AND C.Certification = 'Bronze') OR 
				     (C.CertificationStatus = 16 AND C.Certification IN ('Silver', 'Gold')) 
				THEN 'Certified' 
				ELSE 'Registered' 
			END AS UnitStatus
		FROM Msme M
		INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
		LEFT JOIN MsmeCertifications C ON M.ZedId = C.ZedId
		WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		AND M.CreatedDate >= @StartDate AND M.CreatedDate < DATEADD(DAY, 1, @EndDate)
	)

	-- 3. Final Select using the CTE results
	SELECT 
		ZedId,
		UnitName,
		StateName,
		DistrictName,
		PAddress,
		UnitStatus,
		Certification,
		EnterpriseType,
		Gender,
		SocialCategoryName,
		DATEDIFF(DAY, '18991230', CreatedDate) AS RegistrationDate,
		CASE 
			WHEN UnitStatus = 'Certified' THEN DATEDIFF(DAY, '18991230', CertificationStatusDate)
			ELSE NULL 
		END AS CertificactionDate,
		EmailId,
		MobileNo, 
		UdyogAadharNo, 
		TwoDigitActivity
	FROM UnitData
	ORDER BY CreatedDate;


END

