		DATEDIFF(DAY, '18991230', CreatedDate) AS RegistrationDate,
		CASE 
			WHEN UnitStatus = 'Certified' THEN DATEDIFF(DAY, '18991230', CertificationStatusDate)
			ELSE NULL 
		END AS CertificactionDate,
