/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_ZEDID_ALL_DATES_BRONZE_2022_23]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_ZEDID_ALL_DATES_BRONZE_2022_23]
(
    @UlbCode VARCHAR(100) = NULL,   
    @Userid VARCHAR(100) = NULL,   
    @RoleId VARCHAR(100) = NULL,
    @StartDate DATE = '2022-04-01', 
    @EndDate DATE = '2023-03-31'
)
AS
BEGIN
    SET NOCOUNT ON;

    -- =========================================================================================
    -- STEP 1: TEMP TABLE - Base Certifications
    -- =========================================================================================
    IF OBJECT_ID('tempdb..#BaseCerts') IS NOT NULL DROP TABLE #BaseCerts;
    
    SELECT 
        c.ZedId,
        c.CertificationStatus,
        c.Certification,
        c.DesktopAssessorId,
        c.CertificationBodyUserId,
        c.AcceptOrRejectDate,
        c.DesktopAcceptOrRejectDate,
        c.NcFinalClosureDt,
        c.CertificationStatusDate
    INTO #BaseCerts
    FROM MsmeCertifications c
    WHERE c.Certification = 'Bronze' 
      AND c.CertificationStatus >= 2;

    CREATE CLUSTERED INDEX IX_BaseCerts_ZedId ON #BaseCerts(ZedId);

    -- =========================================================================================
    -- STEP 2: TEMP TABLE - History Aggregations 
    -- =========================================================================================
    IF OBJECT_ID('tempdb..#HistAgg') IS NOT NULL DROP TABLE #HistAgg;
    
    SELECT 
        ZedId,
        MAX(CASE WHEN StatusType = 'ApplicationReceived' THEN CreatedDate END) AS ApplicationReceivedDate,
        MAX(CASE WHEN StatusType = 'BasicInfoStatus' THEN CreatedDate END) AS BasicInfoStatusDate,
        MAX(CASE WHEN StatusType = 'DaAgencyRejected' THEN CreatedDate END) AS DaAgencyRejectedDate,
        MAX(CASE WHEN StatusType = 'Assessor Rejected in NC 5' THEN CreatedDate END) AS AssessorRejectedNC5Date,
        MAX(CASE WHEN StatusType = 'Nc1Raised' THEN CreatedDate END) AS Nc1RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CreatedDate END) AS Nc1SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc2Raised' THEN CreatedDate END) AS Nc2RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CreatedDate END) AS Nc2SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc3Raised' THEN CreatedDate END) AS Nc3RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CreatedDate END) AS Nc3SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc4Raised' THEN CreatedDate END) AS Nc4RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CreatedDate END) AS Nc4SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc5Raised' THEN CreatedDate END) AS Nc5RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CreatedDate END) AS Nc5SubmittedDate,
        MAX(CASE WHEN StatusType = 'NcClosed' THEN CreatedDate END) AS NcFinalClosureDate,
        MAX(CASE WHEN StatusType = 'AgencyAlloted' THEN CreatedDate END) AS AgencyAllotedDate,
        MAX(CASE WHEN StatusType = 'Certification auto Rejected due to NC closure time is exceeded' THEN CreatedDate END) AS PartialRejectionDate
    INTO #HistAgg
    FROM MsmeHistory
    WHERE CertificationType = 'Bronze'
      AND StatusType IN (
          'ApplicationReceived', 'BasicInfoStatus', 'DaAgencyRejected', 'Assessor Rejected in NC 5', 
          'Nc1Raised', 'Nc1Submitted', 'Nc2Raised', 'Nc2Submitted', 'Nc3Raised', 'NcClosed',
          'Nc3Submitted', 'Nc4Raised', 'Nc4Submitted', 'Nc5Raised', 'Nc5Submitted', 
          'NcFinalClosureDate', 'AgencyAlloted', 'Certification auto Rejected due to NC closure time is exceeded'
      )
    GROUP BY ZedId;

    CREATE CLUSTERED INDEX IX_HistAgg_ZedId ON #HistAgg(ZedId);

    -- =========================================================================================
    -- STEP 3: MAIN SELECT QUERY 
    -- =========================================================================================
    SELECT 
        M.ZedId,
        M.EnterpriseTypee AS [Enterprise type],
        B.Gender AS [Gender],
        U.UserName AS AgencyName,
        c.DesktopAssessorId,
        M.PStateName,
        M.PDistrictName,
        
        CASE 
            WHEN c.CertificationStatus = 1 THEN 'Payment Received'
            WHEN c.CertificationStatus = 2 THEN 'Evidence uploaded'
            WHEN c.CertificationStatus = 3 THEN 'DA in progress'
            WHEN c.CertificationStatus = 4 THEN 'NC raised in DA'
            WHEN c.CertificationStatus = 5 THEN 'DA Completed'
            WHEN (c.Certification = 'Bronze' AND c.CertificationStatus = 6) THEN 'Certified' 
            WHEN (c.Certification IN ('Silver','Gold') AND c.CertificationStatus = 6) THEN 'QC Completed'
            WHEN c.CertificationStatus IN (7,99) THEN 'Rejected'
            WHEN c.CertificationStatus = 8 THEN 'SA Planned'
            WHEN c.CertificationStatus = 9 THEN 'SA Planned'
            WHEN c.CertificationStatus = 13 THEN 'SA in progress'
            WHEN c.CertificationStatus = 14 THEN 'NC raised in SA'
            WHEN c.CertificationStatus = 15 THEN 'SA Completed'
            WHEN (c.Certification = 'Silver' AND c.CertificationStatus = 16) THEN 'Silver Certified' 
            WHEN (c.Certification = 'Gold' AND c.CertificationStatus = 16) THEN 'Gold Certified' 
            WHEN (M.IsBronzePaymentDone = 1 OR M.IsSilverPaymentDone = 1 OR M.IsGoldPaymentDone = 1) THEN 'Payment Received'
        END AS [AssessmentStatus (current status)],
        
        c.Certification AS [CertificationLevel],
        
        DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegistrationDate,
        DATEDIFF(DAY, '18991230', hist.ApplicationReceivedDate) AS PaymentDate,
        DATEDIFF(DAY, '18991230', dm.SaStartDateM) AS EvidenceUploadStart,
        DATEDIFF(DAY, '18991230', hist.BasicInfoStatusDate) AS EvidenceUploadDone,
        
        DATEDIFF(DAY, '18991230', 
            CASE 
                WHEN hist.AgencyAllotedDate > ISNULL(aad.AllocDate, '1900-01-01') THEN hist.AgencyAllotedDate 
                ELSE COALESCE(aad.AllocDate, hist.AgencyAllotedDate) 
            END
        ) AS DaAgencyAllocateDate,
        
        DATEDIFF(DAY, '18991230', c.AcceptOrRejectDate) AS DaAgencyAcceptDate,
        DATEDIFF(DAY, '18991230', hist.DaAgencyRejectedDate) AS DaAgencyRejectDate,
        
        --CONCAT(
        --    DATEDIFF(DAY, '<redacted>', 
        --        CASE 
        --            WHEN hist.AgencyAllotedDate > ISNULL(aad.AllocDate, '<redacted>') THEN hist.AgencyAllotedDate 
        --            ELSE COALESCE(aad.AllocDate, hist.AgencyAllotedDate) 
        --        END
        --    ), 
        --    '<redacted>', U.UserName
        --) AS [DaAgencyoldallocateDate1 and agency],
        
        DATEDIFF(DAY, '18991230', c.DesktopAcceptOrRejectDate) AS [DaAssessorAcceptDate],
        DATEDIFF(DAY, '18991230', hist.AssessorRejectedNC5Date) AS DaAssessorRejectDate,
        DATEDIFF(DAY, '18991230', hist.NcFinalClosureDate) AS [DaCloseDate],
        NULL AS [DaQcDate ()],
        DATEDIFF(DAY, '18991230', qb.QcSentBackDate) AS [QcSentBack],
        
        DATEDIFF(DAY, '18991230', hist.Nc1RaisedDate) AS [Nc1Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc1SubmittedDate) AS [Nc1Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc2RaisedDate) AS [Nc2Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc2SubmittedDate) AS [Nc2Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc3RaisedDate) AS [Nc3Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc3SubmittedDate) AS [Nc3Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc4RaisedDate) AS [Nc4Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc4SubmittedDate) AS [Nc4Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc5RaisedDate) AS [Nc5Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc5SubmittedDate) AS [Nc5Submitted],
        
        DATEDIFF(DAY, '18991230', hist.PartialRejectionDate) AS [PartialRejectionDate],
        
        CASE WHEN c.Certification = 'Bronze' AND c.CertificationStatus = 99 THEN DATEDIFF(DAY, '18991230', c.CertificationStatusDate) ELSE NULL END AS [Final Rejection Date],
        CASE WHEN c.Certification = 'Bronze' AND c.CertificationStatus = 6 THEN DATEDIFF(DAY, '18991230', c.CertificationStatusDate) ELSE NULL END AS [Certified Date],
        ncd.Extenddays AS [TotalExtensionGiven(Days)]

    FROM Msme M
    INNER JOIN MsmeBasicInformation B ON B.ZedId = M.Zedid
    INNER JOIN #BaseCerts c ON (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1) = M.ZedId)
    LEFT JOIN MsmePaymentInfo I ON (c.ZedId = I.ZedId AND c.Certification = I.Certification)
    LEFT JOIN Users U ON c.CertificationBodyUserId = U.UserId
    LEFT JOIN #HistAgg hist ON hist.ZedId = c.ZedId
    
    LEFT JOIN (
        SELECT ZedId, MIN(CreatedDate) AS SaStartDateM 
        FROM MsmePhotos 
        WHERE Certification = 'Bronze' 
        GROUP BY ZedId
    ) dm ON dm.ZedId = c.ZedId
    
    LEFT JOIN (
        SELECT ZedId, MAX(CreatedDate) AS QcSentBackDate
        FROM BackendChangesHistory  
        WHERE StatusType = 'Send back from QC to Assessor' AND CertificationType = 'Bronze'
        GROUP BY ZedId
    ) qb ON qb.ZedId = c.ZedId
    
    LEFT JOIN (
        SELECT ZedId, MAX(CreatedDate) AS AllocDate 
        FROM AgencyAllotmentHistory 
        WHERE CertificationType = 'Bronze' 
        GROUP BY ZedId
    ) aad ON aad.ZedId = c.ZedId
    
    LEFT JOIN (
        SELECT ZedId, Certification, SUM(noofDays) AS Extenddays 
        FROM NcClosureDateHistory
        WHERE Certification = 'Bronze'  and noofDays>0
        GROUP BY ZedId, Certification
    ) ncd ON ncd.ZedId = c.ZedId AND ncd.Certification = c.Certification
    
    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915', 'UDYAM-UP-16-0001476')
      AND i.CreatedDate >= @StartDate AND i.CreatedDate < DATEADD(DAY, 1, @EndDate)
    ORDER BY M.ZedId;

    -- Cleanup temp tables
    DROP TABLE #BaseCerts;
    DROP TABLE #HistAgg;

END
