        MAX(CASE WHEN StatusType = 'BasicInfoStatus' THEN CreatedDate END) AS BasicInfoStatusDate,
        MAX(CASE WHEN StatusType = 'DaAgencyRejected' THEN CreatedDate END) AS DaAgencyRejectedDate,
        MAX(CASE WHEN StatusType = 'Assessor Rejected in NC 5' THEN CreatedDate END) AS AssessorRejectedNC5Date,
        MAX(CASE WHEN StatusType = 'Nc1Raised' THEN CreatedDate END) AS Nc1RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CreatedDate END) AS Nc1SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc2Raised' THEN CreatedDate END) AS Nc2RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CreatedDate END) AS Nc2SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc3Raised' THEN CreatedDate END) AS Nc3RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CreatedDate END) AS Nc3SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc4Raised' THEN CreatedDate END) AS Nc4RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CreatedDate END) AS Nc4SubmittedDate,
        MAX(CASE WHEN StatusType = 'Nc5Raised' THEN CreatedDate END) AS Nc5RaisedDate,
        MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CreatedDate END) AS Nc5SubmittedDate,
        MAX(CASE WHEN StatusType = 'NcFinalClosureDate' THEN CreatedDate END) AS NcFinalClosureDate,
		 MAX(CASE WHEN StatusType = 'DirectQC' THEN CreatedDate END) AS DirectQC,
        MAX(CASE WHEN StatusType = 'AgencyAlloted' THEN CreatedDate END) AS AgencyAllotedDate,
		MAX(CASE WHEN StatusType = 'ScheduledOn' THEN CreatedDate END) AS SaScheduleDate,
		MAX(CASE WHEN StatusType = 'NcClosed' THEN CreatedDate END) AS [SaSubmitted from web DateD],

		MAX(CASE WHEN StatusType = 'Certification auto Rejected due to NC closure time is exceeded' THEN CreatedDate END) AS PartialRejectionDate
    INTO #HistAgg
    FROM MsmeHistory
    WHERE CertificationType = 'silver'
      AND StatusType IN (
          'ApplicationReceived', 'BasicInfoStatus', 'DaAgencyRejected', 'Assessor Rejected in NC 5', 
          'Nc1Raised', 'Nc1Submitted', 'Nc2Raised', 'Nc2Submitted', 'Nc3Raised','DirectQC', 
          'Nc3Submitted', 'Nc4Raised', 'Nc4Submitted', 'Nc5Raised', 'Nc5Submitted', 
          'NcFinalClosureDate', 'AgencyAlloted','ScheduledOn','Certification auto Rejected due to NC closure time is exceeded'
		  ,'NcClosed'
      )
    GROUP BY ZedId;

    CREATE CLUSTERED INDEX IX_HistAgg_ZedId ON #HistAgg(ZedId);

    -- =========================================================================================
    -- STEP 3: MAIN SELECT QUERY 
    -- =========================================================================================
    SELECT 
		
        M.ZedId,
		M.PUnitName,
        M.EnterpriseTypee AS [Enterprise type],
        B.Gender AS [Gender],
        U.UserName AS AgencyName,
        c.DesktopAssessorId,
		C.SiteAssessorId,
		C.CoAssessorId,
		
        M.PStateName,
        M.PDistrictName,
        
        --CASE 
        --    WHEN c.CertificationStatus = 1 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 2 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 3 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 4 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 5 THEN '<redacted>'
        --    WHEN (c.Certification = '<redacted>' AND c.CertificationStatus = 6) THEN '<redacted>' 
        --    WHEN (c.Certification IN ('<redacted>','<redacted>') AND c.CertificationStatus = 6) THEN '<redacted>'
        --    WHEN c.CertificationStatus IN (7,99) THEN '<redacted>'
        --    WHEN c.CertificationStatus = 8 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 9 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 13 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 14 THEN '<redacted>'
        --    WHEN c.CertificationStatus = 15 THEN '<redacted>'
        --    WHEN (c.Certification = '<redacted>' AND c.CertificationStatus = 16) THEN '<redacted>' 
        --    WHEN (c.Certification = '<redacted>' AND c.CertificationStatus = 16) THEN '<redacted>' 
        --    WHEN (M.IsBronzePaymentDone = 1 OR M.IsSilverPaymentDone = 1 OR M.IsGoldPaymentDone = 1) THEN '<redacted>'
        --END AS [AssessmentStatus (current status)],

			CASE
			WHEN C.ZedId LIKE '%\_R\_%' ESCAPE '\' THEN 'Certified & Re-applied'
			WHEN C.CertificationStatus = 99 THEN 'Rejected'
			WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
			  OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16) THEN 'Certified'
			ELSE CONCAT(UPPER(C.Certification), ' - ', ISNULL(S.MonitoringGetList, 'Active'))
		    END AS[AssessmentStatus (current status)],

        
        c.Certification AS [CertificationLevel],
        
        DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegistrationDate,
        DATEDIFF(DAY, '18991230', hist.ApplicationReceivedDate) AS PaymentDate,
        DATEDIFF(DAY, '18991230', dm.SaStartDateM) AS EvidenceUploadStart,
        DATEDIFF(DAY, '18991230', hist.BasicInfoStatusDate) AS EvidenceUploadDone,
        
        -- DaAgencyAllocateDate: Checks both tables and outputs the absolute MAX Date
        DATEDIFF(DAY, '18991230', 
            CASE 
                WHEN hist.AgencyAllotedDate > ISNULL(aad.AllocDate, '1900-01-01') THEN hist.AgencyAllotedDate 
                ELSE COALESCE(aad.AllocDate, hist.AgencyAllotedDate) 
            END
        ) AS DaAgencyAllocateDate,
        
        DATEDIFF(DAY, '18991230', c.AcceptOrRejectDate) AS DaAgencyAcceptDate,
        DATEDIFF(DAY, '18991230', hist.DaAgencyRejectedDate) AS DaAgencyRejectDate,
        
        -- DaAgencyoldallocateDate1 and agency: Converted formatting to DATEDIFF before concatenating
        CONCAT(
            DATEDIFF(DAY, '18991230', 
                CASE 
                    WHEN hist.AgencyAllotedDate > ISNULL(aad.AllocDate, '1900-01-01') THEN hist.AgencyAllotedDate 
                    ELSE COALESCE(aad.AllocDate, hist.AgencyAllotedDate) 
                END
            ), 
            ' and ', U.UserName
        ) AS [DaAgencyoldallocateDate1 and agency],
        
        DATEDIFF(DAY, '18991230', c.DesktopAcceptOrRejectDate) AS [DaAssessorAcceptDate],
        DATEDIFF(DAY, '18991230', hist.AssessorRejectedNC5Date) AS DaAssessorRejectDate,
       --DATEDIFF(DAY, '<redacted>', hist.NcFinalClosureDate) AS [DaCloseDate],
		 DATEDIFF(DAY, '18991230', hist.DirectQC) AS [DaCloseDate],
        NULL AS [DaQcDate ()],
        DATEDIFF(DAY, '18991230', qb.QcSentBackDate) AS [QcSentBack],
        DATEDIFF(DAY, '18991230', hist.SaScheduleDate) AS SaScheduleDate,

		DATEDIFF(DAY, '18991230', SDM.[SaCloseDateM(from mobile)]) AS [SaCloseDateM(from mobile)],
		DATEDIFF(DAY, '18991230', hist.[SaSubmitted from web DateD]) AS [SaSubmitted from web DateD],

		DATEDIFF(DAY, '18991230', hist.Nc1RaisedDate) AS [Nc1Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc1SubmittedDate) AS [Nc1Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc2RaisedDate) AS [Nc2Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc2SubmittedDate) AS [Nc2Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc3RaisedDate) AS [Nc3Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc3SubmittedDate) AS [Nc3Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc4RaisedDate) AS [Nc4Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc4SubmittedDate) AS [Nc4Submitted],
        DATEDIFF(DAY, '18991230', hist.Nc5RaisedDate) AS [Nc5Raised], 
        DATEDIFF(DAY, '18991230', hist.Nc5SubmittedDate) AS [Nc5Submitted],
        
        DATEDIFF(DAY, '18991230', hist.PartialRejectionDate) AS [PartialRejectionDate],
        
        CASE WHEN c.Certification = 'Silver' AND c.CertificationStatus = 99 THEN DATEDIFF(DAY, '18991230', c.CertificationStatusDate) ELSE NULL END AS [Final Rejection Date]
       ,CASE WHEN c.Certification = 'Silver' AND c.CertificationStatus = 16 THEN DATEDIFF(DAY, '18991230', c.CertificationStatusDate) ELSE NULL END AS [Certified Date]
       ,ncd.Extenddays AS [TotalExtensionGiven(Days)]

    FROM Msme M
    INNER JOIN MsmeBasicInformation B ON B.ZedId = M.Zedid
    --INNER JOIN #BaseCerts c ON c.ZedId =M.ZedId
	INNER JOIN #BaseCerts  C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, '_R', ''), '_D', ''), CONCAT('_', C.Id), ''))

    LEFT JOIN Users U ON c.CertificationBodyUserId = U.UserId
	LEFT JOIN Users US on (C.SiteAssessorId=US.UserId)
	LEFT JOIN Users UC on (C.CoAssessorId=UC.UserId)
    LEFT JOIN #HistAgg hist ON hist.ZedId = c.ZedId
    LEFT JOIN CertificationStatuses S ON C.CertificationStatus = S.Descrip
    
    -- DesktopandMobileDate (EvidenceUploadStart)
    LEFT JOIN (
        SELECT ZedId, MIN(CreatedDate) AS SaStartDateM 
        FROM MsmePhotos 
        WHERE Certification = 'Silver' 
        GROUP BY ZedId
    ) dm ON dm.ZedId = c.ZedId
    
    -- QC Sent Back
    LEFT JOIN (
        SELECT ZedId, MAX(CreatedDate) AS QcSentBackDate
        FROM BackendChangesHistory  
        WHERE StatusType = 'Send back from QC to Assessor' AND CertificationType = 'Silver'
        GROUP BY ZedId
    ) qb ON qb.ZedId = c.ZedId
    
    -- AgencyAllotmentHistory (Combined with HistAgg for DaAgencyAllocateDate)
    LEFT JOIN (
        SELECT ZedId, MAX(CreatedDate) AS AllocDate 
        FROM AgencyAllotmentHistory 
        WHERE CertificationType = 'Silver' 
        GROUP BY ZedId
    ) aad ON aad.ZedId = c.ZedId

	left join (
	 select zedid,Certification,sum(noofDays) as Extenddays from NcClosureDateHistory
	where Certification = 'Silver' and NoOfDays>0
	group by zedid,Certification
	) ncd on ncd.ZedId = c.ZedId and ncd.Certification = c.Certification
	left join (
	select zedid,certification,max(timestamp) as [SaCloseDateM(from mobile)]
	from SaPhotos where Certification = 'Silver'
	group by zedid,certification
	--order by ZedId
	) SDM on (sdm.ZedId = c.ZedId) and (sdm.Certification = c.Certification)
    
	--left join (
	--select zedid,sectiontype,max(SaUpdatedDate) as [SaSubmitted from web DateD] from msmerequirements where SectionType = '<redacted>'
 --   group by zedid,sectiontype
 --   --order by ZedId

	--)swd on (swd.ZedId = c.ZedId) and (swd.SectionType  = c.Certification)


    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915', 'UDYAM-UP-16-0001476')
    ORDER BY M.ZedId;

    -- Cleanup temp tables
    DROP TABLE #BaseCerts;
    DROP TABLE #HistAgg;
END
