-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_FINAL_AUBMIT] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@IsApproved varchar(50) = NULL,
	@Comments varchar(2000) = NULL,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @RoleId=3
	BEGIN
		IF @IsApproved=1
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=@IsApproved,VerificationStatus=3 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
		END
		ELSE
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=@IsApproved,VerificationStatus=5,ReasonForRejection=@Comments WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
			UPDATE Msme set FinancialAssistanceStatus=1 where ZedId=@ZedId
		END
	END

	IF @RoleId=2
	BEGIN
		IF @IsApproved=1
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=@IsApproved,VerificationStatus=4 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
		END
		ELSE
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=0,VerificationStatus=2,ReasonForRejectionAgency=@Comments WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id			
		END
	END

END


