-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
create PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_UPDATE_ACCOUNT_DETAILS]
(
    @Id INT                 = NULL,
    @ZedId VARCHAR(50)      = NULL,
    @AccountNo VARCHAR(50)  = NULL,
    @IfscCode VARCHAR(20)   = NULL,
    @BranchAddress VARCHAR(500) = NULL,
    @BankName VARCHAR(200)  = NULL,
	@CertificationType VARCHAR(200)  = NULL,
	@UserId VARCHAR(200)  = NULL,
	@RoleId VARCHAR(200)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;


    UPDATE FinancialAssistance
    SET 
        AccountNo = @AccountNo,
        IfscCode = @IfscCode,
        BranchAddress = @BranchAddress,
        BankName = @BankName
    WHERE Id = @Id AND ZedId = @ZedId --AND TechUpgradeStatus != 7

END
