/****** Object:  StoredProcedure [dbo].[SP_Fix_Corrupted_ZedId]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_Fix_Corrupted_ZedId]  --'<redacted>',	'<redacted>',	'<redacted>'
    @OldZedId VARCHAR(50), 
    @UpdatedZedId VARCHAR(50),
    @MsmeId VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    -- Declare variables to store the count for each table
    DECLARE @CountMsmeSections INT = 0,
            @CountMsmeRequirements INT = 0,
            @CountMsmeOptions INT = 0,
            @CountMsmeSubOptions INT = 0,
            @CountMsmeEvidences INT = 0,
            @CountMsmePaymentInfo INT = 0,
			@CountPaymentGateway INT = 0,
            @CountMsme INT = 0,
            @CountMsmeBasicInformation INT = 0,
            @CountUsers INT = 0,
            @CountMsmeHistory INT = 0;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Update MsmeSections
        UPDATE MsmeSections 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND id > 6658984;
        SET @CountMsmeSections = @@ROWCOUNT;

        -- 2. Update MsmeRequirements
        UPDATE MsmeRequirements 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND id > 14176681;
        SET @CountMsmeRequirements = @@ROWCOUNT;

        -- 3. Update msmeoptions
        UPDATE msmeoptions 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND id > 14176630;
        SET @CountMsmeOptions = @@ROWCOUNT;

        -- 4. Update msmesuboptions
        UPDATE msmesuboptions 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND id > 2514553;
        SET @CountMsmeSubOptions = @@ROWCOUNT;

        -- 5. Update msmeevidences
        UPDATE msmeevidences 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND id > 13368727;
        SET @CountMsmeEvidences = @@ROWCOUNT;

        -- 6. Update msmepaymentinfo
        UPDATE msmepaymentinfo 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND CONVERT(DATE, createddate) >= '2026-07-28';
        SET @CountMsmePaymentInfo = @@ROWCOUNT;

		     UPDATE PaymentGatewayTransactions 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND CONVERT(DATE, createddate) >= '2026-07-28';
        SET @CountPaymentGateway = @@ROWCOUNT;

        -- 7. Update msme (Using your precise @MsmeId logic)
        UPDATE msme 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND msmeid = @MsmeId;
        SET @CountMsme = @@ROWCOUNT;

        -- 8. Update msmebasicinformation (Using your precise @MsmeId logic)
        UPDATE msmebasicinformation 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND msmeid = @MsmeId;
        SET @CountMsmeBasicInformation = @@ROWCOUNT;

        -- 9. Update Users
        UPDATE Users 
        SET UserId = @UpdatedZedId 
        WHERE UserId = @OldZedId AND CONVERT(DATE, createddate) >= '2026-07-28';
        SET @CountUsers = @@ROWCOUNT;

        -- 10. Update MsmeHistory
        UPDATE MsmeHistory 
        SET zedid = @UpdatedZedId 
        WHERE zedid = @OldZedId AND CONVERT(DATE, createddate) >= '2026-07-28';
        SET @CountMsmeHistory = @@ROWCOUNT;

        COMMIT TRANSACTION;
        
        -- Output the results as a table for easy reading
        SELECT 
            TableName, 
            UpdatedCount 
        FROM (
            VALUES 
                ('MsmeSections', @CountMsmeSections),
                ('MsmeRequirements', @CountMsmeRequirements),
                ('msmeoptions', @CountMsmeOptions),
                ('msmesuboptions', @CountMsmeSubOptions),
                ('msmeevidences', @CountMsmeEvidences),
                ('msmepaymentinfo', @CountMsmePaymentInfo),
                ('msme', @CountMsme),
                ('msmebasicinformation', @CountMsmeBasicInformation),
                ('Users', @CountUsers),
                ('MsmeHistory', @CountMsmeHistory)
        ) AS UpdateSummary(TableName, UpdatedCount);

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
        BEGIN
            ROLLBACK TRANSACTION;
        END

        -- Surface the exact error for troubleshooting
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_GENERATE_NEXT_ZED_INVOICE_NO]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_GENERATE_NEXT_ZED_INVOICE_NO]
(
    @NewTADAInvoiceNo VARCHAR(50) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @CurrentDate DATE = GETDATE();
    DECLARE @CurrentFY_String VARCHAR(4); 
    DECLARE @NewSequenceNumber BIGINT;
    DECLARE @LastFYStored VARCHAR(4);

    -- Start Transaction with SERIALIZABLE isolation for safety
    SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
    BEGIN TRANSACTION;

    -- 1. DETERMINE THE CURRENT FY STRING 
    SET @CurrentFY_String = 
        CASE
            WHEN MONTH(@CurrentDate) < 4
            THEN CONCAT(RIGHT(CAST(YEAR(@CurrentDate) - 1 AS VARCHAR(4)), 2), RIGHT(CAST(YEAR(@CurrentDate) AS VARCHAR(4)), 2))
            ELSE CONCAT(RIGHT(CAST(YEAR(@CurrentDate) AS VARCHAR(4)), 2), RIGHT(CAST(YEAR(@CurrentDate) + 1 AS VARCHAR(4)), 2))
        END;

    -- 2. Check if the Financial Year has changed
    SELECT @LastFYStored = ConfigValue
    FROM dbo.InvoiceConfig WITH (UPDLOCK) -- Hold lock
    WHERE ConfigKey = 'LastInvoiceFY'; -- Used PascalCase here

    -- IF the FY has changed, reset the sequence and update the config table
    IF @CurrentFY_String <> @LastFYStored
    BEGIN
        -- Reset the sequence object back to 1
        -- Referenced the sequence object using: dbo.Seq_Zed_Invoice_Number
        EXEC('ALTER SEQUENCE dbo.Seq_Zed_Invoice_Number RESTART WITH 1'); 
        
        -- Update the configuration table
        UPDATE dbo.InvoiceConfig SET ConfigValue = @CurrentFY_String 
        WHERE ConfigKey = 'LastInvoiceFY';
    END
    
    -- 3. Get the next sequence number
    -- Referenced the sequence object using: dbo.Seq_Zed_Invoice_Number
    SET @NewSequenceNumber = NEXT VALUE FOR dbo.Seq_Zed_Invoice_Number;

    -- 4. CONSTRUCT and set the OUTPUT variable
    SET @NewTADAInvoiceNo = CONCAT('ZED/', @CurrentFY_String, '/', @NewSequenceNumber);
    
    COMMIT TRANSACTION;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_GENERATE_RAMP_REPORT_DATA_FOR_ZED]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_GENERATE_RAMP_REPORT_DATA_FOR_ZED]
(
    @ZedId varchar(50) = NULL
    
)
AS
BEGIN
    SET NOCOUNT ON;

	TRUNCATE TABLE dbo.MsmeZedRampReport;

	INSERT INTO dbo.MsmeZedRampReport
(
    MsmeCertId,ZedId, UnitName, StateName, DistrictName, Certification,
    EnterpriseType, Gender, SocialCategoryName,
    RegistrationDate, CertificationDate, UdyogAadharNo, SectorsName,
    ApplicationStatus, ReasonForRejection, ApplicationCertificationCategory, AssessmentStatus
)
    
   SELECT 
		concat(M.MsmeId,C.Id),
        m.ZedId AS [ZedId],
        m.PUnitName AS [UnitName],
        m.PStateName AS [StateName],
        m.PDistrictName AS [DistrictName],
        c.Certification AS [Certifications],
        m.EnterpriseType AS [EnterpriseType],
        b.Gender AS [Gender],
        b.SocialCategoryName AS [SocialCategoryName],
        CONVERT(VARCHAR(10), m.CreatedDate, 23) AS [RegistrationDate],
        CONVERT(VARCHAR(10), C.CertificationStatusDate, 23) AS [CertificationDate],
        b.UdyogAadharNo AS [UdyogAadharNo],
        m.TwoDigitActivity AS [Sectors Name],
        CASE 
                WHEN c.Certification = 'Bronze' AND c.CertificationStatus IN (3, 4, 5, 7) THEN 'Under Evaluation'
                WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus IN (13, 14, 15, 17) THEN 'Under Evaluation'
                WHEN c.CertificationStatus = 99 THEN 'Rejected' 
                ELSE NULL
        END AS [Application Status],
        CASE   
                WHEN c.CertificationStatus = 99 AND c.Certification = 'Bronze' THEN c.AssessorRemarks 
                WHEN c.CertificationStatus = 99 AND c.Certification != 'Bronze' THEN c.SaAssessorRemarks 
                ELSE NULL 
        END AS [Reason for rejection],
        c.Certification AS [Application Certification Category],

	        CASE 
            WHEN c.Certification = 'Bronze' AND c.CertificationStatus = 6 THEN 'Completed'
            WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus = 16 THEN 'Completed'
            WHEN c.CertificationStatus = 99 THEN 'Rejected'
            WHEN c.Certification = 'Bronze' AND c.CertificationStatus = 2 AND c.DesktopAccepted = 1 AND c.DesktopAssessorId IS NOT NULL THEN 'Scheduled'
            WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus IN (8,9) AND c.AssessmentDate IS NOT NULL THEN 'Scheduled'
            WHEN c.Certification IN ('Bronze') AND c.CertificationStatus IN (3,4,5,7) THEN 'Under Evaluation'
            WHEN c.Certification IN ('Silver', 'Gold') AND c.CertificationStatus IN (13,14,15,17) THEN 'Under Evaluation'
            ELSE NULL
        END AS [Assessment Status]

	FROM Msme m
    JOIN MsmeBasicInformation b ON m.ZedId = b.ZedId
    LEFT JOIN MsmeCertifications c ON m.ZedId = REPLACE(REPLACE(c.ZedId,'_D',''), CONCAT('_',c.Id),'')
	WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
	AND NOT (
        (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
        OR (C.Certification IN ('Silver','Gold') AND C.CertificationStatus = 16)
    )
	--and m.ZedId = '<redacted>'
	order by m.ZedId ,c.CertificationStatusDate

END;
GO
