-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_API_INCENTIVES] --null,null, null, null,null,null,'<redacted>'
(
	@UdyamNo varchar(50) = NULL,
	@CertificateNo varchar(50) = NULL,
	@State varchar(100) = NULL,
	@CertificationType  varchar(100) = NULL,
	@MsmeSize varchar(50) = NULL,
	@Sector varchar(2000) = NULL,
	@Gender varchar(50) = NULL
)
AS
BEGIN
	
	

	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	IF  @CertificationType='' 
	SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	select M.PUnitName,PStateName, 
	CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,TwoDigitActivity,M.EnterpriseTypee,Certification,
	Token, UdyamNo, Certificateno, Pin, A.ApplicationId, UnitName, District, FCI, DateOfProduction, ServiceName, A.AppliedDate, ApprovalId,
    ApprovedDate, A.CreatedDate, IncentiveName, DisbursedDate, DisbursedAmount, Gender, 'API' DataFrom
	
	from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join ApiIncentives A on (B.UdyogAadharNo=A.UdyamNo)
	where (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
	AND (@State is null or M.StateId=@State) AND (@Gender IS NULL OR B.Gender=@Gender)

	UNION ALL
	---- TO SHOW THE TECHNOLOGY UPGRADATION DATA -------------
	select M.PUnitName,PStateName, 
	CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,TwoDigitActivity,M.EnterpriseTypee,Certification,
	NULL Token, B.UdyogAadharNo, NULL Certificateno, PPin Pin, NULL ApplicationId, PUnitName UnitName, M.DistrictName District, NULL FCI, NULL DateOfProduction, NULL ServiceName, NULL AppliedDate, NULL ApprovalId,
    ApproverDateOfReceiptOfPayment ApprovedDate, A.CreatedDate, NULL IncentiveName, NULL DisbursedDate, ApproverAmount DisbursedAmount, Gender, 'Technology Upgradation' DataFrom 
	
	from ZED_CONSULTANT.DBO.Msme M inner join ZED_CONSULTANT.DBO.MsmeBasicInformation B on (M.ZedId=B.ZedId) 
	inner join ZED_CONSULTANT.DBO.MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join ZED_CONSULTANT.DBO.FinancialAssistance A on (A.ZedId=C.ZedId and A.CertId=C.Id and A.CertificationType=C.Certification)
	where (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
	AND (@State is null or M.StateId=@State) AND (@Gender IS NULL OR B.Gender=@Gender) and TechUpgradeStatus=16



END

GO
/****** Object:  StoredProcedure [dbo].[SP_GET_ASSESSORS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_GET_ASSESSORS] --'<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,					-- Login User UserId
	@AssessorType varchar(100) = NULL,				-- DA / SA
	@CertificationBodyUserId varchar(100)= NULL		-- Agency UserId
)
AS
BEGIN

	IF @AssessorType=''
	SET @AssessorType = NULL

	IF @CertificationBodyUserId = ''
	SET @CertificationBodyUserId = NULL



	SELECT U.*, isnull(States,'Pan-India') States, U1.UserId AgencyUserId, U1.UserName AgencyUserName, CASE WHEN u.IsActive=1 THEN 'Active' else 'In-Active' end as IdStatus,
	ROW_NUMBER() OVER (order by U1.UserId, U.UserId) as RowNumber
	from Users U 
	inner join Users U1 on (U.CreatedBy=U1.UserId AND U1.RoleId=2) 
	left join 
	(SELECT UserId, States=STUFF  
	(  
		(  
		  SELECT DISTINCT ', '+ CAST( e.States as VARCHAR(MAX))  
		  FROM Users G,AgencyUserStates E  
		  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
		  FOR XMl PATH('')  
		),1,1,''  
	)  
	FROM AgencyUserStates t1 
	GROUP BY UserId  ) X

	on (U.UserId=X.Userid)

	WHERE U.RoleId=3 
	AND U.CreatedBy=ISNULL(@CertificationBodyUserId,U.CreatedBy) 
	AND (@AssessorType IS NULL or (@AssessorType='DA' and U.DesktopVerification=1) or (@AssessorType='SA' and U.SiteVerification=1) or (@AssessorType='FA' and U.FinancialVerification=1))
	ORDER BY AgencyUserId, U.UserId

END





GO
/****** Object:  StoredProcedure [dbo].[SP_GET_CERTIFED_COUNT_STATE_WISE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_GET_CERTIFED_COUNT_STATE_WISE]
    @State VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
IF @State = '' SET @State = NULL;
    SELECT
        M.PStateName,
        COUNT(DISTINCT CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN M.ZedId END) AS Bronze,
        COUNT(DISTINCT CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 THEN M.ZedId END) AS Silver,
        COUNT(DISTINCT CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 THEN M.ZedId END) AS Gold
    FROM Msme M
    INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
    INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
    WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
    AND (@State IS NULL OR M.PStateName = @State)
    GROUP BY M.PStateName
    ORDER BY M.PStateName;
END;
GO
