/****** Object:  StoredProcedure [dbo].[SP_GET_LIST_OF_CERTIFIED_UNITS_SUMMARY]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_LIST_OF_CERTIFIED_UNITS_SUMMARY] --'<redacted>', '<redacted>'
(
	@State varchar(50) = NULL,
	@Category varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT  ROW_NUMBER() OVER(ORDER BY StateName) SNo, upper(StateName) StateName, ISNULL(Classified,0) Classified, ISNULL(UnClassified,0) UnClassified, ISNULL(Classified,0) + ISNULL(UnClassified,0) Total FROM
	(
		SELECT StateName, Category, Count(*) Cnt FROM SelfAssessments S 
		WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
		GROUP BY StateName, Category
	) src
	PIVOT
	(
		max(Cnt) for Category in ([Classified],[UnClassified])
	) pvt
	ORDER BY StateName

	SELECT  ISNULL(Classified,0) Classified, ISNULL(UnClassified,0) UnClassified, ISNULL(Classified,0) + ISNULL(UnClassified,0) Total FROM
	(
		SELECT Category, Count(*) Cnt FROM SelfAssessments S 
		WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
		GROUP BY Category
	) src
	PIVOT
	(
		max(Cnt) for Category in ([Classified],[UnClassified])
	) pvt
END

