CREATE PROC [dbo].[SP_GET_PROFESSIONAL_DETAILS_BY_CERT_NO] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	 @UserId varchar(50) = NULL
	,@RoleId varchar(50) = NULL
	,@CertificationNo varchar(50) = NULL
	,@EmailId varchar(100) = NULL
	,@AssessorType varchar(50) = NULL
)
AS
BEGIN

	IF EXISTS(SELECT 1 FROM Users where IsActive=1 and UserId=@UserId AND RoleId=2 AND @RoleId=2)
	BEGIN
		IF EXISTS (SELECT 1 FROM Users WHERE CertificateNo=@CertificationNo and IsActive=1 and AssessorType='BronzeAssessor')
		BEGIN
			SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,NULL ZEDTAC,NULL data, NULL as CertificateNo WHERE 1=2
				
			SELECT 0 Status, 'User Already mapped to another agency' ErrorMessage
		END
		ELSE IF @AssessorType='BronzeAssessor'
		BEGIN
			print 'loop BA'
			IF EXISTS (SELECT 1 from ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates WHERE ZEDTAC=@CertificationNo AND EmailId=@EmailId AND IsActive=1 and left(ZEDTAC,2)='BA')
			BEGIN
				SELECT R.Email,R.ContactNumber,R.Name,R.State,R.District,R.City,C.ZEDTAC,R.data as CertificateNo,
				CONCAT('https://training.zed.org.in/professional',P.PhotoPath) SelfiePath
				FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates C 
				INNER JOIN ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Registrations R ON (C.RegistrationId=R.Id)  
				INNER JOIN 
				(select TOP 1 S.Id,S.BatchNo,S.CandidateId,PhotoPath,CreatedDate from ZED_CENTER_AUDIT_PROFESSIONAL.dbo.SelfiePhotos S inner join ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates C 
				ON (S.BatchNo=C.BatchNo and S.CandidateId=C.CandidateId and C.EmailId=@EmailId and C.ZEDTAC=@CertificationNo) order by S.Id DESC) P on (C.CandidateId=P.CandidateId)
				WHERE ZEDTAC=@CertificationNo and EmailId=@EmailId AND C.IsActive=1 and R.ApplyingFor='Assessor'

				SELECT 1 Status, 'Details Fetched Successfully' ErrorMessage
			END
			ELSE
			BEGIN
				SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,ZEDTAC,NULL data, NULL as CertificateNo FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates 
				WHERE 1=2
				
				SELECT 0 Status, 'Invalid details.' ErrorMessage
			END
		END
		ELSE IF @AssessorType='Assessor'
		BEGIN
			print 'loop AS'
			IF EXISTS (SELECT 1 from ZED_CENTER_AUDIT_V2.dbo.Candidates WHERE ZEDTAC=@CertificationNo AND EmailId=@EmailId AND Zedtac Is not null and left(ZEDTAC,2)='AS')
			BEGIN
				SELECT R.Email,R.ContactNumber,R.Name,R.State,R.District,R.City,C.ZEDTAC,R.data as CertificateNo FROM ZED_CENTER_AUDIT_V2.dbo.Candidates C 
				INNER JOIN ZED_CENTER_AUDIT_V2.dbo.Registrations R ON (C.RegistrationId=R.Id)  
				WHERE ZEDTAC=@CertificationNo and EmailId=@EmailId AND C.zedtac is not null and R.ApplyingFor='Assessor'

				SELECT 1 Status, 'Details Fetched Successfully' ErrorMessage
			END
			ELSE
			BEGIN
				SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,ZEDTAC,NULL data, NULL as CertificateNo FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates 
				WHERE 1=2
				
				SELECT 0 Status, 'Invalid details.' ErrorMessage
			END
		END
		ELSE
			BEGIN
				SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,ZEDTAC,NULL data, NULL as CertificateNo FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates 
				WHERE 1=2
				
				SELECT 0 Status, 'Invalid details.' ErrorMessage
			END
	END

	ELSE
	BEGIN
		SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,ZEDTAC,NULL data, NULL as CertificateNo FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.Candidates 
		WHERE 1=2

		SELECT 0 Status, 'Unauthorised User.' ErrorMessage
	END
	

END
