-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_RE_GENERATE_CERTIFICATE_LIST] --'<redacted>', 7
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	-----******https://loginzed.msme.gov.in/Monitoring/RegenerateCertificate*******-----

	SET NOCOUNT ON;

	 IF (@RoleId = '7')
    BEGIN

		select top 50 C.ZedId, C.Certification from msmecertifications C left join CertificateGenerationStatus G on (c.zedid=g.zedid and c.certification=g.certification)
		where c.certification='Bronze' and
		certificationstatus=6 and certificationstatusdate>='2026-02-23 23:06:04.857'
		and C.zedid like '_____________'
		and G.zedid is null
		order by certificationstatusdate desc
	END
    ELSE
    BEGIN
        -- Optional: Return empty set or error if RoleId is not 7
        SELECT ZedId, Certification FROM CertificateGenerationStatus;
    END
	
	

END








