	  , FORMAT(FinalSubmitDate, 'MMMM d, yyyy h:mm tt') [FinalSubmittedDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,S.[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
	  ,[CertificateNo]
	  ,[RestaurantType]
	  ,REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
	  --isnull(EstablishmentCity,'') + '<redacted>' + isnull(DistrictName,'') + '<redacted>' + StateName EstablishmentFullAddress
	  ,QuestionnaireName
	  ,WebinarId
	  ,convert(varchar,W.WebinarStartTime,100) WebinarStartTime, convert(varchar,W.WebinarEndTime,100) WebinarEndTime
	  ,convert(varchar, W.WebinarDate, 100) WebinarDate
	  ,(select TOP 1 WebinarId from WebinarRegistrations where RegistrationNumber=@RegNo) WebinarUrl,
	  (select count(*) RegCount from WebinarRegistrations where RegistrationNumber=@RegNo) RegCount,
	  --(select WebinarCertificateNo from WebinarRegistrations where RegistrationNumber=@RegNo) WebinarCertificateNo,
	  --(select FeedbackLink from WebinarRegistrations where RegistrationNumber=@RegNo) FeedbackLink,
	  NULL WebinarCertificateNo,
	  NULL FeedbackLink,
	  SaDate,
	  PaymentDate,
	  SaCertificateNo
	FROM SelfAssessments S 
	LEFT JOIN AcommodationTypes A on (S.Acommodationtype=A.Acommodationtype) 
	LEFT JOIN Webinars W on (S.WebinarId=W.Id) 
	WHERE MobileNo=@MobileNo OR RegistrationNumber=@RegNo OR RegistrationNumber=@MobileNo

END


--select len(isnull(EstablishmentCity,'') + '<redacted>' + isnull(DistrictName,'') + '<redacted>' + StateName) l from SelfAssessments order by l desc
