		--select 1 DesktopVerification,
		--1 SiteVerification,
		--CASE WHEN (select count(*) from FinancialAssistance where CertificationBodyUserId=@UserId)>0 THEN 1 ELSE 0 END AS FinancialVerification
	END
	ELSE
	BEGIn
		select 1 DesktopVerification, 1 SiteVerification, 1 FinancialVerification
	END
END

