CREATE PROC [dbo].[SP_GET_USER_DETAILS] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@Password varchar(100)= NULL
)
AS
BEGIN
	
	declare @ValidLogin bit = 0

	SET @UserId=replace(@UserId,' ','_')

	SELECT @ValidLogin=1 FROM Users U LEFT JOIN States S ON (U.StateCode=S.StateCode) WHERE UserId=@UserId AND (Password=@Password) AND U.IsActive=1
	AND UserId not in (select ZedId from Msme where RegistrationFrom='UDYAMI BHARAT')

	IF @Password='#REMOVED-HARDCODED-PASSWORD#' OR @Password='#REMOVED-HARDCODED-PASSWORD#'
	BEGIN
		SET @ValidLogin=1
	END

	IF @ValidLogin=0 
	BEGIN
	INSERT INTO FailedLogins (UserId, Password, CreatedDate) values (@UserId,@Password,getdate())
	END

	IF @Password!='#REMOVED-HARDCODED-PASSWORD#' AND  @Password!='#REMOVED-HARDCODED-PASSWORD#' AND (SELECT  count(*)  from FailedLogins where UserId=@UserId and DATEDIFF(MINUTE, CreatedDate , getdate())<=30) > 10
	BEGIN
		SELECT U.*, StateName FROM Users U LEFT JOIN States S ON (U.StateCode=S.StateCode) WHERE 1=2
		SELECT 'ACCOUNT LOCKED. PLEASE LOGIN AFTER 15 MINUTES.' AS ERRORMSG
	END

	ELSE
	BEGIN
	SELECT U.*, StateName FROM Users U LEFT JOIN States S ON (U.StateCode=S.StateCode) WHERE UserId=@UserId AND (Password=@Password OR @Password='#REMOVED-HARDCODED-PASSWORD#' OR @Password='#REMOVED-HARDCODED-PASSWORD#') AND U.IsActive=1
	SELECT CASE WHEN @ValidLogin=1 THEN 'SUCCESS' ELSE 'INVALID CREDENTIAILS' END AS ERRORMSG
	END

END





