/****** Object:  StoredProcedure [dbo].[SP_IM_GET_COUNTS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_IM_GET_COUNTS] --'<redacted>', 7
(
    @UserId VARCHAR(50),
    @RoleId INT
)
AS
BEGIN
    SET NOCOUNT ON;

    /*
       =========================================================
       STATUS MAPPING FOR DASHBOARD CARDS:
       Completed Invoices --> Status = 4 (Completed)
       Processed          --> Status = 3 (Processed)
       Pending            --> Status = 1 (Submitted) OR Status = 2 (Pending)
       Rejected Invoices  --> Status = 99 (Rejected)

	   --select * from sys.tables order by create_date desc
		--select * from ImMasterInvoiceStatuses

       =========================================================
    */

    SELECT 
        -- 1. Completed Invoices Count (Status = 4)
        ISNULL(SUM(CASE WHEN H.InvoiceStatus = 4 THEN 1 ELSE 0 END), 0) AS CompletedInvoices,

        -- 2. Processed Invoices Count (Status = 3)
        ISNULL(SUM(CASE WHEN H.InvoiceStatus = 3 THEN 1 ELSE 0 END), 0) AS ProcessedInvoices,

        -- 3. Pending Invoices Count (Submitted / Waiting Review - Status 1 or 2)
        ISNULL(SUM(CASE WHEN H.InvoiceStatus IN (1, 2) THEN 1 ELSE 0 END), 0) AS PendingInvoices,

        -- 4. Rejected Invoices Count (Status = 99)
        ISNULL(SUM(CASE WHEN H.InvoiceStatus = 99 THEN 1 ELSE 0 END), 0) AS RejectedInvoices

    FROM 
        dbo.ImInvoiceHeaders H
    WHERE 
        (@RoleId = 7 OR H.SubmittedById = @UserId);
END
GO
/****** Object:  StoredProcedure [dbo].[SP_IM_GET_INVOICE_PREVIEW]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_IM_GET_INVOICE_PREVIEW] --'<redacted>',7,NULL,'<redacted>','<redacted>'
(
    @UserId VARCHAR(50) = NULL,
    @RoleId INT = NULL,
    @StateName VARCHAR(100) = NULL,
    @Certification VARCHAR(100) = NULL,
    @AssessmentMonth DATE = NULL,
    @InvoiceNumber VARCHAR(100) = NULL 
)
AS
BEGIN
    SET NOCOUNT ON;
	   

    -- =====================================================================
    -- SCENARIO 1: INVOICE NUMBER PASSED  (Already Generated Invoice View)
    -- =====================================================================

    IF @InvoiceNumber IS NOT NULL
    BEGIN

		SELECT  
		SubmittedByName as AgencyName,
		@Certification Certification,
		FORMAT(Getdate(), 'MMMM yyyy') InvoiceMonthYear,
		FORMAT(@AssessmentMonth, 'MMMM yyyy') AssessmentMonth
		from ImInvoiceHeaders where InvoiceNumber = @InvoiceNumber

        SELECT 
            FORMAT(H.AssessmentMonth, 'MMMM yyyy') AS AssessmentMonth,
            D.ApprovalType, 
			SubmittedByName,
            SUM(D.Quantity) AS Quantity,
            MAX(D.PricePerUnitWithoutGST) AS PricePerUnitWithoutGST,
            SUM(D.TotalAmountWithoutGST) AS TotalAmountWithoutGST
        FROM 
            ImInvoiceHeaders H
        INNER JOIN 
            ImInvoiceDetails D ON H.Id = D.InvoiceId
        WHERE 
            H.InvoiceNumber = @InvoiceNumber
        GROUP BY 
			SubmittedByName,
            H.AssessmentMonth, 
            D.ApprovalType
        ORDER BY 
            H.AssessmentMonth DESC, 
            D.ApprovalType ASC; 

    END
    -- =====================================================================
    -- SCENARIO 2: INVOICE NUMBER NOT PASSED (New Invoice Preview Modal)
    -- =====================================================================
    ELSE
    BEGIN
		
		SELECT  
		UserName as AgencyName,
		@Certification Certification,
		FORMAT(Getdate(), 'MMMM yyyy') InvoiceMonthYear,
		FORMAT(@AssessmentMonth, 'MMMM yyyy') AssessmentMonth
		from Users  where UserId=@UserId and RoleId=@RoleId
		
        ;WITH CurrentMonthCounts AS (
            SELECT 
                @AssessmentMonth AS AssessmentMonth,
                CASE 
                    WHEN CertificationStatus = 6 AND LOWER(Certification) = 'bronze' THEN 'Approved'
                    WHEN CertificationStatus = 16 AND LOWER(ISNULL(Certification, '')) != 'bronze' THEN 'Approved'
                    WHEN CertificationStatus = 99 THEN 'Rejected'
                END AS ApprovalType,
                COUNT(*) AS Quantity
            FROM 
                MsmeCertifications
            WHERE 
                CertificationbodyUserid = @UserId
                AND Certification = @Certification
                AND DATEFROMPARTS(YEAR(CertificationStatusDate), MONTH(CertificationStatusDate), 1) = @AssessmentMonth
                AND (
                    (CertificationStatus = 6 AND LOWER(Certification) = 'bronze') OR 
                    (CertificationStatus = 16 AND LOWER(ISNULL(Certification, '')) != 'bronze') OR 
                    CertificationStatus = 99
                )
            GROUP BY 
                CASE 
                    WHEN CertificationStatus = 6 AND LOWER(Certification) = 'bronze' THEN 'Approved'
                    WHEN CertificationStatus = 16 AND LOWER(ISNULL(Certification, '')) != 'bronze' THEN 'Approved'
                    WHEN CertificationStatus = 99 THEN 'Rejected'
                END
        ),
        CurrentMonthData AS (
            SELECT 
                FORMAT(C.AssessmentMonth, 'MMMM yyyy') AS AssessmentMonth,
                C.AssessmentMonth AS OrderMonth,
                C.ApprovalType,
                C.Quantity,
                M.PricePerUnitWithoutGST,
                (C.Quantity * M.PricePerUnitWithoutGST) AS TotalAmountWithoutGST
            FROM 
                CurrentMonthCounts C
            LEFT JOIN 
                ImMasterUnitPrices M 
                ON M.AssessmentMonth = C.AssessmentMonth
                AND C.ApprovalType = M.ApprovalType
                AND M.Certification = @Certification
                AND M.IsActive = 1 
        )
        
        SELECT 
            AssessmentMonth, 
            ApprovalType, 
            Quantity, 
            PricePerUnitWithoutGST, 
            TotalAmountWithoutGST
        FROM 
        (
            SELECT 
                AssessmentMonth, 
                OrderMonth, 
                ApprovalType, 
                Quantity, 
                PricePerUnitWithoutGST, 
                TotalAmountWithoutGST
            FROM CurrentMonthData
            WHERE ApprovalType IS NOT NULL
        ) AS FinalResult
        ORDER BY 
            ApprovalType ASC; 

    END

		--It shows the bank details are submitted or not
	select * from ImAgencyBankDetails WHERE UserId=@UserId

END
GO
/****** Object:  StoredProcedure [dbo].[SP_IM_GET_INVOICES]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
