CREATE PROCEDURE [dbo].[SP_IM_GET_INVOICES] --'<redacted>',7
(
    @UserId varchar(50),
    @RoleId INT,
    @StateName VARCHAR(100) = NULL,
    @Certification VARCHAR(100) = NULL,
    @AssessmentMonth DATE = NULL,
    @InvoiceNumber VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        inv.Id AS InvoiceId,
		--inv.InvoiceStatus AS InvoiceStatusCode,
		StatusName InvoiceStatusName,
        inv.InvoiceNumber,
        inv.SubmittedByName,
        inv.AssessmentMonth,
        inv.StateName,
        inv.Certification,
        inv.TotalAmountWithGST,
        inv.TotalAmountWithoutGST,
        --ISNULL(stat.StatusName, '<redacted>') AS PaymentStatus,
        inv.CreatedDate
    FROM 
        ImInvoiceHeaders inv
    LEFT JOIN 
        ImMasterInvoiceStatuses stat ON inv.InvoiceStatus = stat.StatusId
    WHERE 
        -- Role based access filter (Assuming RoleId 1 is QCI Master Admin viewing all)
        (@RoleId = 7 OR inv.SubmittedById = @UserId) 
		AND InvoiceStatus>0
        AND (@StateName IS NULL OR inv.StateName = @StateName)
        AND (@Certification IS NULL OR inv.Certification = @Certification)
        AND (@AssessmentMonth IS NULL OR inv.AssessmentMonth = @AssessmentMonth)
        AND (@InvoiceNumber IS NULL OR inv.InvoiceNumber = @InvoiceNumber)
    ORDER BY 
        inv.CreatedDate DESC;
END
