/****** Object:  StoredProcedure [dbo].[SP_IM_INSERT_INVOICE_HEADERS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_IM_INSERT_INVOICE_HEADERS]
(
    @UserId VARCHAR(100),
    @RoleId INT,
    @AssessmentMonth DATE,
    @StateName VARCHAR(100),
    @Certification VARCHAR(100),
    @ModuleName VARCHAR(100),
    @SubCategory VARCHAR(100)=NULL

)
AS
BEGIN
    SET NOCOUNT ON;
    
    -- 1. Generate the Custom Invoice Number dynamically
    -- Example Output: "INV-2026-00001"
    DECLARE @NextSeqValue INT = NEXT VALUE FOR dbo.InvoiceNumberSeq;
    DECLARE @GeneratedInvoiceNumber VARCHAR(100);
	DECLARE @SubmittedByName VARCHAR(100);

	DECLARE @Quantity INT,
    @PricePerUnitWithGST DECIMAL(18,2),
    @PricePerUnitWithoutGST DECIMAL(18,2),
    @TotalAmountWithGST DECIMAL(18,2),
    @TotalAmountWithoutGST DECIMAL(18,2),

	@AppQty INT = 0, @RejQty INT = 0,
    @AppPrice DECIMAL(18,2) = 0, @RejPrice DECIMAL(18,2) = 0,
    @GrandTotalWithoutGST DECIMAL(18,2) = 0,
    @GrandTotalWithGST DECIMAL(18,2) = 0,
    @GSTPercentage DECIMAL(5,2) = 18.00

	SELECT @SubmittedByName=UserName FROM USERS WHERE UserId=@UserId

	 -- Approved Data
        SELECT 
            @AppQty = COUNT(*),
            @AppPrice = MAX(ISNULL(M.PricePerUnitWithoutGST, 0))
        FROM MsmeCertifications C
        LEFT JOIN ImMasterUnitPrices M ON M.AssessmentMonth = @AssessmentMonth 
            AND M.ApprovalType = 'Approved' AND M.Certification = @Certification AND M.IsActive = 1
        WHERE CertificationbodyUserid = @UserId
          AND M.Certification = @Certification
          AND DATEFROMPARTS(YEAR(CertificationStatusDate), MONTH(CertificationStatusDate), 1) = @AssessmentMonth
          AND ((LOWER(@Certification) = 'bronze' AND CertificationStatus = 6) OR (LOWER(@Certification) != 'bronze' AND CertificationStatus = 16));

        -- Rejected Data
        SELECT 
            @RejQty = COUNT(*),
            @RejPrice = MAX(ISNULL(M.PricePerUnitWithoutGST, 0))
        FROM MsmeCertifications C
        LEFT JOIN ImMasterUnitPrices M ON M.AssessmentMonth = @AssessmentMonth 
            AND M.ApprovalType = 'Rejected' AND M.Certification = @Certification AND M.IsActive = 1
        WHERE CertificationbodyUserid = @UserId
          AND M.Certification = @Certification
          AND DATEFROMPARTS(YEAR(CertificationStatusDate), MONTH(CertificationStatusDate), 1) = @AssessmentMonth
          AND CertificationStatus = 99;

        -- TOTAL CALCULATION
        SET @GrandTotalWithoutGST = (@AppQty * @AppPrice) + (@RejQty * @RejPrice);
        SET @GrandTotalWithGST = @GrandTotalWithoutGST + (@GrandTotalWithoutGST * @GSTPercentage / 100);


    
    -- Format it however you want (e.g., Prefix + Year + Padded Sequence)
    SET @GeneratedInvoiceNumber = 'INV-' + CAST(YEAR(GETDATE()) AS VARCHAR(4)) + '-' + RIGHT('00000' + CAST(@NextSeqValue AS VARCHAR(10)), 5);

    -- 2. Fetch the Pending Status ID
    DECLARE @PendingStatusId INT;
    SELECT TOP 1 @PendingStatusId = StatusId FROM ImMasterInvoiceStatuses WHERE StatusName = 'Pending' AND IsActive = 1;

    -- 3. Insert into the main header table using the GENERATED number
   	 INSERT INTO ImInvoiceHeaders (
            InvoiceNumber, SubmittedById, SubmittedByName, AssessmentMonth, StateName, 
            Certification, ModuleName, SubCategory, TotalAmountWithGST, TotalAmountWithoutGST, 
             InvoiceStatus, CreatedDate
        )
        VALUES (
            @GeneratedInvoiceNumber, @UserId, @SubmittedByName, @AssessmentMonth, @StateName, 
            @Certification, @ModuleName, @SubCategory, @GrandTotalWithGST, @GrandTotalWithoutGST, 
             0, GETDATE()
        );

		 DECLARE @NewInvoiceId INT = SCOPE_IDENTITY();
		
	-- Approved Records
        IF @AppQty > 0
        BEGIN
            INSERT INTO ImInvoiceDetails (InvoiceId, ApprovalType, Quantity, PricePerUnitWithoutGST, PricePerUnitWithGST, TotalAmountWithoutGST, TotalAmountWithGST, CreatedDate)
            VALUES (@NewInvoiceId, 'Approved', @AppQty, @AppPrice, (@AppPrice * 1.18), (@AppQty * @AppPrice), (@AppQty * @AppPrice * 1.18), GETDATE());
        END

        -- Rejected records
        IF @RejQty > 0
        BEGIN
            INSERT INTO ImInvoiceDetails (InvoiceId, ApprovalType, Quantity, PricePerUnitWithoutGST, PricePerUnitWithGST, TotalAmountWithoutGST, TotalAmountWithGST, CreatedDate)
            VALUES (@NewInvoiceId, 'Rejected', @RejQty, @RejPrice, (@RejPrice * 1.18), (@RejQty * @RejPrice), (@RejQty * @RejPrice * 1.18), GETDATE());
        END


   

    -- 4. Call the History SP 
    EXEC SP_IM_INSERT_INVOICE_HISTORY 
        @UserId = @UserId,
        @RoleId = @RoleId,
        @ActionTakenByName = @SubmittedByName,
        @InvoiceId = @NewInvoiceId,
        @StepName = 'Invoice Number Generated',
        --@OldStatusId = NULL,
        @StatusId = @PendingStatusId,
        @Remarks = 'Initial invoice number generation by agency.';

    -- 5. Return both the ID and the generated Number back to the API
    SELECT  *, UPPER(FORMAT(AssessmentMonth, 'MMM')) AssessmentMonthName, FORMAT(AssessmentMonth, 'yyyy') AssessmentYear from ImInvoiceHeaders where InvoiceNumber=@GeneratedInvoiceNumber
END
GO
