/****** Object:  StoredProcedure [dbo].[SP_IM_INVOICE_STATUS_UPDATE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_IM_INVOICE_STATUS_UPDATE]
(
    @UserId VARCHAR(50),
    @RoleId INT,
	@InvoiceNumber varchar(50),	
	@InvoiceStatus INT, 
	@Remarks NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    /*
       =========================================================
       INVOICE STATUS WORKFLOW DEFINITION (For Backup/Reference)
       =========================================================
       Status = 0  --> Draft (Agency yet to submit)
       Status = 1  --> Submitted (Sent by Agency, waiting for QCI)
	   Status = 2  --> Pending (Pending by QCI)
       Status = 3  --> Processed (Processed by QCI)
       Status = 4  --> Completed (Completed by QCI)
       Status = 99 --> Rejected (Sent back to Agency for correction)
       =========================================================
    */


    IF EXISTS (SELECT 1 FROM ImInvoiceHeaders WHERE InvoiceNumber = @InvoiceNumber)
    BEGIN
        UPDATE ImInvoiceHeaders
        SET 
            InvoiceStatus = @InvoiceStatus, 
            UpdatedDate = GETDATE()
        WHERE InvoiceNumber = @InvoiceNumber;

		EXEC [dbo].[SP_IM_INSERT_INVOICE_HISTORY] 
                @UserId = @UserId,
                @RoleId = @RoleId,
                @InvoiceNumber = @InvoiceNumber,
				@StatusId=@InvoiceStatus,
                @Remarks = @Remarks;

        SELECT 1 AS Status, 'Invoice Status Updated Successfully' ErrorMessage  ;
    END
    ELSE
    BEGIN
		SELECT 0 AS Status, 'Invoice Status Update Denied' ErrorMessage ;
    END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_IM_MASTER_GET_UNIT_PRICES]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_IM_MASTER_GET_UNIT_PRICES] --'<redacted>', 7
(
    @UserId VARCHAR(50),
    @RoleId INT,
    @AssessmentMonth DATE = NULL,
    @Certification VARCHAR(100) = NULL,
	@ApprovalType VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;


	SELECT ROW_NUMBER() OVER (ORDER BY AssessmentMonth DESC) AS [SNo],
	AssessmentMonth,	
	GoldApproved,
	GoldRejected,
	SilverApproved,
	SilverRejected,
	BronzeApproved,
	BronzeRejected

	FROM (
		SELECT 
			DATENAME(MONTH, AssessmentMonth) + ' ' + CAST(YEAR(AssessmentMonth) AS VARCHAR(4)) AssessmentMonth,
			Certification + ApprovalType AS PivotColumn,
			PricePerUnitWithOutGST
		FROM ImMasterUnitPrices
		WHERE 
			IsActive = 1
			AND (@AssessmentMonth IS NULL OR AssessmentMonth = @AssessmentMonth)
			AND (@Certification IS NULL OR Certification = @Certification)
			 AND (@ApprovalType IS NULL OR ApprovalType = @ApprovalType)
		 
	) AS SourceTable
	-- 2. Flip the rows into columns
	PIVOT (
		SUM(PricePerUnitWithOutGST)
		FOR PivotColumn IN (
			[GoldApproved], [GoldRejected],
			[SilverApproved], [SilverRejected],
			[BronzeApproved], [BronzeRejected]
		)
	) AS PivotTable
	ORDER BY AssessmentMonth DESC;


   
END
GO
/****** Object:  StoredProcedure [dbo].[SP_IM_MASTER_INSERT_UNIT_PRICE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
