CREATE PROCEDURE [dbo].[SP_IM_MASTER_INSERT_UNIT_PRICE] --'<redacted>', 7, 
(
    @UserId VARCHAR(50),
    @RoleId INT,
	@AssessmentMonth DATE,
    @ApprovalType VARCHAR(50),
    @Certification VARCHAR(100),
    @NewPricePerUnitWithGST DECIMAL(18,2) = NULL,
    @NewPricePerUnitWithoutGST DECIMAL(18,2)
)
AS
BEGIN
    SET NOCOUNT ON;

   
    -- 3. Mark the existing old record as inactive
    UPDATE ImMasterUnitPrices 
    SET 
        IsActive = 0,
        UpdatedDate = GETDATE()
    WHERE AssessmentMonth = @AssessmentMonth and ApprovalType = @ApprovalType and Certification = @Certification 

    -- 4. Insert the new record as the active version
    INSERT INTO ImMasterUnitPrices (
        AssessmentMonth, 
        Certification,                   -- Insert into new record
        ApprovalType, 
        PricePerUnitWithGST, 
        PricePerUnitWithoutGST, 
        IsActive,
        CreatedDate
    )
    VALUES (
        @AssessmentMonth, 
        @Certification,                  -- Insert into new record
        @ApprovalType, 
        @NewPricePerUnitWithGST, 
        @NewPricePerUnitWithoutGST, 
        1, 
        GETDATE()
    );
END
GO
