CREATE PROCEDURE [dbo].[SP_IM_SUBMIT_INVOICE]
(
    @UserId VARCHAR(50),
    @RoleId INT,
    @InvoiceId INT 
)
AS
BEGIN
    SET NOCOUNT ON;

    /*
       =========================================================
       INVOICE STATUS WORKFLOW DEFINITION (For Backup/Reference)
       =========================================================
       Status = 0  --> Draft (Agency yet to submit)
       Status = 1  --> Submitted (Sent by Agency, waiting for QCI)
	   Status = 2  --> Pending (Pending by QCI)
       Status = 3  --> Processed (Processed by QCI)
       Status = 4  --> Completed (Completed by QCI)
       Status = 99 --> Rejected (Sent back to Agency for correction)
       =========================================================
    */


    IF EXISTS (SELECT 1 FROM ImInvoiceHeaders WHERE Id = @InvoiceId AND SubmittedById = @UserId)
    BEGIN
        UPDATE ImInvoiceHeaders
        SET 
            InvoiceStatus = 1, 
            UpdatedDate = GETDATE()
        WHERE Id = @InvoiceId;

		EXEC [dbo].[SP_IM_INSERT_INVOICE_HISTORY] 
                @UserId = @UserId,
                @RoleId = @RoleId,
                @ActionTakenByName = @UserId,
                @InvoiceId = @InvoiceId,
				@StatusId=1,
                @StepName = 'Invoice Submitted',
                @Remarks = 'Agency submitted the invoice.';

        SELECT 1 AS Status, 'Invoice Sumitted Successfully' ErrorMessage  ;
    END
    ELSE
    BEGIN
		SELECT 0 AS Status, 'Invalid Invoice Id or User Access Denied' ErrorMessage ;
    END
END
GO
