CREATE PROCEDURE [dbo].[SP_INSERT_FACILITATOR_DETAILS] --'<redacted>', '<redacted>',null,null,null,null,null,null,null,null,'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@EmailId varchar(100) = NULL,
	@MobileNo varchar(100) = NULL,
	@PhotoId VarChar(2000) = NULL,
	@TimeStamp varchar(2000) = NULL,
	@Latitude VarChar(200) = NULL,
	@Longitude VarChar(200) = NULL,
	@ReferenceId Varchar(2000) = NULL,
	@PhotoPath Varchar(2000) = NULL


)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CertificateNo varchar(200) = NULL,
	@FacilitatorName varchar(200) = NULL,
	@OrganisingPartnerName varchar(200) = NULL,
	@OrganisingPartnerEmailId varchar(200) = NULL,
	@CandidateId varchar(50) = NULL,
	@ExamSelfiePath varchar(2000) = NULL,
	@MsmeCertificationId varchar(50) = NULL,
	@IsActive bit = NULL


	SELECT @MsmeCertificationId=Id FROM MsmeCertifications where ZedId=@ZedId and Certification=@Certification


	SELECT @CertificateNo=ZedTac,@OrganisingPartnerEmailId=OrganisingPartner,@FacilitatorName=concat(FirstName,' ',Lastname), @CandidateId=CandidateId,
			@IsActive=IsActive
	FROM ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Candidates WHERE EmailId=@EmailId and MobileNo=@MobileNo and ZedTac is not null

	SELECT TOP 1 @ExamSelfiePath=PhotoPath from ZED_CENTER_AUDIT_PROFESSIONAL.DBO.SelfiePhotos WHERE CandidateId=@CandidateId ORDER BY ID DESC

	select @OrganisingPartnerName=FirstName from ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Users where UserId=@OrganisingPartnerEmailId and RoleId=3

	--IF EXISTS (select * from MsmefacilitatorEntries where FacilitatorEmailId=@EmailId and FacilitatorMobileNo=@MobileNo and Certification=@Certification and LoginVerified='<redacted>')
	--BEGIN
	--	UPDATE MsmefacilitatorEntries SET FacilitatorName=@FacilitatorName,FacilitatorEmailId=@EmailId,FacilitatorMobileNo=@MobileNo,
	--	CertificateNo=@CertificateNo,OrgPartnerName=@OrganisingPartnerName,OrgPartnerEmailId=@OrganisingPartnerEmailId,LoginVerified,PhotoPath,CreatedDate
	--END



	IF @CertificateNo is not null and @IsActive=1 -- EXISTS(SELECT * FROM ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Candidates WHERE EmailId=@EmailId and MobileNo=@MobileNo and ZedTac is not null)
	BEGIN

		UPDATE MsmeFacilitatorEntries SET LoginVerified='Old' where ZedId=@ZedId and Certification=@Certification and LoginVerified='Yes'

		INSERT INTO MsmeFacilitatorEntries (ZedId,Certification,FacilitatorName,FacilitatorEmailId,FacilitatorMobileNo,CertificateNo,OrgPartnerName,OrgPartnerEmailId,LoginVerified,CreatedDate,PhotoId,TimeStamp,Latitude,Longitude,ReferenceId,ExamSelfiePath,CandidateId,FaciCertId)
		SELECT @ZedId,@Certification,@FacilitatorName,@EmailId,@MobileNo,@CertificateNo,@OrganisingPartnerName,@OrganisingPartnerEmailId,'Yes',getdate(),@PhotoId,@TimeStamp,@Latitude,@Longitude,@ReferenceId,@ExamSelfiePath,@CandidateId,@MsmeCertificationId

		SELECT 1 Status, 'FACILITATOR DETAILS ADDED SUCCESSFULLY' Message
	END
	ELSE
	BEGIN
		INSERT INTO MsmeFacilitatorEntries (ZedId,Certification,FacilitatorName,FacilitatorEmailId,FacilitatorMobileNo,CertificateNo,OrgPartnerName,OrgPartnerEmailId,LoginVerified,CreatedDate,PhotoId,TimeStamp,Latitude,Longitude,ReferenceId,FaciCertId)
		SELECT @ZedId,@Certification,@FacilitatorName,@EmailId,@MobileNo,@CertificateNo,@OrganisingPartnerName,@OrganisingPartnerEmailId,'No',getdate(),@PhotoId,@TimeStamp,@Latitude,@Longitude,@ReferenceId,@MsmeCertificationId
		
		SELECT 0 Status, CASE WHEN @IsActive=1 THEN 'INVALID FACILITATOR DETAILS.' ELSE 'USER IS BLOCKED.' END AS Message
	END

	

END







