CREATE PROC [dbo].[SP_INSERT_USER] 
(
	 @UserId varchar(200)=NULL
	,@UserName varchar(200)
	,@Password varchar(200)=NULL
	,@RoleId int = NULL
	,@Email varchar(200) = NULL
	,@MobileNo varchar(15) = NULL
	,@CreatedBy varchar(50) = NULL
	,@SpocName varchar(200) = NULL
	,@Address varchar(2000) = NULL
	,@PinCode varchar(50) = NULL
	,@PreferredStates varchar(2000) = NULL
	,@NicSectors varchar(4000) = NULL
	,@AreaOfknowledge varchar(4000) = NULL
	,@IdProofType varchar(50) = NULL
	,@IdProofNumber varchar(50) = NULL
	,@GstNumber varchar(50) = NULL
	,@DesktopVerification varchar(50) = NULL
	,@SiteVerification varchar(50) = NULL
	,@FinancialVerification varchar(50) = NULL
	,@ReasonForRejection varchar(2000) = NULL
	,@AssessorType varchar(50) ='Assessor'
	,@CertificateNo varchar(50) = NULL
	,@ProfessionalEmail varchar(50) = NULL
	,@OrgPartnerId varchar(100) = NULL
	

)
AS
BEGIN
     
	 IF @RoleId=2
	  Begin
					------ADDING USERS IN ZED-------------
		DECLARE @BodiesUserId varchar(200),@OrgPartnerName varchar(200) = NULL    
		SET @BodiesUserId =concat ('ZEDAA',RIGHT(concat('00',convert(varchar(200),Next Value For BodiesSequence)),4))
		select @BodiesUserId

		SELECT @OrgPartnerName=FirstName FROM ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Users WHERE ROLEID=3 and UserId=@OrgPartnerId ORDER BY FirstName

		INSERT INTO USERS (UserId, UserName,[Password],Email,MobileNo,SpocName,[Address],PinCode,CreatedBy,RoleId,AgencyGstNumber,IsActive,DesktopVerification,SiteVerification, FinancialVerification, OrgPartnerId, OrgPartnerName)
	    VALUES(@BodiesUserId, @UserName, @Password, @Email, @MobileNo, @SpocName, @Address,@PinCode, @CreatedBy, @RoleId,@GstNumber, 1, @DesktopVerification,@SiteVerification, @FinancialVerification, @OrgPartnerId, @OrgPartnerName)

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		------------------------ADDING USERS IN SURVEILLANCE--------------------
		INSERT INTO ZED_SURVEILLANCE.dbo.USERS (UserId, UserName,[Password],Email,MobileNo,SpocName,[Address],PinCode,CreatedBy,RoleId,AgencyGstNumber,IsActive,DesktopVerification,SiteVerification, FinancialVerification)
	    VALUES(@BodiesUserId, @UserName, @Password, @Email, @MobileNo, @SpocName, @Address,@PinCode, @CreatedBy, @RoleId,@GstNumber, 1, @DesktopVerification,@SiteVerification, @FinancialVerification)

		INSERT INTO ZED_SURVEILLANCE.dbo.AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO ZED_SURVEILLANCE.dbo.UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null
			
	  End

	 IF   @RoleId=3
	  Begin

		DECLARE @IdPrefix varchar(50) 
		IF @AssessorType='Assessor'
		BEGIN
		SET @IdPrefix='ZEDAS'
		END
		ELSE IF @AssessorType='BronzeAssessor'
		BEGIN
		SET @IdPrefix='ZEDBA'
		END

		DECLARE @AssessorsUserId varchar(200)    
		SET @AssessorsUserId =concat (@IdPrefix,RIGHT(concat('00',convert(varchar(200),Next Value For AssessorsSequence)),4))
		select @AssessorsUserId
		select  @DesktopVerification=DesktopVerification,@SiteVerification=SiteVerification, @FinancialVerification=FinancialVerification from users where UserId=@CreatedBy
		IF @SiteVerification=1 
		BEGIN
		SET @DesktopVerification=1
		END

		INSERT INTO USERS (UserId, UserName,[Password],Email,MobileNo,CreatedBy,RoleId,IdProofType,IdProofNumber,DesktopVerification,SiteVerification, FinancialVerification,IsActive,Address,Pincode,AssessorType,CertificateNo,ProfessionalEmailId)
	    VALUES(@AssessorsUserId, @UserName, @Password, @Email, @MobileNo, @CreatedBy, @RoleId,@IdProofType,@IdProofNumber,@DesktopVerification,@SiteVerification, @FinancialVerification, 1,@Address,@PinCode,@AssessorType,@CertificateNo,@ProfessionalEmail)

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @AssessorsUserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @AssessorsUserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO UserAreaOfKnowledge (UserId,RoleId,AreaOfKnowledge,IsActive)
	    select @AssessorsUserId, @RoleId, value, 1 from string_split(@AreaOfknowledge,',')

		---------------- INSERTING USERS IN SURVEILLANCE-----------------------------------
		IF @AssessorType='Assessor'
		BEGIN
			INSERT INTO ZED_SURVEILLANCE.dbo.USERS (UserId, UserName,[Password],Email,MobileNo,CreatedBy,RoleId,IdProofType,IdProofNumber,DesktopVerification,SiteVerification, FinancialVerification,IsActive,Address,Pincode)
			VALUES(@AssessorsUserId, @UserName, @Password, @Email, @MobileNo, @CreatedBy, @RoleId,@IdProofType,@IdProofNumber,@DesktopVerification,@SiteVerification, @FinancialVerification, 1,@Address,@PinCode)

			INSERT INTO ZED_SURVEILLANCE.dbo.AgencyUserStates (UserId,RoleId,States,IsActive)
			select @AssessorsUserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

			INSERT INTO ZED_SURVEILLANCE.dbo.UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
			select @AssessorsUserId, @RoleId, value, 1 from string_split(@NicSectors,',')
			update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

			INSERT INTO ZED_SURVEILLANCE.dbo.UserAreaOfKnowledge (UserId,RoleId,AreaOfKnowledge,IsActive)
			select @AssessorsUserId, @RoleId, value, 1 from string_split(@AreaOfknowledge,',')
		END

			
	  End
END



GO
