CREATE PROC [dbo].[SP_JOB_ENABLE_FOR_RE_CERTIFICATION] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(100) = NULL,
	@HistoryText varchar(255) = 'ReCertification Enabled'
)
AS
BEGIN

		--IF NOT EXISTS (select * from MsmeCertifications where ZedId=@ZedId and ((CertificationStatus<16 and Certification!='<redacted>') OR (CertificationStatus<6 and Certification='<redacted>')) )
		BEGIN
				update MsmeBasicInformation SET ReCertification=1, ReCertificationLevel=@CertificationType where ZedId=@ZedId 		
