/****** Object:  StoredProcedure [dbo].[SP_JOB_FOR_SUSPENDING_ZEDIDS_IN_SURVEILLANCE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_FOR_SUSPENDING_ZEDIDS_IN_SURVEILLANCE] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;


			DECLARE @Updated TABLE (ZedId VARCHAR(50), Certification VARCHAR(50), OldPhase VARCHAR(50))


			---- SUSPEND QUERY (Months 16 to 18)
			--UPDATE C
			--SET C.CertificationPhase = '<redacted>' FROM Msme M
			--INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
			--WHERE C.CertificationStatus = 16
			--  AND C.CertificationPhase = '<redacted>'
			--  AND DATEDIFF(MONTH, C.CertificationStatusDate, GETDATE()) BETWEEN 16 AND 18
			--  AND ((C.Certification = '<redacted>' AND M.IsSurSilverPaymentDone IS NULL) 
			--	   OR (C.Certification = '<redacted>' AND M.IsSurGoldPaymentDone IS NULL))
			--  AND C.RestrictMail IS NULL

		 --INSERT INTO CertificationPhaseChangeHistory (ZedId, Certification, OldPhase, NewPhase)
		 --SELECT ZedId, Certification, OldPhase, '<redacted>' FROM @Updated;

		 --DELETE FROM @Updated;


			---- WITHDRAWN QUERY (Month 19+ and no payment done)
			--UPDATE C
			--SET C.CertificationPhase = '<redacted>' FROM Msme M
			--INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
			--WHERE C.CertificationStatus = 16
			--  AND C.CertificationPhase IN ('<redacted>')
			--  AND DATEDIFF(MONTH, C.CertificationStatusDate, GETDATE()) >= 19
			--  AND ((C.Certification = '<redacted>' AND M.IsSurSilverPaymentDone IS NULL) 
			--	   OR (C.Certification = '<redacted>' AND M.IsSurGoldPaymentDone IS NULL))
			--  AND C.RestrictMail IS NULL

		 --INSERT INTO CertificationPhaseChangeHistory (ZedId, Certification, OldPhase, NewPhase)
		 --SELECT ZedId, Certification, OldPhase, '<redacted>' FROM @Updated;


		 -- 1. SUSPEND LOGIC (Months 16-18 OR Months 28-30)
	UPDATE C
	SET C.CertificationPhase = 'SUSPENDED'
	OUTPUT inserted.ZedId, inserted.Certification, deleted.CertificationPhase INTO @Updated
	FROM Msme M
	INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
	WHERE C.CertificationStatus = 16
	  AND C.CertificationPhase = 'ACTIVE'
	 -- AND C.RestrictMail IS NULL
	  AND (
		-- Surveillance 1 Suspend Condition
		(DATEDIFF(MONTH, C.CertificationStatusDate, GETDATE()) BETWEEN 16 AND 18 
		 AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL)))
		OR 
		-- Surveillance 2 Suspend Condition
		(DATEDIFF(MONTH, C.CertificationStatusDate, GETDATE()) BETWEEN 28 AND 30 
		 AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL)))
	  )

	-- 2. WITHDRAWN LOGIC (Month 19-23 OR Month 31+)
	UPDATE C
	SET C.CertificationPhase = 'WITHDRAWN'
	OUTPUT inserted.ZedId, inserted.Certification, deleted.CertificationPhase INTO @Updated
	FROM Msme M
	INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
	WHERE C.CertificationStatus = 16
	  AND C.CertificationPhase = 'SUSPENDED'
	  --AND C.RestrictMail IS NULL
	  AND (
		-- Surveillance 1 Withdraw Condition
		(DATEDIFF(MONTH, C.CertificationStatusDate, GETDATE()) BETWEEN 19 AND 23 
		 AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL)))
		OR 
		-- Surveillance 2 Withdraw Condition
		(DATEDIFF(MONTH, C.CertificationStatusDate, GETDATE()) >= 31 
		 AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL)))
	  )

	-- Log changes to history
	INSERT INTO CertificationPhaseChangeHistory (ZedId, Certification, OldPhase, NewPhase)
	SELECT ZedId, Certification, OldPhase, 'SUSPENDED/WITHDRAWN' FROM @Updated;


END

