/****** Object:  StoredProcedure [dbo].[SP_JOB_FOR_UPDATE_LASTEST_CERTIFICATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_FOR_UPDATE_LASTEST_CERTIFICATION] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

		WITH RankedCertifications AS (
        SELECT 
            zedid,
            Certification,
            ROW_NUMBER() OVER (
                PARTITION BY zedid 
                ORDER BY 
                    CASE 
                        WHEN Certification = 'gold' THEN 3
                        WHEN Certification = 'silver' THEN 2
                        WHEN Certification = 'bronze' THEN 1
                        ELSE 0
                    END DESC,
                    CertificationStatusDate DESC  
            ) AS rn
        FROM MsmeCertifications WITH (NOLOCK)
        WHERE 
            (Certification = 'bronze' AND CertificationStatus = 6)
            OR 
            (Certification IN ('silver', 'gold') AND CertificationStatus = 16)
    )

    UPDATE B
    SET B.LastestCertification = R.Certification
    FROM msmebasicinformation B WITH (ROWLOCK, UPDLOCK, READPAST)
    JOIN RankedCertifications R ON B.zedid = R.zedid
    WHERE B.LastestCertification IS NULL
      AND R.rn = 1
    OPTION (RECOMPILE);
			


END

GO
/****** Object:  StoredProcedure [dbo].[SP_JOB_FOR_UPDATE_LATEST_CERTIFICATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_JOB_FOR_UPDATE_LATEST_CERTIFICATION] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;


    DECLARE @YesterdayStart DATETIME = CAST(DATEADD(DAY, -1, GETDATE()) AS DATE);
    DECLARE @YesterdayEnd DATETIME   = CAST(GETDATE() AS DATE);

    -- 2. Use a CTE to isolate only the best record per ZEDID from yesterday
    WITH RankedCertifications AS (
        SELECT 
            zedid,
            Certification,
            ROW_NUMBER() OVER (
                PARTITION BY zedid 
                ORDER BY 
                    CASE 
                        WHEN Certification = 'gold' THEN 3
                        WHEN Certification = 'silver' THEN 2
                        WHEN Certification = 'bronze' THEN 1
                        ELSE 0
                    END DESC,
                    CertificationStatusDate DESC  
            ) AS rn
        FROM MsmeCertifications
        WHERE 
            (
                (Certification = 'bronze' AND CertificationStatus = 6)
                OR 
                (Certification IN ('silver', 'gold') AND CertificationStatus = 16)
            )
            -- Filter only for yesterday's data
            AND CertificationStatusDate >= @YesterdayStart 
            AND CertificationStatusDate < @YesterdayEnd
    )

    -- 3. Update only the target column where a change is actually required
    UPDATE B
    SET B.LastestCertification = R.Certification
    FROM msmebasicinformation B
    INNER JOIN RankedCertifications R ON B.zedid = R.zedid
    WHERE R.rn = 1 
      -- ONLY update if the value is different (Prevents hanging/unnecessary locks)
      AND (B.LastestCertification IS NULL OR B.LastestCertification <> R.Certification);
		
END
GO
