CREATE PROCEDURE [dbo].[SP_JOB_TO_CREATE_RENAMING_BATCH_FILES] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	DECLARE @Cmd NVARCHAR(1000);
    DECLARE @Timestamp NVARCHAR(20);

	---------INSERTING COMPLETED RECORDS-----------
	insert into FolderRenameHIstory (Id,ZedId,RenameDate,CertificationType)
	select H.Id,H.ZedId,getdate() RenameDate,CertificationType from MsmeCertifications C WITH (NOLOCK) inner join  
	MsmeHistory H WITH (NOLOCK) on (C.ZedId=H.ZedId) where StatusType like '%unit rejected%' and CertificationType='Bronze' and H.CreatedDate < DATEADD(HOUR, -2, GETDATE())
	and H.id>(select max(Id) from FolderRenameHIstory where RenameDone='Yes')
	order by H.CreatedDate

	IF EXISTS (select * from FolderRenameHIstory where RenameDone is null)
	BEGIN

		-- Get current timestamp in the format YYYYMMDD_HHMMSS
		SET @Timestamp = REPLACE(REPLACE(REPLACE(CONVERT(NVARCHAR, GETDATE(), 120), '-', ''), ' ', '_'), ':', '');

		SET @Cmd = 'bcp "SELECT CONCAT(''REN E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\PDFs\SA\'', CASE WHEN CHARINDEX(''_D_'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D_'', ZedId) - 1) WHEN CHARINDEX(''_D'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D'', ZedId) - 1) ELSE ZedId END,''  '', ZedId) trimmed_string FROM ZEDCS_V2_LIVE.dbo.FolderRenameHIstory WHERE RenameDone is NULL UNION SELECT CONCAT(''REN E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\'', CASE WHEN CHARINDEX(''_D_'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D_'', ZedId) - 1) WHEN CHARINDEX(''_D'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D'', ZedId) - 1) ELSE ZedId END,''  '', ZedId) trimmed_string FROM ZEDCS_V2_LIVE.dbo.FolderRenameHIstory WHERE RenameDone is NULL" queryout "E:\SREENIVAS\FolderRename.bat" -c -T';
 		  ----Execute the bcp command to generate the batch file
		EXEC xp_cmdshell @Cmd;

		 SET @Cmd = 'bcp "SELECT CONCAT(''REN E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\PDFs\SA\'', CASE WHEN CHARINDEX(''_D_'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D_'', ZedId) - 1) WHEN CHARINDEX(''_D'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D'', ZedId) - 1) ELSE ZedId END,''  '', ZedId) trimmed_string FROM ZEDCS_V2_LIVE.dbo.FolderRenameHIstory WHERE RenameDone is NULL UNION SELECT CONCAT(''REN E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\'', CASE WHEN CHARINDEX(''_D_'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D_'', ZedId) - 1) WHEN CHARINDEX(''_D'', ZedId) > 0 THEN LEFT(ZedId, CHARINDEX(''_D'', ZedId) - 1) ELSE ZedId END,''  '', ZedId) trimmed_string FROM ZEDCS_V2_LIVE.dbo.FolderRenameHIstory WHERE RenameDone is NULL" queryout "E:\SREENIVAS\FolderRename_' + @Timestamp + '.txt" -c -T';
 		  ----Execute the bcp command to generate the batch file
		EXEC xp_cmdshell @Cmd;

		-----------UPDATING THE FLAG-------------
		update FolderRenameHIstory set RenameDone='Yes' where RenameDone is null

		---- Execute the created batch file with logging
	 --   SET @Cmd = '<redacted>' + @Timestamp + '<redacted>' + @Timestamp + '<redacted>';
	 --   EXEC xp_cmdshell @Cmd;

		---- Execute the created batch file
	 --   SET @Cmd = '<redacted>' + @Timestamp + '<redacted>';
	 --   EXEC xp_cmdshell @Cmd;

	 END
END

