	SET NOCOUNT ON;

	DECLARE @RecipientEmail NVARCHAR(255)
	DECLARE @ZedId NVARCHAR(255)
	DECLARE @UnitName NVARCHAR(255)
	DECLARE @Address NVARCHAR(255)
	DECLARE @Certification NVARCHAR(255)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))
	DECLARE @Password NVARCHAR(255)
	DECLARE @DueDate NVARCHAR(255)

	
	DECLARE dailyMailCursor CURSOR FOR


	----------NEW LOGIC START------------
	SELECT top 100 M.EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 27, C.CertificationStatusDate), 'MMM dd yyyy') AS DueDate, U.Password 
	FROM Msme M  
	INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId)
	INNER JOIN Users U ON (C.ZedId = U.UserId)
	WHERE C.CertificationStatus = 16
	-- 1. Main Certification Date Logic (23 months ago)
	--AND CAST(C.CertificationStatusDate AS DATE) = CAST(DATEADD(MONTH, -23, GETDATE()) AS DATE)
	--and C.zedid in (select zedid from SecondSurveillanceMailPendingIds)
	and c.ZedId in ('ZEDMSME237291') 
	AND C.CertificationPhase = 'ACTIVE'

	-- 2. Surveillance 1 Completion Check (3 Months should be Completed)
	AND EXISTS (
		SELECT 1 
		FROM ZED_SURVEILLANCE.dbo.MsmeCertifications S1
		WHERE S1.ZedId = C.ZedId 
		AND S1.Certification = C.Certification 
		AND S1.CertificationStatus = 16
		AND DATEDIFF(MONTH, S1.CertificationStatusDate, GETDATE()) >= 3
	)

	-- 3. Upgrade Logic: Exclude Silver users if already Certified Gold
	AND NOT (
		C.Certification = 'Silver' 
		AND EXISTS (
			SELECT 1 FROM MsmeCertifications Upgrade 
			WHERE Upgrade.ZedId = M.ZedId 
			AND Upgrade.Certification = 'Gold'
			AND Upgrade.CertificationStatus = 16
		)
	)

	-- 4. Prevent duplicate emails
	AND (C.AutoMailSend IS NULL OR C.AutoMailSend <> 4)
	
	ORDER BY C.CertificationStatusDate
	----------NEW LOGIC END--------------


	--SELECT M.EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification,FORMAT(DATEADD(MONTH, 27, C.CertificationStatusDate), '<redacted>') AS DueDate, U.Password FROM Msme M  
