		---------------UPDATING THE FLAG AFTER MAIL SEND----------------------------
		UPDATE MsmeCertifications SET AutoMailSend = 4, EnableSurveillance1=2  WHERE ZedId = @ZedId AND Certification = @Certification
		UPDATE MsmeBasicInformation SET SurvCertificationLevel = @Certification WHERE ZedId = @ZedId 

		
		
		IF @Certification='Silver'
		BEGIN
			UPDATE Msme SET IsSurSilverPaymentDone=NULL where ZedId = @ZedId
			UPDATE ZED_SURVEILLANCE.dbo.Msme SET IsSilverPaymentDone=NULL where ZedId = @ZedId

			update zed_surveillance.dbo.MsmeBasicInformation SET ReSurveillance=1, ReSurveillanceLevel=@Certification where ZedId=@ZedId 		
			update  zed_surveillance.dbo.MsmePaymentInfo SET ReSurveillance=1 where ZedId=@ZedId and Certification=@Certification
			update  zed_surveillance.dbo.PaymentGateWayTransactions SET GwReSurveillance=1 where ZedId=@ZedId and Certification=@Certification
		END
