			UPDATE ZED_SURVEILLANCE.dbo.Msme SET IsGoldPaymentDone=NULL where ZedId = @ZedId

			update zed_surveillance.dbo.MsmeBasicInformation SET ReSurveillance=1,ReSurveillanceLevel=@Certification where ZedId=@ZedId 		
			update  zed_surveillance.dbo.MsmePaymentInfo SET ReSurveillance=1 where ZedId=@ZedId and Certification=@Certification
			update  zed_surveillance.dbo.PaymentGateWayTransactions SET GwReSurveillance=1 where ZedId=@ZedId and Certification=@Certification




		END

		INSERT INTO SurveillanceAutoMailHistory (ZedId,Certification,RecipientEmail,UnitName,MailNumber,SurveillanceNo)
		SELECT @ZedId,@Certification,@RecipientEmail,@UnitName,1,2



		FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification,@DueDate, @Password
