-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_TO_SEND_APPLY_FOR_SURVEILLANCE_MAIL] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RecipientEmail NVARCHAR(255)
	DECLARE @ZedId NVARCHAR(255)
	DECLARE @UnitName NVARCHAR(255)
	DECLARE @Address NVARCHAR(255)
	DECLARE @Certification NVARCHAR(255)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))
	DECLARE @Password NVARCHAR(255)
	DECLARE @DueDate NVARCHAR(255)

	
	DECLARE dailyMailCursor CURSOR FOR


	SELECT EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 15, CertificationStatusDate), 'MMM dd yyyy') AS DueDate, U.Password FROM Msme M 
	INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
	INNER JOIN Users U ON C.ZedId = U.UserId
	WHERE CertificationStatus = 16 AND AutoMailSend IS NULL 	
	AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-11, GETDATE()) AS DATE)
	AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL))
	and C.RestrictMail IS NULL
	--and EmailId in ('<redacted>','<redacted>')
	order by CertificationStatusDate

	OPEN dailyMailCursor
	FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @DueDate, @Password

	DECLARE @Subject NVARCHAR(255)
	

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Subject = 'Apply for Surveillance Assessment under “MSME Sustainable (ZED) Certification” Scheme - ' + COALESCE(@ZedId, '')
		DECLARE @htmlBody NVARCHAR(MAX)

		SET @htmlBody = '<html><link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet"><div><table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0" ><tr><td><br><br><div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;background: #ffffff;margin-bottom: 15px;max-width: 600px;"><img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" /></div><table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;"><tr><td style="padding: 0 3em;line-height: 26px;"><p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir, <br>Greetings of the day!</p><p style="font-size: 13px; margin-bottom: 0;">This is with reference to your ZED Certification under “MSME Sustainable (ZED) Certification” Scheme.</p><p style="font-size: 13px; margin-bottom: 0;">As per the scheme guidelines your surveillance assessment will be due after 3 month from date of this email. </p><p style="font-size: 13px; margin-bottom: 0;">Kindly note that the surveillance assessment is mandatory for continuation of the certification. Failure to do so will lead to suspension/withdrawal of the certification.</p><p style="font-size: 13px; margin-bottom: 0;">You may apply for the surveillance assessment using the details given below:</p><table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0"><tbody bgcolor="#ffffff"><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">ZED ID</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">PASSWORD</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Password, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Name</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@UnitName, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Certification, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Address</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Address, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Surveillance Due Date</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@DueDate, '') + '</td></tr></tbody></table> <br/><div style="text-align: center; padding: 30px 0;"><a href="http://loginzed.msme.gov.in/Msme/Login" target="_blank" style="display: block; margin: 0 auto; width: 300px; line-height: 42px; color: #ffffff; background-color: #45A5AD; text-decoration: none; border-radius: 4px; text-align: center;">Click here to Apply</a></div> <br/><p style="font-size: 13px; margin-bottom: 0;">In case of any query, please mail us at: zed@qcin.org. Please mention your ZED ID in all your correspondence.</p><p style="font-size: 13px; margin-bottom: 20px;">Thanks and Regards,<br>ZED Team</p></td></tr></table><div style="text-align: center; padding-top: 30px; padding-bottom: 30px;"><small style="font-size: 12px; color: #ffffff;">&copy; ZED ' + @CurrentYear + '</small></div></td></tr></table></div></html>'


	   -- PRINT @htmlBody

		-----to send the email
		 EXEC msdb.dbo.sp_send_dbmail
			 @profile_name = 'ZedAdmin',
			 @recipients = @RecipientEmail,
			 @subject = @Subject,
			 @body = @htmlBody,
			 @body_format = 'HTML';


		---------------UPDATING THE FLAG AFTER MAIL SEND----------------------------
		UPDATE MsmeCertifications SET AutoMailSend = 1, EnableSurveillance1=1  WHERE ZedId = @ZedId AND Certification = @Certification
		UPDATE MsmeBasicInformation SET SurvCertificationLevel = @Certification WHERE ZedId = @ZedId 

		INSERT INTO SurveillanceAutoMailHistory (ZedId,Certification,RecipientEmail,UnitName,MailNumber)
		SELECT @ZedId,@Certification,@RecipientEmail,@UnitName,1



		FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification,@DueDate, @Password
	END

	CLOSE dailyMailCursor
	DEALLOCATE dailyMailCursor


END

GO
