-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_TO_SEND_APPLY_FOR_SURVEILLANCE_MAIL_REM1] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RecipientEmail NVARCHAR(255)
	DECLARE @ZedId NVARCHAR(255)
	DECLARE @UnitName NVARCHAR(255)
	DECLARE @Address NVARCHAR(255)
	DECLARE @Certification NVARCHAR(255)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))
	DECLARE @Password NVARCHAR(255)
	DECLARE @DueDate NVARCHAR(255)

	
	DECLARE dailyMailCursor CURSOR FOR

	SELECT EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 15, CertificationStatusDate), 'MMM dd yyyy') AS DueDate, U.Password FROM Msme M 
	INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
	INNER JOIN Users U ON C.ZedId = U.UserId
	WHERE CertificationStatus = 16 AND AutoMailSend = 1 
	AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-12, GETDATE()) AS DATE)
	AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL))
	and C.RestrictMail IS NULL
	--and EmailId = '<redacted>'
	order by CertificationStatusDate

	OPEN dailyMailCursor
	FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @DueDate, @Password

	DECLARE @Subject NVARCHAR(255)
	

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Subject = 'Reminder 1: Apply for Surveillance Assessment under “MSME Sustainable (ZED) Certification” Scheme - ' + COALESCE(@ZedId, '')
		DECLARE @htmlBody NVARCHAR(MAX)

		SET @htmlBody = '<html><link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet"><div><table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0" ><tr><td><br><br><div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;background: #ffffff;margin-bottom: 15px;max-width: 600px;"><img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" /></div><table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;"><tr><td style="padding: 0 3em;line-height: 26px;"><p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir, <br>Greetings of the day!</p><p style="font-size: 13px; margin-bottom: 0;">This is with reference to your ZED Certification under “MSME Sustainable (ZED) Certification” Scheme.</p><p style="font-size: 13px; margin-bottom: 0;">As per the scheme guidelines your surveillance assessment will be due after 2 month from date of this email. </p><p style="font-size: 13px; margin-bottom: 0;">Kindly note that the surveillance assessment is mandatory for continuation of the certification. Failure to do so will lead to suspension/withdrawal of the certification.</p><p style="font-size: 13px; margin-bottom: 0;">You may apply for the surveillance assessment using the details given below:</p><table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0"><tbody bgcolor="#ffffff"><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">ZED ID</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">PASSWORD</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Password, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Name</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@UnitName, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Certification, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Address</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Address, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Surveillance Due Date</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@DueDate, '') + '</td></tr></tbody></table> <br/><div style="text-align: center; padding: 30px 0;"><a href="http://loginzed.msme.gov.in/Msme/Login" target="_blank" style="display: block; margin: 0 auto; width: 300px; line-height: 42px; color: #ffffff; background-color: #45A5AD; text-decoration: none; border-radius: 4px; text-align: center;">Click here to Apply</a></div> <br/><p style="font-size: 13px; margin-bottom: 0;">In case of any query, please mail us at: zed@qcin.org. Please mention your ZED ID in all your correspondence.</p><p style="font-size: 13px; margin-bottom: 20px;">Thanks and Regards,<br>ZED Team</p></td></tr></table><div style="text-align: center; padding-top: 30px; padding-bottom: 30px;"><small style="font-size: 12px; color: #ffffff;">&copy; ZED ' + @CurrentYear + '</small></div></td></tr></table></div></html>'


	   -- PRINT @htmlBody

		-----to send the email
		 EXEC msdb.dbo.sp_send_dbmail
			 @profile_name = 'ZedAdmin',
			 @recipients = @RecipientEmail,
			 @subject = @Subject,
			 @body = @htmlBody,
			 @body_format = 'HTML';


		---------------UPDATING THE FLAG AFTER MAIL SEND----------------------------
		UPDATE MsmeCertifications SET AutoMailSend = 2 WHERE ZedId = @ZedId AND Certification = @Certification

		INSERT INTO SurveillanceAutoMailHistory (ZedId,Certification,RecipientEmail,UnitName,MailNumber)
		SELECT @ZedId,@Certification,@RecipientEmail,@UnitName,2



		FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification,@DueDate, @Password
	END

	CLOSE dailyMailCursor
	DEALLOCATE dailyMailCursor


END

GO
/****** Object:  StoredProcedure [dbo].[SP_JOB_TO_SEND_APPLY_FOR_SURVEILLANCE_MAIL_REM2]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_TO_SEND_APPLY_FOR_SURVEILLANCE_MAIL_REM2] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RecipientEmail NVARCHAR(255)
	DECLARE @ZedId NVARCHAR(255)
	DECLARE @UnitName NVARCHAR(255)
	DECLARE @Address NVARCHAR(255)
	DECLARE @Certification NVARCHAR(255)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))
	DECLARE @Password NVARCHAR(255)
	DECLARE @DueDate NVARCHAR(255)

	
	DECLARE dailyMailCursor CURSOR FOR

	SELECT EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 15, CertificationStatusDate), 'MMM dd yyyy') AS DueDate, U.Password FROM Msme M 
	INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
	INNER JOIN Users U ON C.ZedId = U.UserId
	WHERE CertificationStatus = 16 AND AutoMailSend = 2 

	AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-13, GETDATE()) AS DATE)
	AND ((C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL))
	and C.RestrictMail IS NULL
	--and EmailId = '<redacted>'
	order by CertificationStatusDate

	OPEN dailyMailCursor
	FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @DueDate, @Password

	DECLARE @Subject NVARCHAR(255)
	

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Subject = 'Reminder 2: Apply for Surveillance Assessment under “MSME Sustainable (ZED) Certification” Scheme - ' + COALESCE(@ZedId, '')
		DECLARE @htmlBody NVARCHAR(MAX)

		
		SET @htmlBody = '<html><link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet"><div><table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0" ><tr><td><br><br><div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;background: #ffffff;margin-bottom: 15px;max-width: 600px;"><img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" /></div><table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;"><tr><td style="padding: 0 3em;line-height: 26px;"><p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir, <br>Greetings of the day!</p><p style="font-size: 13px; margin-bottom: 0;">This is with reference to your ZED Certification under “MSME Sustainable (ZED) Certification” Scheme.</p><p style="font-size: 13px; margin-bottom: 0;">As per the scheme guidelines your surveillance assessment will be due after 1 month from date of this email. </p><p style="font-size: 13px; margin-bottom: 0;">Kindly note that the surveillance assessment is mandatory for continuation of the certification. Failure to do so will lead to suspension/withdrawal of the certification.</p><p style="font-size: 13px; margin-bottom: 0;">You may apply for the surveillance assessment using the details given below:</p><table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0"><tbody bgcolor="#ffffff"><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">ZED ID</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">PASSWORD</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Password, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Name</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@UnitName, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Certification, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Address</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Address, '') + '</td></tr><tr><td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Surveillance Due Date</td><td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@DueDate, '') + '</td></tr></tbody></table> <br/><div style="text-align: center; padding: 30px 0;"><a href="http://loginzed.msme.gov.in/Msme/Login" target="_blank" style="display: block; margin: 0 auto; width: 300px; line-height: 42px; color: #ffffff; background-color: #45A5AD; text-decoration: none; border-radius: 4px; text-align: center;">Click here to Apply</a></div> <br/><p style="font-size: 13px; margin-bottom: 0;">In case of any query, please mail us at: zed@qcin.org. Please mention your ZED ID in all your correspondence.</p><p style="font-size: 13px; margin-bottom: 20px;">Thanks and Regards,<br>ZED Team</p></td></tr></table><div style="text-align: center; padding-top: 30px; padding-bottom: 30px;"><small style="font-size: 12px; color: #ffffff;">&copy; ZED ' + @CurrentYear + '</small></div></td></tr></table></div></html>'



	   -- PRINT @htmlBody

		-----to send the email
		 EXEC msdb.dbo.sp_send_dbmail
			 @profile_name = 'ZedAdmin',
			 @recipients = @RecipientEmail,
			 @subject = @Subject,
			 @body = @htmlBody,
			 @body_format = 'HTML';


		---------------UPDATING THE FLAG AFTER MAIL SEND----------------------------
		UPDATE MsmeCertifications SET AutoMailSend=3 WHERE ZedId=@ZedId AND Certification=@Certification

		INSERT INTO SurveillanceAutoMailHistory (ZedId,Certification,RecipientEmail,UnitName,MailNumber)
		SELECT @ZedId,@Certification,@RecipientEmail,@UnitName,3



		FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification,@DueDate, @Password
	END

	CLOSE dailyMailCursor
	DEALLOCATE dailyMailCursor


END

GO
/****** Object:  StoredProcedure [dbo].[SP_JOB_TO_SEND_AUTO_MAIL_FOR_CERTIFICATE_RECERTIFICATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_JOB_TO_SEND_AUTO_MAIL_FOR_CERTIFICATE_RECERTIFICATION] 
(
    @UserId varchar(50) = NULL,
    @RoleId varchar(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @RecipientEmail NVARCHAR(255),
            @ZedId NVARCHAR(255),
            @UnitName NVARCHAR(255),
            @Address NVARCHAR(255),
            @Certification NVARCHAR(255),
            @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE())),
            @Password NVARCHAR(255),
            @ExpiryDate NVARCHAR(255),
            @EnterpriseName NVARCHAR(255);

    DECLARE recertCursor CURSOR FOR
        SELECT 
            M.EmailId,
            C.ZedId,
            M.PUnitName,
            M.PAddress,
            C.Certification,
            FORMAT(DATEADD(YEAR, 3, C.CertificationStatusDate), 'MMM dd yyyy') AS ExpiryDate,
            U.Password,
            M.EnterpriseName
        FROM Msme M
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
        INNER JOIN MsmeCertifications C ON (M.ZedId=C.ZedId)
        INNER JOIN Users U ON (M.ZedId=U.UserId)
        WHERE C.CertificationStatus = 16 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
          AND Certification in ('Silver','Gold')
		  AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-30, GETDATE()) AS DATE)
          --AND DATEADD(YEAR, 3, C.CertificationStatusDate) 
          --      BETWEEN GETDATE() AND DATEADD(MONTH, 6, GETDATE())
			 AND NOT EXISTS (
			SELECT 1 
			FROM MsmeCertifications C2
			WHERE 
				C2.ZedId = C.ZedId
				AND C2.Certification = 'Gold'
				AND C2.CertificationStatus >= 1 AND C2.CertificationStatus <= 17
				AND C.Certification = 'Silver'
		)
		-- avoid duplicate mails for same ZedId + Certification
		AND NOT EXISTS (
			SELECT 1 
			FROM SurveillanceAutoMailHistory H
			WHERE 
				H.ZedId = C.ZedId
				AND H.Certification = C.Certification
				AND H.MailType = 'RECERTIFICATION'
		)
		AND NOT EXISTS (
            SELECT 1 
            FROM MsmeHistory H 
            WHERE 
                H.ZedId = C.ZedId
				AND H.CertificationType = C.Certification
                AND H.StatusType = 'RecertificationEnabled'
        )
        ORDER BY C.CertificationStatusDate;

    OPEN recertCursor;
    FETCH NEXT FROM recertCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @ExpiryDate, @Password, @EnterpriseName;

    DECLARE @Subject NVARCHAR(255),
            @htmlBody NVARCHAR(MAX),
            @htmlBody1 NVARCHAR(MAX),
            @htmlBody2 NVARCHAR(MAX);

    WHILE @@FETCH_STATUS = 0
    BEGIN
		
		--Enable recertification button
		EXEC [SP_JOB_ENABLE_FOR_RE_CERTIFICATION] 
			@ZedId = @ZedId, 
			@CertificationType = @Certification;

        SET @Subject = 'Certificate Renewal under “MSME Sustainable (ZED) Certification” Scheme - ' + COALESCE(@ZedId, '');

        SET @htmlBody1 = 
        '<html>
          <link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet">
          <div>
            <table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0">
              <tr>
                <td>
                  <br><br>
                  <div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;background: #ffffff;margin-bottom: 15px;max-width: 600px;">
                    <img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" />
                  </div>

                  <table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;">
                    <tr>
                      <td style="padding: 0 3em;line-height: 26px;">
                        <p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir,</p>
                        <p style="font-size: 13px; margin-bottom: 0;">Greetings!</p>
                        <p style="font-size: 13px; margin-bottom: 0;">This is with reference to your Certification under "MSME Sustainable (ZED) Certification" Scheme.</p>
                        <p style="font-size: 13px; margin-bottom: 0;">Your current certificate is valid for 3 years. Please note that your certificate will be expired on <b>' + COALESCE(@ExpiryDate, '') + '</b>. To ensure continuity of your certification, you are requested to apply for renewal well before the expiry date. Kindly take necessary action to avoid any interruption in certification benefits.</p>
                        
                        <br/>

                        <p style="font-size: 13px; margin-bottom: 0;">Your application details are as follows:</p>
                            <table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0">
                                <tbody bgcolor="#ffffff">
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Enterprise Name</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@EnterpriseName, '') + '</td>
                                    </tr>
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">MSME ZED ID</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td>
                                    </tr>
									<tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Password</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Password, '') + '</td>
                                    </tr>
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification Level</td>
                                        <td style="border-bottom:2px solid #f0f0f0; font-weight: 700;">' + COALESCE(@Certification, '') + '</td>
                                    </tr>
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification Expiry Date</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ExpiryDate, '') + '</td>
                                    </tr>
                                </tbody>
                            </table>';

        SET @htmlBody2 =
        '<div style="text-align: center; padding: 30px 0;">
            <a href="http://loginzed.msme.gov.in/Msme/Login" target="_blank" style="display: block; margin: 0 auto; width: 300px; line-height: 42px; color: #ffffff; background-color: #45A5AD; text-decoration: none; border-radius: 4px; text-align: center;">Go to Login</a>
        </div>
        <p style="font-size: 13px; margin-bottom: 0;">In case of any query, please mail us at: support.zed@qcin.org.</p>						
        <p style="font-size: 13px; margin-top: 20px;">Thanks & Regards,<br>ZED Team</p>
        </td>
        </tr>
        </table>

        <div style="text-align: center; padding-top: 30px; padding-bottom: 30px;">
          <small style="font-size: 12px; color: #ffffff;">&copy; ZED ' + @CurrentYear + '</small>
        </div>
        </td>
        </tr>
        </table>
        </div>
        </html>';

        SET @htmlBody = @htmlBody1 + @htmlBody2;

        -- Send the email
        EXEC msdb.dbo.sp_send_dbmail
             @profile_name = 'ZedAdmin',
             @recipients = @RecipientEmail,
             @subject = @Subject,
             @body = @htmlBody,
             @body_format = 'HTML';

        -- Insert into mail history
        INSERT INTO SurveillanceAutoMailHistory (ZedId, Certification, RecipientEmail, UnitName, MailNumber, MailType)
        VALUES (@ZedId, @Certification, @RecipientEmail, @UnitName, 1, 'RECERTIFICATION');

        FETCH NEXT FROM recertCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @ExpiryDate, @Password, @EnterpriseName;
    END

    CLOSE recertCursor;
    DEALLOCATE recertCursor;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_JOB_TO_SEND_AUTO_MAIL_FOR_CERTIFICATE_SUSPENSION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_TO_SEND_AUTO_MAIL_FOR_CERTIFICATE_SUSPENSION] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RecipientEmail NVARCHAR(255)
	DECLARE @ZedId NVARCHAR(255)
	DECLARE @UnitName NVARCHAR(255)
	DECLARE @Address NVARCHAR(255)
	DECLARE @Certification NVARCHAR(255)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))
	DECLARE @Password NVARCHAR(255)
	DECLARE @DueDate NVARCHAR(255)
	DECLARE @EnterpriseName NVARCHAR(255)
	DECLARE @DetectedSurvNo INT
	
	DECLARE dailyMailCursor CURSOR FOR


	--SELECT EmailId, C.ZedId,M.EnterpriseName, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 15, CertificationStatusDate), '<redacted>') AS DueDate, U.Password FROM Msme M 
	--INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
	--INNER JOIN Users U ON C.ZedId = U.UserId
	--WHERE CertificationStatus = 16 AND AutoMailSend IS NULL 	
	--AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-11, GETDATE()) AS DATE)
	--AND ((C.Certification = '<redacted>' AND M.IsSurSilverPaymentDone IS NULL) OR (C.Certification = '<redacted>' AND M.IsSurGoldPaymentDone IS NULL))
	--and C.RestrictMail IS NULL
	----and EmailId in ('<redacted>','<redacted>')
	--order by CertificationStatusDate

		SELECT 
		M.EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 15, CertificationStatusDate), 'MMM dd yyyy') AS DueDate,
		U.Password,M.EnterpriseName,
		CASE WHEN ISNULL(B.ReSurveillance, 0) = 1 THEN 2 ELSE 1 END AS DetectedSurvNo
		FROM Msme M INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId)
		INNER JOIN Users U ON (C.ZedId = U.UserId)
		LEFT JOIN zed_surveillance.dbo.msmebasicinformation B ON (C.ZedId = B.ZedId)
		WHERE NOT EXISTS (
		SELECT 1 
		FROM zed_surveillance.dbo.msmecertifications S 
		WHERE S.ZedId = C.ZedId and S.certification=C.certification
		)
		--AND CertificationStatus = 16 AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH, -16, GETDATE()) AS DATE)
		AND (
    (ISNULL(B.ReSurveillance, 0) = 0 AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH, -16, GETDATE()) AS DATE))
    OR 
    (ISNULL(B.ReSurveillance, 0) = 1 AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH, -28, GETDATE()) AS DATE))
)
		AND (
			(C.Certification = 'Silver' AND M.IsSurSilverPaymentDone IS NULL 
				AND NOT EXISTS (
					SELECT 1 FROM MsmeCertifications G 
					WHERE G.ZedId = C.ZedId AND G.Certification = 'Gold' and G.CertificationStatus=16
				)
			)
			OR
			(C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL)
		)
		AND CertificationPhase='ACTIVE' 
		----AND c.ZedId='<redacted>'
		ORDER BY CertificationStatusDate


	OPEN dailyMailCursor
	FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @DueDate, @Password, @EnterpriseName,@DetectedSurvNo

	DECLARE @Subject NVARCHAR(255)
	

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Subject = 'Suspension of Certification under “MSME Sustainable (ZED) Certification” Scheme - ' + COALESCE(@ZedId, '')
		DECLARE @htmlBody NVARCHAR(MAX)
		DECLARE @htmlBody1 NVARCHAR(MAX)
		DECLARE @htmlBody2 NVARCHAR(MAX)

		SET @htmlBody1 = 
		'<html>
		  <link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet">
		  <div>
			<table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0">
			  <tr>
				<td>
				  <br><br>
				  <div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;background: #ffffff;margin-bottom: 15px;max-width: 600px;">
					<img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" />
				  </div>

				  <table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;">
					<tr>
					  <td style="padding: 0 3em;line-height: 26px;">
						<p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir,</p>
						<p style="font-size: 13px; margin-bottom: 0;">Greetings!</p>
						<p style="font-size: 13px; margin-bottom: 0;">This is with reference to your Certification under "MSME Sustainable (ZED) Certification" Scheme.</p>
						<p style="font-size: 13px; margin-bottom: 0;">As per the ZED Scheme guidelines, your surveillance assessment has to be completed within 12 to 18 months from the date of certification. Kindly note that surveillance assessment is mandatory for continuation of certification and your organisation has not yet applied for the same. Hence, your certification is being suspended.</p>
						<p style="font-size: 13px; margin-bottom: 0;">In order to revoke the suspension, you may apply and complete your surveillance assessment within 15 days from the date of suspension. Failure to do so will lead to withdrawal of the certification.</p>
						
						<br/>

						<p style="font-size: 13px; margin-bottom: 0;">Your application details are as follows:</p>
                            <table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0">
                                <tbody bgcolor="#ffffff">
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Enterprise Name</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@EnterpriseName, '') + '</td>
                                    </tr>
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">MSME ZED ID</td>
										<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td>
                                    </tr>

                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification Level Applied for </td>
