			 @profile_name = 'ZedAdmin',
			 @recipients = @RecipientEmail,
			 @subject = @Subject,
			 @body = @htmlBody,
			 @body_format = 'HTML';


		---------------UPDATING THE FLAG AFTER MAIL SEND----------------------------
		UPDATE MsmeCertifications SET CertificationPhase='SUSPENDED'  WHERE ZedId = @ZedId AND Certification = @Certification
		UPDATE MsmeBasicInformation SET IsEligibleForBenefits = 0 WHERE ZedId = @ZedId AND IsEligibleForBenefits = 1;

		INSERT INTO SurveillanceAutoMailHistory (ZedId,Certification,RecipientEmail,UnitName,MailNumber,MailType,SurveillanceNo)
		SELECT @ZedId,@Certification,@RecipientEmail,@UnitName,1, 'SUSPENSION',@DetectedSurvNo



		FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification,@DueDate, @Password, @EnterpriseName,@DetectedSurvNo
	END

	CLOSE dailyMailCursor
	DEALLOCATE dailyMailCursor


END

