/****** Object:  StoredProcedure [dbo].[SP_JOB_TO_SEND_AUTO_MAIL_FOR_CERTIFICATE_WITHDRAW]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_JOB_TO_SEND_AUTO_MAIL_FOR_CERTIFICATE_WITHDRAW] 
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RecipientEmail NVARCHAR(255)
	DECLARE @ZedId NVARCHAR(255)
	DECLARE @UnitName NVARCHAR(255)
	DECLARE @Address NVARCHAR(255)
	DECLARE @Certification NVARCHAR(255)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))
	DECLARE @Password NVARCHAR(255)
	DECLARE @DueDate NVARCHAR(255)
	DECLARE @EnterpriseName NVARCHAR(255)
	DECLARE @DetectedSurvNo INT
	
	DECLARE dailyMailCursor CURSOR FOR


		--SELECT 
		--EmailId, C.ZedId, M.PUnitName, M.PAddress, C.Certification, FORMAT(DATEADD(MONTH, 15, C.CertificationStatusDate), '<redacted>') AS DueDate, U.Password,M.EnterpriseName 
		--FROM Msme M INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId)
		--INNER JOIN Users U ON (C.ZedId = U.UserId)
		--INNER JOIN SurveillanceAutoMailHistory H ON (H.ZedId = C.ZedId AND H.Certification = C.Certification AND H.MailType = '<redacted>')

		--WHERE NOT EXISTS (
		--SELECT 1 
		--FROM zed_surveillance.dbo.msmecertifications S 
		--WHERE S.ZedId = C.ZedId and S.certification=C.certification
		--)
		--AND CertificationStatus = 16 AND CAST(C.CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH, -18, GETDATE()) AS DATE)
		--AND (
		--	(C.Certification = '<redacted>' AND M.IsSurSilverPaymentDone IS NULL 
		--		AND NOT EXISTS (
		--			SELECT 1 FROM MsmeCertifications G 
		--			WHERE G.ZedId = C.ZedId AND G.Certification = '<redacted>' and G.CertificationStatus=16
		--		)
		--	)
		--	OR
		--	(C.Certification = '<redacted>' AND M.IsSurGoldPaymentDone IS NULL)
		--)
		--AND CertificationPhase='<redacted>' 
		------AND c.ZedId='<redacted>'
		--ORDER BY C.CertificationStatusDate

		SELECT 
    M.EmailId, 
    C.ZedId, 
    M.PUnitName, 
    M.PAddress, 
    C.Certification, 
    FORMAT(DATEADD(MONTH, 15, C.CertificationStatusDate), 'MMM dd yyyy') AS DueDate, 
    U.Password,
    M.EnterpriseName, 
	CASE WHEN ISNULL(B.ReSurveillance, 0) = 1 THEN 2 ELSE 1 END AS DetectedSurvNo
FROM Msme M 
INNER JOIN MsmeCertifications C ON M.ZedId = C.ZedId
INNER JOIN Users U ON C.ZedId = U.UserId
-- ids which send suspended mails
INNER JOIN SurveillanceAutoMailHistory H ON (H.ZedId = C.ZedId AND H.Certification = C.Certification AND H.MailType = 'SUSPENSION')
LEFT JOIN zed_surveillance.dbo.msmebasicinformation B ON (C.ZedId = B.ZedId)

WHERE 
    -- Condition 1: no records present in surveillance inprogress
    NOT EXISTS (
        SELECT 1 
        FROM zed_surveillance.dbo.msmecertifications S 
        WHERE S.ZedId = C.ZedId AND S.Certification = C.Certification
    )
    -- Condition 2: Certification Status '<redacted>' (Certified) and Phase '<redacted>'
    AND C.CertificationStatus = 16 
    AND C.CertificationPhase = 'SUSPENDED'
    
    -- Condition 3: Exact 18 Months and 10 Days ayyi vundali
    --AND CAST(C.CertificationStatusDate AS DATE) = CAST(DATEADD(DAY, -4, DATEADD(MONTH, -18, GETDATE())) AS DATE)
	AND (
            -- S1: Flag 0 and Exactly 18 Months 7 Days ago
            (ISNULL(B.ReSurveillance, 0) = 0 AND CAST(C.CertificationStatusDate AS DATE) = CAST(DATEADD(DAY, -4, DATEADD(MONTH, -18, GETDATE())) AS DATE))
            OR 
            -- S2: Flag 1 and Exactly 30 Months 7 Days ago
            (ISNULL(B.ReSurveillance, 0) = 1 AND CAST(C.CertificationStatusDate AS DATE) = CAST(DATEADD(DAY, -4, DATEADD(MONTH, -30, GETDATE())) AS DATE))
        )

    -- Condition 4: Silver/Gold specific checks
    AND (
        (C.Certification = 'Silver' 
            AND M.IsSurSilverPaymentDone IS NULL 
            -- if it is silver and it should not upgraded to gold
            AND NOT EXISTS (
                SELECT 1 FROM MsmeCertifications G 
                WHERE G.ZedId = C.ZedId AND G.Certification = 'Gold' AND G.CertificationStatus = 16
            )
        )
        OR
        (C.Certification = 'Gold' AND M.IsSurGoldPaymentDone IS NULL)
    )
ORDER BY C.CertificationStatusDate


	OPEN dailyMailCursor
	FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification, @DueDate, @Password, @EnterpriseName, @DetectedSurvNo

	DECLARE @Subject NVARCHAR(255)
	

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Subject = 'Withdrawal of Certification under “MSME Sustainable (ZED) Certification” Scheme - ' + COALESCE(@ZedId, '')
		DECLARE @htmlBody NVARCHAR(MAX)
		DECLARE @htmlBody1 NVARCHAR(MAX)
		DECLARE @htmlBody2 NVARCHAR(MAX)

		SET @htmlBody1 = 
		'<html>
		  <link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet">
		  <div>
			<table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0">
			  <tr>
				<td>
				  <br><br>
				  <div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;background: #ffffff;margin-bottom: 15px;max-width: 600px;">
					<img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" />
				  </div>

				  <table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;">
					<tr>
					  <td style="padding: 0 3em;line-height: 26px;">
						<p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir,</p>
						<p style="font-size: 13px; margin-bottom: 0;">Greetings!</p>
						<p style="font-size: 13px; margin-bottom: 0;">This is with reference to your Certification under "MSME Sustainable (ZED) Certification" Scheme.</p>
						<p style="font-size: 13px; margin-bottom: 0;">As per the ZED Scheme guidelines, the surveillance assessment has to be completed within 12 to 18 months from the date of certification. However, your organisation has not yet got the surveillance assessment completed in spite of multiple reminders and therefore your certification is being withdrawn.</p>
						<br/>

						<p style="font-size: 13px; margin-bottom: 0;">Your application details are as follows:</p>
                            <table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0">
                                <tbody bgcolor="#ffffff">
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Enterprise Name</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@EnterpriseName, '') + '</td>
                                    </tr>
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">MSME ZED ID</td>
										<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td>
                                    </tr>

                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification Level Applied for </td>
                                        <td style="border-bottom:2px solid #f0f0f0; font-weight: 700;">' + COALESCE(@Certification, '') + '</td>
                                    </tr>
                                    <tr>
                                        <td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Current Status</td>
                                        <td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">Withdrawn</td>

                                    </tr>
                                </tbody>
                            </table>'

						SET @htmlBody2 =
						'<span style="font-size: 12px; line-height: 20px; margin-top: 10px; display: inline-block; margin-bottom: 10px;">(Remember to use your ZED ID in all future correspondence with the ZED Team at QCI)</span>
						<div style="text-align: center; padding: 30px 0;">
							<a href="http://loginzed.msme.gov.in/Msme/Login" target="_blank" style="display: block; margin: 0 auto; width: 300px; line-height: 42px; color: #ffffff; background-color: #45A5AD; text-decoration: none; border-radius: 4px; text-align: center;">Go to Login</a>
						</div>
						<p style="font-size: 13px; margin-bottom: 0;">In case of any query, please mail us at: zed@qcin.org.</p>
						<p style="font-size: 13px; margin-top: 20px;">Thanks & Regards,<br>ZED Team</p>
					  </td>
					</tr>
				  </table>

				  <div style="text-align: center; padding-top: 30px; padding-bottom: 30px;">
					<small style="font-size: 12px; color: #ffffff;">&copy; ZED ' + @CurrentYear + '</small>
				  </div>
				</td>
			  </tr>
			</table>
		  </div>
		</html>'

		SET @htmlBody = @htmlBody1 + @htmlBody2

	   -- PRINT @htmlBody

		-----to send the email
		 EXEC msdb.dbo.sp_send_dbmail
			 @profile_name = 'ZedAdmin',
			 @recipients = @RecipientEmail,
			 @subject = @Subject,
			 @body = @htmlBody,
			 @body_format = 'HTML';


		---------------UPDATING THE FLAG AFTER MAIL SEND----------------------------
		UPDATE MsmeCertifications SET CertificationPhase='WITHDRAWN'  WHERE ZedId = @ZedId AND Certification = @Certification
		UPDATE MsmeBasicInformation SET IsEligibleForBenefits = 0 WHERE ZedId = @ZedId AND IsEligibleForBenefits = 1;


		--ENABLE RECERTIFICATION BUTTON FOR SILVER AND GOLD WITHDRAWN CASES
        IF @Certification IN ('Silver', 'Gold')
        BEGIN
			DECLARE @CustomHistoryMsg VARCHAR(255) = 'ReCertification Enabled due to Certificate Withdrawal';
            EXEC [dbo].[SP_JOB_ENABLE_FOR_RE_CERTIFICATION] @ZedId, @Certification, @CustomHistoryMsg;
        END



		INSERT INTO SurveillanceAutoMailHistory (ZedId,Certification,RecipientEmail,UnitName,MailNumber,MailType,SurveillanceNo)
		values ( @ZedId,@Certification,@RecipientEmail,@UnitName,1, 'WITHDRAWN',@DetectedSurvNo)



		FETCH NEXT FROM dailyMailCursor INTO @RecipientEmail, @ZedId, @UnitName, @Address, @Certification,@DueDate, @Password, @EnterpriseName, @DetectedSurvNo
	END

	CLOSE dailyMailCursor
	DEALLOCATE dailyMailCursor


END

GO
/****** Object:  StoredProcedure [dbo].[SP_JOB_TO_UPDATE_3YEARS_COMPLETED_TO_EXPIRED]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_JOB_TO_UPDATE_3YEARS_COMPLETED_TO_EXPIRED] 
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;

    -- 1. Temporary list to catch the IDs that expire today
    DECLARE @ExpiredZedIds TABLE (ZedId VARCHAR(50));

    -- 2. YOUR ORIGINAL LOGIC - Updated only to include the OUTPUT clause
    UPDATE C SET C.CertificationPhase='EXPIRED'
    OUTPUT inserted.ZedId INTO @ExpiredZedIds(ZedId) -- Captures IDs here
    FROM MsmeCertifications C
    INNER JOIN Msme M ON C.ZedId = M.ZedId
    INNER JOIN Users U ON C.ZedId = U.UserId
    WHERE 
        (
            (C.Certification = 'Bronze' AND C.CertificationStatus = 6 
                AND NOT EXISTS (
                    SELECT 1 FROM MsmeCertifications S 
                    WHERE S.ZedId = C.ZedId AND S.Certification IN ('Silver', 'Gold') AND S.CertificationStatus = 16
                )
            )
            OR
            (C.Certification = 'Silver' AND C.CertificationStatus = 16 
                AND NOT EXISTS (
                    SELECT 1 FROM MsmeCertifications G 
                    WHERE G.ZedId = C.ZedId AND G.Certification = 'Gold' AND G.CertificationStatus = 16
                )
            )
            OR
            (C.Certification = 'Gold' AND C.CertificationStatus = 16)
        )
        AND C.CertificationStatusDate <= DATEADD(YEAR, -3, GETDATE())
        AND C.CertificationPhase != 'EXPIRED'; -- Ensures we don't re-process

    -- 3. THE ADDITION - Syncing the benefits flag
    UPDATE BI
    SET BI.IsEligibleForBenefits = 0
    FROM MsmeBasicInformation BI
    INNER JOIN @ExpiredZedIds E ON BI.ZedId = E.ZedId
    WHERE BI.IsEligibleForBenefits = 1;

END
GO
/****** Object:  StoredProcedure [dbo].[SP_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS] -- NULL,NULL,null,'<redacted>',null,10
(
	@ZedId varchar(50) = NULL,
	@Status varchar(50) =null,
	@State varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	--IF @CertificationType='' 
	--SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	IF @State IS NULL OR @State=''
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	IF @RoleId=10 OR @RoleId=11

	BEGIN
	
		select top 50000 M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, M.ZedId,case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus, 10000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 10000-ApplicantContributionAfterSubsidy FinancialSupport
		,M.PStateName,Gender from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		--MsmePaymentInfo P on (replace(C.ZedId,'<redacted>','')=replace(P.ZedId,'<redacted>','') and C.Certification=p.Certification)
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (replace(C.ZedId,'<redacted>','')=replace(T.ZedId,'<redacted>','') and C.Certification=T.Certification and PaymentStatus='<redacted>' )
		--where P.Certification='<redacted>' and C.Certification='<redacted>' and CertificationStatus>=2
		 where CertificationStatus>=2 and  P.Certification='Bronze'
		and (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR C.Certification=@CertificationType) 
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)

		union all

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType, 'Silver' Certification, M.ZedId,case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus,40000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 40000-ApplicantContributionAfterSubsidy FinancialSupport
		,M.PStateName,Gender from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		--MsmePaymentInfo P on (replace(C.ZedId,'<redacted>','')=replace(P.ZedId,'<redacted>','') and C.Certification=p.Certification)
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (replace(C.ZedId,'<redacted>','')=replace(T.ZedId,'<redacted>','') and C.Certification=T.Certification and PaymentStatus='<redacted>' )
		where P.Certification='Silver' and C.Certification='Silver'  and CertificationStatus>=2
		and (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR C.Certification=@CertificationType) 
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)

		union all

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType, 'Gold' Certification, M.ZedId,case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus,90000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 90000-ApplicantContributionAfterSubsidy FinancialSupport
		,M.PStateName,Gender from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		--MsmePaymentInfo P on (replace(C.ZedId,'<redacted>','')=replace(P.ZedId,'<redacted>','') and C.Certification=p.Certification)
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		--left join 
		--PaymentGateWayTransactions T on (replace(C.ZedId,'<redacted>','')=replace(T.ZedId,'<redacted>','') and C.Certification=T.Certification and PaymentStatus='<redacted>' )
		where P.Certification='Gold' and C.Certification='Gold' and CertificationStatus>=2
		and (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR C.Certification=@CertificationType) 
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)

		union all

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,EnterpriseTypee EnterpriseType,CertificationType Certification,F.ZedId,null ZedIdStatus,null CertificationFee,null Amount,
		isnull(ApproverAmount,0) FinancialSupport, M.PStateName,null Gender--, F.CreatedDate CertificationStatusDate
		from FinancialAssistance F inner join Msme m on (F.ZedId=M.ZedId) 
		where isnull(ApproverAmount,0)>0
		and (@State is null or M.StateId=@State)
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize)
		--order by CertificationStatusDate desc
		
	END

	ELSE 

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,EnterpriseTypee EnterpriseType,CertificationType Certification,F.ZedId,null ZedIdStatus,null CertificationFee,null Amount,isnull(ApproverAmount,0) FinancialSupport
		from FinancialAssistance F left join Msme m on (F.ZedId=M.ZedId) 
		where 1=2

END


