-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MASTER_ACTIVE__DEACTIVE_TECHNOLOGIES]
(
	@IsActive bit = NULL,
	@Id varchar(50) = NULL
	
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @IsActive=1
	BEGIN
		UPDATE Technologies SET IsActive=@IsActive where Id=@Id
		SELECT 200 StatusCode, 'TECHNOLOGY ACTIVATED SUCCESSFULLY' Message
	END

	ELSE IF @IsActive=0
	BEGIN
		UPDATE Technologies SET IsActive=@IsActive where Id=@Id
		SELECT 200 StatusCode, 'TECHNOLOGY DEACTIVATED SUCCESSFULLY' Message
	END
	

END

