CREATE PROCEDURE [dbo].[SP_MASTER_GET_SECTORS]
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT * FROM Sectors ORDER By OrderNo

	SELECT UserId, FirstName FROM ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Users WHERE ROLEID=3 AND ISACTIVE=1 
	AND UserId COLLATE SQL_Latin1_General_CP1_CI_AS not in (select distinct OrgPartnerId from Users where OrgPartnerId is not null and RoleId=2)
	ORDER BY FirstName

	SELECT UserId, FirstName FROM ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Users WHERE ROLEID=3 AND ISACTIVE=1 ORDER BY FirstName

END

