CREATE PROCEDURE [dbo].[SP_MASTER_INSERT_REQUIREMENT]
(
	@SectionType varchar(50) NULL,
	@SectionCode varchar(50) = NULL,
	@QuestionCode varchar(50) = NULL,
	@RequirementName varchar(5000) = NULL,
	@PointList MasterOption2 READONLY,
	@BulletList MasterSubOption READONLY
)
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE @RequirementCode varchar(50)
	SELECT @RequirementCode = ISNULL(max(OrderNo),0)+1 FROM Requirements WHERE SectionType=@SectionType and SectionCode=@SectionCode

    INSERT INTO Requirements(SectionType, SectionCode, QuestionCode, RequirementCode, RequirementName, OrderNo)
	SELECT @SectionType, @SectionCode, @QuestionCode, @RequirementCode, @RequirementName, @RequirementCode

	INSERT INTO Options (SectionType, SectionCode, QuestionCode, RequirementCode, OptionCode, OptionName, OptionImage)
	SELECT @SectionType, @SectionCode, @QuestionCode, @RequirementCode, OptionCode, OptionText, OptionImage FROM @PointList

	INSERT INTO SubOptions (SectionType, SectionCode, QuestionCode, RequirementCode, OptionCode, SubOptionCode, SubOptionName, SubOptionImage)
	SELECT @SectionType, @SectionCode, @QuestionCode, @RequirementCode, OptionCode, SubOptionCode, SubOptionText, SubOptionImage FROM @BulletList

END



