CREATE PROCEDURE [dbo].[SP_MASTER_REMOVE_OPTION]
(
	@OptionId varchar(50),
	@SectionType varchar(50) =NULL,
	@SectionCode varchar(50) = NULL,
	@RequirementCode varchar(50) = NULL,
	@OptionCode varchar(5000) = NULL
)
AS
BEGIN

	SET NOCOUNT ON;
	SELECT @SectionType=SectionType, @SectionCode=SectionCode, @RequirementCode=RequirementCode,@OptionCode=OptionCode   FROM Options WHERE Id=@OptionId

	DELETE FROM Options WHERE Id=@OptionId
	DELETE FROM SubOptions WHERE SectionType=@SectionType and SectionCode=@SectionCode and RequirementCode=@RequirementCode and OptionCode=@OptionCode

END
