CREATE PROC [dbo].[SP_MESE_UPDATE_PAN] 
(
	@ZedId varchar(50) = NULL,
	@PanNo varchar(50) = NULL,
	@UpdatedPanNo varchar(50) = NULL
 
  
)
AS
BEGIN		
	IF EXISTS (SELECT 1 FROM MsmeBasicInformation WHERE ZedId=@ZedId and PanNo=@PanNo)		
	BEGIN
		update MsmeBasicInformation set OldPanNo=@PanNo, PanNo=@UpdatedPanNo where ZedId=@ZedId and PanNo=@PanNo AND PanNo <> @UpdatedPanNo

		update ZED_CONSULTANT.DBO.MsmeBasicInformation set OldPanNo=@PanNo, PanNo=@UpdatedPanNo where ZedId=@ZedId and PanNo=@PanNo AND PanNo <> @UpdatedPanNo

		update ZED_SURVEILLANCE.DBO.MsmeBasicInformation set OldPanNo=@PanNo, PanNo=@UpdatedPanNo where ZedId=@ZedId and PanNo=@PanNo AND PanNo <> @UpdatedPanNo
	END
	ELSE
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ZEDID OR PAN NOT AVAILABLE' where UserId='ZEDMSME000112'
	END
	

END


