CREATE PROC [dbo].[SP_MONITORING_DA_FINAL_SUBMIT] --'<redacted>'
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@QrCodeSeqNo varchar(50) = NULL
)
AS
BEGIN
		Declare @CertificateNo varchar(50)= NULL,
			@SerialNo varchar(50)
		--SET  @SerialNo = Next Value For CertificateSequence; 
		 --select @SerialNo=right(ZedId,6) from MsmeCertifications where ZedId=@ZedId
		 --select @SerialNo=SUBSTRING(ZedId, 8, 50) from MsmeCertifications where ZedId=@ZedId
		 select @SerialNo=STUFF(ZedId, 1, 7, '') from MsmeCertifications where ZedId=@ZedId

		Declare @PlantIdNo varchar(50) = NULL
		select @PlantIdNo=PlantIdNo from Msme where ZedId=@ZedId


		IF @CertificationType='Bronze'
		BEGIN
			select @CertificateNo=concat(replace(convert(varchar, getdate(),103),'/',''),'_',@SerialNo)		

			IF EXISTS (SELECT * FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType AND DaCertificateNo IS NOT NULL) --ZEDMSME129350
			BEGIN
				UPDATE MsmeCertifications SET CertificationStatus=6 where  ZedId=@ZedId and Certification=@CertificationType
			END
			ELSE
			BEGIN
				UPDATE MsmeCertifications SET  DaCertificateNo=@CertificateNo, CertificationStatusDate=getdate(),CertificationStatus=6, CertificationPhase='ACTIVE',FirstSurveDueDate = DATEADD(DAY, 450, GETDATE()) where  ZedId=@ZedId and Certification=@CertificationType
			END
			
			Update MsmeCertifications set QrCodeSeqNo=concat(@PlantIdNo,'2',@QrCodeSeqNo) where ZedId=@ZedId and Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Completed')

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Certificate & Report generated on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'GetCertified')

			EXEC [SP_MOVING_CERTIFIED_MSME_TO_CONSULTANCY] @ZedId, @CertificationType


			---------------THE BELOW COMMENTED CODE IS MOVED TO ABOVE SP -----------------------------------------------------------------------------
			--UPDATE Msme SET FinancialAssistanceStatus=1 WHERE ZedId=@ZedId
			--UPDATE MsmeBasicInformation SET LastestCertification='<redacted>' WHERE ZedId=@ZedId


			----------STARTING ADDING THE COMPLETED RECORD IN ZED CONSULTANT DATABASE-----------------------

			--IF NOT EXISTS (SELECT ZedId from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)
			--BEGIN
			--	INSERT INTO ZED_CONSULTANT.dbo.Msme
			--	 ([MsmeId],[ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType]
			--	,[OrganisationTypeName], [EnterpriseType], [EnterpriseTypee], [MobileNo], [EmailId], [ApplicationId], [UamNumber]
			--	,[PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode]
			--	,[PDistrictName], [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId]
			--	,[PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone], [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo]
			--	,[RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo], [CreatedDate]
			--	,[RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo])

			--	SELECT
			--	[MsmeId],[ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType]
			--	,[OrganisationTypeName], [EnterpriseType], [EnterpriseTypee], [MobileNo], [EmailId], [ApplicationId], [UamNumber]
			--	,[PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode]
			--	,[PDistrictName], [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId]
			--	,[PledgeEmailId], NULL, NULL, NULL, 1, [PledgeCertificateNo]
			--	,[RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo], getdate()
			--	,[RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo]
			--	from Msme where ZedId=@ZedId


			--	INSERT INTO ZED_CONSULTANT.dbo.MsmeBasicInformation(
			--	[MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory]
			--	,[SocialCategoryName], [Gender], [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName]
			--	,[LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName], [EnterpriseType], [EnterpriseTypee]
			--	,[CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId]
			--	,[LastestCertification])
								
			--	SELECT
			--	[MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory]
			--	,[SocialCategoryName], [Gender], [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName]
			--	,[LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName], [EnterpriseType], [EnterpriseTypee]
			--	,[CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId]
