			UPDATE MsmeCertifications SET CertificationStatusDate=getdate(),CertificationStatus=6, DesktopVerificationDate=getdate() where  ZedId=@ZedId and Certification=@CertificationType 
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'DesktopVerification')
