/****** Object:  StoredProcedure [dbo].[SP_MONITORING_GET_LIST_PAGINATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
----[SP_MONITORING_GET_LIST_PAGINATION] '<redacted>', '<redacted>',Silver,'<redacted>',null,null,null,null,1,200,null,null
CREATE PROCEDURE [dbo].[SP_MONITORING_GET_LIST_PAGINATION] --'<redacted>', '<redacted>','<redacted>',null,null,null,null,null,null,null,'<redacted>'
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@State varchar(100) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@PageSize int = 200,
	@NcClosingDate varchar(50) = NULL,
	@SearchBy varchar(100) =null

)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @PageSize is null OR @PageSize > 200 
	set @PageSize = 200

	IF @PageNo is null 
	set @PageNo = 1

	IF @State='' 
	SET @State = NULL

	IF  @CertificationType='' 
	SET @CertificationType = NULL

	IF @Status!=4
	SET @NcClosingDate = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	--DECLARE @RoleId INT 
	SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	IF @SearchBy ='Zed Id' and @ZedId is not null
	BEGIN
		SELECT  P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName, U.UserName AgencyName,
			concat(@CurrentUrl, '/PDFs/SA/',P.ZedId,'/',P.Certification,'_Report.pdf') ReportPath,
			FORMAT(DesktopAcceptOrRejectDate, 'MMMM d, yyyy') DocVerifiAllot, FORMAT(DesktopVerificationDate , 'MMMM d, yyyy') DesktopVerificationCompleted,FORMAT(AssessmentDate , 'MMMM d, yyyy') ScheduledOn,
			UA.UserName as DesktopAssessorName,
			UL.UserName as SiteAssessorName,
			UC.UserName as CoAssessorName,
			CoAssessorId,
			CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
			CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
			M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
			null AssessmentStatus,case when Certification='Silver' and RestrictMail='Gold Certified' then 'Gold Certified' else CertificationPhase end as CertificationPhase,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,SameUdyamAddress, FORMAT(FirstSurveDueDate, 'MMMM d, yyyy') FirstSurveDueDate, 
		--CASE WHEN P.CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN '<redacted>' ELSE '<redacted>' END AS CertificationPath,
		--CASE WHEN M.CreatedDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN '<redacted>' ELSE '<redacted>' END AS PledgePath
		CASE WHEN CAST(P.CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath,
		CASE WHEN CAST(M.CreatedDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS PledgePath,
		P.ZedId as RejectedZedId
		
		FROM MsmeCertifications P
		inner join Msme M ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		--LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users U on  (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)

		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
			AND  (M.ZedId like @ZedId+'%') 
		ORDER By p.CertificationStatusDate desc
		offset ((@PageNo-1) * @PageSize) rows fetch next @PageSize rows only
		OPTION (RECOMPILE);

		SELECT count(*) as TotalCounts, @PageNo PageNo, @PageSize PageSize   
		FROM MsmeCertifications P
		--inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
		INNER JOIN Msme M ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId = B.ZedId)
		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
			AND  (M.ZedId like @ZedId+'%') 
		OPTION (RECOMPILE);
	END


	ELSE IF @SearchBy ='Udyam Number' and @ZedId is not null
	BEGIN
		SELECT  P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName, U.UserName AgencyName,
			concat(@CurrentUrl, '/PDFs/SA/',P.ZedId,'/',P.Certification,'_Report.pdf') ReportPath,
			FORMAT(DesktopAcceptOrRejectDate, 'MMMM d, yyyy') DocVerifiAllot, FORMAT(DesktopVerificationDate , 'MMMM d, yyyy') DesktopVerificationCompleted,FORMAT(AssessmentDate , 'MMMM d, yyyy') ScheduledOn,
			UA.UserName as DesktopAssessorName,
			UL.UserName as SiteAssessorName,
			UC.UserName as CoAssessorName,
			CoAssessorId,
			CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
			CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
			M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
			null AssessmentStatus,case when Certification='Silver' and RestrictMail='Gold Certified' then 'Gold Certified' else CertificationPhase end as CertificationPhase,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,SameUdyamAddress, FORMAT(FirstSurveDueDate, 'MMMM d, yyyy') FirstSurveDueDate,
		--'<redacted>' CertificationPath,
		--'<redacted>'  PledgePath
		CASE WHEN CAST(P.CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath,
		CASE WHEN CAST(M.CreatedDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS PledgePath,
		P.ZedId as RejectedZedId
		
		FROM MsmeCertifications P
		inner join Msme M on (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		--LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users U on  (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		
		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
			AND  (UdyogAadharNo like '%'+@ZedId+'%') 
		ORDER By p.CertificationStatusDate desc
		offset ((@PageNo-1) * @PageSize) rows fetch next @PageSize rows only
		OPTION (RECOMPILE);

		SELECT count(*) as TotalCounts, @PageNo PageNo, @PageSize PageSize   
		FROM MsmeCertifications P
		--inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
		INNER JOIN Msme M ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId = B.ZedId)
		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
		AND  (UdyogAadharNo like '%'+@ZedId+'%') 
		OPTION (RECOMPILE);
		
	END


	ELSE IF @SearchBy ='Unit Name' and @ZedId is not null
	BEGIN
		SELECT  P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName, U.UserName AgencyName,
			concat(@CurrentUrl, '/PDFs/SA/',P.ZedId,'/',P.Certification,'_Report.pdf') ReportPath,
			FORMAT(DesktopAcceptOrRejectDate, 'MMMM d, yyyy') DocVerifiAllot, FORMAT(DesktopVerificationDate , 'MMMM d, yyyy') DesktopVerificationCompleted,FORMAT(AssessmentDate , 'MMMM d, yyyy') ScheduledOn,
			UA.UserName as DesktopAssessorName,
			UL.UserName as SiteAssessorName,
			UC.UserName as CoAssessorName,
			CoAssessorId,
			CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
			CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
			M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
			null AssessmentStatus,case when Certification='Silver' and RestrictMail='Gold Certified' then 'Gold Certified' else CertificationPhase end as CertificationPhase,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,SameUdyamAddress, FORMAT(FirstSurveDueDate, 'MMMM d, yyyy') FirstSurveDueDate,
		--'<redacted>' CertificationPath,
		--'<redacted>'  PledgePath
		CASE WHEN CAST(P.CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath,
		CASE WHEN CAST(M.CreatedDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS PledgePath,
		P.ZedId as RejectedZedId
		
		FROM MsmeCertifications P
		inner join Msme M on (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		--LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users U on  (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
	
		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
			AND  ( M.PUnitName like '%'+@ZedId+'%') 
		ORDER By p.CertificationStatusDate desc
		offset ((@PageNo-1) * @PageSize) rows fetch next @PageSize rows only
		OPTION (RECOMPILE);


		SELECT count(*) as TotalCounts, @PageNo PageNo, @PageSize PageSize   
		FROM MsmeCertifications P
		--inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
		INNER JOIN Msme M ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId = B.ZedId)
		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
		AND  ( M.PUnitName like '%'+@ZedId+'%') 
		OPTION (RECOMPILE);
		
	END

	ELSE
	BEGIN
	SELECT  P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName, U.UserName AgencyName,
			concat(@CurrentUrl, '/PDFs/SA/',P.ZedId,'/',P.Certification,'_Report.pdf') ReportPath,
			FORMAT(DesktopAcceptOrRejectDate, 'MMMM d, yyyy') DocVerifiAllot, FORMAT(DesktopVerificationDate , 'MMMM d, yyyy') DesktopVerificationCompleted,FORMAT(AssessmentDate , 'MMMM d, yyyy') ScheduledOn,
			UA.UserName as DesktopAssessorName,
			UL.UserName as SiteAssessorName,
			UC.UserName as CoAssessorName,
			CoAssessorId,
			CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
			CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
			M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
			null AssessmentStatus,case when Certification='Silver' and RestrictMail='Gold Certified' then 'Gold Certified' else CertificationPhase end as CertificationPhase,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,SameUdyamAddress, FORMAT(FirstSurveDueDate, 'MMMM d, yyyy') FirstSurveDueDate,
		--'<redacted>' CertificationPath,
		--'<redacted>'  PledgePath
		CASE WHEN CAST(P.CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath,
		CASE WHEN CAST(M.CreatedDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS PledgePath,
		P.ZedId as RejectedZedId
		
		FROM MsmeCertifications P
		inner join Msme M on (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		--LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users U on  (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)	


		--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
		WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
			AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
		ORDER By p.CertificationStatusDate desc
		offset ((@PageNo-1) * @PageSize) rows fetch next @PageSize rows only
		OPTION (RECOMPILE);

		IF @State IS NULL AND @MsmeSize IS NULL
		BEGIN
			SELECT COUNT(*) AS TotalCounts, @PageNo AS PageNo, @PageSize AS PageSize    
			FROM MsmeCertifications P
			--WHERE ((P.Certification = '<redacted>' AND CertificationStatus = 6)  OR (P.Certification != '<redacted>' AND CertificationStatus = 16))
			WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
			  AND (@CertificationType IS NULL OR P.Certification = @CertificationType) 
			  AND (@RoleId = 7 
				   OR (@RoleId = 2 AND CertificationBodyUserId = @UserId) 
				   OR (@RoleId = 3 AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId OR CoAssessorId = @UserId)))
			OPTION (RECOMPILE);
		END

		ELSE
		BEGIN
			SELECT count(*) as TotalCounts, @PageNo PageNo, @PageSize PageSize   
			FROM MsmeCertifications P
			INNER JOIN Msme M ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_R_', P.Id), ''), '_D',''))
		    INNER JOIN MsmeBasicInformation B on (M.ZedId = B.ZedId)
			--WHERE ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))
			WHERE ((@Status=6 AND P.Certification='Bronze' and CertificationStatus=6) OR (@Status=6 AND P.Certification!='Bronze' and CertificationStatus=16) OR (@Status=99 and CertificationStatus=99) )
				and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) --AND (@Gender IS NULL OR Gender=@Gender) 
				AND (@RoleId=7 OR (@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) )
				OPTION (RECOMPILE);
		END
		
	END

END







