				UPDATE ZED_CONSULTANT.dbo.MsmeCertifications SET TuStatus=98 where  ZedId=@UserId and Certification=@CertificationType and CertificationStatus=100
			END
		END


		insert into ZED_CONSULTANT.dbo.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
		values (@UserId,concat('Applicant acceptance date: ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'ApplicantAcceptedOn',@NcCount)


		--SET @NcCount=@NcCount+1

		--INSERT INTO ZED_CONSULTANT.dbo.MsmeCertifications (ZedId, Certification, NcCount, NcStatus,CertificationBodyUserId)
		--values( @UserId,@CertificationType,@NcCount,1,@Agency)
		
		--insert into ZED_CONSULTANT.dbo.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
		--values (@UserId,concat('<redacted>',@NcCount, '<redacted>',FORMAT(getdate(), '<redacted>')),getdate(),@CertificationType,concat('<redacted>',@NcCount), @NcCount)

		----INSERTION OF ELEMENTS DATA
		--INSERT INTO ZED_CONSULTANT.dbo.MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,NcCount)
		--SELECT Id,@UserId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,@NcCount FROM Sections WHERE SectionType=@CertificationType ORDER BY SectionCode

		--INSERT INTO ZED_CONSULTANT.dbo.MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,NcCount)
		--SELECT Id,@UserId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,@NcCount FROM Requirements WHERE SectionType=@CertificationType ORDER BY SectionCode, RequirementCode

		--INSERT INTO ZED_CONSULTANT.dbo.MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,NcCount)
		--SELECT Id,@UserId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,@NcCount FROM Options WHERE SectionType=@CertificationType ORDER BY SectionCode, RequirementCode, OptionCode

		--INSERT INTO ZED_CONSULTANT.dbo.MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,NcCount)
		--SELECT Id,@UserId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,@NcCount FROM SubOptions WHERE SectionType=@CertificationType ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

		--INSERT INTO ZED_CONSULTANT.dbo.MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText,NcCount)
		--SELECT Id,@UserId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText,@NcCount FROM Evidences WHERE SectionType=@CertificationType ORDER BY SectionCode, RequirementCode, EvidenceCode

		--UPDATE ZED_CONSULTANT.dbo.MsmeRequirements SET OpenedFlag=1 where ZedId=@UserId and SectionType=@CertificationType and NcCount=@NcCount and concat(sectioncode,'<redacted>',RequirementCode) not in 
		--(SELECT DISTINCT CONCAT(SectionCode,'<redacted>',RequirementCode)  from ZED_CONSULTANT.dbo.MsmeEvidences where ZedId=@UserId and SectionType=@CertificationType and NcCount=@NcCount)


		
