/****** Object:  StoredProcedure [dbo].[SP_MONITORING_RA_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_RA_FINAL_SUBMIT] --'<redacted>'
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@QrCodeSeqNo varchar(50) = NULL
)
AS
BEGIN
		Declare @CertificateNo varchar(50)= NULL,
			@SerialNo varchar(50)
		-- select @SerialNo=right(ZedId,6) from MsmeCertifications where ZedId=@ZedId
		 select @SerialNo=STUFF(ZedId, 1, 7, '') from MsmeCertifications where ZedId=@ZedId

		Declare @PlantIdNo varchar(50) = NULL
		select @PlantIdNo=PlantIdNo from Msme where ZedId=@ZedId

		select @CertificateNo=concat(replace(convert(varchar, getdate(),103),'/',''),'_',@SerialNo)	

		IF EXISTS (SELECT * FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType AND SaCertificateNo IS NOT NULL)
		BEGIN
			UPDATE MsmeCertifications SET CertificationStatus=16 where  ZedId=@ZedId and Certification=@CertificationType 
		END
		ELSE
		BEGIN
			UPDATE MsmeCertifications SET  SaCertificateNo=@CertificateNo, CertificationStatusDate=getdate(),CertificationStatus=16,CertificationPhase='ACTIVE',FirstSurveDueDate = DATEADD(DAY, 365, GETDATE()) where  ZedId=@ZedId and Certification=@CertificationType 
		END

		IF @CertificationType='Silver'
		BEGIN
			Update MsmeCertifications set QrCodeSeqNo=concat(@PlantIdNo,'3',@QrCodeSeqNo) where ZedId=@ZedId and Certification=@CertificationType

						-------IF ALREADY Bronze IS CERTIFIED BEFORE AND UPDATING STRING TO STOP AUTOMAIL-------------
			UPDATE MsmeCertifications SET CertificationPhase='UPGRADED', RestrictMail='Silver Certified',FirstSurveDueDate=NULL where ZedId=@ZedId and Certification='Bronze' and CertificationStatus=6 --and RestrictMail is null

		END
		ELSE
		BEGIN
		Update MsmeCertifications set QrCodeSeqNo=concat(@PlantIdNo,'4',@QrCodeSeqNo) where ZedId=@ZedId and Certification=@CertificationType

			-------IF ALREADY SILVER IS CERTIFIED BEFORE AND UPDATING STRING TO STOP AUTOMAIL-------------
				UPDATE MsmeCertifications SET CertificationPhase='UPGRADED',RestrictMail='Gold Certified', FirstSurveDueDate=NULL where ZedId=@ZedId and Certification='Silver' and CertificationStatus=16
				UPDATE MsmeCertifications SET CertificationPhase='UPGRADED',RestrictMail='Gold Certified', FirstSurveDueDate=NULL where ZedId=@ZedId and Certification='Bronze' and CertificationStatus=6 --and RestrictMail is null
		END


		---------------------------------------------------------------------------------
        -- BENEFIT ELIGIBILITY AUTO-ACTIVATION
        ---------------------------------------------------------------------------------
        DECLARE @BaseZedId VARCHAR(50) = @ZedId;
        DECLARE @IsRecertID INT = CHARINDEX('_R_', @ZedId);

        -- If it contains '<redacted>', we extract the parent ID to keep history clean
        IF @IsRecertID > 0 
        BEGIN
            SET @BaseZedId = LEFT(@ZedId, @IsRecertID - 1);
        END
        ELSE
        BEGIN
            -- FRESH/UPGRADE: Only enable if the CURRENT record is Status 16 and ACTIVE
            UPDATE BI
            SET BI.IsEligibleForBenefits = 1
            FROM MsmeBasicInformation BI
            INNER JOIN MsmeCertifications C ON BI.ZedId = C.ZedId
            WHERE BI.ZedId = @BaseZedId 
              AND C.Certification = @CertificationType
              AND C.CertificationStatus = 16 
              AND C.CertificationPhase = 'ACTIVE'
              AND BI.IsEligibleForBenefits = 0; -- Only update if currently disabled
        END
        ---------------------------------------------------------------------------------


		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Completed')

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Certificate & Report generated on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'GetCertified')


		EXEC [SP_MOVING_CERTIFIED_MSME_TO_CONSULTANCY] @ZedId, @CertificationType

		

END


