/****** Object:  StoredProcedure [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT] 
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN

	
				IF @CertificationType='Bronze'
				BEGIN
					UPDATE Msme SET IsBronzePaymentDone=null where ZedId=@ZedId
				END
			
				IF @CertificationType='Silver'
				BEGIN
					UPDATE Msme SET IsSilverPaymentDone=null where ZedId=@ZedId
				END
			
				IF @CertificationType='Gold'
				BEGIN
					UPDATE Msme SET IsGoldPaymentDone=null where ZedId=@ZedId
				END
			

				UPDATE MsmeCertifications SET CertificationStatusDate=getdate(),CertificationStatus=99,CertificationPhase='REJECTED' where  ZedId=@ZedId and Certification=@CertificationType

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Unit Rejected due to Non submission of docs in nc5 On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Unit Rejected due to NCs')

END


