/****** Object:  StoredProcedure [dbo].[SP_MONITORING_SEND_BACK_TO_AGENCY_FOR_REALLOCATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_MONITORING_SEND_BACK_TO_AGENCY_FOR_REALLOCATION]-- '<redacted>',null,null,'<redacted>'
(
	@ZedId varchar(100),
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@CertificationType varchar(50),
	@SendBackRemarks varchar(2000) = NULL
)
AS
BEGIN
	
	

	SET NOCOUNT ON;

	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType and CertificationStatus in (8,9))
	BEGIN


				insert into ZEDCS_V2_LIVE.dbo.MsmeCertificationsMoveback (
				 Id,CertificationStatus,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,
				 SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,SaManufacturingCapacityUnits,SaManufacturingCapacityValue,
				 SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue
				)
				select 
				Id,CertificationStatus,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,
				SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,SaManufacturingCapacityUnits,SaManufacturingCapacityValue,
				SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue
				from ZEDCS_V2_LIVE.dbo.MsmeCertifications where zedid=@ZedId AND certification=@CertificationType

				insert into ZEDCS_V2_LIVE.dbo.MsmeRequirementsMoveback (
				Id,ZedId,SectionType,SaConformance,SaUpdatedDate,SaAssessorRemarks
				)
				select Id,ZedId,SectionType,SaConformance,SaUpdatedDate,SaAssessorRemarks from ZEDCS_V2_LIVE.dbo.MsmeRequirements 
				where zedid = @ZedId AND sectiontype = @CertificationType;


				update ZEDCS_V2_LIVE.dbo.SaRequirementPhotos set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType

				update ZEDCS_V2_LIVE.dbo.MsmeCertifications set CertificationStatus=6,SiteAssessorId=null,CoAssessorId=null,ModeOfAssessment=null,AssessmentDate=null 
				where zedid=@ZedId AND certification=@CertificationType

				update MsmeCertifications set SaAuditsConducted=null,SaDomesticCustomers=null,SaInternationalCustomers=null,
					SaRawMaterialImported=null,SaOutsourcedProcesses=null,SaEnergySources=null, SaManufacturingCapacityUnits=null,SaManufacturingCapacityValue=null,
					SaMonthlyUtilizationUnits=null,SaMonthlyUtilizationValue=null	where zedid=@ZedId and certification=@CertificationType
				
				update ZEDCS_V2_LIVE.dbo.MsmeSections set AssessorId=null where zedid=@ZedId AND SectionType=@CertificationType
				update ZEDCS_V2_LIVE.dbo.MsmeRequirements set SaConformance=null,SaUpdatedDate=null,SaAssessorRemarks=null where zedid=@ZedId and sectiontype=@CertificationType
				update ZEDCS_V2_LIVE.dbo.SaRawMaterials set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType
				update ZEDCS_V2_LIVE.dbo.AssessorComments set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType and AssessmentType='SA'
				update ZEDCS_V2_LIVE.dbo.MsmeLocations set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType
				update ZEDCS_V2_LIVE.dbo.ScreenshotPhotos set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType
				update ZEDCS_V2_LIVE.dbo.MsmeRawMaterials set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType			
				update ZEDCS_V2_LIVE.dbo.SaPhotos set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType
				update ZEDCS_V2_LIVE.dbo.SaProducts set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType
				update ZEDCS_V2_LIVE.dbo.MsmeSelfies set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@CertificationType
				update ZEDCS_V2_LIVE.dbo.MeetingParticipants set zedid=@ZedId+'RESET' where zedid=@ZedId AND CertificationType=@CertificationType
				update ZEDCS_V2_LIVE.dbo.Meetings set zedid=@ZedId+'RESET' where zedid=@ZedId AND CertificationType=@CertificationType
		


		insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Revert to Agency by reset the assessment for Re-Allocation On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Revert to Agency for Reallocation by reset the assessment' )

		SELECT 1 Status, 'Data Reset Successfully.' ErrorMessage
	
	END
	ELSE
	BEGIN
		SELECT 0 Status, 'Invalid Details.' ErrorMessage
	END

END

GO
/****** Object:  StoredProcedure [dbo].[SP_MONITORING_SEND_BACK_TO_ASSESSOR]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_SEND_BACK_TO_ASSESSOR] --'<redacted>', null, null,'<redacted>', '<redacted>'
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@SendBackRemarks varchar(2000) = NULL
    
	
)
AS
BEGIN

	DECLARE @NcNumber int = NULL,
	@CertiStatus int = NULL,
	@NewCertiStatus int = NULL,
	@ExactNcStatus int = NULL,
	@Nc5Status int = NULL

	----FINDING THE PRESENT CERTIFICATION STATUS, NCCOUNT
	select @NcNumber=NcCount,@CertiStatus=CertificationStatus,
	@NewCertiStatus=case when (NcCount=0 and Certification='Bronze') then 3 when (NcCount>0 and Certification='Bronze') then 4 
	when (NcCount=0 and Certification in ('Silver','Gold')) then 13 when  (NcCount>0 and Certification in ('Silver','Gold')) then 14
	end		
	from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType

	------FINDING THE EXACT NC COUNT TO SEND BACK REJECTION TO ASSESSOR------
	SELECT @Nc5Status=Nc5Status, @ExactNcStatus= CASE
        WHEN Nc5Status <> 0 THEN 5
        WHEN Nc4Status <> 0 THEN 4
        WHEN Nc3Status <> 0 THEN 3
        WHEN Nc2Status <> 0 THEN 2
        WHEN Nc1Status <> 0 THEN 1
        ELSE 0 END
FROM MsmeCertifications where ((Certification='Bronze' and CertificationStatus=7) OR (Certification!='Bronze' and CertificationStatus=17)) 
and ZedId=@ZedId and Certification=@CertificationType



	---THIS BLOCK IS TO CHECK AND UPDATE FROM QC TO ASSESSOR-------
	IF @NcNumber<=5 AND (@CertiStatus=5 OR @CertiStatus=15)
	BEGIN
		IF @CertificationType='Bronze'
		BEGIN
			UPDATE MsmeCertifications set CertificationStatus=@NewCertiStatus, SendBackStatus=1 where ZedId=@ZedId and Certification=@CertificationType and NcCount<=5 AND CertificationStatus=5

			INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			VALUES (@ZedId,@CertificationType,@NcNumber,@SendBackRemarks,GETDATE(),'SB')
			
			insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Send back from QC to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Send back from QC to Assessor' )
		END
		ELSE
		--BEGIN
		--	UPDATE MsmeCertifications set CertificationStatus=@NewCertiStatus, SendBackStatus=1 where ZedId=@ZedId and Certification=@CertificationType and NcCount<=5 AND CertificationStatus=15

		--	INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
		--	VALUES (@ZedId,@CertificationType,@NcNumber,@SendBackRemarks,GETDATE(),'<redacted>')

		--	insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		--	values (@ZedId,concat('<redacted>',FORMAT(getdate(), '<redacted>')),getdate(),@CertificationType,'<redacted>' )
		--END

		BEGIN
			IF @CertiStatus=5   ---- Desktop Assessment stage (Silver/Gold): no NC here, always go to 3
			BEGIN
				UPDATE MsmeCertifications set CertificationStatus=3, SendBackStatus=1 where ZedId=@ZedId and Certification=@CertificationType and NcCount<=5 AND CertificationStatus=5
			END
			ELSE   ---- @CertiStatus=15, Site Assessment stage: keep existing NC-based status
			BEGIN
				UPDATE MsmeCertifications set CertificationStatus=@NewCertiStatus, SendBackStatus=1 where ZedId=@ZedId and Certification=@CertificationType and NcCount<=5 AND CertificationStatus=15
			END

			INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			VALUES (@ZedId,@CertificationType,@NcNumber,@SendBackRemarks,GETDATE(),'SB')

			insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Send back from QC to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Send back from QC to Assessor' )
		END
		

	END

	ELSE
	BEGIN
		IF @CertificationType='Bronze'
		BEGIN
			UPDATE MsmeCertifications set NcCount=@ExactNcStatus,CertificationStatus=4,SendBackStatus=1, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
			IF @Nc5Status=2
			BEGIN
				UPDATE MsmeCertifications set NcStatus=2, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and Nc5Status=2

				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Agency send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Agency Send back to Assessor' )
			END
			ELSE
			BEGIN
				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )

				insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )
			END
		END
		ELSE
		BEGIN
			UPDATE MsmeCertifications set NcCount=@ExactNcStatus,CertificationStatus=14,SendBackStatus=1, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
			IF @Nc5Status=2
			BEGIN
				UPDATE MsmeCertifications set NcStatus=2, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and Nc5Status=2

				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Agency send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Agency Send back to Assessor' )
			END

			ELSE
			BEGIN
				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )

				insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )
			END

		END

		--BEGIN
		--	UPDATE MsmeCertifications set NcCount=5,CertificationStatus=4,NcStatus=2, SendBackStatus=1,CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
		--END
		--ELSE
		--BEGIN
		--	UPDATE MsmeCertifications set NcCount=5,CertificationStatus=14,NcStatus=2, SendBackStatus=1,CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
		--END

		--INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
		--VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'<redacted>')

		--insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		--values (@ZedId,concat('<redacted>',FORMAT(getdate(), '<redacted>')),getdate(),@CertificationType,'<redacted>' )
	END

END




