	@AgencyComments varchar(5000) = NULL
)
AS
BEGIN
		Declare @CertificateNo varchar(50)= NULL,
			@SerialNo bigint
		SET  @SerialNo = Next Value For SaCertificateSequence; 


		select @CertificateNo=concat('ZEDCS_V2_SA_',replace(convert(varchar, getdate(),103),'/',''),'_',@SerialNo)
	
		
		UPDATE SelfAssessments SET  AgencyComments=@AgencyComments, SaCertificateNo=@CertificateNo, SaFinalSubmitDate=getdate(),SaStatus=3 where  RegistrationNumber=@RegistrationNumber

