/****** Object:  StoredProcedure [dbo].[SP_MONITORING_UPDATE_PARAMETER_EXEMPTION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MONITORING_UPDATE_PARAMETER_EXEMPTION] --'<redacted>', 7
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(100) = NULL,
	@SectionCode varchar(50) = NULL,
	@Status VARCHAR(50) = NULL

)
AS
BEGIN
	 

	IF @RoleId=7 AND EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CertificationStatus=8)
	BEGIN
		insert into BackendChangesHistory (ZedId,Descrip,certificationtype,statustype)
		SELECT ZedId,concat('Exemption updated from ',IsAssessmentExcempted, 'to ',@Status),SectionType,'Exemption updation' 
		from MsmeSections where ZedId=@ZedId and SectionType=@Certification and SectionCode=@SectionCode AND NCCOUNT=0

		UPDATE MsmeSections SET IsAssessmentExcempted=@Status WHERE ZedId=@ZedId and SectionType=@Certification and SectionCode=@SectionCode AND NCCOUNT=0

		SELECT 'SUCCESS' AS Status, 'Updated Successfully' AS ErrorMessage
	END
	ELSE
	BEGIN
		SELECT 'ERROR' AS Status, 'Please check with the Administrator' AS ErrorMessage
	END

END

