/****** Object:  StoredProcedure [dbo].[SP_MOVING_CERTIFIED_MSME_TO_CONSULTANCY]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MOVING_CERTIFIED_MSME_TO_CONSULTANCY] --'<redacted>', '<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL

)
AS
BEGIN


		BEGIN TRY
			UPDATE Msme SET FinancialAssistanceStatus=1 WHERE ZedId=@ZedId 
			--UPDATE MsmeBasicInformation SET LastestCertification=@CertificationType WHERE ZedId=@ZedId

			IF @ZedId='ZEDMSME322070'
			BEGIN
				UPDATE Users set IsActive='ABC123' WHERE UserId=@ZedId 
			END


			--------STARTING ADDING THE COMPLETED RECORD IN ZED CONSULTANT DATABASE-----------------------

			IF NOT EXISTS (SELECT ZedId from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)
			BEGIN
				INSERT INTO ZED_CONSULTANT.dbo.Msme
				 ([MsmeId],[ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType]
				,[OrganisationTypeName], [EnterpriseType], [EnterpriseTypee], [MobileNo], [EmailId], [ApplicationId], [UamNumber]
				,[PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode]
				,[PDistrictName], [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId]
				,[PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone], [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo]
				,[RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo], [CreatedDate]
				,[RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo])

				SELECT
				[MsmeId],[ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType]
				,[OrganisationTypeName], [EnterpriseType], [EnterpriseTypee], [MobileNo], [EmailId], [ApplicationId], [UamNumber]
				,[PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode]
				,[PDistrictName], [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId]
				,[PledgeEmailId], NULL, NULL, NULL, 1, [PledgeCertificateNo]
				,[RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo], getdate()
				,[RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo]
				from Msme where ZedId=@ZedId


				INSERT INTO ZED_CONSULTANT.dbo.MsmeBasicInformation(
				[MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory]
				,[SocialCategoryName], [Gender], [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName]
				,[LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName], [EnterpriseType], [EnterpriseTypee]
				,[CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId]
				,[LastestCertification])
								
				SELECT
				[MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory]
				,[SocialCategoryName], [Gender], [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName]
				,[LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName], [EnterpriseType], [EnterpriseTypee]
				,[CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId]
				,@CertificationType from MsmeBasicInformation WITH (NOLOCK) where ZedId=@ZedId

			END

			-------------------END ADDING THE COMPLETED RECORD IN ZED CONSULTANT DATABASE-------------------------------------------------
		END TRY
		BEGIN CATCH
			INSERT INTO ErrorLogForConsultancy (
				ErrorNumber,
				ErrorSeverity,
				ErrorState,
				ErrorProcedure,
				ErrorLine,
				ErrorMessage,
				InputZedId,
				InputCertificationType
			)
			VALUES (
				ERROR_NUMBER(),
				ERROR_SEVERITY(),
				ERROR_STATE(),
				ERROR_PROCEDURE(),
				ERROR_LINE(),
				ERROR_MESSAGE(),
				@ZedId,
				@CertificationType
			)

		END CATCH

	

END

