/****** Object:  StoredProcedure [dbo].[SP_MOVING_FROM_99_TO_7_NEW]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_MOVING_FROM_99_TO_7_NEW] --'<redacted>','<redacted>', '<redacted>'
(	
	@ZedId varchar(50) = NULL,
	@CertZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
	
)
AS
BEGIN

	SET NOCOUNT ON;

	declare @CertId varchar(50) = NULL
	select @CertId=Id from msmecertifications where zedid=@CertZedId

	-- Start a transaction
    BEGIN TRANSACTION;

    BEGIN TRY
				IF @CertificationType='Bronze'
				BEGIN
					UPDATE Msme SET IsBronzePaymentDone=1 where ZedId=@ZedId
					UPDATE MsmeCertifications SET CertificationStatus=7,NcCount=6 where ZedId=@CertZedId and Certification=@CertificationType
				END
			
				IF @CertificationType='Silver'
				BEGIN
					UPDATE Msme SET IsSilverPaymentDone=1 where ZedId=@ZedId
					UPDATE MsmeCertifications SET CertificationStatus=17,NcCount=6 where ZedId=@CertZedId and Certification=@CertificationType
				END
			
				IF @CertificationType='Gold'
				BEGIN
					UPDATE Msme SET IsGoldPaymentDone=1 where ZedId=@ZedId
					UPDATE MsmeCertifications SET CertificationStatus=17,NcCount=6 where ZedId=@CertZedId and Certification=@CertificationType
				END
			
				update SaRequirementPhotos set ZedId=@ZedId where ZedId=@CertZedId
				update MsmeCertifications set ZedId=@ZedId where ZedId=@CertZedId
				update SaRawMaterials set ZedId=@ZedId where ZedId=@CertZedId  
				update AssessorComments set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeLocations set ZedId=@ZedId where ZedId=@CertZedId
				update ScreenshotPhotos set ZedId=@ZedId where ZedId=@CertZedId
				update MsmeRawMaterials set ZedId=@ZedId where ZedId=@CertZedId 
				update PaymentGateWayTransactions set ZedId=@ZedId where ZedId=@CertZedId
				update MsmePaymentInfo set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeSections set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeRequirements set ZedId=@ZedId where ZedId=@CertZedId
				update MsmeOptions set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeSubOptions set ZedId=@ZedId where ZedId=@CertZedId
				update MsmeEvidences set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmePhotos set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeProducts set ZedId=@ZedId where ZedId=@CertZedId 
				update SaPhotos set ZedId=@ZedId where ZedId=@CertZedId 
				update SaProducts set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeSelfies set ZedId=@ZedId where ZedId=@CertZedId 
				update MsmeHistory set ZedId=@ZedId where ZedId=@CertZedId 
				update MeetingParticipants set ZedId=@ZedId where ZedId=@CertZedId
				update Meetings set ZedId=@ZedId where ZedId=@CertZedId 

-- Commit the transaction
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- Rollback the transaction if any error occurs
        ROLLBACK TRANSACTION;

        -- Return the error message
        DECLARE @ErrorMessage NVARCHAR(4000);
        DECLARE @ErrorSeverity INT;
        DECLARE @ErrorState INT;

        SELECT 
            @ErrorMessage = ERROR_MESSAGE(), 
            @ErrorSeverity = ERROR_SEVERITY(), 
            @ErrorState = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH


END

GO
/****** Object:  StoredProcedure [dbo].[SP_MOVING_ONE_STEP_BACK_OF_NC]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_MOVING_ONE_STEP_BACK_OF_NC] --'<redacted>',null,null,'<redacted>',null
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@SendBackRemarks varchar(2000) = NULL
)
AS
BEGIN
	
	DECLARE @NcCount int = NULL,
			--@StatusType varchar(50) = NULL,
			@NcStatusNumber varchar(50) = NULL

	select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType
	--set @StatusType=CONCAT('<redacted>',@NcCount,'<redacted>')


	IF EXISTS(select * from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and CertificationStatus in (4,14))
	BEGIN
			
		delete from MsmeSections where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount
		delete from MsmeRequirements where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount
		delete from MsmeOptions where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount
		delete from MsmeSubOptions where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount
		delete from MsmeEvidences where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount
		delete from MsmeProducts where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount
		delete from AssessorComments where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount-1
		update MsmePhotos set ZedId=concat(ZedId,'_STEPBACK') where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount 

		update MsmeHistory set ZedId=concat(@ZedId,'_STEPBACK') where ZedId=@ZedId and CertificationType=@CertificationType and StatusType = CONCAT('Nc',@NcCount,'Raised')
		update MsmeHistory set ZedId=concat(@ZedId,'_STEPBACK') where ZedId=@ZedId and CertificationType=@CertificationType and StatusType = CONCAT('Nc',@NcCount,'Submitted')

		IF @CertificationType='Bronze'
		BEGIN
			IF @NcCount=1
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,CertificationStatus=3,AssessorRemarks=null,NcStatus=0,Nc1Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount	
				delete from MsmeHistory where ZedId=@ZedId and CertificationType=@CertificationType and StatusType in ('NcFinalClosureDate')
			END
			IF @NcCount=2
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc2Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount
			END
			IF @NcCount=3
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc3Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount
			END
			IF @NcCount=4
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc4Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount
			END
			IF @NcCount=5
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc5Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount
			END

			insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('One step back to Assessor in NC from ',@NcCount,'To ',@NcCount-1,' On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'One Step back to Assessor in NC' )
		
		END

		ELSE

		BEGIN
			IF @NcCount=1
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,CertificationStatus=13,AssessorRemarks=null,NcStatus=0,Nc1Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount			
				delete from MsmeHistory where ZedId=@ZedId and CertificationType=@CertificationType and StatusType in ('NcFinalClosureDate')
			END
			IF @NcCount=2
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc2Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount			
			END
			IF @NcCount=3
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc3Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount			
			END
			IF @NcCount=4
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc4Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount			
			END
			IF @NcCount=5
			BEGIN
				update MsmeCertifications set NcCount=@NcCount-1,AssessorRemarks=null,NcStatus=2,Nc5Status=0 where ZedId=@ZedId and certification=@CertificationType and NcCount=@NcCount			
			END

			insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('One step back to Assessor in NC from ',@NcCount,'To ',@NcCount-1,' On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'One Step back to Assessor in NC' )
		END
		
		
	END
	ELSE
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_MOVING_TO_AGENCY_FOR_REALLOCATION_BY_RESET_CERTIFIED_UNIT]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_MOVING_TO_AGENCY_FOR_REALLOCATION_BY_RESET_CERTIFIED_UNIT] --'<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	------RENAME CERTIFICATE IN SERVER------------------

	SET NOCOUNT ON;

	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CertificationStatus in (13))
	BEGIN


				insert into ZEDCS_V2_LIVE.dbo.MsmeCertificationsMoveback (
				 Id,CertificationStatus,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,
				 SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,SaManufacturingCapacityUnits,SaManufacturingCapacityValue,
				 SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue,SaCertificateNo,SaAssessorRemarks,IsSaVerified
				)
				select 
				Id,CertificationStatus,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,
				SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,SaManufacturingCapacityUnits,SaManufacturingCapacityValue,
				SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue,SaCertificateNo,SaAssessorRemarks,IsSaVerified
				from ZEDCS_V2_LIVE.dbo.MsmeCertifications where zedid=@ZedId AND certification=@Certification


				update ZEDCS_V2_LIVE.dbo.SaRequirementPhotos set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification

				update ZEDCS_V2_LIVE.dbo.MsmeCertifications set CertificationStatus=6,SiteAssessorId=null,CoAssessorId=null,ModeOfAssessment=null,AssessmentDate=null,
				  SaCertificateNo=null
				where zedid=@ZedId AND certification=@Certification

				update MsmeCertifications set SaAuditsConducted=null,SaDomesticCustomers=null,SaInternationalCustomers=null,
					SaRawMaterialImported=null,SaOutsourcedProcesses=null,SaEnergySources=null, SaManufacturingCapacityUnits=null,SaManufacturingCapacityValue=null,
					SaMonthlyUtilizationUnits=null,SaMonthlyUtilizationValue=null	where zedid=@ZedId and certification=@Certification
				
				update ZEDCS_V2_LIVE.dbo.MsmeSections set AssessorId=null where zedid=@ZedId AND SectionType=@Certification
				update ZEDCS_V2_LIVE.dbo.MsmeRequirements set SaConformance=null,SaUpdatedDate=null,SaAssessorRemarks=null where zedid=@ZedId and sectiontype=@Certification
				update ZEDCS_V2_LIVE.dbo.SaRawMaterials set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification
				update ZEDCS_V2_LIVE.dbo.AssessorComments set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification and AssessmentType='SA'
				update ZEDCS_V2_LIVE.dbo.MsmeLocations set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification
				update ZEDCS_V2_LIVE.dbo.ScreenshotPhotos set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification
				update ZEDCS_V2_LIVE.dbo.MsmeRawMaterials set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification			
				update ZEDCS_V2_LIVE.dbo.SaPhotos set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification
				update ZEDCS_V2_LIVE.dbo.SaProducts set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification
				update ZEDCS_V2_LIVE.dbo.MsmeSelfies set zedid=@ZedId+'RESET' where zedid=@ZedId AND certification=@Certification
				update ZEDCS_V2_LIVE.dbo.MeetingParticipants set zedid=@ZedId+'RESET' where zedid=@ZedId AND CertificationType=@Certification
				update ZEDCS_V2_LIVE.dbo.Meetings set zedid=@ZedId+'RESET' where zedid=@ZedId AND CertificationType=@Certification
		


		insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Revert to Agency by reset the assessment for Re-Allocation On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@certification,'Revert to Agency for Reallocation by reset the assessment' )

		SELECT 1 Status, 'Data Reset Successfully.' ErrorMessage
	
	END
	ELSE
	BEGIN
		SELECT 0 Status, 'Invalid Details.' ErrorMessage
	END

END

