		update MsmeRequirements set Conformance=null,AssessorRemarks=null,OpenedFlag=null where zedid=@ZedId and SectionType=@CertificationType   --conformance,assessorremarks,openedflag
		update MsmeEvidences set DocumentOpenedTime=null where zedid=@ZedId and SectionType=@CertificationType  --document opened time, 
		update MsmePhotos set IsVerified=null,AssessorRemarks=null,DocumentOpenedTime=null where zedid=@ZedId and certification=@CertificationType   --isverified, assessorremarks, documentoepnedtime

		update MsmeProducts set IsVerified=null,AssessorRemarks=null where zedid=@ZedId and certification=@CertificationType

		UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@CertificationType and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
		(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@CertificationType and NcCount=0)


		Update A set A.OpenedFlag=1  from MsmeRequirements A inner join 
		(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where ValidationRequired=1 and ZedId=@ZedId and SectionType=@CertificationType and NcCount=0 and SyncedDate is null) B
		on (A.SectionCode=B.SectionCode and A.RequirementCode=B.RequirementCode and A.SectionType=B.SectionType and A.NcCount=B.NcCount) 
		left join 
		(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where  ZedId=@ZedId and SectionType=@CertificationType and NcCount=0 and SyncedDate is not null) C
		on (A.SectionCode=C.SectionCode and A.RequirementCode=C.RequirementCode and A.SectionType=C.SectionType and A.NcCount=C.NcCount) 
		where ZedId=@ZedId and A.SectionType=@CertificationType and A.NcCount=0 AND C.SectionCode IS NULL AND C.RequirementCode IS NULL


	
		insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Revert to masteradmin by reset the assessment for Re-Allocation On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Revert to masteradmin for Reallocation by reset the assessment' )
	
	END
	ELSE
	BEGIN
		SELECT concat(@ZedId,' PLEASE ENTER CORRECT DETAILS')
	END

