/****** Object:  StoredProcedure [dbo].[SP_MSME_AUTO_ALLOT_AGENCY_ROUND_ROBIN]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

--[SP_SEND_MAIL_AUTO_ALLOT_AGENCY] '<redacted>', '<redacted>'

CREATE PROCEDURE [dbo].[SP_MSME_AUTO_ALLOT_AGENCY_ROUND_ROBIN] --'<redacted>', '<redacted>'
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	
			DECLARE @LastUserId varchar(50) = NULL
			DECLARE @LastId varchar(50) = NULL
			DECLARE @NextUserId varchar(50) = NULL
			DECLARE @OrgPartnerEmailId varchar(100) = NULL
			DECLARE @AgencyId varchar(100) = NULL

			

			SELECT @OrgPartnerEmailId=OrgPartnerEmailId FROM MsmeFacilitatorEntries WHERE LoginVerified='Yes' and ZedId=@ZedId AND Certification=@CertificationType

			IF @OrgPartnerEmailId ='' SET @OrgPartnerEmailId = NULL
			
			IF @OrgPartnerEmailId IS NOT NULL
			BEGIN
				SELECT @AgencyId = UserId FROM Users WHERE RoleId = 2 AND AllowBronzeAssessments = 1 AND IsActive = 1 AND LTRIM(RTRIM(OrgPartnerId)) = LTRIM(RTRIM(@OrgPartnerEmailId))
			END

			IF @AgencyId IS NOT NULL
			BEGIN
				UPDATE MsmeCertifications SET CertificationBodyUserId=@AgencyId, AllotmentType='Direct' WHERE ZedId=@ZedId and Certification=@CertificationType and CertificationBodyUserId is null and NcCount=0
			
			INSERT INTO AgencyAllotmentHistory (AgencyId, ZedId, CertificationType, AllotType,  CreatedDate)
				VALUES (@AgencyId, @ZedId, @CertificationType, 'Direct', GETDATE())

				EXEC [SP_SEND_MAIL_AUTO_ALLOT_AGENCY_ROUND_ROBIN] @ZedId, @AgencyId
			END

			ELSE
			BEGIN
				select TOP 1 @LastUserId=AgencyId from AgencyAllotmentHistory where AllotType='Auto' and CertificationType='Bronze' order by Id desc
				select @LastId=Id from Users where UserId=@LastUserId

				select top 1 @NextUserId=UserId from Users where RoleId=2 and AllowBronzeAssessments=1 and IsActive=1 and UserId not in ('ZEDAA001','ZEDAA003','ZEDAA0044') and Id>@LastId order by id

				IF (@NextUserId is null)
				BEGIN
					select top 1 @NextUserId=UserId from Users where RoleId=2 and AllowBronzeAssessments=1 and IsActive=1  and UserId not in ('ZEDAA001','ZEDAA003','ZEDAA0044') order by id
				END


				----update certifications table with auto agency-----
				UPDATE MsmeCertifications SET CertificationBodyUserId=@NextUserId,AllotmentType='RoundRobin' WHERE ZedId=@ZedId and Certification=@CertificationType and CertificationBodyUserId is null and NcCount=0

							-- Insert record into AgencyAllotmentHistory
				INSERT INTO AgencyAllotmentHistory (AgencyId, ZedId, CertificationType, AllotType,  CreatedDate)
				VALUES (@NextUserId, @ZedId, @CertificationType, 'Auto', GETDATE())

				EXEC [SP_SEND_MAIL_AUTO_ALLOT_AGENCY_ROUND_ROBIN] @ZedId, @NextUserId
			END



END
GO
