CREATE PROC [dbo].[SP_MSME_DISABLE_PLANT]
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@DisableRemarks varchar(2000) = NULL
	
)
AS


BEGIN

	IF @RoleId=10 
	BEGIN

		BEGIN TRY
			BEGIN TRAN

			declare @UdyogAadharNo varchar(50) = NULL,
			@PAddress varchar(500) = NULL
			select @UdyogAadharNo=B.UdyogAadharNo, @PAddress=M.PAddress from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where M.ZedId=@ZedId

	insert into MsmeDeletedRecords 
		  (MsmeId,ZedId,StateId,StateName,DistrictId,DistrictName,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,EnterpriseType,EnterpriseTypee,MobileNo,EmailId,ApplicationId
		  ,UamNumber,PFlat,PBuilding,PRoad,PArea,PCity,PAddress,PPin,PStateId,PStateName,PLgDistrictCode,PDistrictName,PPlantDetailId,Activity,TwoDigitActivity,FourDigitActivity,FiveDigitActivity
		  ,ActivityDetailId,PledgeEmailId,IsBronzePaymentDone,IsSilverPaymentDone,IsGoldPaymentDone,IsCouponUsed,PledgeCertificateNo,RegistrationType,IncorporationDate,WhetherProdCommenced
		  ,PlantIdNo,PUnitName,PUnitIdNo,CreatedDate,RegistrationFrom,FinancialAssistanceStatus,WashWebinarCertificateNo,WashCertificateNo,QrCodeNo,DisableRemarks, DisabledBy, DisabledRole)

	SELECT MsmeId,ZedId,StateId,StateName,DistrictId,DistrictName,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,EnterpriseType,EnterpriseTypee,MobileNo,EmailId,ApplicationId
		  ,UamNumber,PFlat,PBuilding,PRoad,PArea,PCity,PAddress,PPin,PStateId,PStateName,PLgDistrictCode,PDistrictName,PPlantDetailId,Activity,TwoDigitActivity,FourDigitActivity,FiveDigitActivity
		  ,ActivityDetailId,PledgeEmailId,IsBronzePaymentDone,IsSilverPaymentDone,IsGoldPaymentDone,IsCouponUsed,PledgeCertificateNo,RegistrationType,IncorporationDate,WhetherProdCommenced
		  ,PlantIdNo,PUnitName,PUnitIdNo,CreatedDate,RegistrationFrom,FinancialAssistanceStatus,WashWebinarCertificateNo,WashCertificateNo,QrCodeNo,@DisableRemarks, @UserId, @RoleId 
		  FROM MSME where ZedId=@ZedId

		 
	
	INSERT INTO MsmeBasicInformationDeletedRecords(
		   Id,MsmeId,ApplicationId,UdyogAadharNo,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,SocialCategory,SocialCategoryName,Gender,PH,PanNo,Address,StateId,StateName,DistrictId
		  ,DistrictName,LgDistrictCode,Pincode,MobileNo,EmailId,MajorActivity,MajorActivityName,EnterpriseType,EnterpriseTypee,CommmenceDate,PreviousEMType,PreviousEMNumber,TotalEmp,InvestmentCost
		  ,DicName,AppliedDate,ZedId,LastestCertification,ReCertification)

	SELECT Id,MsmeId,ApplicationId,UdyogAadharNo,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,SocialCategory,SocialCategoryName,Gender,PH,PanNo,Address,StateId,StateName,DistrictId
		  ,DistrictName,LgDistrictCode,Pincode,MobileNo,EmailId,MajorActivity,MajorActivityName,EnterpriseType,EnterpriseTypee,CommmenceDate,PreviousEMType,PreviousEMNumber,TotalEmp,InvestmentCost
		  ,DicName,AppliedDate,ZedId,LastestCertification,ReCertification FROM MsmeBasicInformation where ZedId=@ZedId

		  

	INSERT INTO MsmeCertificationsDeletedRecords(
		   Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId
		  ,AcceptOrRejectDate,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection
		  ,NcCount,CertificationStatus,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks
		  ,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,CreatedDate,JoinRoomStatus
		  ,QrCodeSeqNo,NcFinalClosureDt)

	SELECT Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId
		  ,AcceptOrRejectDate,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection
		  ,NcCount,CertificationStatus,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks
		  ,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,CreatedDate,JoinRoomStatus
		  ,QrCodeSeqNo,NcFinalClosureDt FROM MsmeCertifications where ZedId=@ZedId


		  UPDATE Users SET IsActive=0 where UserId=@ZedId

		  DELETE FROM Msme where ZedId=@ZedId
		  DELETE FROM MsmeBasicInformation where ZedId=@ZedId
		  DELETE FROM MsmeCertifications where ZedId=@ZedId	

		  ------ UPDATING THE DUPLICATE COUNTS IF ANY FOR THIS ZEDID BASED ON UDYAM NUMBER ---------
		  EXEC [SP_MSME_DUPLICATE_UDYAM_PADDRESS_COUNTS_UPDATE] @UdyogAadharNo, @PAddress

			COMMIT TRAN

		  END TRY

     BEGIN CATCH
             ROLLBACK TRAN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

     END CATCH

	 END
	 ELSE
	 BEGIN
		insert into DisabledFromIosHistory (ZedId)
		values (@ZedId)

	 END



END




GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_DUPLICATE_UDYAM_PADDRESS_COUNTS_UPDATE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_DUPLICATE_UDYAM_PADDRESS_COUNTS_UPDATE] --'<redacted>', '<redacted>'
(
	@UdyogAadharNo varchar(100) = NULL,
	@PAddress varchar(500) = NULL
	
)
AS


BEGIN

		UPDATE M
		SET M.SameUdyamAddress = CASE WHEN Y.counts=1 THEN 0 ELSE Y.counts END
		FROM 
			Msme M
		INNER JOIN 
			MsmeBasicInformation B 
		ON 
			M.ZedId = B.ZedId 
			
		INNER JOIN
		(
			SELECT 
				M.PAddress, 
				B.UdyogAadharNo, 
				COUNT(*) AS counts
			FROM 
				Msme M
			INNER JOIN 
				MsmeBasicInformation B ON M.ZedId = B.ZedId
			WHERE UdyogAadharNo=@UdyogAadharNo AND PAddress = @PAddress
			GROUP BY 
				M.PAddress, 
				B.UdyogAadharNo
		) Y 
		ON 
			M.PAddress = Y.PAddress AND B.UdyogAadharNo=Y.UdyogAadharNo
		
		WHERE 
			B.UdyogAadharNo = @UdyogAadharNo AND M.PAddress = @PAddress

END




GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_MSME_GET_DETAILS] null, '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_MSME_GET_DETAILS] --null, '<redacted>', '<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @CertificationType='SilverMilestone1'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Silver', 1
	END

	ELSE IF @CertificationType='SilverMilestone2'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Silver', 2
	END

	ELSE IF @CertificationType='SilverMilestone3'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Silver', 3
	END

	ELSE IF @CertificationType='GoldMilestone1'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Gold', 1
	END

	ELSE IF @CertificationType='GoldMilestone2'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Gold', 2
	END

	ELSE IF @CertificationType='GoldMilestone3'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Gold', 3
	END

	ELSE IF @CertificationType='Techupgrade'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Techupgrade', 3
	END

	ELSE IF @CertificationType='BronzeSurveillance'
	BEGIN 
		
		exec ZED_SURVEILLANCE.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Bronze'
	END

	ELSE IF @CertificationType='SilverSurveillance'
	BEGIN 
		
		exec ZED_SURVEILLANCE.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Silver'
	END

	ELSE IF @CertificationType='GoldSurveillance'
	BEGIN 
		
		exec ZED_SURVEILLANCE.[dbo].[SP_MSME_GET_DETAILS] null, @ZedId, 'Gold'
	END


	ELSE
	BEGIN
		DECLARE @CurrentUrl varchar(100) = NULL
		
		SELECT @CurrentUrl=UrlName from UrlsMasterData

		DECLARE @LatestCertification varchar(100) = NULL,
				@DateOfAvail varchar(50) = NULL,
				@JoiningRewardAmount varchar(50) = '10000',

				@LevelOfCertificationForFa varchar(100) = NULL,
				@DateOfFaAvail varchar(100) = NULL,
				@FaAmount varchar(100) = NULL,
				@FaReferenceNo varchar(100) = NULL,
				@FaCertificationCategory varchar(100) = NULL,

				@LevelOfCertificationForTu varchar(100) = NULL,
				@DateOfTuAvail varchar(100) = NULL,
				@TuAmount varchar(100) = NULL,
				@TuReferenceNo varchar(100) = NULL,
				@TuCertificationCategory varchar(2000) = NULL


		select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, 'MMMM d, yyyy') from MsmePaymentInfo where ZedId=@ZedId and UseCoupon='Yes' order by CreatedDate desc

		select top 1 @LevelOfCertificationForFa=CertificationType,
				@DateOfFaAvail=ApproverDateOfReceiptOfPayment, 
				@FaAmount=ApproverAmount, 
				@FaReferenceNo=ApproverReferenceNo,
				@FaCertificationCategory=CategoryOfCertificate
		from FinancialAssistance 
		where ZedId=@ZedId order by CreatedDate desc

		--select top 1 @LevelOfCertificationForTu=CertificationType,
		--		@DateOfTuAvail=ApproverDateOfReceiptOfPayment, 
		--		@TuAmount=ApproverAmount, 
		--		@TuReferenceNo=ApproverReferenceNo,
		--		@TuCertificationCategory=CategoryOfCertificate
		--from ZED_CONSULTANT.dbo.FinancialAssistance 
		--where ZedId=@ZedId order by CreatedDate desc

		select @LevelOfCertificationForTu=LastestCertification from ZED_CONSULTANT.dbo.MsmeBasicInformation where ZedId=@ZedId

					SELECT TOP 1 
				--@LevelOfCertificationForTu = FA.CertificationType,
				@DateOfTuAvail = FA.ApproverDateOfReceiptOfPayment,
				@TuAmount = FA.ApproverAmount,
				@TuReferenceNo = FA.ApproverReferenceNo,
				@TuCertificationCategory = STUFF((
					SELECT ', ' + TU.technologyname
					FROM ZED_CONSULTANT.dbo.TechnologyUpgradation TU
					WHERE TU.ZedId = FA.ZedId
					  AND TU.CertificationType = FA.CertificationType
					  AND TU.CertId = FA.CertId
					  AND TU.FinancialAssistanceId = FA.FinancialAssistanceId
					FOR XML PATH('')
				), 1, 2, '')  -- Concatenates technology names, removes leading comma
			FROM ZED_CONSULTANT.dbo.FinancialAssistance FA
			WHERE FA.ZedId=@ZedId
			ORDER BY FA.CreatedDate DESC;


		--if @MsmeId IS NULL
		--	SELECT @MsmeId = MsmeId from msme where ZedId=@ZedId

		SELECT *,
			FORMAT(CreatedDate, 'MMMM d, yyyy') as PledgeOn, @LatestCertification LatestCertification, @DateOfAvail DateOfAvail, @JoiningRewardAmount JoiningRewardAmount,
		
			----ADDING SURVEILLANCE STATUS FOR DASHBOARD
			(SELECT CASE WHEN EXISTS (SELECT 1 FROM MsmeCertifications C INNER JOIN Msme M ON M.ZedId = C.ZedId WHERE CertificationStatus = 6 AND DaCertificateNo IS NOT NULL 
			AND Certification = 'Bronze' AND C.ZedId = @ZedId AND (EnableSurveillance1=1 OR EnableSurveillance1=2) AND CertificationPhase NOT IN ('EXPIRED', 'WITHDRAWN')) THEN 1 ELSE 0 END) BronzeDashboardSurStatus,

			(SELECT CASE WHEN EXISTS (SELECT 1 FROM MsmeCertifications C INNER JOIN Msme M ON M.ZedId = C.ZedId WHERE CertificationStatus = 16 AND SaCertificateNo IS NOT NULL 
			AND Certification = 'Silver' AND C.ZedId = @ZedId AND (EnableSurveillance1=1 OR EnableSurveillance1=2) AND CertificationPhase NOT IN ('EXPIRED', 'WITHDRAWN')) THEN 1 ELSE 0 END) SilverDashboardSurStatus,

			(SELECT CASE WHEN EXISTS (SELECT 1 FROM MsmeCertifications C INNER JOIN Msme M ON M.ZedId = C.ZedId WHERE CertificationStatus = 16 AND SaCertificateNo IS NOT NULL 
			AND Certification = 'Gold' AND C.ZedId = @ZedId AND (EnableSurveillance1=1 OR EnableSurveillance1=2) AND CertificationPhase NOT IN ('EXPIRED', 'WITHDRAWN')) THEN 1 ELSE 0 END) GoldDashboardSurStatus
			-------CertificationStatusDate <= DATEADD(MONTH, -12, GETDATE()) AND AutoMailSend IS NOT NULL  (removed this condition) to enable survillance button----------

		FROM Msme Where ZedId=@ZedId --MsmeId=@MsmeId
		
		SELECT *, case when ReCertification>0 then '_Payment_Receipt_V2.pdf' ELSE '_Payment_Receipt.pdf' end as PaymentReceiptName,
		case when ReCertification>0 then 'ReCertification' ELSE 'Certification' end as CertOrReCert
		FROM MsmeBasicInformation Where ZedId=@ZedId --MsmeId=@MsmeId

		DECLARE @StateId int = NULL
		SELECT @StateId=StateId from Msme where ZedId=@ZedId

	

		SELECT
			CASE WHEN EXISTS (SELECT CertificationStatus from MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' ) THEN 
				(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) BronzeStatus FROM MsmeCertifications where ZedId=@Zedid AND Certification='Bronze'),0))
			ELSE
				(SELECT ISNULL(IsBronzePaymentDone,0) BronzeStatus from Msme where ZedId=@Zedid) 
			END AS BronzeStatus,

			CASE WHEN EXISTS (SELECT CertificationStatus from MsmeCertifications where ZedId=@Zedid AND Certification='Silver' ) THEN 
				(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) SilverStatus FROM MsmeCertifications where ZedId=@Zedid AND Certification='Silver'),0))
			ELSE
				(SELECT ISNULL(IsSilverPaymentDone,0) SilverStatus from Msme where ZedId=@Zedid) 
			END AS SilverStatus,

			CASE WHEN EXISTS (SELECT CertificationStatus from MsmeCertifications where ZedId=@Zedid AND Certification='Gold' ) THEN 
				(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) GoldStatus FROM MsmeCertifications where ZedId=@Zedid AND Certification='Gold'),0))
			ELSE
				(SELECT ISNULL(IsGoldPaymentDone,0) GoldStatus from Msme where ZedId=@Zedid) 
			END AS GoldStatus,
			
			(select FinancialAssistanceStatus from Msme where ZedId=@ZedId)  FinancialAssistanceStatus,
			(select count(*) from ZED_CONSULTANT.dbo.MsmePaymentInfo where ZedId=@Zedid)  ConsultancyStatus,

			(select TechnologyUpgradation from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)  TechnologyUpgradationStatus,
			
			@LevelOfCertificationForFa LevelOfCertificationForFa,
			@DateOfFaAvail DateOfFaAvail,
			@FaAmount FaAmount,
			@FaReferenceNo FaReferenceNo,
			@FaCertificationCategory FaCertificationCategory,


			@LevelOfCertificationForTu LevelOfCertificationForTu,
			@DateOfTuAvail DateOfTuAvail,
			@TuAmount TuAmount,
			@TuReferenceNo TuReferenceNo,
			@TuCertificationCategory TuCertificationCategory,

			--(SELECT 
			--CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN '<redacted>' ELSE '<redacted>' END AS CertificationPath
			--FROM MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType) CertPath,


			(SELECT 
				CASE 
					-- 1. Check if surveillance is completed in ZED_SURVEILLANCE database
					WHEN EXISTS (
						SELECT 1 
						FROM ZED_SURVEILLANCE.dbo.MsmeCertifications 
						WHERE ZedId = @ZedId 
						  AND Certification = @CertificationType 
						  AND CertificationStatus = 16
					) 
					THEN 
						CASE 
							WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Surveillance/Certifications' 
							ELSE 'Surveillance/Certificates' 
						END
					-- 2. Default to standard ZED certification paths if no surveillance record is found
					ELSE 
						CASE 
							WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Certifications' 
							ELSE 'Certificates' 
						END
				END AS CertificationPath
			FROM MsmeCertifications 
			WHERE ZedId=@ZedId AND Certification=@CertificationType) CertPath,


			(SELECT 
			CASE WHEN CreatedDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END AS PledgePath
			FROM Msme where ZedId=@ZedId) PledgePath

			


			select 
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=', @CertificationType) as AvailIncentive,
				--case when @CertificationType='<redacted>' then concat(@CurrentUrl + '<redacted>',@StateId,'<redacted>') 
				--	 when @CertificationType='<redacted>' then concat(@CurrentUrl + '<redacted>',@StateId,'<redacted>') 
				--	 when @CertificationType='<redacted>' then concat(@CurrentUrl + '<redacted>',@StateId,'<redacted>') end as AvailIncentive,
				[ApplicationReceived],
				[NcFinalClosureDate]			
			from 
				(select Descrip,StatusType from MsmeHistory where ZedId=@ZedId and CertificationType=@CertificationType and statustype is not null) A
				pivot (
					max(descrip) for StatusType in (
					[BasicInfoStatus],
					[DesktopVerification],
					[ScheduledOn],
					[Completed],
					[Nc1Raised],
					[Nc1Submitted],
					[Nc2Raised],
					[Nc2Submitted],
					[Nc3Raised],
					[Nc3Submitted],
					[Nc4Raised],
					[Nc4Submitted],
					[Nc5Raised],
					[Nc5Submitted],
					[NcClosed],
					[GetCertified],
					[ApplicationReceived],
					[NcFinalClosureDate])
				) as Pvt
	

		select top 1 *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) SubsidyCoupon,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel,
		cast((TotalAfterCoupon*isnull(StateSubsidyPercentage,0))/100 as int) StateSubsidyCoupon,
		cast((Total*isnull(StateSubsidyPercentage,0))/100 as int) StateSubsidy, concat('(',cast(isnull(StateSubsidyPercentage,0) as int),'%',')') StateSubsidyLabel		
		from MsmePaymentInfo where ZedId=@ZedId and (@CertificationType is null OR Certification=@CertificationType) order by id desc


		
		
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_FILE_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_MSME_GET_FILE_DETAILS] '<redacted>',5,'<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_MSME_GET_FILE_DETAILS] --'<redacted>',5,'<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@Type varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @RoleId=5
	BEGIN
	SET @ZedId=@UserId
	END

	DECLARE @Url varchar(100) = NULL
	SET @Url = 'E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\'

	DECLARE @WebinarCertificateNo varchar(50) = NULL,
			@WashId varchar(50) = NULL

	IF @Certification in ('Pledge','Wash','Webinar')
	BEGIN
		IF(select count(*) from Msme where zedid=@ZedId AND (@RoleId=7 OR (@ZedId=@UserId AND @RoleId=5)))=0
		SET @ZedId='000'
		ELSE 
		SET @ZedId=@ZedId					
	END
	ELSE IF (@Type='Evidence')
	BEGIN
		IF(select count(*) from MsmeCertifications where zedid=@ZedId and ((DesktopAssessorId=@UserId and @RoleId=3) OR (SiteAssessorId=@UserId and @RoleId=3) OR (CoAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=7) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=8) OR (ZedId=@UserId AND ( @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END
		ELSE 
		SET @ZedId=@ZedId	
	END
	ELSE
	BEGIN
		IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((DesktopAssessorId=@UserId and @RoleId=3) OR (SiteAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=7) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=8) OR (ZedId=@UserId AND ( @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END
	END

	
	IF @Type='Certificate'
	BEGIN
		IF @Certification='Pledge'
		BEGIN
			
			SELECT CONCAT(CASE WHEN CreatedDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'https://loginzed.msme.gov.in/Certifications' ELSE @Url+'Certificates' END,'\',@ZedId,'\Pledge.pdf') FilePath, 'Pledge.pdf' FileName,
			CASE WHEN CreatedDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END AS PathStatus
			from Msme where ZedId=@ZedId
		END
		ELSE IF @Certification in ('Bronze','Silver','Gold')
		BEGIN
			--SELECT CONCAT(@Url,'<redacted>',@ZedId,'<redacted>') FilePath, '<redacted>' FileName

			SELECT 
			CONCAT(CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'https://loginzed.msme.gov.in/Certifications' ELSE @Url+'Certificates' END,'\DA\',@ZedId,'\',Certification,'.pdf') FilePath, Certification,'.pdf' FileName,
			CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Certifications' ELSE 'Certificates' END AS PathStatus
			
			FROM MsmeCertifications WHERE Certification=@Certification and ZedId=@ZedId
		END
		--ELSE IF @Certification='<redacted>'
		--BEGIN
		--	SELECT CONCAT(@Url,'<redacted>',@ZedId,'<redacted>') FilePath, '<redacted>' FileName
		--END
		--ELSE IF @Certification='<redacted>'
		--BEGIN
		--	SELECT CONCAT(@Url,'<redacted>',@ZedId,'<redacted>') FilePath, '<redacted>' FileName
		--END
		ELSE IF @Certification='Wash'
		BEGIN
			SELECT @WashId=ZedId FROM Kawach.dbo.MsmeCertifications WHERE DaCertificateNo in (select WashCertificateNo from Msme where ZedId=@ZedId)
			SELECT CONCAT('D:\Publish\KAWACH\Certificates\DA\',@WashId,'\Bronze.pdf') FilePath, 'Wash.Pdf' FileName, '' PathStatus
		END
		ELSE IF @Certification='Webinar'
		BEGIN
			SELECT @WebinarCertificateNo=WashWebinarCertificateNo FROM Msme WHERE ZedId=@ZedId			
			SELECT CONCAT('D:\Publish\KAWACH\WebinarCertificates\',@WebinarCertificateNo,'.pdf') FilePath, 'Webinar.Pdf' FileName, '' PathStatus
		END
		ELSE
		BEGIN
			SELECT '' FilePath, '' FileName, '' PathStatus
		END
	END

	ELSE IF @Type='Report'
	BEGIN
		IF @Certification='Bronze'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Bronze_Report.pdf') FilePath, 'Bronze_Report.pdf' FileName, '' PathStatus
		END
		ELSE IF @Certification='Silver'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Silver_Report.pdf') FilePath, 'Silver_Report.pdf' FileName, '' PathStatus
		END
		ELSE IF @Certification='Gold'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Gold_Report.pdf') FilePath, 'Gold_Report.pdf' FileName, '' PathStatus
		END
		--ELSE IF @Certification='<redacted>'
		--BEGIN
		--	SELECT CONCAT('<redacted>',@ZedId,'<redacted>') FilePath, '<redacted>' FileName
		--END
		ELSE
		BEGIN
			SELECT '' FilePath, '' FileName, '' PathStatus
		END
	END
	
	ELSE IF @Type='Receipt'
	BEGIN
		IF @Certification='Bronze'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Bronze_Payment_Receipt.pdf') FilePath, 'Bronze_Payment_Receipt.pdf' FileName, '' PathStatus
		END
		ELSE IF @Certification='Silver'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Silver_Payment_Receipt.pdf') FilePath, 'Silver_Payment_Receipt.pdf' FileName, '' PathStatus
		END
		ELSE IF @Certification='Gold'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Gold_Payment_Receipt.pdf') FilePath, 'Gold_Payment_Receipt.pdf' FileName, '' PathStatus
		END
		ELSE
		BEGIN
			SELECT '' FilePath, '' FileName, '' PathStatus
		END
	END

	ELSE IF @Type='Document'
	BEGIN
		SELECT CONCAT(@Url,'Uploads\Documents\',@Certification) FilePath, @Certification FileName, '' PathStatus
	END

	ELSE IF @Type='Evidence'
		BEGIN
			---D:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\ZEDMSME000020\Bronze\Evidences\20.pdf
			SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\',@ZedId,'/',SectionType,'/Evidences/',@Certification,'.pdf') FilePath, EvidenceName+'.pdf' FileName, '' PathStatus
			from MsmeEvidences where ZedId=@ZedId and EvidenceId=@Certification
		END
	ELSE
		BEGIN
			SELECT '' FilePath, '' FileName, '' PathStatus
		END

END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_MY_DOCUMENTS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_MY_DOCUMENTS] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @PledgeFolder varchar(50) = NULL

	SELECT @PledgeFolder = CASE WHEN CAST(CreatedDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END FROM Msme WHERE ZedId = @ZedId
	


	SELECT @ZedId ZedId, DocumentName, @CurrentUrl + '/' + DocumentPath DocumentPath, OrderNo FROM MyDocuments ORDER BY OrderNo

    --SELECT @ZedId ZedId, @CurrentUrl + '<redacted>'+@ZedId+'<redacted>' Pledge,
	SELECT @ZedId ZedId, @CurrentUrl + '/' + @PledgeFolder + '/' + @ZedId + '/Pledge.pdf' AS Pledge,
	--(select case when DaCertificateNo is null then NULL else @CurrentUrl + '<redacted>' + (CASE WHEN CAST(CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN '<redacted>' ELSE '<redacted>' END) + '<redacted>' + @ZedId + '<redacted>' end as Bronze from MsmeCertifications where ZedId=@ZedId and Certification='<redacted>') Bronze, 
	--(select case when SaCertificateNo is null then NULL else @CurrentUrl + '<redacted>' + (CASE WHEN CAST(CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN '<redacted>' ELSE '<redacted>' END) + '<redacted>' + @ZedId + '<redacted>' end as Bronze from MsmeCertifications where ZedId=@ZedId and Certification='<redacted>') Silver, 
	--(select case when SaCertificateNo is null then NULL else @CurrentUrl + '<redacted>' + (CASE WHEN CAST(CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN '<redacted>' ELSE '<redacted>' END) + '<redacted>' + @ZedId + '<redacted>' end as Bronze from MsmeCertifications where ZedId=@ZedId and Certification='<redacted>') Gold, 

	---------------------------------------------------------
	-- BRONZE CERTIFICATE PATH LOGIC
	---------------------------------------------------------
	(SELECT 
		CASE WHEN DaCertificateNo IS NULL THEN NULL ELSE 
			@CurrentUrl + '/' + 
			(CASE 
				WHEN EXISTS (
					SELECT 1 FROM ZED_SURVEILLANCE.dbo.MsmeCertifications 
					WHERE ZedId = @ZedId AND Certification = 'Bronze' AND CertificationStatus = 6
				) 
				THEN 
					CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Surveillance/Certifications' ELSE 'Surveillance/Certificates' END
				ELSE 
					CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Certifications' ELSE 'Certificates' END
			END) 
			+ '/DA/' + @ZedId + '/Bronze.pdf' 
		END 
	FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification='Bronze') AS Bronze, 
	
	---------------------------------------------------------
	-- SILVER CERTIFICATE PATH LOGIC
	---------------------------------------------------------
	(SELECT 
		CASE WHEN SaCertificateNo IS NULL THEN NULL ELSE 
			@CurrentUrl + '/' + 
			(CASE 
				WHEN EXISTS (
					SELECT 1 FROM ZED_SURVEILLANCE.dbo.MsmeCertifications 
					WHERE ZedId = @ZedId AND Certification = 'Silver' AND CertificationStatus = 16
				) 
				THEN 
					CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Surveillance/Certifications' ELSE 'Surveillance/Certificates' END
				ELSE 
					CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Certifications' ELSE 'Certificates' END
			END) 
			+ '/SA/' + @ZedId + '/Silver.pdf' 
		END 
	FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification='Silver') AS Silver, 
	
	---------------------------------------------------------
	-- GOLD CERTIFICATE PATH LOGIC
	---------------------------------------------------------
	(SELECT 
		CASE WHEN SaCertificateNo IS NULL THEN NULL ELSE 
			@CurrentUrl + '/' + 
			(CASE 
				WHEN EXISTS (
					SELECT 1 FROM ZED_SURVEILLANCE.dbo.MsmeCertifications 
					WHERE ZedId = @ZedId AND Certification = 'Gold' AND CertificationStatus = 16
				) 
				THEN 
					CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Surveillance/Certifications' ELSE 'Surveillance/Certificates' END
				ELSE 
					CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME)) THEN 'Certifications' ELSE 'Certificates' END
			END) 
			+ '/SA/' + @ZedId + '/Gold.pdf' 
		END 
	FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification='Gold') AS Gold, 
	

	(select case when DaCertificateNo is null then NULL else 'https://msmekawach.org.in/Certificates/DA/'+ZedId+'/Bronze.pdf' end as Wash
	from KAWACH.dbo.MsmeCertifications where DaCertificateNo in (
	SELECT WashCertificateNo from msme where zedid=@ZedId)) Wash,
	(select case when WebinarCertificateNo is null then NULL else 'https://msmekawach.org.in/WebinarCertificates/'+WashWebinarCertificateNo+'.pdf' end as Webinar
	from KAWACH.dbo.WebinarRegistrations where WebinarCertificateNo in (
	SELECT WashWebinarCertificateNo from msme where zedid=@ZedId)) Webinar 
	FROM Msme WHERE ZedId=@ZedId

    SELECT @ZedId ZedId, case when IsBronzePaymentDone is null then NULL else @CurrentUrl + '/PDFs/SA/'+@ZedId+'/Bronze_Payment_Receipt.pdf' end as BronzeReceipt,
	case when IsSilverPaymentDone is null then NULL else @CurrentUrl + '/PDFs/SA/'+@ZedId+'/Silver_Payment_Receipt.pdf' end as SilverReceipt,
	case when IsGoldPaymentDone is null then NULL else @CurrentUrl + '/PDFs/SA/'+@ZedId+'/Gold_Payment_Receipt.pdf' end as GoldReceipt, NULL WashReceipt, NULL WebinarReceipt, NULL ConsultancyReceipt FROM Msme WHERE ZedId=@ZedId


	---------- FOR Invoice AND Receipt DATA----------
		
		SELECT 
			TadaInvoiceNo, 
			@CurrentUrl + '/' + REPLACE(InvoicePath, '\', '/') AS InvoicePath, 
			DocumentType, 
			ModuleName,
			Certification,
			SubModuleName,
			MileStoneNo
		FROM MsmeInvoiceData 
		WHERE ZedId = @ZedId 
		ORDER BY id DESC

END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_PAYMENT_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_PAYMENT_DETAILS] --NULL, '<redacted>','<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE @EnterpriseTypee varchar(50), @SpecialCategory varchar(50), @IsAspirationalDt varchar(50), @SubsidyUsed bit = 0,
	@IsRecertification int = 0,
	@RecertificationLevel varchar(50) = '',
	@PanNo varchar(50) =NULL,
	@StateCode varchar(50) = NULL,
	@UdyamNo varchar(50) = NULL

	
	select @IsAspirationalDt=IsAspirationalDt,@StateCode=StateCode from Districts where DistrictCode in (select PLgDistrictCode from Msme where ZedId=@ZedId)

	if @MsmeId IS NULL
		SELECT @MsmeId = MsmeId from msme where ZedId=@ZedId

		SELECT @EnterpriseTypee=EnterpriseTypee FROM Msme Where ZedId=@ZedId

		-- checking recertification
    SELECT @IsRecertification=Recertification,@RecertificationLevel=ReCertificationLevel, @PanNo=PanNo, @UdyamNo=UdyogAadharNo FROM MsmeBasicInformation WHERE ZedId=@ZedId --and UdyogAadharNo IN ('<redacted>', '<redacted>', '<redacted>','<redacted>')

		---IF SUBSIDY USED INITIALLY THEN NO SUBSIDY FOR REJECTED CASES
		IF EXISTS(SELECT * FROM PaymentGateWayTransactions  where Certification=@Certification and PaymentStatus='success' and ZedId like CONCAT(@ZedId,'[_]D%'))
			SET @SubsidyUsed = 1
		
		ELSE IF EXISTS(SELECT * FROM MsmePaymentInfo  where Certification=@Certification and Certification in ('Bronze','Silver','Gold') and ZedId like CONCAT(@ZedId,'[_]D%'))
			SET @SubsidyUsed = 1 

		--ELSE IF EXISTS(SELECT * FROM MsmePaymentInfo  where Certification=@Certification and Certification='<redacted>' and (UseCoupon IS NULL OR UseCoupon='<redacted>')  and ZedId like CONCAT(@ZedId,'<redacted>'))
		--	SET @SubsidyUsed = 1 


    --SELECT @SpecialCategory=1 FROM MsmeBasicInformation Where MsmeId=@MsmeId
	SELECT  @SpecialCategory = CASE WHEN Gender='Female' then 2 WHEN SocialCategoryName in ('SC','ST') THEN 1 WHEN @IsAspirationalDt=1 then 1 else 0 END FROM MsmeBasicInformation Where MsmeId=@MsmeId







	IF @StateCode=28 AND (@IsRecertification = 0 OR (@IsRecertification = 1 AND @ReCertificationLevel!=@Certification)) and @Certification in ('Silver','Gold') AND NOT EXISTS (SELECT 1 FROM MsmeCertifications WHERE ZedId LIKE CONCAT(@ZedId, '[_]D%') AND Certification = @Certification)
	--IF @UdyamNo='<redacted>' and @Certification in ('<redacted>','<redacted>')
	BEGIN
		
		SELECT *,@PanNo UdyamPanNo,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel,
		concat('(',cast(StateSubsidyPercentage as int),'%',')') StateSubsidyLabel, 'Yes' IsEligibleStateSubsidy
		FROM StateAssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		print 'state logic 1'


		SELECT *,@PanNo UdyamPanNo,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel,
		concat('(',cast(StateSubsidyPercentage as int),'%',')') StateSubsidyLabel, 'Yes' IsEligibleStateSubsidy
		FROM StateAssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory = @SpecialCategory
		print 'state logic 2'

	END

	ELSE IF (select count(*) from MsmeCertifications where ZedId like CONCAT(@ZedId,'[_]D%') and Certification=@Certification)>0 AND @SubsidyUsed=1
	BEGIN
		
		SELECT *, 'No' IsEligibleStateSubsidy,@PanNo UdyamPanNo,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NOT NULL --AND SpecialCategory IS  NULL	
		print 1
		SELECT *, 'No' IsEligibleStateSubsidy,@PanNo UdyamPanNo,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NULL --AND SpecialCategory IS  NULL	
		print 2

	END

	ELSE IF (@IsRecertification = 1 AND @Certification=@RecertificationLevel)
        BEGIN
            SELECT *, 'No' IsEligibleStateSubsidy,@PanNo UdyamPanNo,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel  FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NOT NULL;
            
            SELECT *, 'No' IsEligibleStateSubsidy,@PanNo UdyamPanNo,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NULL;
        END

    ELSE
	BEGIN		
		SELECT *, 'No' IsEligibleStateSubsidy,@PanNo UdyamPanNo,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		print 3
		SELECT *, 'No' IsEligibleStateSubsidy,@PanNo UdyamPanNo,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory = @SpecialCategory
		print 4
		--IF @SpecialCategory = 1
		--BEGIN
		--	SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		--	print 3
		--	SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory = @SpecialCategory
		--	print 4
		--END
		--ELSE
		--BEGIN
		--	SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory IS NULL
		--	print 5
		--	SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory IS NULL
		--	print 6
		--END
	END

	SELECT  case when ((@IsRecertification=1 AND @Certification=@RecertificationLevel) OR IsCouponUsed=1)  then 1 else 0 end as IsCouponUsed, @IsRecertification IsRecertification, @RecertificationLevel RecertificationLevel from msme where ZedId=@ZedId
END
GO
