/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_STATUS_can delete]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
