-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_STATUS_can delete] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT 
	'Submitted on May 06, 2021' BasicInfoStatus,
	'In-progress' DesktopVerification,
	'Scheduled on May 06, 2021' RemoteOnsiteAssessment,
	'' SaScheduledOn,
	'' SaCompletedOn,
	'' SaNcFinalClosureDate,
	'' SaNc1Raised,
	'' SaNc1Submitted,
	'' SaNc2Raised,
	'' SaNc2Submitted,
	'' SaNc3Raised,
	'' SaNc3Submitted,
	'' SaNc4Raised,
	'' SaNc4Submitted,
	'' SaNc5Raised,
	'' SaNc5Submitted,
	'' SaNcClosed,
	'' SaCompleted,
	'Certificate and Report generated on May 11, 2021' GetCertified,
	'' AvailIncentive
	
	
	FROM MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType

END

