CREATE PROCEDURE [dbo].[SP_MSME_GET_ZEDID_ENTIRE_HISTORY] --NULL, NULL, '<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@SearchZedID varchar(50)
)
AS
BEGIN

    SET NOCOUNT ON;


	IF @SearchZedID IS NULL OR @SearchZedID='' OR @RoleId not in ('7') 
	BEGIN
		SET @SearchZedID='ABCD0000'
	END




    ;WITH History AS
    (
        SELECT 'CERTIFICATION' AS Source_DB, Id, ZedId, Descrip AS [Description],
               CreatedDate, CertificationType, StatusType, '' AS MiletoneNo
        FROM ZEDCS_V2_LIVE.dbo.MsmeHistory WITH (NOLOCK)
        WHERE ZedId = @SearchZedID
           OR ZedId LIKE @SearchZedID + '[_]%'

        UNION ALL

        SELECT 'HANDHOLDING' AS Source_DB, Id, ZedId, Descrip AS [Description],
               CreatedDate, CertificationType, StatusType, NcCount AS MiletoneNo
        FROM ZED_CONSULTANT.dbo.MsmeHistory WITH (NOLOCK)
        WHERE ZedId = @SearchZedID
           OR ZedId LIKE @SearchZedID + '[_]%'

        UNION ALL

        SELECT 'SURVEILLANCE' AS Source_DB, Id, ZedId, Descrip AS [Description],
               CreatedDate, CertificationType, StatusType, '' AS MiletoneNo
        FROM ZED_SURVEILLANCE.dbo.MsmeHistory WITH (NOLOCK)
        WHERE ZedId = @SearchZedID
           OR ZedId LIKE @SearchZedID + '[_]%'
    )
    SELECT
        Source_DB,
        Id,
        ZedId,
        @SearchZedID AS BaseZedId,   -- OPTIONAL: base id for grouping the _DEL / _D_<id> copies.
                                     -- Drop this line if a strict DTO/model rejects extra columns.
        [Description],
        CreatedDate,
        CertificationType,
        StatusType,
        MiletoneNo
    FROM History
    ORDER BY CreatedDate ASC
    OPTION (RECOMPILE);
END
	
	
--	DECLARE @ZapID VARCHAR(60) = @SearchZedID + '<redacted>'; 
	
--	SELECT '<redacted>' AS Source_DB, Id, ZedId,Descrip as Description,CreatedDate,CertificationType,StatusType,'' MiletoneNo
--	FROM ZEDCS_V2_LIVE.dbo.msmehistory WITH (NOLOCK) 
--	WHERE zedid LIKE @ZapID
	
--	UNION ALL
	
--	SELECT '<redacted>' AS Source_DB, Id, ZedId,Descrip as Description,CreatedDate,CertificationType,StatusType, NcCount MiletoneNo
--	FROM ZED_CONSULTANT.dbo.msmehistory WITH (NOLOCK)
--	WHERE zedid LIKE @ZapID
	
--	UNION ALL
	
--	SELECT '<redacted>' AS Source_DB, Id, ZedId,Descrip as Description,CreatedDate,CertificationType,StatusType,'' MiletoneNo
--	FROM ZED_SURVEILLANCE.dbo.msmehistory WITH (NOLOCK)
--	WHERE zedid LIKE @ZapID
	
--	ORDER BY createddate ASC
