CREATE PROCEDURE [dbo].[SP_MSME_INSERT_UAM_DETAILS] --'<redacted>', '<redacted>'
(
	@MsmeId	varchar(50)	= NULL,
	@ZedId	varchar(50)	= NULL,
	@StateId	varchar(50)	= NULL,
	@StateName	varchar(100)	= NULL,
	@DistrictId	varchar(50)	= NULL,
	@DistrictName	varchar(100)	= NULL,
	@OwnerName	varchar(200)	= NULL,
	@EnterpriseName	varchar(250)	= NULL,
	@OrganisationType	varchar(50)	= NULL,
	@OrganisationTypeName	varchar(50)	= NULL,
	@EnterpriseType	varchar(50)	= NULL,
	@EnterpriseTypee	varchar(50)	= NULL,
	@MobileNo	varchar(50)	= NULL,
	@EmailId	varchar(200)	= NULL,
	@PledgeEmailId	varchar(200)	= NULL,
	@ApplicationId	varchar(50)	= NULL,
	@PFlat	varchar(200)	= NULL,
	@PBuilding	varchar(200)	= NULL,
	@PRoad	varchar(200)	= NULL,
	@PArea	varchar(200)	= NULL,
	@PCity	varchar(200)	= NULL,
	@PPin	varchar(50)	= NULL,
	@PStateId	varchar(50)	= NULL,
	@PStateName	varchar(100)	= NULL,
	@PLgDistrictCode	varchar(50)	= NULL,
	@PDistrictName	varchar(100)	= NULL,
	@PPlantDetailId	varchar(50)	= NULL,
	@Activity	varchar(100)	= NULL,
	@TwoDigitActivity	varchar(2000)	= NULL,
	@FourDigitActivity	varchar(2000)	= NULL,
	@FiveDigitActivity	varchar(2000)	= NULL,
	@ActivityDetailId	varchar(50)	= NULL,
	@UdyogAadharNo	varchar(50)	= NULL,
	@SocialCategory	varchar(50)	= NULL,
	@SocialCategoryName	varchar(50)	= NULL,
	@Gender	varchar(50)	= NULL,
	@PH	varchar(50)	= NULL,
	@PanNo	varchar(50)	= NULL,
	@Address	varchar(max)	= NULL,
	@MajorActivity	varchar(50)	= NULL,
	@MajorActivityName	varchar(50)	= NULL,
	@CommmenceDate	varchar(50)	= NULL,	
	@LgDistrictCode	varchar(50)	= NULL,
	@Pincode	varchar(50)	= NULL,
	@PreviousEMType	varchar(50)	= NULL,
	@PreviousEMNumber	varchar(50)	= NULL,
	@TotalEmp	varchar(50)	= NULL,
	@InvestmentCost	varchar(50)	= NULL,
	@DicName	varchar(50)	= NULL,
	@AppliedDate varchar(50)	= NULL,
	@Password varchar(50) = NULL,
	@IpAddress varchar(50) = NULL,
	@PAddress varchar(2000) = NULL

)
AS
BEGIN
	  
	SET @MsmeId = Next Value For MsmeIdSequence; 
	SET @ZedId = CONCAT('ZEDQCI',RIGHT(concat('00000',convert(varchar(50),@MsmeId)),6)); 

	Declare @CertificateNo varchar(50)= NULL
	select @CertificateNo=concat('ZED_',replace(convert(varchar, getdate(),103),'/',''),'_',@MsmeId)
	
	IF @Password IS NULL 
	BEGIN
		SET @Password=@ZedId
	END


	INSERT INTO Msme (MsmeId, ZedId, StateId, StateName, DistrictId, DistrictName, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName, EnterpriseType, EnterpriseTypee, MobileNo, EmailId,PledgeEmailId,
		ApplicationId,UamNumber, PFlat, PBuilding, PRoad, PArea, PCity, PPin, PStateId, PStateName, PLgDistrictCode, PDistrictName, PPlantDetailId, Activity, TwoDigitActivity, FourDigitActivity,
		FiveDigitActivity, ActivityDetailId,PledgeCertificateNo,RegistrationType
	)
	VALUES(@MsmeId, @ZedId, @StateId, @StateName, @DistrictId, @DistrictName, @OwnerName, @EnterpriseName, @OrganisationType, @OrganisationTypeName, @EnterpriseType, 
		@EnterpriseTypee, @MobileNo, @EmailId, @PledgeEmailId, @ApplicationId,@UdyogAadharNo, @PFlat, @PBuilding, @PRoad, @PArea, @PCity, @PPin, @PStateId, @PStateName, @PLgDistrictCode, 
		@PDistrictName, @PPlantDetailId, @Activity, @TwoDigitActivity, @FourDigitActivity, @FiveDigitActivity, @ActivityDetailId, @CertificateNo,'UAM'
	)


	INSERT INTO MsmeBasicInformation(MsmeId,ZedId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName, SocialCategory, SocialCategoryName, Gender, PH, PanNo, Address, 
		StateId, StateName, DistrictId, DistrictName, LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivity, MajorActivityName, EnterpriseType, EnterpriseTypee,
		CommmenceDate, PreviousEMType, PreviousEMNumber, TotalEmp, InvestmentCost, DicName, AppliedDate
	)
	VALUES(@MsmeId,@ZedId,@ApplicationId,@UdyogAadharNo,@OwnerName,@EnterpriseName,@OrganisationType,@OrganisationTypeName,@SocialCategory,@SocialCategoryName,@Gender,@PH,@PanNo,@Address,
		@StateId,@StateName,@DistrictId,@DistrictName,@LgDistrictCode,@Pincode,@MobileNo,@EmailId,@MajorActivity,@MajorActivityName,@EnterpriseType,@EnterpriseTypee,@CommmenceDate,@PreviousEMType,@PreviousEMNumber,
		@TotalEmp,@InvestmentCost,@DicName,@AppliedDate	
	)


	INSERT INTO USERS(UserId, Password,	UserName, RoleId, IsActive, Email, MobileNo, CreatedBy, CreatedDate, StateCode,	DistrictCode)
	VALUES(@ZedId, @Password, @EnterpriseName, 5, 1, @PledgeEmailId, @MobileNo, null, getdate(), @PStateId, @PLgDistrictCode)
	

    SELECT *, @Password Password, FORMAT(GETDATE(), 'MMMM d, yyyy') DateOfPledge, @CertificateNo CertificateNo FROM Msme Where MsmeId=@MsmeId

	Insert into MsmeHistory (ZedId,Descrip,CreatedDate)
	values (@ZedId,'Registered from UAM',getdate())

END
GO
