	@Password varchar(50) = NULL,
	@IpAddress varchar(50) = NULL,
	@PAddress varchar(2000) = NULL,
	@UamNumber varchar(50) = NULL,
	@IncorporationDate varchar(50) = NULL,
	@WhetherProdCommenced varchar(50) = NULL,
	@PlantIdNo varchar(50) = NULL,
	@UnitName varchar(500) = NULL,
	@UnitIdNo varchar(50) = NULL,
	@RegistrationFrom varchar(50) = NULL,
	@ZedCertified  bit = NULL,
	@QrCodeNo varchar(50) = NULL
)
AS
BEGIN
	  
	--SET @MsmeId = Next Value For MsmeIdSequence; 
	--SET @ZedId = CONCAT('<redacted>',RIGHT(concat('<redacted>',convert(varchar(50),@MsmeId)),6)); 

	SET @MsmeId = Next Value For MsmeIdSequence; 
	SET @ZedId = CONCAT('ZEDMSME', FORMAT(CAST(@MsmeId AS BIGINT), '000000'));

	Declare @CertificateNo varchar(50)= NULL
	select @CertificateNo=concat('ZED_',replace(convert(varchar, getdate(),103),'/',''),'_',@MsmeId), @QrCodeNo=concat(@PlantIdNo,'1',UPPER(@Password))

	
	IF @Password IS NULL 
	BEGIN
		SET @Password=@ZedId
	END

	IF @StateId IS NULL 
	BEGIN
		select @StateId=StateCode from Districts where DistrictCode=@PLgDistrictCode
	END

	set @PDistrictName=replace(@PDistrictName,'(','')
	set @PDistrictName=replace(@PDistrictName,')','')

	BEGIN TRY
		BEGIN TRAN

			INSERT INTO Msme (MsmeId, ZedId, StateId, StateName, DistrictId, DistrictName, OwnerName, EnterpriseName, OrganisationTypeName, EnterpriseTypee, EnterpriseType, MobileNo, EmailId,PledgeEmailId,
				ApplicationId,UamNumber, PFlat, PBuilding, PRoad, PArea, PCity,PAddress, PPin, PStateId, PStateName, PLgDistrictCode, PDistrictName, PPlantDetailId, Activity, TwoDigitActivity, FourDigitActivity,
				FiveDigitActivity, ActivityDetailId,PledgeCertificateNo,RegistrationType,IncorporationDate, WhetherProdCommenced,PlantIdNo,PUnitName,PUnitIdNo,RegistrationFrom,QrCodeNo
			)
			VALUES(@MsmeId, @ZedId, @StateId, @StateName, @DistrictId, @DistrictName, @OwnerName, @EnterpriseName, @OrganisationType, 
				@EnterpriseType, @EnterpriseType, @MobileNo, @PledgeEmailId, @PledgeEmailId, @ApplicationId,@UamNumber, @PFlat, @PBuilding, @PRoad, @PArea, @PCity,@PAddress, @PPin, @PStateId, @PStateName, @PLgDistrictCode, 
				@PDistrictName, @PPlantDetailId, @Activity, @TwoDigitActivity, @FourDigitActivity, @FiveDigitActivity, @ActivityDetailId, @CertificateNo,'UDYAM', @IncorporationDate, @WhetherProdCommenced,@PlantIdNo,
				@UnitName,@UnitIdNo,@RegistrationFrom,@QrCodeNo
			)


			INSERT INTO MsmeBasicInformation(MsmeId,ZedId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationTypeName, SocialCategoryName, Gender, PH, PanNo, Address, 
				StateName, DistrictName, LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivityName, EnterpriseTypee, CommmenceDate, PreviousEMType, PreviousEMNumber, 
				TotalEmp, InvestmentCost, DicName, AppliedDate
			)
			VALUES(@MsmeId,@ZedId,@ApplicationId,@UdyogAadharNo,@OwnerName,@EnterpriseName,@OrganisationType,@SocialCategory,@Gender,@PH,@PanNo,@Address,
				@StateName,@DistrictName,@LgDistrictCode,@Pincode,@MobileNo,@PledgeEmailId,@MajorActivity,@EnterpriseType,@CommmenceDate,@PreviousEMType,@PreviousEMNumber,
				@TotalEmp,@InvestmentCost,@DicName,@AppliedDate	
			)


			INSERT INTO USERS(UserId, Password,	UserName, RoleId, IsActive, Email, MobileNo, CreatedBy, CreatedDate, StateCode,	DistrictCode)
			VALUES(@ZedId, @Password, @UnitName, 5, 1, @PledgeEmailId, @MobileNo, null, getdate(), @StateId, @PLgDistrictCode)


			SELECT @MsmeId [MsmeId]
			  ,@ZedId [ZedId]
			  ,@StateId [StateId]
			  ,@StateName [StateName]
			  ,@DistrictId [DistrictId]
			  ,@DistrictName [DistrictName]
			  ,@OwnerName [OwnerName]
			  ,@EnterpriseName [EnterpriseName]
			  ,@OrganisationType [OrganisationType]
			  ,@OrganisationType [OrganisationTypeName]
			  ,@EnterpriseType[EnterpriseType]
			  ,@EnterpriseType[EnterpriseTypee]
			  ,@MobileNo [MobileNo]
			  ,@PledgeEmailId [EmailId]
			  ,@ApplicationId [ApplicationId]
			  ,@UamNumber [UamNumber]
			  ,@PFlat [PFlat]                           
			  ,@PBuilding [PBuilding]
			  ,@PRoad [PRoad]
			  ,@PArea [PArea]
			  ,@PCity [PCity]
			  ,@PAddress [PAddress]
			  ,@PPin [PPin]
			  ,@PStateId [PStateId]
			  ,@PStateName [PStateName]
			  ,@PLgDistrictCode [PLgDistrictCode]
			  ,@PDistrictName [PDistrictName]                      
			  ,@PPlantDetailId [PPlantDetailId]
			  ,@Activity [Activity]
			  ,@TwoDigitActivity [TwoDigitActivity]
			  ,@FourDigitActivity [FourDigitActivity]
			  ,@FiveDigitActivity [FiveDigitActivity]
			  ,@ActivityDetailId [ActivityDetailId]
			  ,@PledgeEmailId [PledgeEmailId]
			  ,NULL [IsBronzePaymentDone]
			  ,NULL [IsSilverPaymentDone]
			  ,NULL [IsGoldPaymentDone]
			  ,NULL [IsCouponUsed]
			  ,@CertificateNo [PledgeCertificateNo]
			  ,'UDYAM' [RegistrationType]
			  ,@IncorporationDate [IncorporationDate]
			  ,@WhetherProdCommenced [WhetherProdCommenced], @Password Password, FORMAT(GETDATE(), 'MMMM d, yyyy') DateOfPledge, @CertificateNo CertificateNo, 
			  concat(@PAddress,', ',@PDistrictName,', ',@PStateName,'-',@PPin)  as Address,
			  concat('https://loginzed.msme.gov.in/Verify/PC/',@QrCodeNo) QrCodeNo
	

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Registered from UDYAM via ',@RegistrationFrom),getdate(),NULL,NULL)

			EXEC [SP_MSME_DUPLICATE_UDYAM_PADDRESS_COUNTS_UPDATE] @UdyogAadharNo, @PAddress

			---CALLING THIS SP TO SEND THE DETAILS TO FINANCE API---
			EXEC [SP_API_FINANCE_GET_UNIT_DETAILS] @ZedId

	COMMIT TRAN

		  END TRY

     BEGIN CATCH
             ROLLBACK TRAN

			 INSERT INTO ErrorLogForConsultancy (
				ErrorNumber,
				ErrorSeverity,
				ErrorState,
				ErrorProcedure,
				ErrorLine,
				ErrorMessage,
				InputZedId
			)
			VALUES (
				ERROR_NUMBER(),
				ERROR_SEVERITY(),
				ERROR_STATE(),
				ERROR_PROCEDURE(),
				ERROR_LINE(),
				ERROR_MESSAGE(),
				@ZedId
			)

			 UPDATE DummyUsersForError SET IsActive='REGISTRATION' where UserId='ZEDMSME000112'

     END CATCH

END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	--@PaymentStatus varchar(50) = NULL,
	--@PaymentResponse varchar(5000) = NULL,
	--@IpAddress varchar(50) = NULL,
	--@PgType varchar(50) = NULL,
	--@BankRefNumber varchar(50) = NULL,
	--@BankCode varchar(50) = NULL,
	--@ErrorMessage varchar(2000) = NULL,
	--@AmountPaid varchar(50) = NULL,
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL ,
	@Certification varchar(50) = NULL,
	@PaymentRemarks varchar(2000) = NULL
)
AS
BEGIN

	IF @RoleId=10
	BEGIN
	
		DECLARE @PaymentStatus varchar(50) = 'Success'

		BEGIN TRY
				BEGIN TRAN

				DECLARE @IsRecertification int = 0;

				SELECT @IsRecertification=Recertification FROM MsmeBasicInformation WHERE ZedId=@ZedId and ReCertificationLevel=@Certification

				IF @IsRecertification=1 and @PaymentStatus='success'
				BEGIN
					update MsmeBasicInformation set Recertification=2 WHERE ZedId=@ZedId and ReCertificationLevel=@Certification
					EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @Certification
					EXEC [SP_RESET_FOR_RE_CERTIFICATION] NULL, @ZedId, @Certification, NULL
				END

		UPDATE PaymentGatewayTransactions 
		SET PaymentStatus	= @PaymentStatus,
			--PaymentResponse	= @PaymentResponse,
			--IpAddress		= @IpAddress,
			--PgType			= @PgType,
			--BankRefNumber   = @BankRefNumber,
			--BankCode        = @BankCode,
			--ErrorMessage    = @ErrorMessage,
			IsManuallyUpdated=1,
			PaymentRemarks= @PaymentRemarks
			--UpdatedDate		= GETDATE()
		WHERE ZedId=@ZedId and TransactionId=@TransactionId	and Certification=@Certification

	
			IF @Certification = 'Bronze'
				UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
			ELSE IF @Certification = 'Silver'
				UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
			ELSE IF @Certification = 'Gold'
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
		
	
			IF (SELECT UseCoupon FROM PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId and Certification=@Certification) = 'Yes'
			BEGIN
				UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

				IF @Certification='Bronze'
				BEGIN
					UPDATE Msme SET SurCouponAmount=2000 WHERE ZEDId=@ZedId
				END

			END


			    DECLARE @NewInvoiceNumber VARCHAR(50);

				EXEC [SP_GENERATE_NEXT_ZED_INVOICE_NO] 
				@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 


			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage], PaymentVersion, TaDaInvoiceNo
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
				PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage], 'V2', @NewInvoiceNumber
			FROM AssessmentFee F, PaymentGatewayTransactions P
			WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId and P.Certification=@Certification

			-----INSERTING EXTRA FIELDS IN SEPARATE TABLE --------------
			INSERT INTO ManualUpdatePaymentDetails (ZedId,Certification,TransactionNumber,TransactionDate,GstNumber,TanNumber,TdsPercentage)
			SELECT @ZedId,@Certification,@TransactionId,GETDATE(),Gstin,TanNumber,CAST(Tds AS VARCHAR) FROM PaymentGatewayTransactions 
			WHERE ZedId = @ZedId AND TransactionId=@TransactionId AND Certification=@Certification;

			declare @PaidAmount varchar(50) = NULL
			select @PaidAmount=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,'Manual Update of Payment Status')

			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM Sections WHERE SectionType=@Certification ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType FROM Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
			SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode

			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)




			COMMIT TRAN

			  END TRY

		 BEGIN CATCH
				 ROLLBACK TRAN
				 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		 END CATCH
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS_WITH_INFO]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---- THIS SP IS TO SAVE THE BANK DATA WHILE MANUAL UPDATING
CREATE PROC [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS_WITH_INFO] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	--@PaymentStatus varchar(50) = NULL,
	--@PaymentResponse varchar(5000) = NULL,
	--@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@PaymentReceivedDate    DATETIME = NULL,
	--@ErrorMessage varchar(2000) = NULL,
	--@AmountPaid varchar(50) = NULL,
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL ,
	@Certification varchar(50) = NULL,
	@PaymentRemarks varchar(2000) = NULL,
	@TrackingId varchar(50) = NULL,
	@GstNumber varchar(50) = NULL
)
AS
BEGIN

	IF @RoleId=10
	BEGIN
	
		DECLARE @PaymentStatus varchar(50) = 'Success'

		BEGIN TRY
				BEGIN TRAN

				DECLARE @IsRecertification int = 0;
				DECLARE @IsGstinManualUpdated int = 0;

				SELECT @IsRecertification=Recertification FROM MsmeBasicInformation WHERE ZedId=@ZedId and ReCertificationLevel=@Certification


				IF @IsRecertification=1 and @PaymentStatus='success'
				BEGIN
					update MsmeBasicInformation set Recertification=2 WHERE ZedId=@ZedId and ReCertificationLevel=@Certification
					EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @Certification
					EXEC [SP_RESET_FOR_RE_CERTIFICATION] NULL, @ZedId, @Certification, NULL
				END

				IF @GstNumber IS NOT NULL
				BEGIN
					SET @IsGstinManualUpdated = 1;
				END

						-- Convert incoming UTC Date to IST (+5 hours 30 mins)
			IF @PaymentReceivedDate IS NOT NULL
			BEGIN
				SET @PaymentReceivedDate = DATEADD(MINUTE, 330, @PaymentReceivedDate);
			END


		UPDATE PaymentGatewayTransactions 
		SET PaymentStatus	= @PaymentStatus,
			--PaymentResponse	= @PaymentResponse,
			--IpAddress		= @IpAddress,
			PgType			= @PgType,
			BankRefNumber   = @BankRefNumber,
			BankCode        = @BankCode,
			--ErrorMessage    = @ErrorMessage,
			IsManuallyUpdated=1,
			PaymentRemarks= @PaymentRemarks,
			TransactionDate     = ISNULL(@PaymentReceivedDate, TransactionDate),
			UpdatedDate		= GETDATE(),
			TrackingId=@TrackingId,
			Gstin=ISNULL(Gstin,@GstNumber)
		WHERE ZedId=@ZedId and TransactionId=@TransactionId	and Certification=@Certification


	
			IF @Certification = 'Bronze'
				UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
			ELSE IF @Certification = 'Silver'
				UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
			ELSE IF @Certification = 'Gold'
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
		
	
			IF (SELECT UseCoupon FROM PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId and Certification=@Certification) = 'Yes'
			BEGIN
				UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

				IF @Certification='Bronze'
				BEGIN
					UPDATE Msme SET SurCouponAmount=2000 WHERE ZEDId=@ZedId
				END

			END


			    DECLARE @NewInvoiceNumber VARCHAR(50);

				EXEC [SP_GENERATE_NEXT_ZED_INVOICE_NO] 
				@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 


			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage], PaymentVersion, TaDaInvoiceNo
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
				PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage], 'V2', @NewInvoiceNumber
			FROM AssessmentFee F, PaymentGatewayTransactions P
			WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId and P.Certification=@Certification

			-----INSERTING EXTRA FIELDS IN SEPARATE TABLE --------------
			INSERT INTO ManualUpdatePaymentDetails (ZedId,Certification,TransactionNumber,TransactionDate,GstNumber,TanNumber,TdsPercentage, IsGstinManualUpdated,PaymentRemarks)
			SELECT @ZedId,@Certification,@TransactionId,GETDATE(),Gstin,TanNumber,CAST(Tds AS VARCHAR),@IsGstinManualUpdated,@PaymentRemarks FROM PaymentGatewayTransactions 
			WHERE ZedId = @ZedId AND TransactionId=@TransactionId AND Certification=@Certification;

			declare @PaidAmount varchar(50) = NULL
			select @PaidAmount=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,'Manual Update of Payment Status')

			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM Sections WHERE SectionType=@Certification ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType FROM Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
			SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode

			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)




			COMMIT TRAN

			  END TRY

		 BEGIN CATCH
				 ROLLBACK TRAN
				 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		 END CATCH
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_NEFT_PAYMENT_DETAILS_notusing]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_NEFT_PAYMENT_DETAILS_notusing] --'<redacted>', '<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@UtrNumber	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL
)
AS
BEGIN
	IF @Certification = 'Bronze'
		UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
	ELSE IF @Certification = 'Silver'
		UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
	ELSE IF @Certification = 'Gold'
		UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
		
	DECLARE @AmountToBePaid varchar(50)

	IF @UseCoupon = 'Yes'
		UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

		IF @TdsDeductible='No'
		BEGIN
			select @AmountToBePaid=ApplicantContributionAfterSubsidy from AssessmentFee where Id=@PaymentRefId
		END
	IF @TdsDeductible='Yes'
		BEGIN			
				select @AmountToBePaid = CASE WHEN @Tds='1.5' THEN NetPaybleTds15 WHEN @Tds='7.5' THEN NetPaybleTds75 END from AssessmentFee where Id=@PaymentRefId
		END


	INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], [UtrNumber],
		[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
		[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [AmountPaid], [SubsidyPercentage]
	)
	SELECT @ZedId, [EnterpriseTypee], @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, @UtrNumber,
		@PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
		[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'NEFT', @AmountToBePaid, [SubsidyPercentage]
	FROM AssessmentFee 
	WHERE Id=@PaymentRefId



END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_PAYMENT_BASIC_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_PAYMENT_BASIC_DETAILS] --'<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@UtrNumber	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL,
	@TransactionId varchar(50) = NULL
)
AS
BEGIN
	DECLARE @AmountToBePaid varchar(50)

	IF @Gstin='Yes'
	BEGIN
		SET @Gstin=@UnitGstin
		SET @UnitGstin='Yes'
	END

	IF @Gstin='No'
	BEGIN
		SET @Gstin=NULL
		SET @UnitGstin='No'
	END
	
	IF @TransactionId IS NULL 
		SET @TransactionId = Next Value For PaymentSequence; 

	IF @TdsDeductible='No'
		BEGIN
			select @AmountToBePaid=ApplicantContributionAfterSubsidy from AssessmentFee where Id=@PaymentRefId
		END
	IF @TdsDeductible='Yes'
		BEGIN	
			IF @Tds='15' 
				SET @Tds='1.5'

			IF @Tds='75' 
				SET @Tds='7.5'

				select @AmountToBePaid = CASE WHEN @Tds='1.5' THEN NetPaybleTds15 WHEN @Tds='7.5' THEN NetPaybleTds75 END from AssessmentFee where Id=@PaymentRefId
		END

	Insert into PaymentGatewayTransactions (ZedId,TransactionId,TransactionStatus,Amount,TransactionDate, Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, PaymentRefId)
	values (@ZedId,@TransactionId,1,@AmountToBePaid,getdate(), @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, @PaymentRefId)

	IF @ZedId in ('ZEDMSME290077','ZEDMSME290083','ZEDMSME290085','ZEDMSME006274','ZEDMSME006944','ZEDMSME009119','ZEDMSME012337','ZEDMSME031062','ZEDMSME122204','ZEDMSME163342',
	'ZEDMSME185598','ZEDMSME018700','ZEDMSME087049','ZEDMSME012646','ZEDMSME389759','ZEDMSME396956','ZEDMSME427207','ZEDMSME428463','ZEDMSME428482',
	'ZEDMSME436698','ZEDMSME438031','ZEDMSME438853','ZEDMSME457903','ZEDMSME465741','ZEDMSME476947','ZEDMSME476949','ZEDMSME503642','ZEDMSME792874',
	'ZEDMSME010118','ZEDMSME011942','ZEDMSME013502','ZEDMSME013583','ZEDMSME013889','ZEDMSME016650','ZEDMSME017215','ZEDMSME018700',
	'ZEDMSME018746','ZEDMSME021670','ZEDMSME129350','ZEDMSME538558','ZEDMSME579233','ZEDMSME579228','ZEDMSME579532','ZEDMSME585555','ZEDMSME590970','ZEDMSME591091',
	'ZEDMSME592797','ZEDMSME592792','ZEDMSME599912','ZEDMSME663452','ZEDMSME670725','ZEDMSME673288','ZEDMSME727192','ZEDMSME778108','ZEDMSME816083'
	,'ZEDMSME434892','ZEDMSME741661','ZEDMSME655928','ZEDMSME1023273')
	BEGIN
	SET @AmountToBePaid=1.00  ---to test the payment gateway
	END

	IF EXISTS(select * from MsmeBasicInformation where ZedId=@ZedId and ReCertificationLevel=@Certification and ReCertification=1)
	BEGIN
		IF (select count(*) from MsmePaymentInfo where zedid=@ZedId and Certification=@Certification AND ReClassification=0)>0
		BEGIN
			SET @ZedId='0000'
		END
	END

	ELSE IF (select count(*) from MsmePaymentInfo where zedid=@ZedId and Certification=@Certification)>0
	BEGIN
		SET @ZedId='0000'
	END


	SELECT @AmountToBePaid AmountToBePaid, @TransactionId TransactionId,'Certification' MerchantParam3, * FROM Msme WHERE ZedId=@ZedId



END



GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_PAYMENT_GATEWAY_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_PAYMENT_GATEWAY_DETAILS] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@PaymentStatus varchar(50) = NULL,
	@PaymentResponse varchar(5000) = NULL,
	@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@ErrorMessage varchar(2000) = NULL,
	@AmountPaid varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@ApiType varchar(50) = 'REGULAR'
)
AS
BEGIN

	-- Extracting the ID from the incoming @PaymentResponse string
	DECLARE @ExtractedTrackingId VARCHAR(100) = NULL;
	IF @PaymentResponse LIKE '%tracking_id=%'
	BEGIN
		SET @ExtractedTrackingId = SUBSTRING(
			@PaymentResponse, 
			CHARINDEX('tracking_id=', @PaymentResponse) + 12, 
			CHARINDEX('&', @PaymentResponse + '&', CHARINDEX('tracking_id=', @PaymentResponse)) - (CHARINDEX('tracking_id=', @PaymentResponse) + 12)
		)
	END


	DECLARE @IsRecertification int = 0;

	SELECT @IsRecertification=Recertification FROM MsmeBasicInformation WHERE ZedId=@ZedId and ReCertificationLevel=@Certification

	IF @IsRecertification=1 and @PaymentStatus='success'
	BEGIN
		update MsmeBasicInformation set Recertification=2 WHERE ZedId=@ZedId and ReCertificationLevel=@Certification
		EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @Certification
		EXEC [SP_RESET_FOR_RE_CERTIFICATION] NULL, @ZedId, @Certification, NULL
	END

	IF (select count(*) from PaymentGatewayTransactions where ZedId=@ZedId and TransactionId=@TransactionId and (PaymentStatus is null OR PaymentStatus!='Success')) > 0
	BEGIN

		UPDATE PaymentGatewayTransactions 
		SET PaymentStatus	= @PaymentStatus,
			PaymentResponse	= @PaymentResponse,
			IpAddress		= @IpAddress,
			PgType			= @PgType,
			BankRefNumber   = @BankRefNumber,
			BankCode        = @BankCode,
			ErrorMessage    = @ErrorMessage,
			UpdatedDate		= GETDATE(),
			ApiType			= @ApiType,
			TrackingId       = @ExtractedTrackingId
		WHERE ZedId=@ZedId and TransactionId=@TransactionId	

		IF @PaymentStatus='success'
		BEGIN
			IF @Certification = 'Bronze'
				UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
			ELSE IF @Certification = 'Silver'
				UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
			ELSE IF @Certification = 'Gold'
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
		
	
			IF (SELECT UseCoupon FROM PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId) = 'Yes'
			BEGIN
				UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

				IF @Certification='Bronze'
				BEGIN
					UPDATE Msme SET SurCouponAmount=2000 WHERE ZEDId=@ZedId
				END

			END
				


				DECLARE @NewInvoiceNumber VARCHAR(50);

				EXEC ZEDCS_V2_LIVE.DBO.[SP_GENERATE_NEXT_ZED_INVOICE_NO] 
					@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 

			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage], PaymentVersion, TaDaInvoiceNo
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
				PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage], 'V2', @NewInvoiceNumber
			FROM AssessmentFee F, PaymentGatewayTransactions P
			WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId

		
		END


		IF @PaymentStatus='success'
			BEGIN 

			declare @PaidAmount varchar(50) = NULL
			select @PaidAmount=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,NULL)


			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM Sections WHERE SectionType=@Certification ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType FROM Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode


			IF @IsRecertification>0
			BEGIN
				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT Id+100,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode
			END
			ELSE
			BEGIN
				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode
			END

			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)

			END
		ELSE
			BEGIN
			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment failed through PaymentGateway for ',@Certification),getdate(),@Certification,NULL)
			END
	END

	ELSE
	BEGIN
	--MsmeHistoryForDuplicates
		Insert into MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
		values (@ZedId,concat('Response came again from PaymentGateway for ',@Certification),getdate(),@Certification,NULL,@ApiType)

		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

	END

END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_PAYMENT_GATEWAY_DETAILS_RECONCILIATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_MSME_PAYMENT_GATEWAY_DETAILS_RECONCILIATION] 
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@PaymentStatus varchar(50) = NULL,
	@PaymentResponse varchar(5000) = NULL,
	@ApiType varchar(50) = 'RECONCILIATION',
	@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@ErrorMessage varchar(2000) = NULL,
	@AmountPaid varchar(50) = NULL,
	@RawData nvarchar(MAX) = NULL,
	@PaymentResponseNv nvarchar(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE @ModuleName varchar(50) = 'OTHERS'

	IF EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.PaymentGatewayTransactions WHERE TransactionId = @TransactionId)
	BEGIN
		SET @ModuleName='SURVEILLANCE'
	END
	ELSE IF EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.PaymentGatewayTransactions WHERE TransactionId = @TransactionId)
	BEGIN
		SET @ModuleName='CONSULTANCY'
	END
	ELSE IF EXISTS (SELECT 1 FROM PaymentGatewayTransactions WHERE TransactionId = @TransactionId)
	BEGIN
		SET @ModuleName='ZED'
	END



    -- 1. LOG THE RESPONSE (Master Log)
    INSERT INTO PaymentGatewayResponses (ZedId, Certification, TransactionId, PaymentStatus, PaymentResponse, ApiType, 
                IpAddress, PgType, BankRefNumber, BankCode, ErrorMessage, AmountPaid, RawData, PaymentResponseNv, ModuleName)
    VALUES (@ZedId, @Certification, @TransactionId, @PaymentStatus, @PaymentResponse, @ApiType, 
                @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @RawData, @PaymentResponseNv, @ModuleName);

    -----------------------------------------------------------------------------------------
    -- 2. ROUTE TO SURVEILLANCE
    -----------------------------------------------------------------------------------------
	DECLARE @IsReSurveillance int = 0;
	SELECT @IsReSurveillance=EnableSurveillance1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification

    IF @ModuleName='SURVEILLANCE'
    BEGIN
        -- Original Surveillance Logic
		IF @IsReSurveillance=1
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.MsmePaymentInfo WHERE ZedId=@ZedId AND Certification=@Certification)
			BEGIN
				EXEC ZED_SURVEILLANCE.dbo.[SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
			END	
			ELSE
			BEGIN
				INSERT INTO ZED_SURVEILLANCE.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
				VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for SURV1 ', @Certification), GETDATE(), @Certification, NULL, @ApiType)
			END
		END
		ELSE IF @IsReSurveillance=2
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.MsmePaymentInfo WHERE ZedId=@ZedId AND Certification=@Certification)
			BEGIN
			    EXEC ZED_SURVEILLANCE.dbo.[SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
			END
			ELSE
			BEGIN
				INSERT INTO ZED_SURVEILLANCE.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
				VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for SURV2', @Certification), GETDATE(), @Certification, NULL, @ApiType)
			END
		END       
		
        ELSE
        BEGIN
            INSERT INTO ZED_SURVEILLANCE.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
            VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for ',@IsReSurveillance, ' ', @Certification), GETDATE(), @Certification, NULL, @ApiType)
        END
    END

    -----------------------------------------------------------------------------------------
    -- 3. ROUTE TO CONSULTANCY (Including NcCount Logic)
    -----------------------------------------------------------------------------------------
    ELSE IF @ModuleName='CONSULTANCY'
    BEGIN
        -- Specific Consultancy Logic for NcCount
        DECLARE @NcCount int = NULL
        SELECT @NcCount = ISNULL(MAX(NcCount), 0) + 1 
        FROM ZED_CONSULTANT.dbo.MsmeCertifications 
        WHERE ZedId = @ZedId AND Certification = @Certification AND CertificationStatus > 15

        IF NOT EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.MsmePaymentInfo WHERE ZedId=@ZedId AND Certification=@Certification AND MileStoneNum=@NcCount)
        BEGIN
            EXEC [SP_CONSULTANCY_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
        END
        ELSE
        BEGIN
            INSERT INTO ZED_CONSULTANT.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
            VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for ', @Certification), GETDATE(), @Certification, NULL, @ApiType)
        END
    END

    -----------------------------------------------------------------------------------------
    -- 4. STANDARD MSME LOGIC (Runs only if not Surveillance/Consultancy)
    -----------------------------------------------------------------------------------------
	ELSE IF @ModuleName='ZED'
    BEGIN
		DECLARE @IsRecertification int = 0;
		SELECT @IsRecertification=Recertification FROM MsmeBasicInformation WHERE ZedId=@ZedId AND ReCertificationLevel=@Certification

		IF NOT EXISTS (SELECT 1 FROM MsmePaymentInfo WHERE ZedId=@ZedId AND Certification=@Certification AND @IsRecertification=0)
		BEGIN
			EXEC [SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
		END
		ELSE IF NOT EXISTS (SELECT 1 FROM MsmePaymentInfo WHERE ZedId=@ZedId AND Certification=@Certification AND @IsRecertification=1 AND ReClassification=0)
		BEGIN
			EXEC [SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
		END
		ELSE
		BEGIN
			INSERT INTO MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
			VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for ', @Certification), GETDATE(), @Certification, NULL, @ApiType)
		END
	END

	
	select @ModuleName as ModuleName


END
GO
