	@PaymentResponseNv nvarchar(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. LOG THE RESPONSE (Master Log)
    INSERT INTO PaymentGatewayResponses (ZedId, Certification, TransactionId, PaymentStatus, PaymentResponse, ApiType, 
                IpAddress, PgType, BankRefNumber, BankCode, ErrorMessage, AmountPaid, RawData, PaymentResponseNv)
    VALUES (@ZedId, @Certification, @TransactionId, @PaymentStatus, @PaymentResponse, @ApiType, 
                @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @RawData, @PaymentResponseNv);

    -----------------------------------------------------------------------------------------
    -- 2. ROUTE TO SURVEILLANCE
    -----------------------------------------------------------------------------------------
	DECLARE @IsReSurveillance int = 0;
	SELECT @IsReSurveillance=EnableSurveillance1 FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification

    IF EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.PaymentGatewayTransactions WHERE TransactionId = @TransactionId)
    BEGIN
        -- Original Surveillance Logic
        IF NOT EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.PaymentGatewayTransactions WHERE ZedId=@ZedId AND Certification=@Certification and @IsReSurveillance=1 AND (PaymentStatus IS NOT NULL AND PaymentStatus='Success'))
        BEGIN
            EXEC ZED_SURVEILLANCE.dbo.[SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
        END
		ELSE IF NOT EXISTS (SELECT 1 FROM ZED_SURVEILLANCE.dbo.PaymentGatewayTransactions WHERE ZedId=@ZedId AND Certification=@Certification and @IsReSurveillance=2 AND GwReSurveillance=0 AND (PaymentStatus IS NOT NULL AND PaymentStatus='Success'))
        BEGIN
            EXEC ZED_SURVEILLANCE.dbo.[SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
        END
        ELSE
        BEGIN
            INSERT INTO ZED_SURVEILLANCE.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
            VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for ', @Certification), GETDATE(), @Certification, NULL, @ApiType)
        END
        
        RETURN; -- Exit immediately
    END

    -----------------------------------------------------------------------------------------
    -- 3. ROUTE TO CONSULTANCY (Including NcCount Logic)
    -----------------------------------------------------------------------------------------
    IF EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.PaymentGatewayTransactions WHERE TransactionId = @TransactionId)
    BEGIN
        -- Specific Consultancy Logic for NcCount
        DECLARE @NcCount int = NULL
        SELECT @NcCount = ISNULL(MAX(NcCount), 0) + 1 
        FROM ZED_CONSULTANT.dbo.MsmeCertifications 
        WHERE ZedId = @ZedId AND Certification = @Certification AND CertificationStatus > 15

        IF NOT EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.PaymentGatewayTransactions WHERE ZedId=@ZedId AND Certification=@Certification AND MileStoneNumber=@NcCount AND (PaymentStatus IS NOT NULL AND PaymentStatus='Success'))
        BEGIN
            EXEC [SP_CONSULTANCY_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
        END
        ELSE
        BEGIN
            INSERT INTO ZED_CONSULTANT.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
            VALUES (@ZedId, CONCAT('RECONCILIATION Response from PaymentGateway for ', @Certification), GETDATE(), @Certification, NULL, @ApiType)
        END

        RETURN; -- Exit immediately
    END

    -----------------------------------------------------------------------------------------
    -- 4. STANDARD MSME LOGIC (Runs only if not Surveillance/Consultancy)
    -----------------------------------------------------------------------------------------
	DECLARE @IsRecertification int = 0;
	SELECT @IsRecertification=Recertification FROM MsmeBasicInformation WHERE ZedId=@ZedId AND ReCertificationLevel=@Certification

	IF NOT EXISTS (SELECT 1 FROM PaymentGatewayTransactions WHERE ZedId=@ZedId AND Certification=@Certification AND @IsRecertification=0 AND (PaymentStatus IS NOT NULL AND PaymentStatus='Success'))
