	END
	ELSE IF NOT EXISTS (SELECT 1 FROM PaymentGatewayTransactions WHERE ZedId=@ZedId AND Certification=@Certification AND @IsRecertification=1 AND GwReClassification=0 AND (PaymentStatus IS NOT NULL AND PaymentStatus='Success'))
	BEGIN
		EXEC [SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
	END
	ELSE
	BEGIN
