CREATE PROCEDURE [dbo].[SP_MSME_PWD_UPDATE_TOKEN] --'<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@PwdCode varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF (SELECT  count(*)  from ForgotPwdLinks where UserId=@UserId and DATEDIFF(MINUTE, CreatedDate , getdate())<=30) > 2
	BEGIN
		--UPDATE DummyUsersForError SET IsActive='<redacted>' where UserId='<redacted>'
		SELECT 'ACCOUNT LOCKED. PLEASE LOGIN AFTER 30 MINUTES.' AS ERRORMSG 
	END
	ELSE
	BEGIN
		UPDATE Users SET PwdCode=@PwdCode Where UserId=@UserId
		insert into ForgotPwdLinks (UserId, PasswordToken) values (@UserId, @PwdCode)
		SELECT 'A Reset link has been sent your Registered Email ID.' AS ERRORMSG
	END

	--[ForgotPwdLinks]

END

GO
