CREATE PROC [dbo].[SP_MSME_RECLASSIFICATION_CERTIFICATION] 
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
		
				EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @CertificationType

		BEGIN TRY
			BEGIN TRAN

				update SaRequirementPhotos set ZedId=concat(ZedId,'_RC_',SaReqCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeCertifications set ZedId=concat(ZedId,'_RC_',Id) where ZedId=@ZedId and Certification=@CertificationType
				update SaRawMaterials set ZedId=concat(ZedId,'_RC_',SaRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update AssessorComments set ZedId=concat(ZedId,'_RC_',AsCmtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeLocations set ZedId=concat(ZedId,'_RC_',MsmeLocCertId) where ZedId=@ZedId and Certification=@CertificationType
				update ScreenshotPhotos set ZedId=concat(ZedId,'_RC_',SrnCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeRawMaterials set ZedId=concat(ZedId,'_RC_',MsmeRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update PaymentGateWayTransactions set ZedId=concat(ZedId,'_RC_',PmtGtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmePaymentInfo set ZedId=concat(ZedId,'_RC_',MsmePmtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeSections set ZedId=concat(ZedId,'_RC_',SecCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeRequirements set ZedId=concat(ZedId,'_RC_',ReqCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeOptions set ZedId=concat(ZedId,'_RC_',OptCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeSubOptions set ZedId=concat(ZedId,'_RC_',SubCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeEvidences set ZedId=concat(ZedId,'_RC_',EviCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmePhotos set ZedId=concat(ZedId,'_RC_',MsPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeProducts set ZedId=concat(ZedId,'_RC_',MsPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaPhotos set ZedId=concat(ZedId,'_RC_',SaPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaProducts set ZedId=concat(ZedId,'_RC_',SaPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeSelfies set ZedId=concat(ZedId,'_RC_',MsSelfCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeHistory set ZedId=concat(ZedId,'_RC_',MsHistCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update MeetingParticipants set ZedId=concat(ZedId,'_RC_',MeetPartCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update Meetings set ZedId=concat(ZedId,'_RC_',MeetCertId) where ZedId=@ZedId and CertificationType=@CertificationType

			COMMIT TRAN
		END TRY


		BEGIN CATCH

             ROLLBACK TRAN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		END CATCH

END


