CREATE PROC [dbo].[SP_MSME_REVERT_DISABLED_PLANT]
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@DisableRemarks varchar(2000) = NULL
	
)
AS


BEGIN
	

		UPDATE MsmeDeletedRecords set RevertToLive='Yes' where ZedId=@ZedId 

	insert into Msme 
		  (MsmeId,ZedId,StateId,StateName,DistrictId,DistrictName,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,EnterpriseType,EnterpriseTypee,MobileNo,EmailId,ApplicationId
		  ,UamNumber,PFlat,PBuilding,PRoad,PArea,PCity,PAddress,PPin,PStateId,PStateName,PLgDistrictCode,PDistrictName,PPlantDetailId,Activity,TwoDigitActivity,FourDigitActivity,FiveDigitActivity
		  ,ActivityDetailId,PledgeEmailId,IsBronzePaymentDone,IsSilverPaymentDone,IsGoldPaymentDone,IsCouponUsed,PledgeCertificateNo,RegistrationType,IncorporationDate,WhetherProdCommenced
		  ,PlantIdNo,PUnitName,PUnitIdNo,CreatedDate,RegistrationFrom,FinancialAssistanceStatus,WashWebinarCertificateNo,WashCertificateNo,QrCodeNo)

	SELECT top 1 MsmeId,ZedId,StateId,StateName,DistrictId,DistrictName,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,EnterpriseType,EnterpriseTypee,MobileNo,EmailId,ApplicationId
		  ,UamNumber,PFlat,PBuilding,PRoad,PArea,PCity,PAddress,PPin,PStateId,PStateName,PLgDistrictCode,PDistrictName,PPlantDetailId,Activity,TwoDigitActivity,FourDigitActivity,FiveDigitActivity
		  ,ActivityDetailId,PledgeEmailId,IsBronzePaymentDone,IsSilverPaymentDone,IsGoldPaymentDone,IsCouponUsed,PledgeCertificateNo,RegistrationType,IncorporationDate,WhetherProdCommenced
		  ,PlantIdNo,PUnitName,PUnitIdNo,CreatedDate,RegistrationFrom,FinancialAssistanceStatus,WashWebinarCertificateNo,WashCertificateNo,QrCodeNo 
		  FROM MsmeDeletedRecords where ZedId=@ZedId

		 
	
	INSERT INTO MsmeBasicInformation(
		   MsmeId,ApplicationId,UdyogAadharNo,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,SocialCategory,SocialCategoryName,Gender,PH,PanNo,Address,StateId,StateName,DistrictId
		  ,DistrictName,LgDistrictCode,Pincode,MobileNo,EmailId,MajorActivity,MajorActivityName,EnterpriseType,EnterpriseTypee,CommmenceDate,PreviousEMType,PreviousEMNumber,TotalEmp,InvestmentCost
		  ,DicName,AppliedDate,ZedId,LastestCertification)

	SELECT top 1 MsmeId,ApplicationId,UdyogAadharNo,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,SocialCategory,SocialCategoryName,Gender,PH,PanNo,Address,StateId,StateName,DistrictId
		  ,DistrictName,LgDistrictCode,Pincode,MobileNo,EmailId,MajorActivity,MajorActivityName,EnterpriseType,EnterpriseTypee,CommmenceDate,PreviousEMType,PreviousEMNumber,TotalEmp,InvestmentCost
		  ,DicName,AppliedDate,ZedId,LastestCertification FROM MsmeBasicInformationDeletedRecords where ZedId=@ZedId

		  
	SET IDENTITY_INSERT MsmeCertifications ON;
	INSERT INTO MsmeCertifications(
		   Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId
		  ,AcceptOrRejectDate,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection
		  ,NcCount,CertificationStatus,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks
		  ,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,CreatedDate,JoinRoomStatus
		  ,QrCodeSeqNo,NcFinalClosureDt)

	SELECT top 1 Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId
		  ,AcceptOrRejectDate,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection
		  ,NcCount,CertificationStatus,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks
		  ,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,CreatedDate,JoinRoomStatus
		  ,QrCodeSeqNo,NcFinalClosureDt FROM MsmeCertificationsDeletedRecords where ZedId=@ZedId
	SET IDENTITY_INSERT MsmeCertifications OFF;

		 UPDATE Users SET IsActive=1 where UserId=@ZedId


END




