/****** Object:  StoredProcedure [dbo].[SP_MSME_UPDATE_PROFILE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_UPDATE_PROFILE]
(
	@ZedId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@EnterpriseName	varchar(250) = NULL,
	@OwnerName	varchar(200) = NULL,
	@PUnitName varchar(500) = NULL,
	@EmailId	varchar(200) = NULL,
	@TwoDigitActivity	varchar(2000) = NULL,
	@FourDigitActivity	varchar(2000) = NULL,
	@FiveDigitActivity	varchar(2000) = NULL


)
AS
BEGIN
	
	IF @TwoDigitActivity='' SET @TwoDigitActivity= NULL
	IF @FourDigitActivity='' SET @FourDigitActivity= NULL
	IF @FiveDigitActivity='' SET @FiveDigitActivity= NULL

	SET NOCOUNT ON;

	IF  @RoleId=10
	BEGIN
		INSERT INTO MsmeUpdatedRecords([MsmeId], [ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [EnterpriseType], [EnterpriseTypee]
		, [MobileNo], [EmailId], [ApplicationId], [UamNumber], [PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode], [PDistrictName]
		, [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId], [PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone]
		, [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo], [RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo]
		, [RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo])

		SELECT [MsmeId], [ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [EnterpriseType], [EnterpriseTypee]
		, [MobileNo], [EmailId], [ApplicationId], [UamNumber], [PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode], [PDistrictName]
		, [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId], [PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone]
		, [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo], [RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo]
		, [RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo] FROM Msme WHERE ZedId=@ZedId


		INSERT INTO MsmeBasicInformationUpdatedRecords([Id], [MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory], [SocialCategoryName], [Gender]
		, [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName], [LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName]
		, [EnterpriseType], [EnterpriseTypee], [CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId], [LastestCertification],Recertification)

		SELECT [Id], [MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory], [SocialCategoryName], [Gender]
		, [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName], [LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName]
		, [EnterpriseType], [EnterpriseTypee], [CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId], [LastestCertification],Recertification
		FROM MsmeBasicInformation where ZedId=@ZedId


		UPDATE MSME SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,PUnitName=@PUnitName,EmailId=@EmailId,PledgeEmailId=@EmailId,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity)
		where ZedId=@ZedId


		UPDATE MsmeBasicInformation SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,EmailId=@EmailId where ZedId=@ZedId
		UPDATE Users SET UserName=@EnterpriseName,Email=@EmailId where UserId=@ZedId and RoleId=5

		--------- FOR CONSULTANCY-------------------
		UPDATE ZED_CONSULTANT.dbo.MSME SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,PUnitName=@PUnitName,EmailId=@EmailId,PledgeEmailId=@EmailId,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity)
		where ZedId=@ZedId
		UPDATE ZED_CONSULTANT.dbo.MsmeBasicInformation SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,EmailId=@EmailId where ZedId=@ZedId

		--------- FOR SURVEILLANCE-------------------
		UPDATE ZED_SURVEILLANCE.DBO.MSME SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,PUnitName=@PUnitName,EmailId=@EmailId,PledgeEmailId=@EmailId,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity)
		where ZedId=@ZedId
		UPDATE ZED_SURVEILLANCE.DBO.MsmeBasicInformation SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,EmailId=@EmailId where ZedId=@ZedId
		
	END
	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_UPDATE_UDYAM_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_UPDATE_UDYAM_DETAILS] --'<redacted>', '<redacted>'
(
    @UdyamNumber VARCHAR(50) = NULL,
    @EnterpriseType VARCHAR(50) = NULL,
	@PaymentModule varchar(50) = 'ZED LIVE',
	@ModifiedDataType varchar(50) = 'EnterpriseType',
    @Activity	varchar(100)	= NULL,
	@TwoDigitActivity	varchar(2000)	= NULL,
	@FourDigitActivity	varchar(2000)	= NULL,
	@FiveDigitActivity	varchar(2000)	= NULL,
	@ActivityDetailId	varchar(50)	= NULL,
	@ZedId varchar(50) = NULL
   
)
AS
BEGIN
	IF @ModifiedDataType IS NULL OR @ModifiedDataType=''
	SET @ModifiedDataType='EnterpriseType'
	
	SET NOCOUNT ON;

		INSERT INTO MsmeUpdatedRecords([MsmeId], [ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [EnterpriseType], [EnterpriseTypee]
		, [MobileNo], [EmailId], [ApplicationId], [UamNumber], [PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode], [PDistrictName]
		, [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId], [PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone]
		, [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo], [RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo]
		, [RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo], UpdatedData,InsertionDate,PaymentModule)

		SELECT [MsmeId], [ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [EnterpriseType], [EnterpriseTypee]
		, [MobileNo], [EmailId], [ApplicationId], [UamNumber], [PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode], [PDistrictName]
		, [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId], [PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone]
		, [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo], [RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo]
		, [RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo], @ModifiedDataType,getdate(),@PaymentModule FROM Msme WHERE ZedId in
		(select zedid from MsmeBasicInformation where UdyogAadharNo=@UdyamNumber)

		IF @ModifiedDataType='EnterpriseType'
		BEGIN
			Update Msme set OldEnterpriseType=EnterpriseType where ZedId in (select zedid from MsmeBasicInformation where UdyogAadharNo=@UdyamNumber) 
			AND (OldEnterpriseType IS NULL OR OldEnterpriseType != EnterpriseType)

			-- 2. Update Consultant
			UPDATE M SET OldEnterpriseType = M.EnterpriseType FROM ZED_CONSULTANT.dbo.Msme M INNER JOIN ZED_CONSULTANT.dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
			WHERE B.UdyogAadharNo = @UdyamNumber  AND (M.OldEnterpriseType IS NULL OR M.OldEnterpriseType != M.EnterpriseType)

			-- 3. Update Surveillance
			UPDATE M SET OldEnterpriseType = M.EnterpriseType FROM ZED_SURVEILLANCE.dbo.Msme M	INNER JOIN ZED_SURVEILLANCE.dbo.MsmeBasicInformation B ON M.ZedId = B.ZedId
			WHERE B.UdyogAadharNo = @UdyamNumber AND (M.OldEnterpriseType IS NULL OR M.OldEnterpriseType != M.EnterpriseType)

		END


		INSERT INTO MsmeBasicInformationUpdatedRecords([Id], [MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory], [SocialCategoryName], [Gender]
		, [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName], [LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName]
		, [EnterpriseType], [EnterpriseTypee], [CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId], [LastestCertification], UpdatedData, ReCertification)

		SELECT [Id], [MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory], [SocialCategoryName], [Gender]
		, [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName], [LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName]
		, [EnterpriseType], [EnterpriseTypee], [CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId], [LastestCertification],'EnterpriseType',ReCertification
		FROM MsmeBasicInformation where UdyogAadharNo=@UdyamNumber



	--IF @UdyamNumber IN ('<redacted>','<redacted>','<redacted>')
	IF @ModifiedDataType='EnterpriseType'
	BEGIN
		UPDATE M SET EnterpriseType=@EnterpriseType, EnterpriseTypee=@EnterpriseType from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo=@UdyamNumber
		UPDATE B SET EnterpriseTypee=@EnterpriseType from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo=@UdyamNumber

		UPDATE M SET EnterpriseType=@EnterpriseType, EnterpriseTypee=@EnterpriseType from ZED_CONSULTANT.dbo.Msme M inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo=@UdyamNumber
		UPDATE B SET EnterpriseTypee=@EnterpriseType from ZED_CONSULTANT.dbo.Msme M inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo=@UdyamNumber

		UPDATE M SET EnterpriseType=@EnterpriseType, EnterpriseTypee=@EnterpriseType from ZED_SURVEILLANCE.dbo.Msme M inner join ZED_SURVEILLANCE.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo=@UdyamNumber
		UPDATE B SET EnterpriseTypee=@EnterpriseType from ZED_SURVEILLANCE.dbo.Msme M inner join ZED_SURVEILLANCE.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo=@UdyamNumber
	END

	ELSE IF @ModifiedDataType='Activity' AND @ZedId is not null
	BEGIN
		UPDATE Msme SET
		Activity=@Activity,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity),
		ActivityDetailId=@ActivityDetailId
		WHERE ZedId=@ZedId

		UPDATE ZED_SURVEILLANCE.dbo.Msme SET
		Activity=@Activity,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity),
		ActivityDetailId=@ActivityDetailId
		WHERE ZedId=@ZedId

		UPDATE ZED_CONSULTANT.dbo.Msme SET
		Activity=@Activity,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity),
		ActivityDetailId=@ActivityDetailId
		WHERE ZedId=@ZedId

		UPDATE ZED_IMPACT_ASSESSMENT.dbo.Msme SET
		Activity=@Activity,
		TwoDigitActivity=ISNULL(@TwoDigitActivity,TwoDigitActivity),
		FourDigitActivity=ISNULL(@FourDigitActivity,FourDigitActivity),
		FiveDigitActivity=ISNULL(@FiveDigitActivity,FiveDigitActivity),
		ActivityDetailId=@ActivityDetailId
		WHERE ZedId=@ZedId
	END


	
	--SELECT @Status StatusCode, @Message StatusMessage


END

