-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_VALIDATE_GSTIN] --'<redacted>', '<redacted>'
(
    @ZedId VARCHAR(50) = NULL,
    @CertificationType VARCHAR(50) = NULL,
    @GSTIN VARCHAR(50) = NULL,
    @Status BIT = NULL,
    @Message VARCHAR(2000) = NULL,
    @NameOfCompany VARCHAR(500) = NULL,
    @StatusOfCompany VARCHAR(500) = NULL,
    @StateOfCompany VARCHAR(500) = NULL,
    @TradeName VARCHAR(500) = NULL,
    @CompanyStatus VARCHAR(500) = NULL,
    @HouseNumber VARCHAR(500) = NULL,
    @Street VARCHAR(500) = NULL,
    @District VARCHAR(500) = NULL,
    @City VARCHAR(500) = NULL,
    @State VARCHAR(500) = NULL,
    @Pincode VARCHAR(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @EnterpriseName VARCHAR(500), @EnterpriseState VARCHAR(500)

	--IF EXISTS (select * from MsmeBasicInformation where ZedId=@ZedId and UdyogAadharNo in ('<redacted>','<redacted>','<redacted>','<redacted>'))
	BEGIN
			IF @Status = 1
		BEGIN

			SELECT TOP 1 @EnterpriseName=EnterpriseName, @EnterpriseState=PStateName FROM Msme WHERE ZedId=@ZedId

			WHILE CHARINDEX('  ', @EnterpriseName) > 0
			SET @EnterpriseName = REPLACE(@EnterpriseName, '  ', ' ')

			WHILE CHARINDEX('  ', @NameOfCompany) > 0
			SET @NameOfCompany = REPLACE(@NameOfCompany, '  ', ' ')


		 --IF (LTRIM(RTRIM(@EnterpriseName))=LTRIM(RTRIM(@NameOfCompany)) AND LTRIM(RTRIM(@EnterpriseState))=LTRIM(RTRIM(@State)))
		 --IF (LTRIM(RTRIM(@EnterpriseState))=LTRIM(RTRIM(@State)))
		 IF (((LTRIM(RTRIM(@EnterpriseState)) = LTRIM(RTRIM(@State))) OR (LEFT(@GSTIN, 2) = '26' AND @EnterpriseState LIKE '%DAMAN%')))
			BEGIN
				SET @Message = 'Your Unit Details are Matched';
				INSERT INTO GstDetails (ZedId,CertificationType,GSTIN,Status,Message,NameOfCompany,StatusOfCompany,StateOfCompany,TradeName,CompanyStatus,HouseNumber,Street,District,City,State,Pincode) 
				VALUES (@ZedId,@CertificationType,@GSTIN,@Status,@Message,@NameOfCompany,@StatusOfCompany,@StateOfCompany,@TradeName,@CompanyStatus,@HouseNumber,@Street,@District,@City,@State,@Pincode)

				SELECT 1 StatusCode, @Message StatusMessage
			END
			ELSE
			BEGIN
				SET @Message = 'Your Unit Details are not Matched';
				INSERT INTO GstDetails (ZedId,CertificationType,GSTIN,Status,Message,NameOfCompany,StatusOfCompany,StateOfCompany,TradeName,CompanyStatus,HouseNumber,Street,District,City,State,Pincode) 
				VALUES (@ZedId,@CertificationType,@GSTIN,@Status,@Message,@NameOfCompany,@StatusOfCompany,@StateOfCompany,@TradeName,@CompanyStatus,@HouseNumber,@Street,@District,@City,@State,@Pincode)

				SELECT 0 StatusCode, @Message StatusMessage
            
			END
		END

		ELSE
		BEGIN
				INSERT INTO GstDetails (ZedId,CertificationType,GSTIN,Status,Message,NameOfCompany,StatusOfCompany,StateOfCompany,TradeName,CompanyStatus,HouseNumber,Street,District,City,State,Pincode) 
				VALUES (@ZedId,@CertificationType,@GSTIN,@Status,@Message,@NameOfCompany,@StatusOfCompany,@StateOfCompany,@TradeName,@CompanyStatus,@HouseNumber,@Street,@District,@City,@State,@Pincode)

				SELECT 0 StatusCode, @Message StatusMessage
		END
	END

	--ELSE
	--BEGIN
	--	SELECT 1 StatusCode, '' StatusMessage
	--END


	

END

