-- =============================================
-- Author:      <Your Name>
-- Create date: <Current Date>
-- Description: Validate GSTIN using new Protean API parameters
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_VALIDATE_GSTIN_PROTEAN] 
(
    @ZedId VARCHAR(50) = NULL,
    @CertificationType VARCHAR(50) = NULL,
    @GSTIN VARCHAR(50) = NULL,
    @Status VARCHAR(2) = NULL,
    @Reason VARCHAR(2000) = NULL,
    @ErrorCode VARCHAR(100) = NULL,
    @RegistrationDate VARCHAR(50) = NULL,
    @TypeOfCompany VARCHAR(200) = NULL,
    @StatusOfCompany VARCHAR(100) = NULL,
    @NameOfCompany VARCHAR(500) = NULL,
    @StateOfCompany VARCHAR(200) = NULL,
    @CentreJurisdiction VARCHAR(500) = NULL,
    @NatureOfBusinessActivity VARCHAR(1000) = NULL,
    @DateOfCancellation VARCHAR(50) = NULL,
    @LastUpdatedDate VARCHAR(50) = NULL,
    @StateJurisdictionCode VARCHAR(200) = NULL,
    @CentreJurisdictionCode VARCHAR(200) = NULL,
    @TradeName VARCHAR(500) = NULL,
    @TaxpayerType VARCHAR(100) = NULL,
    @NatureOfPrincPlaceBusiness VARCHAR(1000) = NULL,
    @BuildingName VARCHAR(500) = NULL,
    @FloorName VARCHAR(500) = NULL,
    @DoorNum VARCHAR(200) = NULL,
    @Street VARCHAR(500) = NULL,
    @Loc VARCHAR(500) = NULL,
    @StateName VARCHAR(200) = NULL,
    @PinCode VARCHAR(20) = NULL,
    @AdditionalBuildingName VARCHAR(500) = NULL,
    @AdditionalFloorName VARCHAR(500) = NULL,
    @AdditionalDoorNum VARCHAR(200) = NULL,
    @AdditionalStreet VARCHAR(500) = NULL,
    @AdditionalLoc VARCHAR(500) = NULL,
    @AdditionalState VARCHAR(200) = NULL,
    @AdditionalPin VARCHAR(20) = NULL,
	@ResponseJson nvarchar(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EnterpriseName VARCHAR(500), @EnterpriseState VARCHAR(500)
    DECLARE @ValidationMessage VARCHAR(2000) = @Reason

	

    BEGIN
        -- Assuming '<redacted>' means valid/active in the new Protean Status field. 
        -- If it returns '<redacted>' or '<redacted>', change this condition to: IF @Status IN ('<redacted>', '<redacted>', '<redacted>')
        IF @Status = 'S' AND (@Reason IS NULL OR LTRIM(RTRIM(@Reason)) = '')
        BEGIN


			SELECT TOP 1 @StateName=StateName FROM GstStateNames WHERE StateCode=(LEFT(@GSTIN, 2))
            SELECT TOP 1 @EnterpriseName=EnterpriseName, @EnterpriseState=PStateName FROM Msme WHERE ZedId=@ZedId	

            WHILE CHARINDEX('  ', @EnterpriseName) > 0
                SET @EnterpriseName = REPLACE(@EnterpriseName, '  ', ' ')

            WHILE CHARINDEX('  ', @NameOfCompany) > 0
                SET @NameOfCompany = REPLACE(@NameOfCompany, '  ', ' ')


            -- Replaced @State with @StateName from Protean params
            IF (((LTRIM(RTRIM(@EnterpriseState)) = LTRIM(RTRIM(@StateName))) ))
            BEGIN
                SET @ValidationMessage = 'Your Unit Details are Matched';
                
                INSERT INTO GstDetails_Protean (
                    ZedId, CertificationType, GSTIN, Status, Reason, ErrorCode, RegistrationDate, TypeOfCompany, StatusOfCompany, NameOfCompany, 
                    StateOfCompany, CentreJurisdiction, NatureOfBusinessActivity, DateOfCancellation, LastUpdatedDate, StateJurisdictionCode, 
                    CentreJurisdictionCode, TradeName, TaxpayerType, NatureOfPrincPlaceBusiness, BuildingName, FloorName, DoorNum, Street, 
                    Loc, StateName, PinCode, AdditionalBuildingName, AdditionalFloorName, AdditionalDoorNum, AdditionalStreet, AdditionalLoc, 
                    AdditionalState, AdditionalPin, ValidationMessage, ResponseJson
                ) 
                VALUES (
                    @ZedId, @CertificationType, @GSTIN, @Status, @Reason, @ErrorCode, @RegistrationDate, @TypeOfCompany, @StatusOfCompany, @NameOfCompany, 
                    @StateOfCompany, @CentreJurisdiction, @NatureOfBusinessActivity, @DateOfCancellation, @LastUpdatedDate, @StateJurisdictionCode, 
                    @CentreJurisdictionCode, @TradeName, @TaxpayerType, @NatureOfPrincPlaceBusiness, @BuildingName, @FloorName, @DoorNum, @Street, 
                    @Loc, @StateName, @PinCode, @AdditionalBuildingName, @AdditionalFloorName, @AdditionalDoorNum, @AdditionalStreet, @AdditionalLoc, 
                    @AdditionalState, @AdditionalPin, @ValidationMessage, @ResponseJson
                )

                SELECT 1 StatusCode, @ValidationMessage StatusMessage
            END
            ELSE
            BEGIN
                SET @ValidationMessage = 'Your Unit Details are not Matched';
                
                INSERT INTO GstDetails_Protean (
                    ZedId, CertificationType, GSTIN, Status, Reason, ErrorCode, RegistrationDate, TypeOfCompany, StatusOfCompany, NameOfCompany, 
                    StateOfCompany, CentreJurisdiction, NatureOfBusinessActivity, DateOfCancellation, LastUpdatedDate, StateJurisdictionCode, 
                    CentreJurisdictionCode, TradeName, TaxpayerType, NatureOfPrincPlaceBusiness, BuildingName, FloorName, DoorNum, Street, 
                    Loc, StateName, PinCode, AdditionalBuildingName, AdditionalFloorName, AdditionalDoorNum, AdditionalStreet, AdditionalLoc, 
                    AdditionalState, AdditionalPin, ValidationMessage
                ) 
                VALUES (
                    @ZedId, @CertificationType, @GSTIN, @Status, @Reason, @ErrorCode, @RegistrationDate, @TypeOfCompany, @StatusOfCompany, @NameOfCompany, 
                    @StateOfCompany, @CentreJurisdiction, @NatureOfBusinessActivity, @DateOfCancellation, @LastUpdatedDate, @StateJurisdictionCode, 
                    @CentreJurisdictionCode, @TradeName, @TaxpayerType, @NatureOfPrincPlaceBusiness, @BuildingName, @FloorName, @DoorNum, @Street, 
                    @Loc, @StateName, @PinCode, @AdditionalBuildingName, @AdditionalFloorName, @AdditionalDoorNum, @AdditionalStreet, @AdditionalLoc, 
                    @AdditionalState, @AdditionalPin, @ValidationMessage
                )

                SELECT 0 StatusCode, @ValidationMessage StatusMessage
            END
        END
        ELSE
        BEGIN
            -- Fallback message if Reason is empty
            SET @ValidationMessage = ISNULL(NULLIF(@Reason, ''), 'GSTIN Validation Failed or Inactive');

            INSERT INTO GstDetails_Protean (
                ZedId, CertificationType, GSTIN, Status, Reason, ErrorCode, RegistrationDate, TypeOfCompany, StatusOfCompany, NameOfCompany, 
                StateOfCompany, CentreJurisdiction, NatureOfBusinessActivity, DateOfCancellation, LastUpdatedDate, StateJurisdictionCode, 
                CentreJurisdictionCode, TradeName, TaxpayerType, NatureOfPrincPlaceBusiness, BuildingName, FloorName, DoorNum, Street, 
                Loc, StateName, PinCode, AdditionalBuildingName, AdditionalFloorName, AdditionalDoorNum, AdditionalStreet, AdditionalLoc, 
                AdditionalState, AdditionalPin, ValidationMessage
            ) 
            VALUES (
                @ZedId, @CertificationType, @GSTIN, @Status, @Reason, @ErrorCode, @RegistrationDate, @TypeOfCompany, @StatusOfCompany, @NameOfCompany, 
                @StateOfCompany, @CentreJurisdiction, @NatureOfBusinessActivity, @DateOfCancellation, @LastUpdatedDate, @StateJurisdictionCode, 
                @CentreJurisdictionCode, @TradeName, @TaxpayerType, @NatureOfPrincPlaceBusiness, @BuildingName, @FloorName, @DoorNum, @Street, 
                @Loc, @StateName, @PinCode, @AdditionalBuildingName, @AdditionalFloorName, @AdditionalDoorNum, @AdditionalStreet, @AdditionalLoc, 
                @AdditionalState, @AdditionalPin, @ValidationMessage
            )

            SELECT 0 StatusCode, @ValidationMessage StatusMessage
        END
    END
END
