/****** Object:  StoredProcedure [dbo].[SP_MSME_VALIDATE_UDYAM_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_VALIDATE_UDYAM_DETAILS] --'<redacted>', '<redacted>',NULL,NULL,'<redacted>'
(
	@UdyogAadharNo varchar(50) = NULL,
	@PlantIdNo varchar(50) = NULL,
	@TwoDigitActivity varchar(200) = NULL,
	@IpAddress varchar(200) = NULL,
	@EmailId varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT * FROM MsmeBasicInformation B inner join Msme M on (B.ZedId=M.ZedId) Where UdyogAadharNo=@UdyogAadharNo AND PlantIdNo=@PlantIdNo --and 1=2

	SELECT * FROM Sectors WHERE @TwoDigitActivity like SectorCode+'%'

	----- to check the email id counter
	--IF @EmailId IS NOT NULL AND ( SELECT COUNT(*) FROM Msme where EmailId=@EmailId) >= 5
	--BEGIN
	--	SELECT 1 EmailCountStatus, '<redacted>' ErrorMessage
	--END
	--ELSE
	--BEGIN
	--	SELECT 0 EmailCountStatus, '' ErrorMessage
	--END
	   	 

	--- To check the email id across various roles
		IF @EmailId IS NULL OR @EmailId = ''
		BEGIN
			SELECT 1 AS EmailCountStatus, 'Invalid Email' AS ErrorMessage
		END

		-- 1. Check in Users table (Local)
		ELSE IF EXISTS (SELECT 1 FROM Users WHERE Email = @EmailId AND RoleId != 5)
		BEGIN
			SELECT 1 AS EmailCountStatus, 'Email ID already registered as Assessor.' AS ErrorMessage
		END
		-- 2. Check in Zed Consultant Database
		ELSE IF EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.users WHERE Email = @EmailId AND RoleId != 5)
		BEGIN
			SELECT 1 AS EmailCountStatus, 'Email ID already registered as Consultant.' AS ErrorMessage
		END
		-- 3. Check in Training Program
		ELSE IF EXISTS (SELECT 1 FROM ZED_CENTER_AUDIT_V2.dbo.candidates WHERE EmailId = @EmailId)
		BEGIN
			SELECT 1 AS EmailCountStatus, 'Email ID already registered in Training Program.' AS ErrorMessage
		END
		-- 4. Check in Professional Training Program
		ELSE IF EXISTS (SELECT 1 FROM ZED_CENTER_AUDIT_PROFESSIONAL.dbo.candidates WHERE EmailId = @EmailId )
		BEGIN
			SELECT 1 AS EmailCountStatus, 'Email ID already registered in Professional Training Program.' AS ErrorMessage
		END
		-- 5. Existing MSME count check (Max 5)
		ELSE IF (SELECT COUNT(*) FROM Msme WHERE EmailId = @EmailId) >= 5
		BEGIN
			SELECT 1 AS EmailCountStatus, 'This Email Id is already registered' AS ErrorMessage
		END
		-- If none of the above, email is valid
		ELSE
		BEGIN
			SELECT 0 AS EmailCountStatus, '' AS ErrorMessage
		END
	

END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_ZERO_PAYMENT_DETAILS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
