-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_ZERO_PAYMENT_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL
)
AS
BEGIN

	IF @Gstin='Yes' 
	BEGIN
		SET @Gstin=@UnitGstin
		SET @UnitGstin='Yes'
	END

	IF @Gstin='No'
	BEGIN
		SET @Gstin=NULL
		SET @UnitGstin='No'
	END

	DECLARE @UdyamNo VARCHAR(50) =NULL
	DECLARE @StateCode VARCHAR(50) =NULL
	DECLARE @IsRecertification int = 0
	DECLARE @ReCertificationLevel VARCHAR(50) = ''

	select @StateCode=StateCode from Districts where DistrictCode in (select PLgDistrictCode from Msme where ZedId=@ZedId)
	SELECT @UdyamNo=UdyogAadharNo,@IsRecertification=Recertification,@ReCertificationLevel=ReCertificationLevel FROM MsmeBasicInformation WHERE ZedId=@ZedId 


	IF NOT EXISTS (select * from Msme where ZedId=@ZedId and ((@Certification='Bronze' and IsBronzePaymentDone=1) OR (@Certification='Silver' and IsSilverPaymentDone=1) OR (@Certification='Gold' and IsGoldPaymentDone=1)))
	BEGIN

		IF @Certification = 'Bronze'
			UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
		ELSE IF @Certification = 'Silver'
			UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
		ELSE IF @Certification = 'Gold'
			UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId

	
		IF @UseCoupon = 'Yes'
		BEGIN
			UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

			IF @Certification='Bronze'
				BEGIN
					UPDATE Msme SET SurCouponAmount=2000 WHERE ZEDId = @ZedId
				END
		END
			

		IF @StateCode=28 AND (@IsRecertification = 0 OR (@IsRecertification = 1 AND @ReCertificationLevel!=@Certification)) and @Certification in ('Silver','Gold') AND NOT EXISTS (SELECT 1 FROM MsmeCertifications WHERE ZedId LIKE CONCAT(@ZedId, '[_]D%') AND Certification = @Certification)
		--IF @UdyamNo='<redacted>' and @Certification in ('<redacted>','<redacted>')
		BEGIN
			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
				[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage],
				PaymentVersion,StateContributionAfterSubsidy,StateSubsidyPercentage
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, 
				@PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
				[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage],
				'V2',StateContributionAfterSubsidy,StateSubsidyPercentage
			FROM StateAssessmentFee 
			WHERE Id=@PaymentRefId
		END

		ELSE
		BEGIN
			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
			[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
			[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage], PaymentVersion
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, 
				@PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
				[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage], 'V2'
			FROM AssessmentFee 
			WHERE Id=@PaymentRefId
		END

		

		--INSERT INTO MsmeCertifications ([ZedId], [Certification])
		--SELECT @ZedId, @Certification

		Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Payment of Rs. 0 successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')


			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM Sections WHERE SectionType=@Certification ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType FROM Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
			SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode


			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)
	END

	ELSE
	BEGIN
	UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END

END
GO
