/****** Object:  StoredProcedure [dbo].[Sp_Process_Missed_ERP_Issues]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Sp_Process_Missed_ERP_Issues]
AS
BEGIN
    SET NOCOUNT ON;

    -- =========================================================================
    -- STEP 1: పర్మనెంట్ మ్యాపింగ్ టేబుల్ (dbo.InvoiceMapping) రీసెట్
    -- =========================================================================
    PRINT 'Step 1: Resetting InvoiceMapping table...';
    
    IF OBJECT_ID('dbo.InvoiceMapping') IS NOT NULL 
        DROP TABLE dbo.InvoiceMapping;

    CREATE TABLE dbo.InvoiceMapping (
        MappingId INT IDENTITY(1,1) PRIMARY KEY,
        ZedId VARCHAR(50),
        UTR_No VARCHAR(100),
        SheetName VARCHAR(100),
        ErpInvoiceNo VARCHAR(100),
        DetectedModule VARCHAR(50),
        MileStoneNo INT NULL,           -- కన్సల్టెన్సీ కి మాత్రమే వస్తుంది, మిగతా వాటికి NULL
        Certification VARCHAR(50),      
        ImportedDate DATETIME DEFAULT GETDATE()
    );

    -- =========================================================================
    -- STEP 2: Tracking ID దొరికిన టేబుల్ ఆధారంగా మోడ్యూల్ & మైల్‌స్టోన్ లాగడం
    -- =========================================================================
    PRINT 'Step 2: Fetching Module and Milestone dynamically based on Tracking ID...';

    INSERT INTO dbo.InvoiceMapping (ZedId, UTR_No, SheetName, ErpInvoiceNo, DetectedModule, MileStoneNo, Certification)
    SELECT DISTINCT
        m.[Invoice Reference No] AS ZedId,
        CAST(m.[CCAvenue Ref Number] AS VARCHAR(100)) AS UTR_No,
        m.SheetName,
        -- ERP ఇన్వాయిస్ నంబర్ (ఉంటే వస్తుంది, లేదంటే NULL ఉంటుంది)
        COALESCE(zed.TaDaInvoiceNo, con.TaDaInvoiceNo, sur.TaDaInvoiceNo) AS ErpInvoiceNo,
        
        -- పక్కా మోడ్యూల్ డిటెక్షన్ (ఏ టేబుల్ లో ట్రాకింగ్ ఐడి దొరికితే ఆ మోడ్యూల్)
        CASE 
            WHEN ztx.TrackingId IS NOT NULL THEN 'ZED'
            WHEN ctx.TrackingId IS NOT NULL THEN 'CONSULTANCY'
            WHEN stx.TrackingId IS NOT NULL THEN 'SURVEILLANCE'
            ELSE 'UNKNOWN'
        END AS DetectedModule,
        
        -- మీ ఐడియా ప్రకారం: కేవలం కన్సల్టెన్సీ టేబుల్ (ctx) లో దొరికితేనే మైల్‌స్టోన్ నంబర్, మిగతా వాటికి NULL
        CASE 
            WHEN ctx.TrackingId IS NOT NULL THEN ctx.milestonenumber
            ELSE NULL 
        END AS MileStoneNo,
        
        -- సర్టిఫికేషన్ లెవెల్ కూడా డైనమిక్
        COALESCE(ztx.certification, ctx.certification, stx.certification) AS Certification
    FROM MissedERP_2507 m
    -- 1. ZED Main Database Link
    LEFT JOIN ZEDCS_V2_LIVE.dbo.PaymentGateWayTransactions ztx 
        ON CAST(m.[CCAvenue Ref Number] AS VARCHAR(100)) = CAST(ztx.TrackingId AS VARCHAR(100))
    LEFT JOIN ZEDCS_V2_LIVE.dbo.msmepaymentinfo zed 
         ON ztx.zedid = zed.zedid AND ztx.certification = zed.certification AND ztx.paymentrefid = zed.paymentrefid

    -- 2. Consultant Database Link (నేరుగా ఇక్కడి నుంచే మైల్‌స్టోన్ వస్తుంది)
    LEFT JOIN ZED_consultant.dbo.PaymentGateWayTransactions ctx 
        ON CAST(m.[CCAvenue Ref Number] AS VARCHAR(100)) = CAST(ctx.TrackingId AS VARCHAR(100))
    LEFT JOIN ZED_consultant.dbo.msmepaymentinfo con 
         ON ctx.zedid = con.zedid AND ctx.certification = con.certification AND ctx.paymentrefid = con.paymentrefid AND ctx.milestonenumber = con.milestonenum

    -- 3. Surveillance Database Link
    LEFT JOIN zed_surveillance.dbo.PaymentGateWayTransactions stx 
        ON CAST(m.[CCAvenue Ref Number] AS VARCHAR(100)) = CAST(stx.TrackingId AS VARCHAR(100))
    LEFT JOIN zed_surveillance.dbo.msmepaymentinfo sur 
        ON stx.zedid = sur.zedid AND stx.certification = sur.certification AND stx.paymentrefid = sur.paymentrefid
		ORDER BY ZEDID;

   -- =========================================================================
    -- STEP 3 (మీ ఐడియా ప్రకారం): ముందుగా Errors టేబుల్లోకి రీ-పుష్ డేటా నెట్టడం
    -- =========================================================================
    PRINT 'Step 3: Pushing new records to ApiFinanceUnitDetailsResponseErrors first...';

    -- A. Sheet 1: ఇన్వాయిస్ & రిసిప్ట్ రెండూ పుష్ చేయాలి
    INSERT INTO ApiFinanceUnitDetailsResponseErrors 
        (ZedId, ApiType, Certification, ModuleName, MileStoneNo, VersionNo, ProcessDate)
    SELECT DISTINCT 
        ZedId, 'InvoiceData', Certification, DetectedModule, CASE WHEN DetectedModule = 'CONSULTANCY' THEN MileStoneNo ELSE NULL END, 'V2', CONVERT(VARCHAR(10), GETDATE(), 23)
    FROM dbo.InvoiceMapping WHERE SheetName = 'import_receipt+invoice_issue'
    UNION ALL
    SELECT DISTINCT 
        ZedId, 'ReceiptData', Certification, DetectedModule, CASE WHEN DetectedModule = 'CONSULTANCY' THEN MileStoneNo ELSE NULL END, 'V2', CONVERT(VARCHAR(10), GETDATE(), 23)
    FROM dbo.InvoiceMapping WHERE SheetName = 'import_receipt+invoice_issue';

    -- B. Sheet 2: ఇన్వాయిస్ మాత్రమే పుష్ చేయాలి
    INSERT INTO ApiFinanceUnitDetailsResponseErrors 
        (ZedId, ApiType, Certification, ModuleName, MileStoneNo, VersionNo, ProcessDate)
    SELECT DISTINCT 
        ZedId, 'InvoiceData', Certification, DetectedModule, CASE WHEN DetectedModule = 'CONSULTANCY' THEN MileStoneNo ELSE NULL END, 'V2', CONVERT(VARCHAR(10), GETDATE(), 23)
    FROM dbo.InvoiceMapping WHERE SheetName = 'import_invoice_issue';


	 INSERT INTO ApiFinanceUnitDetailsResponseErrors 
			(ZedId, ApiType, Certification, ModuleName, VersionNo, ProcessDate)
	select Zedid, 'CustomerData', max(Certification),'ZED','V2',CONVERT(VARCHAR(10), GETDATE(), 23) 
	 FROM dbo.InvoiceMapping WHERE SheetName = 'import_customer_issue' group by ZedId;





    -- =========================================================================
    -- STEP 4 (మీ ఐడియా ప్రకారం): Errors టేబుల్ ని బేస్ చేసుకుని లాస్ట్ లో '<redacted>' అప్‌డేట్ చేయడం
    -- =========================================================================
    PRINT 'Step 4: Invalidating old records in ApiFinanceUnitDetailsResponse based on Errors table entries...';

    -- కేవలం ఈ ఒక్క క్వెరీతో రెండు షీట్ల అప్‌డేట్లూ పర్ఫెక్ట్ గా అయిపోతాయి!
    UPDATE r
    SET r.ZedId = r.ZedId + '_DEL250726'
    FROM ApiFinanceUnitDetailsResponse r
    JOIN ApiFinanceUnitDetailsResponseErrors e 
        ON r.ZedId = e.ZedId            -- క్లీన్ జెడ్ ఐడి మ్యాచ్ అవుతుంది
        AND r.ApiType = e.ApiType        -- Invoice కి Invoice, Receipt కి Receipt కరెక్ట్ గా మ్యాచ్ అవుతుంది
        AND r.ModuleName = e.ModuleName
        AND ISNULL(r.MileStoneNo, 0) = ISNULL(e.MileStoneNo, 0)
    WHERE e.ProcessDate = CONVERT(VARCHAR(10), GETDATE(), 23) -- కేవలం ఈరోజు యాడ్ చేసిన ఎర్రర్స్ ని మాత్రమే చూస్తుంది
      AND r.ZedId NOT LIKE '%_del';

    PRINT 'Process Completed Successfully with your optimized logic!';
END

GO
