		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=3 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=3 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
