		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT * FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=4

