   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=5 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT * FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=5
	END

	ELSE
	BEGIN
		SELECT Id,ZedId,Certification,ProductName,Exported,IsSaVerified IsVerified,SaAssessorRemarks AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=1
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=1 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, '' SaConformance,'' SaAssessorRemarks  FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT *FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=1
	
		SELECT Id,ZedId,Certification,ProductName,Exported,IsSaVerified IsVerified,SaAssessorRemarks AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=2
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=2 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, '' SaConformance,'' SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=2 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=2 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=2 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=2 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT *FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=2

		SELECT Id,ZedId,Certification,ProductName,Exported,IsSaVerified IsVerified,SaAssessorRemarks AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=3
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=3 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, '' SaConformance, '' SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=3 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=3 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=3 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=3 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT *FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=3

		SELECT Id,ZedId,Certification,ProductName,Exported,IsSaVerified IsVerified,SaAssessorRemarks AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=4
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=4 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, '' SaConformance,'' SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=4 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT * FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=4

		SELECT Id,ZedId,Certification,ProductName,Exported,IsSaVerified IsVerified,SaAssessorRemarks AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=5
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=5 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, '' SaConformance,'' SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=5 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT * FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=5
	END


	SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
	SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
	SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
	SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification

	SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Opening Meeting Photo.jpg') as PhotoPath, name  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification	
	SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Close Meeting Photo.jpg') as PhotoPath, name  FROM SaPhotos WHERE Name in ('Close Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification	
	SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') as PhotoPath, name  FROM SaPhotos WHERE PhotoType in ('SiteTour') AND ZedId=@ZedId AND Certification=@Certification

END


