-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_RESET_DOCUMENT_UPLOAD]  --'<redacted>', '<redacted>'
(	
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
	
)
AS
BEGIN

	SET NOCOUNT ON;


	UPDATE MsmeCertifications SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmeProducts SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmePhotos SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmeSections SET IsAssessmentExcempted = NULL, UpdatedDate=null,AssessorId=null WHERE ZedId = @ZedId AND SectionType = @Certification

	UPDATE MsmeEvidences SET SyncedDate = NULL, DocumentOpenedTime=null WHERE ZedId = @ZedId AND SectionType = @Certification

	UPDATE MsmeRequirements SET Conformance = NULL, AssessorRemarks=null,UpdatedDate=null,OpenedFlag=null WHERE ZedId = @ZedId AND SectionType = @Certification

	UPDATE msmehistory SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND CertificationType = @Certification and statustype!='ApplicationReceived'

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('RESET THIS ID ON REQUEST OF QCI ON ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@Certification,'RESET DONE ON QCI REQUEST')
				




END

