-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_RESET_DOCUMENT_UPLOAD_PAYMENT_RESET] 
(	
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
	
)
AS
BEGIN

	SET NOCOUNT ON;

	UPDATE MsmeSections SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeRequirements SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeOptions SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeSubOptions SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeEvidences SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification


	UPDATE MsmeCertifications SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmePhotos SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmePaymentInfo SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	UPDATE PaymentGateWayTransactions SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE AssessorComments SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	UPDATE ScreenshotPhotos SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	UPDATE MsmeProducts SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	--New Added table--
	UPDATE MsmeHistory SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND CertificationType = @Certification


	UPDATE Msme
	SET 
		IsGoldPaymentDone   = CASE WHEN @Certification = 'Gold' THEN NULL ELSE IsGoldPaymentDone END,
		IsSilverPaymentDone = CASE WHEN @Certification = 'Silver' THEN NULL ELSE IsSilverPaymentDone END,
		IsBronzePaymentDone = CASE WHEN @Certification = 'Bronze' THEN NULL ELSE IsBronzePaymentDone END
	WHERE ZedId = @ZedId

	INSERT INTO MsmeHistory(ZedId, Descrip, CreatedDate, CertificationType)
	VALUES (@ZedId, 'Reset  Payment  on the request of QCI', GETDATE(), @Certification)

END

