/****** Object:  StoredProcedure [dbo].[SP_RESET_FOR_RE_CERTIFICATION]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_RESET_FOR_RE_CERTIFICATION] 
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN		
				

		BEGIN TRY

				BEGIN TRAN

				DECLARE @CertId VARCHAR(20);

				SELECT TOP 1 @CertId = CAST(Id AS VARCHAR(20))
				FROM MsmeCertifications WITH (NOLOCK)
				WHERE ZedId = @ZedId 
				  AND Certification = @CertificationType
				ORDER BY Id DESC;

				update SaRequirementPhotos set ZedId=concat(ZedId,'_R_',SaReqCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeCertifications set ZedId=concat(ZedId,'_R_',Id) where ZedId=@ZedId and Certification=@CertificationType
				update SaRawMaterials set ZedId=concat(ZedId,'_R_',SaRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update AssessorComments set ZedId=concat(ZedId,'_R_',AsCmtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeLocations set ZedId=concat(ZedId,'_R_',MsmeLocCertId) where ZedId=@ZedId and Certification=@CertificationType
				update ScreenshotPhotos set ZedId=concat(ZedId,'_R_',SrnCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeRawMaterials set ZedId=concat(ZedId,'_R_',MsmeRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update PaymentGateWayTransactions set ZedId=concat(ZedId,'_R_',PmtGtCertId) where ZedId=@ZedId and Certification=@CertificationType and GwReClassification=1 
				update MsmePaymentInfo set ZedId=concat(ZedId,'_R_',MsmePmtCertId) where ZedId=@ZedId and Certification=@CertificationType and ReClassification=1 
				update MsmeSections set ZedId=concat(ZedId,'_R_',SecCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeRequirements set ZedId=concat(ZedId,'_R_',ReqCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeOptions set ZedId=concat(ZedId,'_R_',OptCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeSubOptions set ZedId=concat(ZedId,'_R_',SubCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeEvidences set ZedId=concat(ZedId,'_R_',EviCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmePhotos set ZedId=concat(ZedId,'_R_',MsPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeProducts set ZedId=concat(ZedId,'_R_',MsPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaPhotos set ZedId=concat(ZedId,'_R_',SaPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaProducts set ZedId=concat(ZedId,'_R_',SaPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeSelfies set ZedId=concat(ZedId,'_R_',MsSelfCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeHistory set ZedId=concat(ZedId,'_R_',MsHistCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update MeetingParticipants set ZedId=concat(ZedId,'_R_',MeetPartCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update Meetings set ZedId=concat(ZedId,'_R_',MeetCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update EsgCheckList set ZedId=concat(ZedId,'_R_',EsgCertId) where ZedId=@ZedId and Certification=@CertificationType


				IF @CertId IS NOT NULL
				BEGIN
					UPDATE ApiFinanceUnitDetailsResponse 
					SET ZedId = CONCAT(ZedId, '_R_', @CertId) 
					WHERE ZedId = @ZedId 
					  AND Certification = @CertificationType 
					  AND ModuleName='ZED'
					  AND ApiType IN ('InvoiceData', 'ReceiptData') 
					  ;

					UPDATE ApiFinanceUnitDetailsResponseErrors 
					SET ZedId = CONCAT(ZedId, '_R_', @CertId) 
					WHERE ZedId = @ZedId 
					  AND Certification = @CertificationType 
					  AND ModuleName='ZED'
					  AND ApiType IN ('InvoiceData', 'ReceiptData') 
					  ;
				END




				--UPDATE MsmeCertifications SET CertificationStatusDate=getdate(),CertificationStatus=101 where  ZedId=@ZedId and Certification=@CertificationType
				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Unit data of ', @CertificationType,' is reset for Re-Certification On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Unit data reset for Recertification')
				

			COMMIT TRAN
		END TRY


		BEGIN CATCH

             ROLLBACK TRAN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		END CATCH

END


GO
/****** Object:  StoredProcedure [dbo].[SP_SA_APP_CHECK_STATUS]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_CHECK_STATUS] --'<redacted>', '<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@AssessorId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @LeadAssessor varchar(50) = NULL,
			@CoAssessor   varchar(50) = NULL,
			@True bit = 1,
			@False bit = 0

			SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	SELECT 
		1 SaStatus,
		CASE WHEN 
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='Open Meeting')>0 THEN @True ELSE @False end as OpenMeetingSubmitted, 

		CASE WHEN
		(select  count(*) from MsmeRequirements E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and S.NcCount=E.NcCount and E.NcCount=0 and S.SectionType=E.SectionType)
		left join SaRequirementPhotos P on (E.Id=P.RequirementId and E.ZedId=P.ZedId and E.NcCount=P.NcCount and E.NcCount=0 and P.Certification=E.SectionType)
		where AssessorId=@LeadAssessor and E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='No' OR IsAssessmentExcempted IS NULL) 
		and ((E.SaConformance='Yes' and P.RequirementId is null) OR E.SaConformance IS NULL))=0 THEN @True ELSE @False end as AllParametersSyncedByLead,

		CASE WHEN
		(select  count(*) from MsmeRequirements E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and S.NcCount=E.NcCount and E.NcCount=0 and S.SectionType=E.SectionType)
		left join SaRequirementPhotos P on (E.Id=P.RequirementId and E.ZedId=P.ZedId and E.NcCount=P.NcCount and E.NcCount=0 and P.Certification=E.SectionType) 
		where AssessorId=@CoAssessor and E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='No' OR IsAssessmentExcempted IS NULL) 
		and ((E.SaConformance='Yes' And  P.RequirementId is null) OR E.SaConformance IS NULL))=0 THEN @True ELSE @False end as AllParametersSyncedByCo,

		CASE 
		WHEN @CoAssessor IS NULL THEN @True
		WHEN (select count(*) from MsmeSections where zedid=@ZedId and SectionType=@Certification and AssessorId=@CoAssessor)=0 then @True
		WHEN (select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@CoAssessor and MeetingType='Final Submit')>0 THEN @True ELSE @False end as FinalSubmissionDone,

		CASE WHEN
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='Close Meeting')>0 THEN @True ELSE @False end as ClosingMeetingSubmitted,

		CASE WHEN
		(SELECT count(*) FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification and SiteAssessorId=@AssessorId)>0 THEN @True ELSE @False end as LeadAssessor



	--select 1 SaStatus, 
	--	1 OpenMeetingSubmitted, 
	--	1 AllParametersSyncedByLead, 
	--	1 AllParametersSyncedByCo,
	--	1 FinalSubmissionDone, 
	--	1 ClosingMeetingSubmitted,
	--	1 LeadAssessor

	--from MsmeCertifications 
	--where ZedId=@ZedId 
	--	and Certification=@Certification
	
END






GO
/****** Object:  StoredProcedure [dbo].[SP_SA_APP_INSERT_CLOSE_MEETING]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_INSERT_CLOSE_MEETING] 
(
	@RefId                    VarChar(50)			= NULL,
	@RegistrationNumber       VarChar(200)			= NULL,
	@AssessorId               VarChar(200)			= NULL,
	@Latitude                 VarChar(200)			= NULL,
	@Longitude                VarChar(200)			= NULL,
	@Comments                 VarChar(5000)			= NULL,
	@ParticipantsList   DynamicParticipants  READONLY
)
AS
BEGIN
	      
	SET NOCOUNT ON;
	
	
	DELETE FROM Meetings where MeetingType='CLOSE' and RegistrationNumber=@RegistrationNumber

	INSERT INTO Meetings(RefId,RegistrationNumber,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType)
	values(@RefId,@RegistrationNumber,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,'CLOSE')

	DELETE FROM MeetingParticipants where MeetingType='CLOSE' and RegistrationNumber=@RegistrationNumber

	INSERT INTO MeetingParticipants (RefId,RegistrationNumber,Name,Designation,MeetingType)
	select @RefId,@RegistrationNumber,Name,Designation,'CLOSE' from @ParticipantsList

	Update SelfAssessments set SaStatus=2,SaLastSyncTime=getdate() where RegistrationNumber=@RegistrationNumber 

	
END



GO
