CREATE PROC [dbo].[SP_SA_REJECT_UNIT]
(
	@RegistrationNumber varchar(50) = NULL,
	@ReasonForRejection varchar(100) = NULL
)
AS
BEGIN

	UPDATE SelfAssessments SET ReasonForRejection=@ReasonForRejection,AcceptOrRejectDate=getdate() where  RegistrationNumber=@RegistrationNumber

	INSERT INTO SaAllotmentHistory (RegistrationNumber,SaDate, CertificationBodyUserId, AssessorUserId, FinalSaDate,AcceptOrRejectDate, ReasonForRejection, IsSaDeclarationAccepted,PaymentDate, AmountPaid, UtrNumber,CreatedDate)
	select RegistrationNumber,SaDate, CertificationBodyUserId, AssessorUserId, FinalSaDate,AcceptOrRejectDate, ReasonForRejection, IsSaDeclarationAccepted,PaymentDate, AmountPaid, UtrNumber,getdate()
	from SelfAssessments  where RegistrationNumber=@RegistrationNumber

END


