/****** Object:  StoredProcedure [dbo].[SP_SEND_MAIL_STATUS_COUNTS_AGENCY]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_SEND_MAIL_STATUS_COUNTS_AGENCY]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @columns NVARCHAR(MAX) = '', 
            @sum_columns NVARCHAR(MAX) = '',
            @sql     NVARCHAR(MAX) = '',
            @tableHTML  NVARCHAR(MAX) = '';

    -- 1. Generate columns with specific sorting
    SELECT 
        @columns += QUOTENAME(StatusLabel) + ',',
        @sum_columns += 'SUM(ISNULL(' + QUOTENAME(StatusLabel) + ', 0)) AS ' + QUOTENAME(StatusLabel) + ','
    FROM (
        SELECT DISTINCT 
            CASE 
                WHEN C.DesktopAssessorId IS NULL AND S.TrainingGetList = 'EVIDENCE UPLOAD DONE BY MSME' THEN 'NOT YET ALLOTTED'
                WHEN C.DesktopAssessorId IS NOT NULL AND S.TrainingGetList = 'EVIDENCE UPLOAD DONE BY MSME' THEN 'ASSESSOR ALLOTTED'
                ELSE S.TrainingGetList 
            END AS StatusLabel,
            CASE 
                WHEN C.DesktopAssessorId IS NULL AND S.TrainingGetList = 'EVIDENCE UPLOAD DONE BY MSME' THEN 1
                WHEN C.DesktopAssessorId IS NOT NULL AND S.TrainingGetList = 'EVIDENCE UPLOAD DONE BY MSME' THEN 2
                WHEN S.TrainingGetList = 'NC RAISED' THEN 3
                WHEN S.TrainingGetList = 'DA VERIFICATION IN PROGRESS' THEN 4
                WHEN S.TrainingGetList = 'QUALITY CHECK' THEN 5
                WHEN S.TrainingGetList = 'BRONZE CERTIFIED' THEN 6
                ELSE 99 
            END AS SortOrder
        FROM MsmeCertifications C
        INNER JOIN CertificationStatuses S ON (C.CertificationStatus = S.Descrip)
        WHERE C.certificationbodyuserid = 'ZEDAA0065'
    ) AS T
    ORDER BY SortOrder;

    -- Remove trailing commas
    SET @columns = LEFT(@columns, LEN(@columns) - 1);
    SET @sum_columns = LEFT(@sum_columns, LEN(@sum_columns) - 1);

    -- 2. Build the HTML Rows (Removed extra comma columns)
    SET @sql = '
    WITH RawData AS (
        SELECT 
            ISNULL(U.UserName, ''----------'') AS AssessorName,
            CASE 
                WHEN C.DesktopAssessorId IS NULL AND S.TrainingGetList = ''EVIDENCE UPLOAD DONE BY MSME'' THEN ''NOT YET ALLOTTED''
                WHEN C.DesktopAssessorId IS NOT NULL AND S.TrainingGetList = ''EVIDENCE UPLOAD DONE BY MSME'' THEN ''ASSESSOR ALLOTTED''
                ELSE S.TrainingGetList 
            END AS StatusLabel
        FROM MsmeCertifications C
        INNER JOIN CertificationStatuses S ON (C.CertificationStatus = S.Descrip)
        LEFT JOIN Users U ON (C.DesktopAssessorId = U.UserId)
        WHERE C.certificationbodyuserid = ''ZEDAA0065''
    ),
    PivotedData AS (
        SELECT * FROM RawData PIVOT (COUNT(StatusLabel) FOR StatusLabel IN (' + @columns + ')) AS pvt
    ),
    FinalResult AS (
        SELECT 
            CASE WHEN GROUPING(AssessorName) = 1 THEN ''GRAND TOTAL'' ELSE AssessorName END AS [ASSESSOR NAME],
            ' + @sum_columns + ',
            GROUPING(AssessorName) AS IsTotalRow
        FROM PivotedData
        GROUP BY ROLLUP(AssessorName)
    )
    SELECT @htmlOUT = CAST(( 
        SELECT 
            CASE WHEN IsTotalRow = 1 THEN ''font-weight:bold; background-color:#D9E1F2;'' ELSE '''' END AS ''@style'',
            [Assessor Name] AS ''td'', '''', 
            ' + REPLACE(@columns, ',', ' AS ''td'', '''', ') + ' AS ''td''
        FROM FinalResult 
        ORDER BY IsTotalRow ASC, [Assessor Name] ASC
        FOR XML PATH(''tr'')
    ) AS NVARCHAR(MAX))';

    EXEC sp_executesql @sql, N'@htmlOUT NVARCHAR(MAX) OUTPUT', @htmlOUT = @tableHTML OUTPUT;

    -- 3. Final HTML Formatting (Fixed Header spacing)
    SET @tableHTML = 
        N'<html><head><style>' +
        N'table { border-collapse: collapse; font-family: Calibri, sans-serif; width: 100%; border: 1px solid #ddd; }' +
        N'th { background-color: #4472C4; color: white; padding: 10px; text-align: left; border: 1px solid #ddd; }' +
        N'td { padding: 8px; border: 1px solid #ddd; text-align: center; }' +
        N'td:first-child { text-align: left; }' +
        N'tr:nth-child(even) { background-color: #f9f9f9; }' +
        N'</style></head><body>' +
        N'<h3>Daily MSME Status Report</h3>' +
        N'<table><tr><th>Assessor Name</th><th>' + 
        REPLACE(REPLACE(REPLACE(@columns, '[', ''), ']', ''), ',', '</th><th>') + N'</th></tr>' +
        ISNULL(@tableHTML, '') + 
        N'</table><p><i>Automated system report via ZedAdmin Profile.</i></p></body></html>';

    -- 4. Send the Email
    EXEC msdb.dbo.sp_send_dbmail
        @profile_name = 'ZedAdmin',  -- Using your working profile
        @recipients = 'ks@geostat.in;keerthisreenu@gmail.com', 
        @subject = 'Daily Skill Express Status Report',
        @body = @tableHTML,
        @body_format = 'HTML';
END
