-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SURVEILLANCE_MSME_GET_PAYMENT_STATUS] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;


	IF EXISTS (SELECT * FROM Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId and C.Certification=@Certification AND C.CertificationStatus=16)
	WHERE ((@Certification = 'Silver' AND IsSurSilverPaymentDone IS NULL) OR (@Certification='Gold' AND IsSurGoldPaymentDone IS NULL)) AND M.ZedId=@ZedId )

	SELECT 1 PaymentStatus

	ELSE IF EXISTS (SELECT * FROM Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId and C.Certification=@Certification AND C.CertificationStatus=6)
	WHERE ((@Certification = 'Bronze' AND IsSurBronzePaymentDone IS NULL)) AND M.ZedId=@ZedId )

		SELECT 1 PaymentStatus
	ELSE
		SELECT 0 PaymentStatus


END



GO
