CREATE PROC [dbo].[SP_SURVEILLANCE_MSME_PAYMENT_GATEWAY_DETAILS_RECONCILIATION_delete] --'<redacted>','<redacted>','<redacted>',null,null,null,null,null,null,null,'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@PaymentStatus varchar(50) = NULL,
	@PaymentResponse varchar(5000) = NULL,
	@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@ErrorMessage varchar(2000) = NULL,
	@AmountPaid varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@ApiType varchar(50) = 'RECONCILIATION'
)
AS
BEGIN

		IF NOT EXISTS (select 1 from ZED_SURVEILLANCE.dbo.PaymentGatewayTransactions where ZedId=@ZedId and Certification=@Certification and (PaymentStatus is NOT null AND PaymentStatus='Success'))
	BEGIN
			EXEC ZED_SURVEILLANCE.dbo.[SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId, @TransactionId, @PaymentStatus, @PaymentResponse, @IpAddress, @PgType, @BankRefNumber, @BankCode, @ErrorMessage, @AmountPaid, @Certification, @ApiType
		
	END
	--ELSE IF NOT EXISTS (select 1 from PaymentGatewayTransactions where ZedId=@ZedId and Certification=@Certification and @IsRecertification=1 AND GwReClassification=0 and (PaymentStatus is NOT null AND PaymentStatus='<redacted>'))
	--BEGIN
	--	EXEC [SP_MSME_PAYMENT_GATEWAY_DETAILS] @ZedId,@TransactionId,@PaymentStatus,@PaymentResponse,@IpAddress,@PgType,@BankRefNumber,@BankCode,@ErrorMessage,@AmountPaid,@Certification,@ApiType
		
	--END

	ELSE
	BEGIN
		Insert into ZED_SURVEILLANCE.dbo.MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
		values (@ZedId,concat('RECONCILIATION Response from PaymentGateway for ',@Certification),getdate(),@Certification,NULL,@ApiType)
		
		
	END

		

END
