/****** Object:  StoredProcedure [dbo].[sp_SyncMSMERequirementsBySpecificIDs]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_SyncMSMERequirementsBySpecificIDs] --'<redacted>','<redacted>'
    @SourceZEDID VARCHAR(50),
    @TargetZEDID VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    -- Update only the specific 8 IDs for the target ZEDID
    -- by pulling values from the source ZEDID
    UPDATE target
    SET 
        target.conformance = source.conformance,
        target.AssessorRemarks = source.AssessorRemarks,
        target.updateddate = GETDATE()
    FROM MSMEREQUIREMENTS AS target
    INNER JOIN MSMEREQUIREMENTS AS source 
        ON target.sectioncode = source.sectioncode 
        AND target.RequirementCode = source.RequirementCode
    WHERE source.ZEDID = @SourceZEDID
      AND target.ZEDID = @TargetZEDID
      AND target.requirementid IN (172, 173, 174, 177, 179, 180, 182, 330, 334);

    -- Provide feedback on how many rows were updated
    DECLARE @UpdatedCount INT = @@ROWCOUNT;
    PRINT CAST(@UpdatedCount AS VARCHAR) + ' requirements updated for ' + @TargetZEDID;
END
GO
