/****** Object:  StoredProcedure [dbo].[SP_TECHNOLOGY_UPGRADATION_GET_LIST]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_TECHNOLOGY_UPGRADATION_GET_LIST] '<redacted>','<redacted>','<redacted>'
--[SP_TECHNOLOGY_UPGRADATION_GET_LIST] '<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_TECHNOLOGY_UPGRADATION_GET_LIST] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@CertId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@Roleid varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	 select R.Id, R.TechnologyCode,R.TechnologyName,R.Description,R.Sectors,R.Categories,R.OrderNo,
		'Yes'AS IsSelected, CASE WHEN T.TechnologyCode is not null THEN 1 ELSE 0 END AS Submitted,
		R.CertId, R.Certification AS CertificationType, ROW_NUMBER() over(order by R.TechnologyCode) SNo, SubsidyPercentage EligibleSubsidyPer,
		DATEDIFF(DAY, C1.CertificationStatusDate, GETDATE()) DaysLimit
		--case when DATEDIFF(DAY, C.CertificationStatusDate, GETDATE())=0 then 1 ELSE DATEDIFF(DAY, C.CertificationStatusDate, GETDATE())
		--END AS DaysLimit

	from ZED_CONSULTANT.dbo.RecommandedTechnologies R
	INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P on (R.ZedId=P.ZedId and R.Certification=P.Certification and P.MsmePmtCertId=@CertId and MileStoneNum=3)
	INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications C on (R.ZedId=C.ZedId and R.Certification=C.Certification and C.Id=@CertId and NcCount=3)
	INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications C1 ON (R.ZedId = C1.ZedId AND R.Certification = C1.Certification AND C1.NcCount = 1)
	LEFt join 
	(select X.* from ZED_CONSULTANT.dbo.TechnologyUpgradation X inner join ZED_CONSULTANT.dbo.FinancialAssistance Y on (X.FinancialAssistanceId=Y.FinancialAssistanceId and Y.TechUpgradeStatus=1)
	)  T on (T.TechnologyCode=R.TechnologyCode and R.CertId=T.CertId and R.ZedId=T.ZedId and R.Certification=T.CertificationType) 
	WHERE R.CertId=@CertId and R.ZedId=@ZedId and R.Certification=@Certification
	order by SNo

	SELECT ROW_NUMBER() over(order by TechnologyCode) SNo,T.* FROM ZED_CONSULTANT.dbo.FinancialAssistance F
	INNER JOIN ZED_CONSULTANT.dbo.TechnologyUpgradation T ON (F.FinancialAssistanceId=T.FinancialAssistanceId)
	WHERE T.ZedId=@ZedId and T.CertificationType=@Certification and T.CertId=@CertId AND F.TechUpgradeStatus=1 order by SNo

	SELECT Id, ZedId, PhotoId photoPath, Name AS photoType, TimeStamp AS timeStamp, Latitude, Longitude, CreatedDate, CertificationType, IsVerified, 
		SourceOfValidation, AssessorRemarks, UpdatedDate, DocumentOpenedTime, FinancialAssistanceId, TechDetailsId, TechnologyCode, CertId
	FROM ZED_CONSULTANT.dbo.FinancialAssistancePhotos
	WHERE ZedId=@ZedId and CertificationType=@Certification and CertId=@CertId order by Id

	select TechnologyUpgradation from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId   -- if flag is 1 then ready to insert data by msme

END

GO
/****** Object:  StoredProcedure [dbo].[SP_UNDO__AGENCY_TO_REVERT]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_UNDO__AGENCY_TO_REVERT]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	BEGIN
		
			-- A. Restore MsmeCertifications data from Moveback table
			-- Note: We assume Id, ZedId, and Certification are the primary keys/unique identifiers
			UPDATE T1
			SET
				T1.CertificationStatus = T2.CertificationStatus,
				T1.SiteAssessorId = T2.SiteAssessorId,
				T1.CoAssessorId = T2.CoAssessorId,
				T1.ModeOfAssessment = T2.ModeOfAssessment,
				T1.AssessmentDate = T2.AssessmentDate,
				T1.SaAuditsConducted = T2.SaAuditsConducted,
				T1.SaDomesticCustomers = T2.SaDomesticCustomers,
				T1.SaInternationalCustomers = T2.SaInternationalCustomers,
				T1.SaRawMaterialImported = T2.SaOutsourcedProcesses, -- Assuming a typo in original SP, matching column to column
				T1.SaOutsourcedProcesses = T2.SaOutsourcedProcesses,
				T1.SaEnergySources = T2.SaEnergySources,
				T1.SaManufacturingCapacityUnits = T2.SaManufacturingCapacityUnits,
				T1.SaManufacturingCapacityValue = T2.SaManufacturingCapacityValue,
				T1.SaMonthlyUtilizationUnits = T2.SaMonthlyUtilizationUnits,
				T1.SaMonthlyUtilizationValue = T2.SaMonthlyUtilizationValue
			FROM ZEDCS_V2_LIVE.dbo.MsmeCertifications AS T1
			INNER JOIN ZEDCS_V2_LIVE.dbo.MsmeCertificationsMoveback AS T2 
				ON T1.Id = T2.Id 
				AND T1.ZedId = @ZedId 
				AND T1.Certification = @Certification;

			
			UPDATE T1
			SET 
				T1.SaConformance = T2.SaConformance,
				T1.SaUpdatedDate = T2.SaUpdatedDate,
				T1.SaAssessorRemarks = T2.SaAssessorRemarks
			FROM ZEDCS_V2_LIVE.dbo.MsmeRequirements AS T1
			INNER JOIN ZEDCS_V2_LIVE.dbo.MsmeRequirementsMoveback AS T2
				ON T1.Id = T2.Id
			WHERE T1.ZedId = @ZedId 
			AND T1.SectionType = @Certification;		



			DECLARE @SiteAssessorId varchar(50) = NULL
			SELECT  @SiteAssessorId=SiteAssessorId FROM MsmeCertifications where ZedId=@ZedId and certification = @Certification

			UPDATE ZEDCS_V2_LIVE.dbo.SaRequirementPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.SaRawMaterials SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.AssessorComments SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification AND AssessmentType = 'SA';

			UPDATE ZEDCS_V2_LIVE.dbo.MsmeLocations SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.ScreenshotPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.MsmeRawMaterials SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;			
            
			UPDATE ZEDCS_V2_LIVE.dbo.SaPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.SaProducts SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.MsmeSelfies SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND certification = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.MeetingParticipants SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND CertificationType = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.Meetings SET zedid = @ZedId 
            WHERE zedid = @ZedId + 'RESET' AND CertificationType = @Certification;

			UPDATE ZEDCS_V2_LIVE.dbo.MsmeSections SET AssessorId=@SiteAssessorId
            WHERE zedid = @ZedId AND SectionType = @Certification;
	END
            

END
GO
