CREATE PROC [dbo].[SP_UPDATE_USER] 
(
	 @UserId varchar(200)=NULL
	,@UserName varchar(200)
	,@Password varchar(200)=NULL
	,@RoleId int = NULL
	,@Email varchar(200) = NULL
	,@MobileNo varchar(15) = NULL
	,@CreatedBy varchar(50) = NULL
	,@SpocName varchar(200) = NULL
	,@Address varchar(2000) = NULL
	,@PinCode varchar(50) = NULL
	,@PreferredStates varchar(2000) = NULL
	,@NicSectors varchar(4000) = NULL
	,@AreaOfknowledge varchar(4000) = NULL
	,@IdProofType varchar(50) = NULL
	,@IdProofNumber varchar(50) = NULL
	,@GstNumber varchar(50) = NULL
	,@DesktopVerification varchar(50) = NULL
	,@SiteVerification varchar(50) = NULL
	,@FinancialVerification varchar(50) = NULL
	,@ReasonForRejection varchar(2000) = NULL
	,@AssessorType varchar(50) = NULL
	,@CertificateNo varchar(50) = NULL
	,@ProfessionalEmail varchar(50) = NULL
	,@OrgPartnerId varchar(100) = NULL


)
AS
BEGIN
     
	 IF @RoleId=2
	  Begin

	   DECLARE @OrgPartnerName varchar(200) = NULL

	    SELECT @OrgPartnerName=FirstName FROM ZED_CENTER_AUDIT_PROFESSIONAL.DBO.Users WHERE ROLEID=3 and UserId=@OrgPartnerId ORDER BY FirstName

		UPDATE Users set UserName=@UserName,Email=@Email, MobileNo=@MobileNo,SpocName=@SpocName,Address=@Address,Pincode=@PinCode, AgencyGstNumber=@GstNumber, DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification,ReasonForRejection=@ReasonForRejection,UpdatedByAgencyDate=GETDATE(), OrgPartnerId=@OrgPartnerId, OrgPartnerName=@OrgPartnerName  where UserId=@UserId

		Delete from AgencyUserStates where UserId=@UserId
		Delete from UserNicSectors where UserId=@UserId

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		update users set DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification where RoleId=3 AND CreatedBy=@UserId
		update users set DesktopVerification=1 where SiteVerification=1 and RoleId=3 AND CreatedBy=@UserId


		------UPDATING SURVEILLANCE USERS----------------
		UPDATE ZED_SURVEILLANCE.DBO.Users set UserName=@UserName,Email=@Email, MobileNo=@MobileNo,SpocName=@SpocName,Address=@Address,Pincode=@PinCode, AgencyGstNumber=@GstNumber, DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification,ReasonForRejection=@ReasonForRejection,UpdatedByAgencyDate=GETDATE()  where UserId=@UserId

		Delete from ZED_SURVEILLANCE.DBO.AgencyUserStates where UserId=@UserId
		Delete from ZED_SURVEILLANCE.DBO.UserNicSectors where UserId=@UserId

		INSERT INTO ZED_SURVEILLANCE.DBO.AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO ZED_SURVEILLANCE.DBO.UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join ZED_SURVEILLANCE.DBO.UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		update ZED_SURVEILLANCE.DBO.users set DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification where RoleId=3 AND CreatedBy=@UserId
		update ZED_SURVEILLANCE.DBO.users set DesktopVerification=1 where SiteVerification=1 and RoleId=3 AND CreatedBy=@UserId


			
	  End

	 IF   @RoleId=3
	  Begin


		UPDATE Users set UserName=@UserName,Email=@Email, MobileNo=@MobileNo,IdProofType=@IdProofType,IdProofNumber=@IdProofNumber,ReasonForRejection=@ReasonForRejection,Address=@Address,Pincode=@PinCode
		--,DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification 
		where UserId=@UserId

		Delete from AgencyUserStates where UserId=@UserId
		Delete from UserNicSectors where UserId=@UserId
		Delete from UserAreaOfKnowledge where UserId=@UserId

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO UserAreaOfKnowledge (UserId,RoleId,AreaOfKnowledge,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@AreaOfknowledge,',')


		----------------------UPDATE SURVEILLANCE USERS---------------------------------------
		UPDATE ZED_SURVEILLANCE.DBO.Users set UserName=@UserName,Email=@Email, MobileNo=@MobileNo,IdProofType=@IdProofType,IdProofNumber=@IdProofNumber,ReasonForRejection=@ReasonForRejection,Address=@Address,Pincode=@PinCode
		--,DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification 
		where UserId=@UserId

		Delete from ZED_SURVEILLANCE.DBO.AgencyUserStates where UserId=@UserId
		Delete from ZED_SURVEILLANCE.DBO.UserNicSectors where UserId=@UserId
		Delete from ZED_SURVEILLANCE.DBO.UserAreaOfKnowledge where UserId=@UserId

		INSERT INTO ZED_SURVEILLANCE.DBO.AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO ZED_SURVEILLANCE.DBO.UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join ZED_SURVEILLANCE.DBO.UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO ZED_SURVEILLANCE.DBO.UserAreaOfKnowledge (UserId,RoleId,AreaOfKnowledge,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@AreaOfknowledge,',')
			
	  End
END



