				update ScreenshotPhotos set ZedId=concat(ZedId,'_EXP_',SrnCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeRawMaterials set ZedId=concat(ZedId,'_EXP_',MsmeRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update PaymentGateWayTransactions set ZedId=concat(ZedId,'_EXP_',PmtGtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmePaymentInfo set ZedId=concat(ZedId,'_EXP_',MsmePmtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeSections set ZedId=concat(ZedId,'_EXP_',SecCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeRequirements set ZedId=concat(ZedId,'_EXP_',ReqCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeOptions set ZedId=concat(ZedId,'_EXP_',OptCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeSubOptions set ZedId=concat(ZedId,'_EXP_',SubCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeEvidences set ZedId=concat(ZedId,'_EXP_',EviCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmePhotos set ZedId=concat(ZedId,'_EXP_',MsPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeProducts set ZedId=concat(ZedId,'_EXP_',MsPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaPhotos set ZedId=concat(ZedId,'_EXP_',SaPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaProducts set ZedId=concat(ZedId,'_EXP_',SaPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeSelfies set ZedId=concat(ZedId,'_EXP_',MsSelfCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeHistory set ZedId=concat(ZedId,'_EXP_',MsHistCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update MeetingParticipants set ZedId=concat(ZedId,'_EXP_',MeetPartCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update Meetings set ZedId=concat(ZedId,'_EXP_',MeetCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update EsgCheckList set ZedId=concat(ZedId,'_EXP_',EsgCertId) where ZedId=@ZedId and Certification=@CertificationType

			COMMIT TRAN
		END TRY


		BEGIN CATCH

             ROLLBACK TRAN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

