/****** Object:  StoredProcedure [dbo].[SP_UPDATING_OPENEDFLAG]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_UPDATING_OPENEDFLAG] 
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@NcCount INT = 0
)
AS
BEGIN

	
		Update A set A.OpenedFlag=1  from MsmeRequirements A inner join 
		(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where ValidationRequired=1 and ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is null) B
		on (A.SectionCode=B.SectionCode and A.RequirementCode=B.RequirementCode and A.SectionType=B.SectionType and A.NcCount=B.NcCount) 
		left join 
		(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where  ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is not null) C
		on (A.SectionCode=C.SectionCode and A.RequirementCode=C.RequirementCode and A.SectionType=C.SectionType and A.NcCount=C.NcCount) 
		where ZedId=@ZedId and A.SectionType=@CertificationType and A.NcCount=@NcCount AND C.SectionCode IS NULL AND C.RequirementCode IS NULL

		Update A set A.IsAssessmentExcempted='No'  from MsmeSections A inner join 
		(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where ValidationRequired=1 and ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is null) B
		on (A.SectionCode=B.SectionCode and A.SectionType=B.SectionType and A.NcCount=B.NcCount) 
		left join 
		(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where  ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is not null) C
		on (A.SectionCode=C.SectionCode and A.SectionType=C.SectionType and A.NcCount=C.NcCount) 
		where ZedId=@ZedId and A.SectionType=@CertificationType and A.NcCount=@NcCount AND C.SectionCode IS NULL AND C.RequirementCode IS NULL

		UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and OpenedFlag is null and SectionType=@CertificationType and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
		(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@CertificationType and NcCount=0)

				

END


GO
/****** Object:  StoredProcedure [dbo].[SP_VERIFY_QR_CODE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_VERIFY_QR_CODE]  --'<redacted>','<redacted>'
(
	@QrCodeNo VARCHAR(50) = NULL,
	@CertificationType VARCHAR(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @ZedId varchar(50) = NULL
	DECLARE @SurveillanceCompletionDate varchar(50) = NULL
	DECLARE @OldSurveillanceCompletionDate varchar(50) = NULL
	DECLARE	@ReSurveillance int = 0
	DECLARE	@OldZedId varchar(50) = NULL


	select @ZedId=ZedId from MsmeCertifications where QrCodeSeqNo=@QrCodeNo and Certification=@CertificationType

	select @SurveillanceCompletionDate=FORMAT(CertificationStatusDate, 'MMMM d, yyyy') from ZED_SURVEILLANCE.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType 
	and ((Certification!='Bronze' and CertificationStatus=16) OR (Certification='Bronze' and CertificationStatus=6))

	
	select @ReSurveillance=ReSurveillance from ZED_SURVEILLANCE.dbo.MsmeBasicInformation where ZedId=@ZedId
	IF @ReSurveillance>=1
	BEGIN
		SELECT TOP 1 @OldZedId = CONCAT(@ZedId, '_S_', Id) 
		FROM ZED_SURVEILLANCE.dbo.MsmeCertifications 
		WHERE ZedId LIKE @ZedId + '_S_%' AND Certification = @CertificationType order by Id
		
		SELECT @OldSurveillanceCompletionDate = FORMAT(CertificationStatusDate, 'MMMM d, yyyy') 
		FROM ZED_SURVEILLANCE.dbo.MsmeCertifications 
		WHERE ZedId = @OldZedId AND Certification = @CertificationType 
		AND ((Certification != 'Bronze' AND CertificationStatus = 16) OR (Certification = 'Bronze' AND CertificationStatus = 6))
	END

	IF @CertificationType='Pledge'
	BEGIN
	SELECT M.PUnitName EnterpriseName,	concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin)  as Address,
	b.UdyogAadharNo,
	FORMAT(CreatedDate, 'MMMM d, yyyy') DateOfPledge,PledgeCertificateNo CertificateNo, '' CertificationPhase
	FROM Msme M	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) WHERE QrCodeNo=@QrCodeNo
	END
	ELSE 
	select 
		M.PUnitName EnterpriseName,
		case when @CertificationType='Bronze' then DaCertificateNo else SaCertificateNo end as CertificateNo,
		FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DateOfCertification,
		FORMAT(convert(date,dateadd(yy,3,CertificationStatusDate)), 'MMMM d, yyyy') DateOfExpiry,
		concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) as Address ,	
		B.UdyogAadharNo,
		M.MobileNo,
		M.EmailId,
		case when Certification='Silver' and RestrictMail='Gold Certified' then 'Gold Certified' else CertificationPhase end as CertificationPhase,
		FORMAT(FirstSurveDueDate, 'MMMM d, yyyy') FirstSurveDueDate, Certification, @SurveillanceCompletionDate SurveillanceCompletionDate,
		@OldSurveillanceCompletionDate AS OldSurveillanceDate
	    from Msme M inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_R',''),concat('_',C.Id),'')) 
	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where QrCodeSeqNo=@QrCodeNo and Certification=@CertificationType

END


GO
