/****** Object:  StoredProcedure [dbo].[SP_WEB_SITE_LIST_OF_CERTIFIED_MSME]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEB_SITE_LIST_OF_CERTIFIED_MSME] --null,null,null,'<redacted>'
(
	  
	
	@CertificationType varchar(50) = NULL,
	@State varchar(100) = NULL,
	@MsmeSize varchar(50) = NULL,
	@Sector varchar(2000) = NULL
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME
	IF @State=''
	set @State=NULL

	SET NOCOUNT ON;
		
		SELECT 
		ROW_NUMBER() OVER(order by M.MsmeId) as Sno,
		M.PUnitName EnterpriseName,
		TwoDigitActivity,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,PStateName StateName,M.EnterpriseTypee,Certification, CertificationPhase
			--M.CreatedDate ReigstrationDate,
			-- U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			--UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			--Us.UserName as SiteAssessor, P.SiteAssessorId,
			--UC.UserName as coAssessor, P.CoAssessorId,
		
			--PDistrictName DistrictName,  EnterpriseName, ModeOfAssessment,FORMAT(AssessmentDate, '<redacted>') SaAssessmentDate,
			--DaCertificateNo,SaCertificateNo,
		--	CertificationStatusDate CertificationDate
		

		--FROM Msme M
		--INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		--INNER join MsmeCertifications P on (P.ZedId=M.ZedId and P.Certification=B.LastestCertification)
		--WHERE CertificationStatus in (6,16)
		--AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		--AND (@State is null or M.StateId=@State)
		--AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
		--AND UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		--ORDER By M.MsmeId 	

		FROM Msme M
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		INNER join MsmeCertifications P ON (M.ZedId = REPLACE(P.ZedId, CONCAT('_R_', P.Id), ''))
		--WHERE CertificationStatus in (6,16)
		--AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		where ((certification='Bronze' and Certificationstatus=6) or (certification!='Bronze' and Certificationstatus=16))
		AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		--WHERE CertificationStatus=16
		--AND SaCertificateNo is not null
		AND (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
		AND UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
		ORDER By M.MsmeId 	
	
END


GO
/****** Object:  StoredProcedure [dbo].[SP_WEB_SITE_LIST_OF_KAWACH_CERTIFIED_MSME]    Script Date: 9/19/2026 4:28:42 AM ******/
