CREATE PROCEDURE [dbo].[SP_WEB_SITE_LIST_OF_KAWACH_CERTIFIED_MSME] --null,null,null,'<redacted>'
(
	  
	
	@CertificationType varchar(50) = NULL,
	@State varchar(100) = NULL,
	@MsmeSize varchar(50) = NULL,
	@Sector varchar(2000) = NULL
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;
		
		SELECT 
		ROW_NUMBER() OVER(order by MsmeId) as Sno,
		M.EnterpriseName,
		TwoDigitActivity,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,PStateName StateName,EnterpriseTypee--,Certification
			--M.CreatedDate ReigstrationDate,
			-- U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			--UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			--Us.UserName as SiteAssessor, P.SiteAssessorId,
			--UC.UserName as coAssessor, P.CoAssessorId,
		
			--PDistrictName DistrictName,  EnterpriseName, ModeOfAssessment,FORMAT(AssessmentDate, '<redacted>') SaAssessmentDate,
			--DaCertificateNo,SaCertificateNo,
		--	CertificationStatusDate CertificationDate
		

		FROM kawach.dbo.Msme M
		INNER join kawach.dbo.MsmeCertifications P on (P.ZedId=M.ZedId)
		WHERE CertificationStatus in (6)
		AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		AND (@State is null or M.StateId=@State)
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
		ORDER By MsmeId 	
	
END


