AS
BEGIN

	SELECT R.Title, R.FirstName, R.LastName, UPPER(R.Title + ' ' + R.FirstName) FullName, UPPER(S.EstablishmentName) EstablishmentName, S.RegistrationNumber, 
		R.WebinarCertificateNo, FORMAT(R.CertificateDate, 'MMMM d, yyyy h:mm tt') CertificateDate,
		REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress

	FROM WebinarRegistrations R
	--INNER JOIN Webinars W on (R.WebinarId=W.Id)
	--INNER JOIN SelfAssessments S on (S.WebinarId=R.WebinarId AND R.RegistrationNumber=S.RegistrationNumber)
	INNER JOIN SelfAssessments S on (R.RegistrationNumber=S.RegistrationNumber)
	WHERE (R.RegistrationNumber=@RegistrationNumber AND CertificateVersion=1) OR (WebinarCertificateId=@RegistrationNumber)

