/****** Object:  StoredProcedure [dbo].[SP_WEBINAR_INSERT_REGISTRATION_DATA]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEBINAR_INSERT_REGISTRATION_DATA] --'<redacted>', '<redacted>'
(
	@RespondentMobileNo varchar(50) = NULL,
	@RegistrationNumber varchar(50) = NULL,
	@WebinarId varchar(50) = NULL,
	@Title varchar(50) = NULL,
	@FirstName varchar(100) = NULL,
	@LastName varchar(100) = NULL,
	@MobileNo varchar(100) = NULL,
	@Email varchar(100) = NULL
)
AS
BEGIN

	declare @NoOfRegistrations int = null
	declare @RegistrationCount int = null
	declare @NumOfRooms int = null

	IF EXISTS (	SELECT top 1 * from WebinarRegistrations where RegistrationNumber=@RegistrationNumber)
	BEGIN
	Set @NumOfRooms=0
	END
	ELSE 
	BEGIN
	SELECT @NumOfRooms=TotalRooms from SelfAssessments where RegistrationNumber=@RegistrationNumber
	END

	SET NOCOUNT ON;

	BEGIN
		INSERT INTO WebinarRegistrations (
			[WebinarId]
		  ,[RegistrationNumber]
		  ,[RespondentMobileNo]
		  ,[Title]
		  ,[FirstName]
		  ,[LastName]
		  ,[MobileNo]
		  ,[Email]
		  ,[CreatedDate]
		  ,[NumOfRooms]
		) VALUES (
			@WebinarId,
			@RegistrationNumber,
			@RespondentMobileNo, 
			@Title, 
			@FirstName, 
			@LastName, 
			@MobileNo, 
			@Email, 
			getdate(),
			@NumOfRooms
		)

		--UPDATE SelfAssessments SET WebinarId=@WebinarId WHERE RegistrationNumber=@RegistrationNumber --MobileNo=@RespondentMobileNo
	END

	SELECT @NoOfRegistrations=COUNT(*) from WebinarRegistrations where WebinarId=@WebinarId
	SELECT @RegistrationCount=RegistrationCount from Webinars where Id=@WebinarId

	--IF @NoOfRegistrations>=@RegistrationCount 
	IF @NoOfRegistrations>=200
	BEGIN
	UPDATE Webinars SET IsRegistrationsClosed=1 WHERE Id=@WebinarId
	END

	


END
