/****** Object:  StoredProcedure [dbo].[USP_REFRESH_DASHBOARD_CACHE]    Script Date: 9/19/2026 4:28:42 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROC [dbo].[USP_REFRESH_DASHBOARD_CACHE]
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Clear the old cache
    TRUNCATE TABLE Dashboard_Summary_Cache;

    ---------------------------------------------------------------------------
    -- GROUP 1: ADMIN ROLES (7, 10, 8, 11)
    -- We calculate global stats once and map them to each Admin user
    ---------------------------------------------------------------------------
    INSERT INTO Dashboard_Summary_Cache (
        UserId, RoleId, LastUpdated, AssessmentAgencies, DesktopAssessors, SiteAssessors, FinancialAssessors,
        BronzeCompleted, FaBronzeCompleted, BronzePending, SilverCompleted, FaSilverCompleted, SilverPending,
        GoldCompleted, FaGoldCompleted, GoldPending, BronzeTotal, SilverTotal, GoldTotal,
        FaTotal, FaPending, FaCompleted, FaRejected, SaSilverCompleted, SaGoldCompleted, SaSilverPending, SaGoldPending,
        BronzeRejected, SilverRejected, GoldRejected, BronzeNcRaised, SilverNcRaised, GoldNcRaised
    )
    SELECT 
        U.UserId, U.RoleId, GETDATE(),
        Stats.AssessmentAgencies, Stats.DesktopAssessors, Stats.SiteAssessors, Stats.FinancialAssessors,
        Stats.BronzeCompleted, Stats.FaBronzeCompleted, Stats.BronzePending, Stats.SilverCompleted, Stats.FaSilverCompleted, Stats.SilverPending,
        Stats.GoldCompleted, Stats.FaGoldCompleted, Stats.GoldPending, Stats.BronzeTotal, Stats.SilverTotal, Stats.GoldTotal,
        Stats.FaTotal, Stats.FaPending, Stats.FaCompleted, Stats.FaRejected, Stats.SaSilverCompleted, Stats.SaGoldCompleted, Stats.SaSilverPending, Stats.SaGoldPending,
        Stats.BronzeRejected, Stats.SilverRejected, Stats.GoldRejected, Stats.BronzeNcRaised, Stats.SilverNcRaised, Stats.GoldNcRaised
    FROM Users U
    CROSS APPLY (
        SELECT 
            (SELECT COUNT(*) FROM Users WHERE RoleId = 2) AS AssessmentAgencies,
            (SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND DesktopVerification = 1) AS DesktopAssessors,
            (SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND SiteVerification = 1) AS SiteAssessors,
            (SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND FinancialVerification = 1) AS FinancialAssessors,
            SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN 1 ELSE 0 END) AS BronzeCompleted,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Bronze' AND IsApproved = 1) AS FaBronzeCompleted,
            SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus IN (2,3) THEN 1 ELSE 0 END) AS BronzePending,
            SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 6 THEN 1 ELSE 0 END) AS SilverCompleted,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Silver' AND IsApproved = 1) AS FaSilverCompleted,
            SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus < 6 AND C.CertificationStatus > 1 THEN 1 ELSE 0 END) AS SilverPending,
            SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 6 THEN 1 ELSE 0 END) AS GoldCompleted,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Gold' AND IsApproved = 1) AS FaGoldCompleted,
            SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus < 6 AND C.CertificationStatus > 1 THEN 1 ELSE 0 END) AS GoldPending,
            SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus != 1 THEN 1 ELSE 0 END) AS BronzeTotal,
            SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus != 1 THEN 1 ELSE 0 END) AS SilverTotal,
            SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus != 1 THEN 1 ELSE 0 END) AS GoldTotal,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus != 5) AS FaTotal,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus < 5) AS FaPending,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 6) AS FaCompleted,
            (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 5) AS FaRejected,
            SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 THEN 1 ELSE 0 END) AS SaSilverCompleted,
            SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 THEN 1 ELSE 0 END) AS SaGoldCompleted,
            SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus IN (2,3,5,6,8,9,13) THEN 1 ELSE 0 END) AS SaSilverPending,
            SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus IN (2,3,5,6,8,9,13) THEN 1 ELSE 0 END) AS SaGoldPending,
            SUM(CASE WHEN C.CertificationStatus = 99 AND C.Certification = 'Bronze' THEN 1 ELSE 0 END) AS BronzeRejected,
            SUM(CASE WHEN C.CertificationStatus = 99 AND C.Certification = 'Silver' THEN 1 ELSE 0 END) AS SilverRejected,
            SUM(CASE WHEN C.CertificationStatus = 99 AND C.Certification = 'Gold' THEN 1 ELSE 0 END) AS GoldRejected,
            SUM(CASE WHEN C.CertificationStatus IN (4,5,7) AND C.Certification = 'Bronze' THEN 1 ELSE 0 END) AS BronzeNcRaised,
            SUM(CASE WHEN C.CertificationStatus IN (14,15,17) AND C.Certification = 'Silver' THEN 1 ELSE 0 END) AS SilverNcRaised,
            SUM(CASE WHEN C.CertificationStatus IN (14,15,17) AND C.Certification = 'Gold' THEN 1 ELSE 0 END) AS GoldNcRaised
        FROM MsmeCertifications C
        INNER JOIN Msme M ON (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1) = M.ZedId)
        INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
        WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
    ) Stats
    WHERE U.RoleId IN (7, 10, 8, 11);

    ---------------------------------------------------------------------------
    -- GROUP 2: ASSESSMENT AGENCIES (RoleId 2)
    -- We calculate unique counts per Agency
    ---------------------------------------------------------------------------
    INSERT INTO Dashboard_Summary_Cache (UserId, RoleId, LastUpdated, AssessmentAgencies, DesktopAssessors, SiteAssessors, FinancialAssessors, BronzeCompleted, BronzePending, SilverCompleted, SilverPending, GoldCompleted, GoldPending, SaSilverCompleted, SaSilverPending, SaGoldCompleted, SaGoldPending, BronzeTotal, SilverTotal, GoldTotal, FaTotal, FaPending, FaCompleted, FaRejected, BronzeRejected, SilverRejected, GoldRejected, BronzeNcRaised, SilverNcRaised, GoldNcRaised)
    SELECT 
        U.UserId, 2, GETDATE(), 0,
        (SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND DesktopVerification = 1 AND CreatedBy = U.UserId),
        (SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND SiteVerification = 1 AND CreatedBy = U.UserId),
        (SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND FinancialVerification = 1 AND CreatedBy = U.UserId),
        SUM(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NULL AND CertificationStatus BETWEEN 2 AND 5 THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NULL AND CertificationStatus BETWEEN 3 AND 5 THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NULL AND CertificationStatus BETWEEN 2 AND 5 THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Silver' AND ModeOfAssessment IS NOT NULL AND SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Silver' AND ModeOfAssessment IS NOT NULL AND SaCertificateNo IS NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Gold' AND ModeOfAssessment IS NOT NULL AND SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Gold' AND ModeOfAssessment IS NOT NULL AND SaCertificateNo IS NULL THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Bronze' THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Silver' THEN 1 ELSE 0 END),
        SUM(CASE WHEN Certification = 'Gold' THEN 1 ELSE 0 END),
        (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus != 5 AND CertificationBodyUserId = U.UserId),
        (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus < 5 AND CertificationBodyUserId = U.UserId),
        (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 6 AND CertificationBodyUserId = U.UserId),
        (SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 5 AND CertificationBodyUserId = U.UserId),
        SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Bronze' THEN 1 ELSE 0 END),
        SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Silver' THEN 1 ELSE 0 END),
        SUM(CASE WHEN CertificationStatus = 99 AND Certification = 'Gold' THEN 1 ELSE 0 END),
        SUM(CASE WHEN CertificationStatus IN (4,5,7) AND Certification = 'Bronze' THEN 1 ELSE 0 END),
        SUM(CASE WHEN CertificationStatus IN (14,15,17) AND Certification = 'Silver' THEN 1 ELSE 0 END),
        SUM(CASE WHEN CertificationStatus IN (14,15,17) AND Certification = 'Gold' THEN 1 ELSE 0 END)
    FROM Users U
    LEFT JOIN MsmeCertifications C ON U.UserId = C.CertificationBodyUserId
    WHERE U.RoleId = 2
    GROUP BY U.UserId;

    -- Note: Role 3 (Assessors) would follow the same pattern as Role 2 above.
END
GO
